INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u1-C1','math',4,2,'u1',2,'단위분수의 개수와 대분수·가분수 — 진분수·가분수·대분수를 가르고, 분수를 단위분수가 몇 개인 수로 보며 대분수와 가분수를 서로 바꾸기',ARRAY['4수01-15']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u1-C2','math',4,2,'u1',2,'1을 가르고 분수를 모으기 — 1을 분모와 분자가 같은 분수(⟨b/b⟩)로 나타내고, 1을 분모가 같은 두 분수로 가르거나 두 분수를 모아 1 만들기',ARRAY['4수01-15']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u1-C3','math',4,2,'u1',3,'진분수의 덧셈 — 분모가 같은 진분수끼리는 분모는 그대로 두고 분자끼리 더하며, 결과가 1보다 크면 대분수로 나타내기',ARRAY['4수01-15']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u1-C4','math',4,2,'u1',4,'진분수의 뺄셈과 1 − 진분수 — 분모가 같은 진분수끼리 분자끼리 빼고, 1에서 뺄 때는 1을 ⟨b/b⟩로 바꾸어 빼기',ARRAY['4수01-15']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u1-C5','math',4,2,'u1',5,'대분수의 덧셈 — 자연수끼리·진분수끼리 더하고 진분수끼리의 합이 1보다 크면 1을 자연수로 넘기거나, 가분수로 바꾸어 더하기',ARRAY['4수01-15']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u1-C6','math',4,2,'u1',6,'대분수의 뺄셈 — 자연수끼리·진분수끼리 빼거나 가분수로 바꾸어 빼기(자연수 부분이 없어지는 뺄셈 포함)',ARRAY['4수01-15']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u1-C7','math',4,2,'u1',7,'자연수 − 분수 — 자연수에서 1만큼을 분모가 같은 분수로 바꾸어(3 = ⟨2 4/4⟩) 빼기, 자연수 부분은 1 줄어든다',ARRAY['4수01-15']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u1-C8','math',4,2,'u1',7,'대분수 − 진분수(1만큼 바꾸기) — 진분수끼리 뺄 수 없으면 자연수에서 1만큼을 ⟨b/b⟩로 바꾸어 분수 부분에 더한 뒤 빼거나, 가분수로 바꾸어 빼기',ARRAY['4수01-15']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u1-C9','math',4,2,'u1',8,'대분수 − 대분수(1만큼 바꾸기) — 진분수끼리 뺄 수 없는 대분수의 뺄셈을 1만큼 바꾸어 부분끼리 또는 가분수로 바꾸어 계산하고, 잘못 계산한 곳을 찾아 고치기',ARRAY['4수01-15']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u1-C10','math',4,2,'u1',9,'분수 카드로 식 만들기 — 결과에 맞는 덧셈식·뺄셈식을 어림해서 고르고 계산으로 확인하며, 합·차가 가장 크거나 작게 되는 식 만들기',ARRAY['4수01-15']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X01','math',4,'u1',ARRAY['M4-2-u1-C3','M4-2-u1-C4','M4-2-u1-C5','M4-2-u1-C6']::text[],'분모끼리도 더하거나 뺀다(⟨1/5⟩ + ⟨3/5⟩ → ⟨4/10⟩)','분모는 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X02','math',4,'u1',ARRAY['M4-2-u1-C1']::text[],'진분수·가분수·대분수의 뜻이나 단위분수의 개수를 헷갈린다(⟨7/9⟩ → ⟨1/9⟩이 9개)','분자 = 단위분수 개수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X03','math',4,'u1',ARRAY['M4-2-u1-C1','M4-2-u1-C5','M4-2-u1-C6','M4-2-u1-C9']::text[],'대분수를 가분수로 바꿀 때 자연수 부분을 단위분수 개수로 바꾸지 않는다(⟨2 1/3⟩ → ⟨3/3⟩)','자연수 1 = 분모만큼') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X04','math',4,'u1',ARRAY['M4-2-u1-C1','M4-2-u1-C3','M4-2-u1-C5']::text[],'가분수를 대분수로 바꿀 때 자연수(통째 1)를 잘못 센다(⟨11/4⟩ → ⟨3 3/4⟩·⟨1 3/4⟩)','분모만큼씩 모아 1') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X05','math',4,'u1',ARRAY['M4-2-u1-C2','M4-2-u1-C4','M4-2-u1-C7']::text[],'1을 분모와 분자가 같은 분수로 보지 못한다(1 = ⟨1/7⟩)','1 = ⟨b/b⟩') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X06','math',4,'u1',ARRAY['M4-2-u1-C2']::text[],'모아서 1이 되는 분수를 구할 때 분모에서 분자를 빼지 않는다(⟨4/9⟩와 모아 1 → ⟨4/9⟩·⟨9/4⟩)','모자란 단위분수 개수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X07','math',4,'u1',ARRAY['M4-2-u1-C3','M4-2-u1-C5']::text[],'진분수끼리의 합이 1보다 클 때 1을 자연수에 더하지 않는다(⟨1 3/5⟩ + ⟨1 4/5⟩ → ⟨2 2/5⟩)','넘친 1은 자연수로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X08','math',4,'u1',ARRAY['M4-2-u1-C4','M4-2-u1-C7']::text[],'1에서 진분수를 뺄 때 1을 ⟨b/b⟩로 바꾸지 않고 분자에서 1을 뺀다(1 − ⟨2/7⟩ → ⟨1/7⟩)','1 = ⟨b/b⟩로 바꾸기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X09','math',4,'u1',ARRAY['M4-2-u1-C7','M4-2-u1-C8','M4-2-u1-C9']::text[],'1만큼을 분수로 바꾸고도 자연수 부분에서 1을 빼지 않는다(3 − ⟨1/4⟩ → ⟨3 3/4⟩, ⟨5 1/6⟩ − ⟨2 5/6⟩ → ⟨3 2/6⟩)','바꾼 1은 자연수에서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X10','math',4,'u1',ARRAY['M4-2-u1-C7']::text[],'자연수에서 분수를 뺄 때 빼는 분수를 그대로 쓴다(3 − ⟨1/4⟩ → ⟨2 1/4⟩)','⟨4/4⟩에서 덜어 내기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X11','math',4,'u1',ARRAY['M4-2-u1-C8','M4-2-u1-C9']::text[],'진분수끼리 뺄 수 없을 때 큰 분자에서 작은 분자를 거꾸로 뺀다(⟨5 1/6⟩ − ⟨2 5/6⟩ → ⟨3 4/6⟩)','거꾸로 빼지 않기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X12','math',4,'u1',ARRAY['M4-2-u1-C8','M4-2-u1-C9']::text[],'1만큼을 분수로 바꿀 때 분자에 분모가 아닌 10을 더한다(⟨5 1/6⟩ → ⟨4 11/6⟩)','1 = 분모만큼') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X13','math',4,'u1',ARRAY['M4-2-u1-C5','M4-2-u1-C6','M4-2-u1-C8','M4-2-u1-C9']::text[],'대분수의 덧셈·뺄셈에서 자연수 부분을 빼먹는다(⟨3 5/6⟩ − ⟨1 2/6⟩ → ⟨3/6⟩)','자연수끼리도 계산') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X14','math',4,'u1',ARRAY['M4-2-u1-C3','M4-2-u1-C4','M4-2-u1-C5','M4-2-u1-C6','M4-2-u1-C7','M4-2-u1-C9','M4-2-u1-C10']::text[],'더해야 할 때 빼거나 빼야 할 때 더한다(「얼마나 더」·「남은」을 덧셈으로)','모으면 덧셈·덜어 내면 뺄셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X15','math',4,'u1',ARRAY['M4-2-u1-C1','M4-2-u1-C2','M4-2-u1-C3','M4-2-u1-C4','M4-2-u1-C5','M4-2-u1-C6','M4-2-u1-C7','M4-2-u1-C8','M4-2-u1-C9','M4-2-u1-C10']::text[],'묻는 말을 거꾸로 읽는다 — 남은↔쓴, 더 많은↔더 적은, 가장 큰↔가장 작은','물음에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X16','math',4,'u1',ARRAY['M4-2-u1-C1','M4-2-u1-C2','M4-2-u1-C3','M4-2-u1-C4','M4-2-u1-C5','M4-2-u1-C7','M4-2-u1-C10']::text[],'분자를 하나 많거나 적게 세거나, □에 들어갈 수를 셀 때 경계의 수를 넣거나 뺀다','하나씩 넣어 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X17','math',4,'u1',ARRAY['M4-2-u1-C10']::text[],'어림 없이 분자나 자연수 하나만 보고 식의 크기를 정한다(합을 가장 크게 하려고 분자가 큰 카드 하나만 본다)','어림한 뒤 계산으로 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X18','math',4,'u1',ARRAY['M4-2-u1-C3','M4-2-u1-C5','M4-2-u1-C10']::text[],'계산해서 견줄 수 있는데도 「알 수 없다」·「같다」고 한다','계산해서 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X19','math',4,'u1',ARRAY['M4-2-u1-C1','M4-2-u1-C7']::text[],'자연수와 분수를 함께 계산할 때 자연수를 분자처럼 더하거나 뺀다(5 + ⟨5/9⟩ → ⟨10/9⟩, 4 − ⟨3/9⟩ → ⟨1/9⟩)','자연수는 분모만큼의 단위분수 — 4 = ⟨3 9/9⟩') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X20','math',4,'u1',ARRAY['M4-2-u1-C3','M4-2-u1-C4']::text[],'더하는 두 분수의 전체를 합쳐 새 전체로 본다 — 전체 6칸짜리 두 개를 12칸으로 보고 ⟨2/6⟩ + ⟨3/6⟩ = ⟨5/12⟩라고 한다','더해도 전체 1은 그대로 — 단위분수 ⟨1/6⟩의 개수만 센다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L02_basic#1','math',4,2,'u1','L02','tb_g4_2_math_u1_L02_basic','lesson_basic','M4-2-u1-C2',1,'sa','auto','분수 띠를 보고 1은 단위분수 ⟨1/4⟩이 몇 개인지 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u1-C2","difficulty":1,"kind":"sa","stem":"분수 띠를 보고 1은 단위분수 ⟨1/4⟩이 몇 개인지 숫자로 쓰세요.","answer":["4"],"explanation":["분수 띠에서 1을 똑같이 4칸으로 나눈 것 중 한 칸이 ⟨1/4⟩이에요.","⟨1/4⟩ 칸을 세면 4칸이에요.","1은 ⟨1/4⟩이 4개 — 1 = ⟨4/4⟩예요."],"asset":{"type":"fbar","bars":[{"den":4,"num":4}]},"variant_rule":{"alt":[{"stem":"「익힘」 분수 띠를 보고 1은 단위분수 ⟨1/5⟩이 몇 개인지 숫자로 쓰세요.","answer":["5"],"explanation":["1을 똑같이 5칸으로 나눈 것 중 한 칸이 ⟨1/5⟩이에요.","⟨1/5⟩ 칸을 세면 5칸이에요.","1은 ⟨1/5⟩이 5개 — 1 = ⟨5/5⟩예요."],"asset":{"type":"fbar","bars":[{"den":5,"num":5}]}},{"stem":"「익힘」 분수 띠를 보고 1은 단위분수 ⟨1/2⟩이 몇 개인지 숫자로 쓰세요.","answer":["2"],"explanation":["1을 똑같이 2칸으로 나눈 것 중 한 칸이 ⟨1/2⟩이에요.","⟨1/2⟩ 칸을 세면 2칸이에요.","1은 ⟨1/2⟩이 2개 — 1 = ⟨2/2⟩예요."],"asset":{"type":"fbar","bars":[{"den":2,"num":2}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L02_basic#2','math',4,2,'u1','L02','tb_g4_2_math_u1_L02_basic','lesson_basic','M4-2-u1-C2',1,'mc','auto','「확인 문제」 1을 분모가 8인 분수로 나타내면 무엇인가요?',ARRAY['M4-2-u1-X05','M4-2-u1-X16']::text[],true,'{"seq":2,"concept":"M4-2-u1-C2","difficulty":1,"kind":"mc","stem":"「확인 문제」 1을 분모가 8인 분수로 나타내면 무엇인가요?","options":[{"t":"⟨8/8⟩","correct":true},{"t":"⟨1/8⟩","mis":"M4-2-u1-X05"},{"t":"⟨7/8⟩","mis":"M4-2-u1-X16"},{"t":"⟨9/8⟩","mis":"M4-2-u1-X16"}],"explanation":["분모가 8이면 1을 똑같이 8칸으로 나눈 것 중 한 칸이 ⟨1/8⟩이에요.","1은 ⟨1/8⟩이 8개예요.","1 = ⟨8/8⟩ — 분모와 분자가 같아요."],"variant_rule":{"alt":[{"stem":"「확인 문제」 1을 분모가 9인 분수로 나타내면 무엇인가요?","options":[{"t":"⟨9/9⟩","correct":true},{"t":"⟨1/9⟩","mis":"M4-2-u1-X05"},{"t":"⟨8/9⟩","mis":"M4-2-u1-X16"},{"t":"⟨10/9⟩","mis":"M4-2-u1-X16"}],"explanation":["분모가 9이면 1을 똑같이 9칸으로 나눈 것 중 한 칸이 ⟨1/9⟩이에요.","1은 ⟨1/9⟩이 9개예요.","1 = ⟨9/9⟩ — 분모와 분자가 같아요."]},{"stem":"「확인 문제」 1을 분모가 12인 분수로 나타내면 무엇인가요?","options":[{"t":"⟨12/12⟩","correct":true},{"t":"⟨1/12⟩","mis":"M4-2-u1-X05"},{"t":"⟨11/12⟩","mis":"M4-2-u1-X16"},{"t":"⟨13/12⟩","mis":"M4-2-u1-X16"}],"explanation":["분모가 12이면 1을 똑같이 12칸으로 나눈 것 중 한 칸이 ⟨1/12⟩이에요.","1은 ⟨1/12⟩이 12개예요.","1 = ⟨12/12⟩ — 분모와 분자가 같아요."]},{"stem":"「확인 문제」 1을 분모가 20인 분수로 나타내면 무엇인가요?","options":[{"t":"⟨20/20⟩","correct":true},{"t":"⟨1/20⟩","mis":"M4-2-u1-X05"},{"t":"⟨19/20⟩","mis":"M4-2-u1-X16"},{"t":"⟨21/20⟩","mis":"M4-2-u1-X16"}],"explanation":["분모가 20이면 1을 똑같이 20칸으로 나눈 것 중 한 칸이 ⟨1/20⟩이에요.","1은 ⟨1/20⟩이 20개예요.","1 = ⟨20/20⟩ — 분모와 분자가 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L02_basic#3','math',4,2,'u1','L02','tb_g4_2_math_u1_L02_basic','lesson_basic','M4-2-u1-C2',1,'mc','auto','분수 띠로 1을 ⟨1/4⟩과 □로 갈랐어요. □에 알맞은 분수는 무엇인가요?',ARRAY['M4-2-u1-X06','M4-2-u1-X16']::text[],true,'{"seq":3,"concept":"M4-2-u1-C2","difficulty":1,"kind":"mc","stem":"분수 띠로 1을 ⟨1/4⟩과 □로 갈랐어요. □에 알맞은 분수는 무엇인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨1/4⟩","mis":"M4-2-u1-X06"},{"t":"⟨2/4⟩","mis":"M4-2-u1-X16"},{"t":"⟨5/4⟩","mis":"M4-2-u1-X06"}],"explanation":["1 = ⟨4/4⟩ — ⟨1/4⟩이 4개예요.","⟨1/4⟩은 ⟨1/4⟩이 1개라 4 − 1 = 3개가 모자라요.","⟨1/4⟩ + ⟨3/4⟩ = ⟨4/4⟩ = 1이에요."],"asset":{"type":"fbar","bars":[{"den":4,"num":1,"label":"1을 가르기"}]},"variant_rule":{"alt":[{"stem":"분수 띠로 1을 ⟨2/6⟩와 □로 갈랐어요. □에 알맞은 분수는 무엇인가요?","options":[{"t":"⟨4/6⟩","correct":true},{"t":"⟨2/6⟩","mis":"M4-2-u1-X06"},{"t":"⟨6/2⟩","mis":"M4-2-u1-X06"},{"t":"⟨5/6⟩","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨6/6⟩ — ⟨1/6⟩이 6개예요.","⟨2/6⟩는 ⟨1/6⟩이 2개라 6 − 2 = 4개가 모자라요.","⟨2/6⟩ + ⟨4/6⟩ = ⟨6/6⟩ = 1이에요."],"asset":{"type":"fbar","bars":[{"den":6,"num":2,"label":"1을 가르기"}]}},{"stem":"분수 띠로 1을 ⟨1/3⟩과 □로 갈랐어요. □에 알맞은 분수는 무엇인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨1/3⟩","mis":"M4-2-u1-X06"},{"t":"⟨4/3⟩","mis":"M4-2-u1-X06"},{"t":"⟨3/3⟩","mis":"M4-2-u1-X05"}],"explanation":["1 = ⟨3/3⟩ — ⟨1/3⟩이 3개예요.","⟨1/3⟩은 ⟨1/3⟩이 1개라 3 − 1 = 2개가 모자라요.","⟨1/3⟩ + ⟨2/3⟩ = ⟨3/3⟩ = 1이에요."],"asset":{"type":"fbar","bars":[{"den":3,"num":1,"label":"1을 가르기"}]}},{"stem":"「확인 문제」 분수 띠로 1을 ⟨3/5⟩과 □로 갈랐어요. □에 알맞은 분수는 무엇인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨3/5⟩","mis":"M4-2-u1-X06"},{"t":"⟨5/3⟩","mis":"M4-2-u1-X06"},{"t":"⟨1/5⟩","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨5/5⟩ — ⟨1/5⟩이 5개예요.","⟨3/5⟩은 ⟨1/5⟩이 3개라 5 − 3 = 2개가 모자라요.","⟨3/5⟩ + ⟨2/5⟩ = ⟨5/5⟩ = 1이에요."],"asset":{"type":"fbar","bars":[{"den":5,"num":3,"label":"1을 가르기"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L02_basic#4','math',4,2,'u1','L02','tb_g4_2_math_u1_L02_basic','lesson_basic','M4-2-u1-C1',1,'mc','auto','「준비하기」 다음 중 대분수는 무엇인가요?',ARRAY['M4-2-u1-X02']::text[],true,'{"seq":4,"concept":"M4-2-u1-C1","difficulty":1,"kind":"mc","stem":"「준비하기」 다음 중 대분수는 무엇인가요?","options":[{"t":"⟨1 1/2⟩","correct":true},{"t":"⟨7/5⟩","mis":"M4-2-u1-X02"},{"t":"⟨7/8⟩","mis":"M4-2-u1-X02"},{"t":"⟨4/4⟩","mis":"M4-2-u1-X02"}],"explanation":["대분수는 자연수와 진분수로 이루어진 분수예요.","⟨1 1/2⟩은 자연수 1과 진분수 ⟨1/2⟩로 이루어졌어요.","⟨7/8⟩은 진분수, ⟨7/5⟩과 ⟨4/4⟩는 가분수예요."],"variant_rule":{"alt":[{"stem":"「준비하기」 다음 중 가분수는 무엇인가요?","options":[{"t":"⟨7/5⟩","correct":true},{"t":"⟨2/3⟩","mis":"M4-2-u1-X02"},{"t":"⟨5 6/7⟩","mis":"M4-2-u1-X02"},{"t":"⟨7/8⟩","mis":"M4-2-u1-X02"}],"explanation":["가분수는 분자가 분모와 같거나 분모보다 큰 분수예요.","⟨7/5⟩은 분자 7이 분모 5보다 커요.","⟨2/3⟩와 ⟨7/8⟩은 진분수, ⟨5 6/7⟩은 대분수예요."]},{"stem":"「준비하기」 다음 중 진분수는 무엇인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨4/4⟩","mis":"M4-2-u1-X02"},{"t":"⟨7/5⟩","mis":"M4-2-u1-X02"},{"t":"⟨1 1/2⟩","mis":"M4-2-u1-X02"}],"explanation":["진분수는 분자가 분모보다 작은 분수예요.","⟨2/3⟩는 분자 2가 분모 3보다 작아요.","⟨4/4⟩와 ⟨7/5⟩은 가분수, ⟨1 1/2⟩은 대분수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L02_basic#5','math',4,2,'u1','L02','tb_g4_2_math_u1_L02_basic','lesson_basic','M4-2-u1-C1',2,'mc','auto','「익힘」 ⟨9/7⟩를 대분수로 나타내면 무엇인가요?',ARRAY['M4-2-u1-X04','M4-2-u1-X16','M4-2-u1-X02']::text[],true,'{"seq":5,"concept":"M4-2-u1-C1","difficulty":2,"kind":"mc","stem":"「익힘」 ⟨9/7⟩를 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨1 2/7⟩","correct":true},{"t":"⟨2 2/7⟩","mis":"M4-2-u1-X04"},{"t":"⟨1 3/7⟩","mis":"M4-2-u1-X16"},{"t":"⟨2 1/7⟩","mis":"M4-2-u1-X02"}],"explanation":["⟨9/7⟩는 ⟨1/7⟩이 9개예요.","⟨1/7⟩이 7개 모이면 1 — 7개씩 모으면 1이 1번, 2개가 남아요.","⟨9/7⟩ = ⟨1 2/7⟩."],"variant_rule":{"alt":[{"stem":"「익힘」 ⟨1 5/6⟩를 가분수로 나타내면 무엇인가요?","options":[{"t":"⟨11/6⟩","correct":true},{"t":"⟨6/6⟩","mis":"M4-2-u1-X03"},{"t":"⟨12/6⟩","mis":"M4-2-u1-X16"},{"t":"⟨10/6⟩","mis":"M4-2-u1-X16"}],"explanation":["자연수 1은 ⟨1/6⟩이 1 × 6 = 6개예요.","분수 부분 ⟨5/6⟩는 ⟨1/6⟩이 5개예요.","6 + 5 = 11 — ⟨1 5/6⟩ = ⟨11/6⟩."]},{"stem":"「익힘」 ⟨3 2/9⟩를 가분수로 나타내면 무엇인가요?","options":[{"t":"⟨29/9⟩","correct":true},{"t":"⟨5/9⟩","mis":"M4-2-u1-X03"},{"t":"⟨30/9⟩","mis":"M4-2-u1-X16"},{"t":"⟨28/9⟩","mis":"M4-2-u1-X16"}],"explanation":["자연수 3은 ⟨1/9⟩이 3 × 9 = 27개예요.","분수 부분 ⟨2/9⟩는 ⟨1/9⟩이 2개예요.","27 + 2 = 29 — ⟨3 2/9⟩ = ⟨29/9⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L02_basic#6','math',4,2,'u1','L02','tb_g4_2_math_u1_L02_basic','lesson_basic','M4-2-u1-C2',2,'match','auto','「익힘」 모았을 때 1이 되는 것끼리 알맞게 이으세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u1-C2","difficulty":2,"kind":"match","stem":"「익힘」 모았을 때 1이 되는 것끼리 알맞게 이으세요.","pairs":[{"l":"⟨5/6⟩","r":"⟨1/6⟩"},{"l":"⟨2/6⟩","r":"⟨4/6⟩"},{"l":"⟨3/6⟩","r":"⟨3/6⟩"}],"mis":"M4-2-u1-X06","explanation":["1 = ⟨6/6⟩ — ⟨1/6⟩이 모두 6개가 되게 짝을 찾아요.","⟨5/6⟩ + ⟨1/6⟩ = ⟨6/6⟩, ⟨2/6⟩ + ⟨4/6⟩ = ⟨6/6⟩이에요.","⟨3/6⟩ + ⟨3/6⟩ = ⟨6/6⟩ = 1 — 같은 분수끼리도 짝이 돼요."],"variant_rule":{"alt":[{"stem":"모았을 때 1이 되는 것끼리 알맞게 이으세요.","pairs":[{"l":"⟨4/5⟩","r":"⟨1/5⟩"},{"l":"⟨2/5⟩","r":"⟨3/5⟩"},{"l":"⟨3/5⟩","r":"⟨2/5⟩"}],"explanation":["1 = ⟨5/5⟩ — ⟨1/5⟩이 모두 5개가 되게 짝을 찾아요.","⟨4/5⟩ + ⟨1/5⟩ = ⟨5/5⟩예요.","⟨2/5⟩ + ⟨3/5⟩ = ⟨5/5⟩ = 1이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L02_basic#7','math',4,2,'u1','L02','tb_g4_2_math_u1_L02_basic','lesson_basic','M4-2-u1-C2',2,'ox','auto','지유는 「⟨1/3⟩이 1개인 분수와 ⟨1/3⟩이 2개인 분수를 모으면 1이 돼.」라고 했어요. 지유의 말이 옳은가요?',ARRAY['M4-2-u1-X01']::text[],false,'{"seq":7,"concept":"M4-2-u1-C2","difficulty":2,"kind":"ox","stem":"지유는 「⟨1/3⟩이 1개인 분수와 ⟨1/3⟩이 2개인 분수를 모으면 1이 돼.」라고 했어요. 지유의 말이 옳은가요?","answer":"O","reason_options":[{"t":"⟨1/3⟩이 1 + 2 = 3개면 ⟨3/3⟩ = 1이라서","correct":true},{"t":"분모 3과 3을 더해 6이 되어서","mis":"M4-2-u1-X01"}],"mis":"M4-2-u1-X01","explanation":["⟨1/3⟩이 1개인 분수는 ⟨1/3⟩, 2개인 분수는 ⟨2/3⟩예요.","⟨1/3⟩ + ⟨2/3⟩ = ⟨3/3⟩ = 1이에요.","지유의 말이 옳아요 — 분모는 더하지 않아요."],"asset":{"type":"fbar","bars":[{"den":3,"num":1},{"den":3,"num":2}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L02_basic#8','math',4,2,'u1','L02','tb_g4_2_math_u1_L02_basic','lesson_basic','M4-2-u1-C2',2,'sa','auto','「확인 문제」 ⟨4/5⟩ + ⟨□/5⟩ = 1 — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u1-C2","difficulty":2,"kind":"sa","stem":"「확인 문제」 ⟨4/5⟩ + ⟨□/5⟩ = 1 — □에 알맞은 수를 쓰세요.","answer":["1"],"explanation":["1 = ⟨5/5⟩ — ⟨1/5⟩이 5개예요.","⟨4/5⟩는 ⟨1/5⟩이 4개라 5 − 4 = 1개가 더 있어야 해요.","⟨4/5⟩ + ⟨1/5⟩ = 1 — □ = 1."],"variant_rule":{"alt":[{"stem":"「확인 문제」 1 = ⟨3/5⟩ + ⟨□/5⟩ — □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["1 = ⟨5/5⟩ — ⟨1/5⟩이 5개예요.","⟨3/5⟩은 ⟨1/5⟩이 3개라 5 − 3 = 2개가 남아요.","1 = ⟨3/5⟩ + ⟨2/5⟩ — □ = 2."]},{"stem":"1 = ⟨2/6⟩ + ⟨□/6⟩ — □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["1 = ⟨6/6⟩ — ⟨1/6⟩이 6개예요.","⟨2/6⟩는 ⟨1/6⟩이 2개라 6 − 2 = 4개가 남아요.","1 = ⟨2/6⟩ + ⟨4/6⟩ — □ = 4."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L02_basic#9','math',4,2,'u1','L02','tb_g4_2_math_u1_L02_basic','lesson_basic','M4-2-u1-C1',2,'mc','auto','「익힘」 두 분수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨11/6⟩ ○ ⟨7/6⟩',ARRAY['M4-2-u1-X02','M4-2-u1-X18']::text[],true,'{"seq":9,"concept":"M4-2-u1-C1","difficulty":2,"kind":"mc","stem":"「익힘」 두 분수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨11/6⟩ ○ ⟨7/6⟩","options":[{"t":">","correct":true},{"t":"<","mis":"M4-2-u1-X02"},{"t":"=","mis":"M4-2-u1-X18"},{"t":"알 수 없어요","mis":"M4-2-u1-X18"}],"explanation":["분모가 같은 가분수는 분자가 클수록 커요.","⟨1/6⟩이 11개와 7개 — 11 > 7이에요.","⟨11/6⟩ > ⟨7/6⟩."],"variant_rule":{"alt":[{"stem":"「익힘」 두 분수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨2 3/5⟩ ○ ⟨3 1/5⟩","options":[{"t":"<","correct":true},{"t":">","mis":"M4-2-u1-X02"},{"t":"=","mis":"M4-2-u1-X18"},{"t":"알 수 없어요","mis":"M4-2-u1-X18"}],"explanation":["대분수는 자연수 부분부터 견주어요.","자연수 2 < 3이에요.","⟨2 3/5⟩ < ⟨3 1/5⟩."]},{"stem":"「익힘」 두 분수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨17/7⟩ ○ ⟨3 1/7⟩","options":[{"t":"<","correct":true},{"t":">","mis":"M4-2-u1-X02"},{"t":"=","mis":"M4-2-u1-X18"},{"t":"알 수 없어요","mis":"M4-2-u1-X18"}],"explanation":["⟨3 1/7⟩을 가분수로 바꾸면 ⟨3 1/7⟩ = ⟨22/7⟩예요.","⟨1/7⟩의 개수로 견주면 17 < 22예요.","⟨17/7⟩ < ⟨3 1/7⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L02_basic#10','math',4,2,'u1','L02','tb_g4_2_math_u1_L02_basic','lesson_basic','M4-2-u1-C2',3,'mc','auto','「지도서」 대분수를 계산할 때 자연수 1을 분수로 나타내야 할 때가 있어요. ⟨1 5/9⟩의 자연수 1은 어떤 분수로 나타내야 하나요?',ARRAY['M4-2-u1-X03','M4-2-u1-X05']::text[],true,'{"seq":10,"concept":"M4-2-u1-C2","difficulty":3,"kind":"mc","stem":"「지도서」 대분수를 계산할 때 자연수 1을 분수로 나타내야 할 때가 있어요. ⟨1 5/9⟩의 자연수 1은 어떤 분수로 나타내야 하나요?","options":[{"t":"⟨9/9⟩","correct":true},{"t":"⟨5/9⟩","mis":"M4-2-u1-X03"},{"t":"⟨1/9⟩","mis":"M4-2-u1-X05"},{"t":"⟨4/4⟩","mis":"M4-2-u1-X05"}],"explanation":["⟨1 5/9⟩에서 단위가 되는 분수는 ⟨1/9⟩이에요.","1은 ⟨1/9⟩이 9개 — 1 = ⟨9/9⟩예요.","⟨4/4⟩도 1이지만 ⟨5/9⟩와 함께 계산하려면 단위분수 ⟨1/9⟩로 센 ⟨9/9⟩로 나타내요."],"variant_rule":{"alt":[{"stem":"「지도서」 대분수를 계산할 때 자연수 1을 분수로 나타내야 할 때가 있어요. ⟨1 1/4⟩의 자연수 1은 어떤 분수로 나타내야 하나요?","options":[{"t":"⟨4/4⟩","correct":true},{"t":"⟨1/4⟩","mis":"M4-2-u1-X05"},{"t":"⟨2/4⟩","mis":"M4-2-u1-X03"},{"t":"⟨9/9⟩","mis":"M4-2-u1-X05"}],"explanation":["⟨1 1/4⟩에서 단위가 되는 분수는 ⟨1/4⟩이에요.","1은 ⟨1/4⟩이 4개 — 1 = ⟨4/4⟩예요.","⟨9/9⟩도 1이지만 ⟨1/4⟩과 함께 계산하려면 ⟨4/4⟩로 나타내요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L02_challenge#1','math',4,2,'u1','L02','tb_g4_2_math_u1_L02_challenge','lesson_challenge','M4-2-u1-C1',2,'sa','auto','「단원 도입」 사과 상자에 ⟨1 3/4⟩ kg이라고 쓰여 있어요. ⟨1 3/4⟩은 ⟨1/4⟩이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u1-C1","difficulty":2,"kind":"sa","stem":"「단원 도입」 사과 상자에 ⟨1 3/4⟩ kg이라고 쓰여 있어요. ⟨1 3/4⟩은 ⟨1/4⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["1은 ⟨1/4⟩이 4개 — 자연수 1은 1 × 4 = 4개예요.","⟨3/4⟩은 ⟨1/4⟩이 3개예요.","모두 4 + 3 = 7개 — ⟨1 3/4⟩ = ⟨7/4⟩."],"variant_rule":{"alt":[{"stem":"「단원 도입」 사과 상자에 ⟨2 2/4⟩ kg이라고 쓰여 있어요. ⟨2 2/4⟩는 ⟨1/4⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["1은 ⟨1/4⟩이 4개 — 자연수 2는 2 × 4 = 8개예요.","⟨2/4⟩는 ⟨1/4⟩이 2개예요.","모두 8 + 2 = 10개 — ⟨2 2/4⟩ = ⟨10/4⟩."]},{"stem":"「익힘」 ⟨3 2/9⟩는 ⟨1/9⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["29"],"explanation":["1은 ⟨1/9⟩이 9개 — 자연수 3은 3 × 9 = 27개예요.","⟨2/9⟩는 ⟨1/9⟩이 2개예요.","모두 27 + 2 = 29개 — ⟨3 2/9⟩ = ⟨29/9⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L02_challenge#2','math',4,2,'u1','L02','tb_g4_2_math_u1_L02_challenge','lesson_challenge','M4-2-u1-C2',2,'sa','auto','「익힘 퐁당」 1을 ⟨3/4⟩과 ⟨1/4⟩로 가른 뒤, ⟨3/4⟩을 다시 단위분수로 갈랐어요. ⟨3/4⟩은 ⟨1/4⟩ 몇 개로 갈라지나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u1-C2","difficulty":2,"kind":"sa","stem":"「익힘 퐁당」 1을 ⟨3/4⟩과 ⟨1/4⟩로 가른 뒤, ⟨3/4⟩을 다시 단위분수로 갈랐어요. ⟨3/4⟩은 ⟨1/4⟩ 몇 개로 갈라지나요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨3/4⟩은 ⟨1/4⟩이 3개인 분수예요.","그래서 ⟨3/4⟩ = ⟨1/4⟩ + ⟨1/4⟩ + ⟨1/4⟩ — 3개로 갈라져요.","1은 ⟨1/4⟩이 모두 4개 — 1 = ⟨4/4⟩예요."],"asset":{"type":"fbar","bars":[{"den":4,"num":3,"label":"1을 가르기"}]},"variant_rule":{"alt":[{"stem":"「익힘 퐁당」 1을 ⟨2/5⟩와 ⟨3/5⟩으로 가른 뒤, 두 분수를 모두 단위분수로 갈랐어요. 단위분수 ⟨1/5⟩은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["⟨2/5⟩는 ⟨1/5⟩이 2개, ⟨3/5⟩은 ⟨1/5⟩이 3개예요.","2 + 3 = 5 — ⟨1/5⟩이 5개예요.","1 = ⟨5/5⟩ — 1은 ⟨1/5⟩이 5개예요."],"asset":{"type":"fbar","bars":[{"den":5,"num":2,"label":"1을 가르기"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L02_challenge#3','math',4,2,'u1','L02','tb_g4_2_math_u1_L02_challenge','lesson_challenge','M4-2-u1-C2',3,'error','auto','분수 띠로 1을 가르고 모으는 활동을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X15']::text[],true,'{"seq":3,"concept":"M4-2-u1-C2","difficulty":3,"kind":"error","stem":"분수 띠로 1을 가르고 모으는 활동을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"건우 — 「⟨1/5⟩과 ⟨4/5⟩를 모으면 ⟨5/10⟩야.」","correct":true,"mis_target":"M4-2-u1-X01"},{"t":"서준 — 「1 = ⟨4/4⟩야.」","mis":"M4-2-u1-X15"},{"t":"채원 — 「⟨1/3⟩과 ⟨2/3⟩를 모으면 1이야.」","mis":"M4-2-u1-X15"},{"t":"지유 — 「1은 ⟨3/6⟩과 ⟨3/6⟩으로 가를 수 있어.」","mis":"M4-2-u1-X15"}],"explanation":["분모가 같은 분수를 모을 때는 단위분수의 개수만 세어요.","⟨1/5⟩ + ⟨4/5⟩ = ⟨5/5⟩ = 1이에요.","건우는 분모끼리도 더했어요 — 분모는 그대로예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 분수 띠로 1을 가르고 모으는 활동을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「1을 분모가 8인 분수로 나타내면 ⟨1/8⟩이야.」","correct":true,"mis_target":"M4-2-u1-X05"},{"t":"서준 — 「1 = ⟨4/4⟩야.」","mis":"M4-2-u1-X15"},{"t":"채원 — 「⟨1/3⟩과 ⟨2/3⟩를 모으면 1이야.」","mis":"M4-2-u1-X15"},{"t":"지유 — 「1은 ⟨3/6⟩과 ⟨3/6⟩으로 가를 수 있어.」","mis":"M4-2-u1-X15"}],"explanation":["1은 분모와 분자가 같은 분수로 나타내요.","분모가 8이면 1 = ⟨8/8⟩이에요.","⟨1/8⟩은 1을 8칸으로 나눈 한 칸일 뿐이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L02_challenge#4','math',4,2,'u1','L02','tb_g4_2_math_u1_L02_challenge','lesson_challenge','M4-2-u1-C2',3,'sa','auto','분수 띠로 1을 분모가 6인 진분수 두 개로 가르려고 해요. 순서만 바꾼 것은 한 가지로 셀 때, 가르는 방법은 모두 몇 가지인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u1-C2","difficulty":3,"kind":"sa","stem":"분수 띠로 1을 분모가 6인 진분수 두 개로 가르려고 해요. 순서만 바꾼 것은 한 가지로 셀 때, 가르는 방법은 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["1 = ⟨6/6⟩ — 두 분수의 분자의 합이 6이 되게 갈라요.","⟨1/6⟩과 ⟨5/6⟩, ⟨2/6⟩와 ⟨4/6⟩, ⟨3/6⟩과 ⟨3/6⟩이에요.","순서만 바꾼 것은 한 가지로 세면 모두 3가지예요."],"variant_rule":{"alt":[{"stem":"분수 띠로 1을 분모가 5인 진분수 두 개로 가르려고 해요. 순서만 바꾼 것은 한 가지로 셀 때, 가르는 방법은 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["1 = ⟨5/5⟩ — 두 분수의 분자의 합이 5가 되게 갈라요.","⟨1/5⟩과 ⟨4/5⟩, ⟨2/5⟩와 ⟨3/5⟩이에요.","순서만 바꾼 것은 한 가지로 세면 모두 2가지예요."]},{"stem":"분수 띠로 1을 분모가 4인 진분수 두 개로 가르려고 해요. 순서만 바꾼 것은 한 가지로 셀 때, 가르는 방법은 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["1 = ⟨4/4⟩ — 두 분수의 분자의 합이 4가 되게 갈라요.","⟨1/4⟩과 ⟨3/4⟩, ⟨2/4⟩와 ⟨2/4⟩예요.","순서만 바꾼 것은 한 가지로 세면 모두 2가지예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L02_challenge#5','math',4,2,'u1','L02','tb_g4_2_math_u1_L02_challenge','lesson_challenge','M4-2-u1-C1',3,'mc','auto','「익힘」 분모가 5인 분수를 수직선에 나타냈어요. ⟨8/5⟩은 어느 두 자연수 사이에 있나요?',ARRAY['M4-2-u1-X04','M4-2-u1-X02']::text[],true,'{"seq":5,"concept":"M4-2-u1-C1","difficulty":3,"kind":"mc","stem":"「익힘」 분모가 5인 분수를 수직선에 나타냈어요. ⟨8/5⟩은 어느 두 자연수 사이에 있나요?","options":[{"t":"1과 2 사이","correct":true},{"t":"2와 3 사이","mis":"M4-2-u1-X04"},{"t":"0과 1 사이","mis":"M4-2-u1-X02"},{"t":"8과 9 사이","mis":"M4-2-u1-X02"}],"explanation":["1 = ⟨5/5⟩, 2 = ⟨10/5⟩이에요.","⟨8/5⟩은 ⟨5/5⟩보다 크고 ⟨10/5⟩보다 작아요.","⟨8/5⟩ = ⟨1 3/5⟩ — 1과 2 사이에 있어요."],"asset":{"type":"number_line","cells":["0","1","2","3"]},"variant_rule":{"alt":[{"stem":"「익힘」 분모가 5인 분수를 수직선에 나타냈어요. ⟨2 2/5⟩는 어느 두 자연수 사이에 있나요?","options":[{"t":"2와 3 사이","correct":true},{"t":"1과 2 사이","mis":"M4-2-u1-X02"},{"t":"3과 4 사이","mis":"M4-2-u1-X04"},{"t":"0과 1 사이","mis":"M4-2-u1-X02"}],"explanation":["⟨2 2/5⟩는 자연수 2와 진분수 ⟨2/5⟩로 이루어졌어요.","2보다 ⟨2/5⟩만큼 더 크고 3보다는 작아요.","⟨2 2/5⟩ = ⟨12/5⟩ — 2와 3 사이에 있어요."],"asset":{"type":"number_line","cells":["0","1","2","3"]}},{"stem":"「익힘」 분모가 5인 분수를 수직선에 나타냈어요. ⟨3/5⟩은 어느 두 자연수 사이에 있나요?","options":[{"t":"0과 1 사이","correct":true},{"t":"1과 2 사이","mis":"M4-2-u1-X02"},{"t":"3과 4 사이","mis":"M4-2-u1-X02"},{"t":"2와 3 사이","mis":"M4-2-u1-X02"}],"explanation":["⟨3/5⟩은 진분수 — 1보다 작아요.","1 = ⟨5/5⟩이고 ⟨3/5⟩은 ⟨1/5⟩이 3개예요.","⟨3/5⟩ < 1 — 0과 1 사이에 있어요."],"asset":{"type":"number_line","cells":["0","1","2","3"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L02_challenge#6','math',4,2,'u1','L02','tb_g4_2_math_u1_L02_challenge','lesson_challenge','M4-2-u1-C2',3,'ox','auto','지유는 「1은 언제나 ⟨4/4⟩로만 나타낼 수 있어.」라고 했어요. 지유의 말이 옳은가요?',ARRAY['M4-2-u1-X05']::text[],false,'{"seq":6,"concept":"M4-2-u1-C2","difficulty":3,"kind":"ox","stem":"지유는 「1은 언제나 ⟨4/4⟩로만 나타낼 수 있어.」라고 했어요. 지유의 말이 옳은가요?","answer":"X","reason_options":[{"t":"1을 몇 칸으로 나누느냐에 따라 ⟨9/9⟩처럼 다르게 나타내서","correct":true},{"t":"1을 나타내는 분수는 하나뿐이라서","mis":"M4-2-u1-X05"}],"mis":"M4-2-u1-X05","explanation":["1은 나누기 전의 전체예요.","⟨1/4⟩이 단위면 1 = ⟨4/4⟩, ⟨1/9⟩이 단위면 1 = ⟨9/9⟩예요.","분모와 분자가 같은 분수는 모두 1이에요 — 지유의 말은 틀렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L02_challenge#7','math',4,2,'u1','L02','tb_g4_2_math_u1_L02_challenge','lesson_challenge','M4-2-u1-C2',3,'mc','auto','「익힘」 ⟨5/6⟩와 모아서 1이 되는 분수는 무엇인가요?',ARRAY['M4-2-u1-X06','M4-2-u1-X16']::text[],true,'{"seq":7,"concept":"M4-2-u1-C2","difficulty":3,"kind":"mc","stem":"「익힘」 ⟨5/6⟩와 모아서 1이 되는 분수는 무엇인가요?","options":[{"t":"⟨1/6⟩","correct":true},{"t":"⟨5/6⟩","mis":"M4-2-u1-X06"},{"t":"⟨6/5⟩","mis":"M4-2-u1-X06"},{"t":"⟨2/6⟩","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨6/6⟩ — ⟨1/6⟩이 6개예요.","⟨5/6⟩는 ⟨1/6⟩이 5개라 6 − 5 = 1개가 모자라요.","⟨5/6⟩ + ⟨1/6⟩ = ⟨6/6⟩ = 1이에요."],"variant_rule":{"alt":[{"stem":"「익힘」 ⟨2/6⟩와 모아서 1이 되는 분수는 무엇인가요?","options":[{"t":"⟨4/6⟩","correct":true},{"t":"⟨2/6⟩","mis":"M4-2-u1-X06"},{"t":"⟨6/2⟩","mis":"M4-2-u1-X06"},{"t":"⟨5/6⟩","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨6/6⟩ — ⟨1/6⟩이 6개예요.","⟨2/6⟩는 ⟨1/6⟩이 2개라 6 − 2 = 4개가 모자라요.","⟨2/6⟩ + ⟨4/6⟩ = ⟨6/6⟩ = 1이에요."]},{"stem":"「익힘」 ⟨4/5⟩와 모아서 1이 되는 분수는 무엇인가요?","options":[{"t":"⟨1/5⟩","correct":true},{"t":"⟨4/5⟩","mis":"M4-2-u1-X06"},{"t":"⟨5/4⟩","mis":"M4-2-u1-X06"},{"t":"⟨2/5⟩","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨5/5⟩ — ⟨1/5⟩이 5개예요.","⟨4/5⟩는 ⟨1/5⟩이 4개라 5 − 4 = 1개가 모자라요.","⟨4/5⟩ + ⟨1/5⟩ = ⟨5/5⟩ = 1이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L02_challenge#8','math',4,2,'u1','L02','tb_g4_2_math_u1_L02_challenge','lesson_challenge','M4-2-u1-C2',4,'essay','teacher','「지도서」 자연수 1은 모두 같은데, ⟨1 1/4⟩을 계산할 때는 1 = ⟨4/4⟩로, ⟨1 5/9⟩를 계산할 때는 1 = ⟨9/9⟩로 나타내요. 1을 나타내는 분수가 다른 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u1-C2","difficulty":4,"kind":"essay","stem":"「지도서」 자연수 1은 모두 같은데, ⟨1 1/4⟩을 계산할 때는 1 = ⟨4/4⟩로, ⟨1 5/9⟩를 계산할 때는 1 = ⟨9/9⟩로 나타내요. 1을 나타내는 분수가 다른 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 1은 나누기 전의 전체이다. ⟨1 1/4⟩에서는 ⟨1/4⟩이 단위가 되므로 1을 ⟨1/4⟩ 4개인 ⟨4/4⟩로 나타내고, ⟨1 5/9⟩에서는 ⟨1/9⟩이 단위가 되므로 1을 ⟨1/9⟩ 9개인 ⟨9/9⟩로 나타낸다. 전체를 몇 개로 똑같이 나누었는지에 따라 1을 나타내는 분수가 달라진다.","scoring_points":["1은 나누기 전의 전체라고 썼는가","단위가 되는 분수(⟨1/4⟩·⟨1/9⟩)를 찾아 썼는가","똑같이 나눈 개수에 따라 분수가 달라진다고 설명했는가"]},"explanation":["1 = ⟨4/4⟩ = ⟨9/9⟩예요.","단위분수가 ⟨1/4⟩이면 4개, ⟨1/9⟩이면 9개가 1이에요.","함께 계산하는 분수의 분모에 맞추어 1을 나타내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L02_challenge#9','math',4,2,'u1','L02','tb_g4_2_math_u1_L02_challenge','lesson_challenge','M4-2-u1-C1',4,'essay','teacher','「지도서 오류」 한 친구가 「5 + ⟨5/9⟩ = ⟨10/9⟩」이라고 계산했어요. 이 계산이 틀린 까닭을 대분수나 단위분수를 써서 설명하고, 바르게 계산해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u1-C1","difficulty":4,"kind":"essay","stem":"「지도서 오류」 한 친구가 「5 + ⟨5/9⟩ = ⟨10/9⟩」이라고 계산했어요. 이 계산이 틀린 까닭을 대분수나 단위분수를 써서 설명하고, 바르게 계산해 보세요.","answer_guide":{"answer":"예: 5 + ⟨5/9⟩는 자연수 5와 진분수 ⟨5/9⟩로 이루어진 대분수 ⟨5 5/9⟩이므로 5보다 큰 수이다. 그런데 ⟨10/9⟩ = ⟨1 1/9⟩은 1보다 조금 큰 수이므로 두 수는 같을 수 없다. 5는 ⟨1/9⟩이 45개인 ⟨45/9⟩이므로 ⟨45/9⟩ + ⟨5/9⟩ = ⟨50/9⟩ = ⟨5 5/9⟩이다.","scoring_points":["5 + ⟨5/9⟩ = ⟨5 5/9⟩이라고 썼는가","⟨10/9⟩은 1보다 조금 큰 수라 같을 수 없다고 설명했는가","자연수 5를 ⟨45/9⟩로 바꾸어 바르게 계산했는가"]},"explanation":["5 = ⟨45/9⟩예요.","⟨45/9⟩ + ⟨5/9⟩ = ⟨50/9⟩ = ⟨5 5/9⟩예요.","자연수를 분자에 그대로 더하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L02_challenge#10','math',4,2,'u1','L02','tb_g4_2_math_u1_L02_challenge','lesson_challenge','M4-2-u1-C2',4,'essay','teacher','1을 분모가 6인 진분수 두 개로 가르는 방법을 모두 쓰고, 두 분수의 분자의 합이 언제나 6이 되는 까닭을 설명해 보세요(순서만 바꾼 것은 한 가지로 세요).','{}'::text[],false,'{"seq":10,"concept":"M4-2-u1-C2","difficulty":4,"kind":"essay","stem":"1을 분모가 6인 진분수 두 개로 가르는 방법을 모두 쓰고, 두 분수의 분자의 합이 언제나 6이 되는 까닭을 설명해 보세요(순서만 바꾼 것은 한 가지로 세요).","answer_guide":{"answer":"예: ⟨1/6⟩과 ⟨5/6⟩, ⟨2/6⟩와 ⟨4/6⟩, ⟨3/6⟩과 ⟨3/6⟩ — 3가지이다. 1 = ⟨6/6⟩이고 1은 ⟨1/6⟩이 6개이므로 두 분수의 ⟨1/6⟩ 개수를 합하면 6이 되어야 한다.","scoring_points":["세 가지를 모두 썼는가","1 = ⟨6/6⟩이라고 썼는가","⟨1/6⟩의 개수의 합이 6이라고 설명했는가"]},"explanation":["1 = ⟨6/6⟩이에요.","1 + 5, 2 + 4, 3 + 3 — 분자의 합이 6이에요.","모두 3가지예요."],"asset":{"type":"fbar","bars":[{"den":6,"num":6}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L03_basic#1','math',4,2,'u1','L03','tb_g4_2_math_u1_L03_basic','lesson_basic','M4-2-u1-C3',1,'sa','auto','⟨2/6⟩ + ⟨3/6⟩ = ⟨□/6⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u1-C3","difficulty":1,"kind":"sa","stem":"⟨2/6⟩ + ⟨3/6⟩ = ⟨□/6⟩ — □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["⟨2/6⟩는 ⟨1/6⟩이 2개, ⟨3/6⟩은 ⟨1/6⟩이 3개예요.","⟨2/6⟩ + ⟨3/6⟩ = ⟨5/6⟩ — 분모는 그대로 두고 분자끼리 더해요.","분모끼리 더한 ⟨5/12⟩는 답이 아니에요 — 답은 ⟨5/6⟩."],"asset":{"type":"fbar","bars":[{"den":6,"num":2},{"den":6,"num":3}]},"variant_rule":{"alt":[{"stem":"「익힘」 ⟨2/5⟩ + ⟨1/5⟩ = ⟨□/5⟩ — □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["⟨2/5⟩는 ⟨1/5⟩이 2개, ⟨1/5⟩은 ⟨1/5⟩이 1개예요.","⟨2/5⟩ + ⟨1/5⟩ = ⟨3/5⟩ — 분모는 그대로 두고 분자끼리 더해요.","분모끼리 더한 ⟨3/10⟩은 답이 아니에요 — 답은 ⟨3/5⟩."],"asset":{"type":"fbar","bars":[{"den":5,"num":2},{"den":5,"num":1}]}},{"stem":"⟨4/7⟩ + ⟨2/7⟩ = ⟨□/7⟩ — □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["⟨4/7⟩는 ⟨1/7⟩이 4개, ⟨2/7⟩는 ⟨1/7⟩이 2개예요.","⟨4/7⟩ + ⟨2/7⟩ = ⟨6/7⟩ — 분모는 그대로 두고 분자끼리 더해요.","분모끼리 더한 ⟨6/14⟩은 답이 아니에요 — 답은 ⟨6/7⟩."],"asset":{"type":"fbar","bars":[{"den":7,"num":4},{"den":7,"num":2}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L03_basic#2','math',4,2,'u1','L03','tb_g4_2_math_u1_L03_basic','lesson_basic','M4-2-u1-C3',1,'mc','auto','⟨4/10⟩ + ⟨5/10⟩를 계산해 보세요.',ARRAY['M4-2-u1-X01','M4-2-u1-X16']::text[],true,'{"seq":2,"concept":"M4-2-u1-C3","difficulty":1,"kind":"mc","stem":"⟨4/10⟩ + ⟨5/10⟩를 계산해 보세요.","options":[{"t":"⟨9/10⟩","correct":true},{"t":"⟨9/20⟩","mis":"M4-2-u1-X01"},{"t":"1","mis":"M4-2-u1-X16"},{"t":"⟨8/10⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨4/10⟩는 ⟨1/10⟩이 4개, ⟨5/10⟩는 ⟨1/10⟩이 5개예요.","⟨4/10⟩ + ⟨5/10⟩ = ⟨9/10⟩ — 분모는 그대로 두고 분자끼리 더해요.","분모끼리 더한 ⟨9/20⟩는 답이 아니에요 — 답은 ⟨9/10⟩."],"variant_rule":{"alt":[{"stem":"「익힘」 ⟨2/9⟩ + ⟨5/9⟩를 계산해 보세요.","options":[{"t":"⟨7/9⟩","correct":true},{"t":"⟨7/18⟩","mis":"M4-2-u1-X01"},{"t":"⟨8/9⟩","mis":"M4-2-u1-X16"},{"t":"⟨6/9⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨2/9⟩는 ⟨1/9⟩이 2개, ⟨5/9⟩는 ⟨1/9⟩이 5개예요.","⟨2/9⟩ + ⟨5/9⟩ = ⟨7/9⟩ — 분모는 그대로 두고 분자끼리 더해요.","분모끼리 더한 ⟨7/18⟩은 답이 아니에요 — 답은 ⟨7/9⟩."]},{"stem":"「익힘」 ⟨4/11⟩ + ⟨6/11⟩을 계산해 보세요.","options":[{"t":"⟨10/11⟩","correct":true},{"t":"⟨10/22⟩","mis":"M4-2-u1-X01"},{"t":"1","mis":"M4-2-u1-X16"},{"t":"⟨9/11⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨4/11⟩는 ⟨1/11⟩이 4개, ⟨6/11⟩은 ⟨1/11⟩이 6개예요.","⟨4/11⟩ + ⟨6/11⟩ = ⟨10/11⟩ — 분모는 그대로 두고 분자끼리 더해요.","분모끼리 더한 ⟨10/22⟩은 답이 아니에요 — 답은 ⟨10/11⟩."]},{"stem":"「확인 문제」 ⟨4/8⟩ + ⟨3/8⟩을 계산해 보세요.","options":[{"t":"⟨7/8⟩","correct":true},{"t":"⟨7/16⟩","mis":"M4-2-u1-X01"},{"t":"1","mis":"M4-2-u1-X16"},{"t":"⟨6/8⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨4/8⟩는 ⟨1/8⟩이 4개, ⟨3/8⟩은 ⟨1/8⟩이 3개예요.","⟨4/8⟩ + ⟨3/8⟩ = ⟨7/8⟩ — 분모는 그대로 두고 분자끼리 더해요.","분모끼리 더한 ⟨7/16⟩은 답이 아니에요 — 답은 ⟨7/8⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L03_basic#3','math',4,2,'u1','L03','tb_g4_2_math_u1_L03_basic','lesson_basic','M4-2-u1-C3',1,'mc','auto','⟨3/4⟩ + ⟨2/4⟩를 계산하여 대분수로 나타내면 얼마인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X04']::text[],true,'{"seq":3,"concept":"M4-2-u1-C3","difficulty":1,"kind":"mc","stem":"⟨3/4⟩ + ⟨2/4⟩를 계산하여 대분수로 나타내면 얼마인가요?","options":[{"t":"⟨1 1/4⟩","correct":true},{"t":"⟨5/8⟩","mis":"M4-2-u1-X01"},{"t":"⟨1/4⟩","mis":"M4-2-u1-X04"},{"t":"⟨2 1/4⟩","mis":"M4-2-u1-X04"}],"explanation":["⟨3/4⟩은 ⟨1/4⟩이 3개, ⟨2/4⟩는 ⟨1/4⟩이 2개예요.","⟨3/4⟩ + ⟨2/4⟩ = ⟨5/4⟩ — 분모는 그대로 두고 분자끼리 더해요.","⟨5/4⟩ = ⟨1 1/4⟩ — 분모끼리 더하지 않아요."],"asset":{"type":"fbar","bars":[{"den":4,"num":3},{"den":4,"num":2}]},"variant_rule":{"alt":[{"stem":"⟨7/9⟩ + ⟨5/9⟩를 계산하여 대분수로 나타내면 얼마인가요?","options":[{"t":"⟨1 3/9⟩","correct":true},{"t":"⟨12/18⟩","mis":"M4-2-u1-X01"},{"t":"⟨3/9⟩","mis":"M4-2-u1-X04"},{"t":"⟨2 3/9⟩","mis":"M4-2-u1-X04"}],"explanation":["⟨7/9⟩은 ⟨1/9⟩이 7개, ⟨5/9⟩는 ⟨1/9⟩이 5개예요.","⟨7/9⟩ + ⟨5/9⟩ = ⟨12/9⟩ — 분모는 그대로 두고 분자끼리 더해요.","⟨12/9⟩ = ⟨1 3/9⟩ — 분모끼리 더하지 않아요."],"asset":{"type":"fbar","bars":[{"den":9,"num":7},{"den":9,"num":5}]}},{"stem":"「익힘」 ⟨5/7⟩ + ⟨4/7⟩를 계산하여 대분수로 나타내면 얼마인가요?","options":[{"t":"⟨1 2/7⟩","correct":true},{"t":"⟨9/14⟩","mis":"M4-2-u1-X01"},{"t":"⟨2/7⟩","mis":"M4-2-u1-X04"},{"t":"⟨2 2/7⟩","mis":"M4-2-u1-X04"}],"explanation":["⟨5/7⟩는 ⟨1/7⟩이 5개, ⟨4/7⟩는 ⟨1/7⟩이 4개예요.","⟨5/7⟩ + ⟨4/7⟩ = ⟨9/7⟩ — 분모는 그대로 두고 분자끼리 더해요.","⟨9/7⟩ = ⟨1 2/7⟩ — 분모끼리 더하지 않아요."],"asset":{"type":"fbar","bars":[{"den":7,"num":5},{"den":7,"num":4}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L03_basic#4','math',4,2,'u1','L03','tb_g4_2_math_u1_L03_basic','lesson_basic','M4-2-u1-C3',1,'ox','auto','서준이는 「⟨2/6⟩와 ⟨3/6⟩은 전체가 각각 6개니까 모두 12개, 색칠한 것은 2개와 3개니까 5개야. 그래서 ⟨2/6⟩ + ⟨3/6⟩ = ⟨5/12⟩야.」라고 했어요. 서준이의 말이 옳은가요?',ARRAY['M4-2-u1-X20']::text[],false,'{"seq":4,"concept":"M4-2-u1-C3","difficulty":1,"kind":"ox","stem":"서준이는 「⟨2/6⟩와 ⟨3/6⟩은 전체가 각각 6개니까 모두 12개, 색칠한 것은 2개와 3개니까 5개야. 그래서 ⟨2/6⟩ + ⟨3/6⟩ = ⟨5/12⟩야.」라고 했어요. 서준이의 말이 옳은가요?","answer":"X","reason_options":[{"t":"더해도 전체 1은 그대로라 ⟨1/6⟩이 2 + 3 = 5개인 ⟨5/6⟩이라서","correct":true},{"t":"두 분수의 전체를 합치면 12칸이 되어서","mis":"M4-2-u1-X20"}],"mis":"M4-2-u1-X20","explanation":["⟨2/6⟩와 ⟨3/6⟩의 전체는 똑같이 1이에요.","⟨2/6⟩ + ⟨3/6⟩ = ⟨5/6⟩ — ⟨1/6⟩이 2 + 3 = 5개예요.","전체를 12칸으로 다시 만들지 않아요 — 서준이의 말은 틀렸어요."],"asset":{"type":"fbar","bars":[{"den":6,"num":2},{"den":6,"num":3}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L03_basic#5','math',4,2,'u1','L03','tb_g4_2_math_u1_L03_basic','lesson_basic','M4-2-u1-C3',2,'mc','auto','파란색 페인트 ⟨6/8⟩ L와 노란색 페인트 ⟨4/8⟩ L를 섞어서 초록색 페인트를 만들었어요. 초록색 페인트는 모두 몇 L인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X04']::text[],false,'{"seq":5,"concept":"M4-2-u1-C3","difficulty":2,"kind":"mc","stem":"파란색 페인트 ⟨6/8⟩ L와 노란색 페인트 ⟨4/8⟩ L를 섞어서 초록색 페인트를 만들었어요. 초록색 페인트는 모두 몇 L인가요?","options":[{"t":"⟨1 2/8⟩ L","correct":true},{"t":"⟨10/16⟩ L","mis":"M4-2-u1-X01"},{"t":"⟨2/8⟩ L","mis":"M4-2-u1-X04"},{"t":"⟨2 2/8⟩ L","mis":"M4-2-u1-X04"}],"explanation":["⟨6/8⟩은 ⟨1/8⟩이 6개, ⟨4/8⟩는 ⟨1/8⟩이 4개예요.","⟨6/8⟩ + ⟨4/8⟩ = ⟨10/8⟩ — 분모는 그대로 두고 분자끼리 더해요.","⟨10/8⟩ = ⟨1 2/8⟩ L — 분모끼리 더하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L03_basic#6','math',4,2,'u1','L03','tb_g4_2_math_u1_L03_basic','lesson_basic','M4-2-u1-C3',2,'mc','auto','「익힘」 계산 결과를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨2/8⟩ + ⟨3/8⟩ ○ ⟨2/8⟩ + ⟨7/8⟩',ARRAY['M4-2-u1-X15','M4-2-u1-X18']::text[],true,'{"seq":6,"concept":"M4-2-u1-C3","difficulty":2,"kind":"mc","stem":"「익힘」 계산 결과를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨2/8⟩ + ⟨3/8⟩ ○ ⟨2/8⟩ + ⟨7/8⟩","options":[{"t":"<","correct":true},{"t":">","mis":"M4-2-u1-X15"},{"t":"=","mis":"M4-2-u1-X18"},{"t":"알 수 없어요","mis":"M4-2-u1-X18"}],"explanation":["왼쪽 ⟨2/8⟩ + ⟨3/8⟩ = ⟨5/8⟩예요.","오른쪽 ⟨2/8⟩ + ⟨7/8⟩ = ⟨1 1/8⟩이에요.","⟨2/8⟩ + ⟨3/8⟩ < ⟨2/8⟩ + ⟨7/8⟩ — 계산해서 견주면 알 수 있어요."],"variant_rule":{"alt":[{"stem":"「익힘」 계산 결과를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨3/14⟩ + ⟨12/14⟩ ○ ⟨12/14⟩ + ⟨3/14⟩","options":[{"t":"=","correct":true},{"t":">","mis":"M4-2-u1-X15"},{"t":"<","mis":"M4-2-u1-X15"},{"t":"알 수 없어요","mis":"M4-2-u1-X18"}],"explanation":["왼쪽 ⟨3/14⟩ + ⟨12/14⟩ = ⟨1 1/14⟩이에요.","오른쪽 ⟨12/14⟩ + ⟨3/14⟩ = ⟨1 1/14⟩이에요.","⟨3/14⟩ + ⟨12/14⟩ = ⟨12/14⟩ + ⟨3/14⟩ — 계산해서 견주면 알 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L03_basic#7','math',4,2,'u1','L03','tb_g4_2_math_u1_L03_basic','lesson_basic','M4-2-u1-C3',2,'error','auto','친구들이 분수의 덧셈을 했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X15']::text[],false,'{"seq":7,"concept":"M4-2-u1-C3","difficulty":2,"kind":"error","stem":"친구들이 분수의 덧셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"채원 — 「⟨5/8⟩ + ⟨6/8⟩ = ⟨11/16⟩」","correct":true,"mis_target":"M4-2-u1-X01"},{"t":"도윤 — 「⟨4/7⟩ + ⟨2/7⟩ = ⟨6/7⟩」","mis":"M4-2-u1-X15"},{"t":"지유 — 「⟨4/10⟩ + ⟨5/10⟩ = ⟨9/10⟩」","mis":"M4-2-u1-X15"},{"t":"건우 — 「⟨3/4⟩ + ⟨2/4⟩ = ⟨1 1/4⟩」","mis":"M4-2-u1-X15"}],"explanation":["분모가 같은 분수의 덧셈은 분모는 그대로 두고 분자끼리 더해요.","⟨5/8⟩ + ⟨6/8⟩ = ⟨11/8⟩ = ⟨1 3/8⟩이에요.","채원이는 분모끼리도 더해 ⟨11/16⟩이라고 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L03_basic#8','math',4,2,'u1','L03','tb_g4_2_math_u1_L03_basic','lesson_basic','M4-2-u1-C3',2,'mc','auto','「확인 문제」 ⟨8/12⟩ + ⟨9/12⟩를 계산하여 대분수로 나타내면 얼마인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X04']::text[],true,'{"seq":8,"concept":"M4-2-u1-C3","difficulty":2,"kind":"mc","stem":"「확인 문제」 ⟨8/12⟩ + ⟨9/12⟩를 계산하여 대분수로 나타내면 얼마인가요?","options":[{"t":"⟨1 5/12⟩","correct":true},{"t":"⟨17/24⟩","mis":"M4-2-u1-X01"},{"t":"⟨5/12⟩","mis":"M4-2-u1-X04"},{"t":"⟨2 5/12⟩","mis":"M4-2-u1-X04"}],"explanation":["⟨8/12⟩은 ⟨1/12⟩이 8개, ⟨9/12⟩는 ⟨1/12⟩이 9개예요.","⟨8/12⟩ + ⟨9/12⟩ = ⟨17/12⟩ — 분모는 그대로 두고 분자끼리 더해요.","⟨17/12⟩ = ⟨1 5/12⟩ — 분모끼리 더하지 않아요."],"variant_rule":{"alt":[{"stem":"「확인 문제」 ⟨7/15⟩ + ⟨10/15⟩을 계산하여 대분수로 나타내면 얼마인가요?","options":[{"t":"⟨1 2/15⟩","correct":true},{"t":"⟨17/30⟩","mis":"M4-2-u1-X01"},{"t":"⟨2/15⟩","mis":"M4-2-u1-X04"},{"t":"⟨2 2/15⟩","mis":"M4-2-u1-X04"}],"explanation":["⟨7/15⟩은 ⟨1/15⟩이 7개, ⟨10/15⟩은 ⟨1/15⟩이 10개예요.","⟨7/15⟩ + ⟨10/15⟩ = ⟨17/15⟩ — 분모는 그대로 두고 분자끼리 더해요.","⟨17/15⟩ = ⟨1 2/15⟩ — 분모끼리 더하지 않아요."]},{"stem":"「익힘」 ⟨8/13⟩ + ⟨7/13⟩을 계산하여 대분수로 나타내면 얼마인가요?","options":[{"t":"⟨1 2/13⟩","correct":true},{"t":"⟨15/26⟩","mis":"M4-2-u1-X01"},{"t":"⟨2/13⟩","mis":"M4-2-u1-X04"},{"t":"⟨2 2/13⟩","mis":"M4-2-u1-X04"}],"explanation":["⟨8/13⟩은 ⟨1/13⟩이 8개, ⟨7/13⟩은 ⟨1/13⟩이 7개예요.","⟨8/13⟩ + ⟨7/13⟩ = ⟨15/13⟩ — 분모는 그대로 두고 분자끼리 더해요.","⟨15/13⟩ = ⟨1 2/13⟩ — 분모끼리 더하지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L03_basic#9','math',4,2,'u1','L03','tb_g4_2_math_u1_L03_basic','lesson_basic','M4-2-u1-C3',2,'mc','auto','「지도서」 ⟨2/4⟩ + ⟨1/4⟩을 계산하지 않아도 ⟨3/8⟩이 답이 될 수 없다는 것을 알 수 있어요. 그 까닭으로 알맞은 것은 무엇인가요?',ARRAY['M4-2-u1-X16','M4-2-u1-X01','M4-2-u1-X14']::text[],false,'{"seq":9,"concept":"M4-2-u1-C3","difficulty":2,"kind":"mc","stem":"「지도서」 ⟨2/4⟩ + ⟨1/4⟩을 계산하지 않아도 ⟨3/8⟩이 답이 될 수 없다는 것을 알 수 있어요. 그 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"⟨2/4⟩는 전체의 반인데 ⟨3/8⟩은 반보다 작아서","correct":true},{"t":"분자 3이 홀수라서","mis":"M4-2-u1-X16"},{"t":"⟨3/8⟩의 분모 8이 4보다 커서","mis":"M4-2-u1-X01"},{"t":"⟨1/4⟩이 ⟨2/4⟩보다 작아서","mis":"M4-2-u1-X14"}],"explanation":["⟨2/4⟩는 전체의 반이에요.","⟨2/4⟩에 ⟨1/4⟩을 더하면 반보다 커야 하는데 ⟨3/8⟩은 반보다 작아요.","바른 답은 ⟨2/4⟩ + ⟨1/4⟩ = ⟨3/4⟩ — 분모끼리 더하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L03_basic#10','math',4,2,'u1','L03','tb_g4_2_math_u1_L03_basic','lesson_basic','M4-2-u1-C3',3,'sa','auto','「익힘」 ⟨8/9⟩ + ⟨6/9⟩ > ⟨1 □/9⟩일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u1-C3","difficulty":3,"kind":"sa","stem":"「익힘」 ⟨8/9⟩ + ⟨6/9⟩ > ⟨1 □/9⟩일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["⟨8/9⟩ + ⟨6/9⟩ = ⟨14/9⟩ = ⟨1 5/9⟩예요.","⟨1 5/9⟩가 더 크려면 □는 5보다 작아야 해요.","□는 1, 2, 3, 4 — 모두 4개예요(5를 넣으면 크기가 같아요)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L03_challenge#1','math',4,2,'u1','L03','tb_g4_2_math_u1_L03_challenge','lesson_challenge','M4-2-u1-C3',2,'mc','auto','「확인 문제」 계산 결과가 큰 것부터 차례대로 기호를 쓴 것은 무엇인가요?  ㉠ ⟨4/9⟩ + ⟨8/9⟩  ㉡ ⟨4/9⟩ + ⟨6/9⟩  ㉢ ⟨8/9⟩ + ⟨7/9⟩',ARRAY['M4-2-u1-X15','M4-2-u1-X17','M4-2-u1-X16']::text[],false,'{"seq":1,"concept":"M4-2-u1-C3","difficulty":2,"kind":"mc","stem":"「확인 문제」 계산 결과가 큰 것부터 차례대로 기호를 쓴 것은 무엇인가요?  ㉠ ⟨4/9⟩ + ⟨8/9⟩  ㉡ ⟨4/9⟩ + ⟨6/9⟩  ㉢ ⟨8/9⟩ + ⟨7/9⟩","options":[{"t":"㉢, ㉠, ㉡","correct":true},{"t":"㉡, ㉠, ㉢","mis":"M4-2-u1-X15"},{"t":"㉠, ㉢, ㉡","mis":"M4-2-u1-X17"},{"t":"㉢, ㉡, ㉠","mis":"M4-2-u1-X16"}],"explanation":["하나씩 계산해요 — ㉠ ⟨4/9⟩ + ⟨8/9⟩ = ⟨1 3/9⟩, ㉡ ⟨4/9⟩ + ⟨6/9⟩ = ⟨1 1/9⟩, ㉢ ⟨8/9⟩ + ⟨7/9⟩ = ⟨1 6/9⟩.","⟨1 6/9⟩ > ⟨1 3/9⟩ > ⟨1 1/9⟩이에요.","계산 결과가 큰 것부터 쓰면 ㉢, ㉠, ㉡예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L03_challenge#2','math',4,2,'u1','L03','tb_g4_2_math_u1_L03_challenge','lesson_challenge','M4-2-u1-C3',2,'sa','auto','「익힘」 ⟨8/13⟩ + ⟨7/13⟩ = ⟨1 □/13⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u1-C3","difficulty":2,"kind":"sa","stem":"「익힘」 ⟨8/13⟩ + ⟨7/13⟩ = ⟨1 □/13⟩ — □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["⟨8/13⟩은 ⟨1/13⟩이 8개, ⟨7/13⟩은 ⟨1/13⟩이 7개예요.","⟨8/13⟩ + ⟨7/13⟩ = ⟨15/13⟩ — 분모는 그대로 두고 분자끼리 더해요.","⟨15/13⟩ = ⟨1 2/13⟩ — 분모끼리 더하지 않아요."],"variant_rule":{"alt":[{"stem":"⟨7/9⟩ + ⟨5/9⟩ = ⟨1 □/9⟩ — □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["⟨7/9⟩은 ⟨1/9⟩이 7개, ⟨5/9⟩는 ⟨1/9⟩이 5개예요.","⟨7/9⟩ + ⟨5/9⟩ = ⟨12/9⟩ — 분모는 그대로 두고 분자끼리 더해요.","⟨12/9⟩ = ⟨1 3/9⟩ — 분모끼리 더하지 않아요."]},{"stem":"⟨6/8⟩ + ⟨4/8⟩ = ⟨1 □/8⟩ — □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["⟨6/8⟩은 ⟨1/8⟩이 6개, ⟨4/8⟩는 ⟨1/8⟩이 4개예요.","⟨6/8⟩ + ⟨4/8⟩ = ⟨10/8⟩ — 분모는 그대로 두고 분자끼리 더해요.","⟨10/8⟩ = ⟨1 2/8⟩ — 분모끼리 더하지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L03_challenge#3','math',4,2,'u1','L03','tb_g4_2_math_u1_L03_challenge','lesson_challenge','M4-2-u1-C3',3,'mc','auto','「익힘 퐁당」 채원이는 「⟨5/8⟩ + ⟨6/8⟩은 분모끼리, 분자끼리 각각 더해서 ⟨11/16⟩입니다.」라고 설명했어요. 잘못된 부분으로 알맞은 것은 무엇인가요?',ARRAY['M4-2-u1-X04','M4-2-u1-X16','M4-2-u1-X14']::text[],false,'{"seq":3,"concept":"M4-2-u1-C3","difficulty":3,"kind":"mc","stem":"「익힘 퐁당」 채원이는 「⟨5/8⟩ + ⟨6/8⟩은 분모끼리, 분자끼리 각각 더해서 ⟨11/16⟩입니다.」라고 설명했어요. 잘못된 부분으로 알맞은 것은 무엇인가요?","options":[{"t":"분모는 그대로 두고 분자끼리만 더해야 하는데 분모끼리도 더했다","correct":true},{"t":"⟨11/16⟩을 대분수로 바꾸지 않았다","mis":"M4-2-u1-X04"},{"t":"분자 5와 6을 더하면 12인데 11이라고 했다","mis":"M4-2-u1-X16"},{"t":"큰 분수에서 작은 분수를 빼야 했다","mis":"M4-2-u1-X14"}],"explanation":["⟨5/8⟩와 ⟨6/8⟩은 ⟨1/8⟩이 5개, 6개예요.","⟨5/8⟩ + ⟨6/8⟩ = ⟨11/8⟩ = ⟨1 3/8⟩이에요.","분모끼리 더한 ⟨11/16⟩은 ⟨6/8⟩보다도 작아서 두 분수의 합이 될 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L03_challenge#4','math',4,2,'u1','L03','tb_g4_2_math_u1_L03_challenge','lesson_challenge','M4-2-u1-C3',3,'mc','auto','「익힘」 지난주에 해바라기의 키를 쟀더니 ⟨6/10⟩ m였어요. 오늘 다시 재어 보니 지난주보다 ⟨8/10⟩ m가 더 자라 있었어요. 오늘 해바라기의 키는 몇 m인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X04']::text[],false,'{"seq":4,"concept":"M4-2-u1-C3","difficulty":3,"kind":"mc","stem":"「익힘」 지난주에 해바라기의 키를 쟀더니 ⟨6/10⟩ m였어요. 오늘 다시 재어 보니 지난주보다 ⟨8/10⟩ m가 더 자라 있었어요. 오늘 해바라기의 키는 몇 m인가요?","options":[{"t":"⟨1 4/10⟩ m","correct":true},{"t":"⟨14/20⟩ m","mis":"M4-2-u1-X01"},{"t":"⟨4/10⟩ m","mis":"M4-2-u1-X04"},{"t":"⟨2 4/10⟩ m","mis":"M4-2-u1-X04"}],"explanation":["⟨6/10⟩은 ⟨1/10⟩이 6개, ⟨8/10⟩은 ⟨1/10⟩이 8개예요.","⟨6/10⟩ + ⟨8/10⟩ = ⟨14/10⟩ — 분모는 그대로 두고 분자끼리 더해요.","⟨14/10⟩ = ⟨1 4/10⟩ m — 분모끼리 더하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L03_challenge#5','math',4,2,'u1','L03','tb_g4_2_math_u1_L03_challenge','lesson_challenge','M4-2-u1-C3',3,'ox','auto','건우는 「⟨7/9⟩ + ⟨5/9⟩의 답을 ⟨12/9⟩로 써도 맞고 ⟨1 3/9⟩으로 써도 맞아.」라고 했어요. 건우의 말이 옳은가요?',ARRAY['M4-2-u1-X02']::text[],false,'{"seq":5,"concept":"M4-2-u1-C3","difficulty":3,"kind":"ox","stem":"건우는 「⟨7/9⟩ + ⟨5/9⟩의 답을 ⟨12/9⟩로 써도 맞고 ⟨1 3/9⟩으로 써도 맞아.」라고 했어요. 건우의 말이 옳은가요?","answer":"O","reason_options":[{"t":"⟨12/9⟩와 ⟨1 3/9⟩은 크기가 같은 수라서","correct":true},{"t":"덧셈의 답은 꼭 대분수로만 써야 해서","mis":"M4-2-u1-X02"}],"mis":"M4-2-u1-X02","explanation":["⟨7/9⟩ + ⟨5/9⟩ = ⟨12/9⟩예요.","⟨12/9⟩ = ⟨1 3/9⟩ — 가분수와 대분수로 나타낸 같은 수예요.","따로 「대분수로」라고 하지 않으면 둘 다 맞아요 — 건우의 말이 옳아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L03_challenge#6','math',4,2,'u1','L03','tb_g4_2_math_u1_L03_challenge','lesson_challenge','M4-2-u1-C3',3,'mc','auto','계산 결과가 1보다 큰 것은 무엇인가요?',ARRAY['M4-2-u1-X17']::text[],false,'{"seq":6,"concept":"M4-2-u1-C3","difficulty":3,"kind":"mc","stem":"계산 결과가 1보다 큰 것은 무엇인가요?","options":[{"t":"⟨7/9⟩ + ⟨5/9⟩","correct":true},{"t":"⟨4/7⟩ + ⟨2/7⟩","mis":"M4-2-u1-X17"},{"t":"⟨4/10⟩ + ⟨5/10⟩","mis":"M4-2-u1-X17"},{"t":"⟨2/9⟩ + ⟨5/9⟩","mis":"M4-2-u1-X17"}],"explanation":["분자의 합이 분모보다 크면 1보다 커요.","⟨7/9⟩ + ⟨5/9⟩ = ⟨12/9⟩ = ⟨1 3/9⟩이에요.","⟨4/7⟩ + ⟨2/7⟩ = ⟨6/7⟩, ⟨4/10⟩ + ⟨5/10⟩ = ⟨9/10⟩, ⟨2/9⟩ + ⟨5/9⟩ = ⟨7/9⟩은 1보다 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L03_challenge#7','math',4,2,'u1','L03','tb_g4_2_math_u1_L03_challenge','lesson_challenge','M4-2-u1-C3',3,'sa','auto','「익힘 퐁당」 ⟨5/8⟩ + ⟨□/8⟩ = ⟨1 3/8⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u1-C3","difficulty":3,"kind":"sa","stem":"「익힘 퐁당」 ⟨5/8⟩ + ⟨□/8⟩ = ⟨1 3/8⟩ — □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["⟨1 3/8⟩ = ⟨11/8⟩ — ⟨1/8⟩이 11개예요.","⟨5/8⟩는 ⟨1/8⟩이 5개라 11 − 5 = 6개를 더 모아야 해요.","⟨5/8⟩ + ⟨6/8⟩ = ⟨1 3/8⟩ — □ = 6."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩ + ⟨□/4⟩ = ⟨1 1/4⟩ — □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["⟨1 1/4⟩ = ⟨5/4⟩ — ⟨1/4⟩이 5개예요.","⟨3/4⟩은 ⟨1/4⟩이 3개라 5 − 3 = 2개를 더 모아야 해요.","⟨3/4⟩ + ⟨2/4⟩ = ⟨1 1/4⟩ — □ = 2."]},{"stem":"⟨6/8⟩ + ⟨□/8⟩ = ⟨1 2/8⟩ — □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["⟨1 2/8⟩ = ⟨10/8⟩ — ⟨1/8⟩이 10개예요.","⟨6/8⟩은 ⟨1/8⟩이 6개라 10 − 6 = 4개를 더 모아야 해요.","⟨6/8⟩ + ⟨4/8⟩ = ⟨1 2/8⟩ — □ = 4."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L03_challenge#8','math',4,2,'u1','L03','tb_g4_2_math_u1_L03_challenge','lesson_challenge','M4-2-u1-C3',4,'essay','teacher','서준이는 「⟨2/6⟩와 ⟨3/6⟩은 전체가 각각 6개니까 모두 12개, 색칠한 것은 5개니까 ⟨2/6⟩ + ⟨3/6⟩ = ⟨5/12⟩야.」라고 했어요. 서준이의 생각에서 잘못된 점을 쓰고, 분수 띠를 떠올려 바르게 계산해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u1-C3","difficulty":4,"kind":"essay","stem":"서준이는 「⟨2/6⟩와 ⟨3/6⟩은 전체가 각각 6개니까 모두 12개, 색칠한 것은 5개니까 ⟨2/6⟩ + ⟨3/6⟩ = ⟨5/12⟩야.」라고 했어요. 서준이의 생각에서 잘못된 점을 쓰고, 분수 띠를 떠올려 바르게 계산해 보세요.","answer_guide":{"answer":"예: 두 분수의 전체는 모두 같은 1이므로 전체를 12칸으로 합치면 안 된다. ⟨2/6⟩는 ⟨1/6⟩이 2개, ⟨3/6⟩은 ⟨1/6⟩이 3개이므로 ⟨2/6⟩ + ⟨3/6⟩은 ⟨1/6⟩이 5개인 ⟨5/6⟩이다. 분모는 그대로 두고 분자끼리 더한다.","scoring_points":["전체 1이 그대로라는 것(12칸으로 합치면 안 됨)을 썼는가","⟨1/6⟩의 개수로 설명했는가","⟨5/6⟩이라고 답했는가"]},"explanation":["전체는 1 그대로예요.","⟨1/6⟩이 2 + 3 = 5개예요.","⟨2/6⟩ + ⟨3/6⟩ = ⟨5/6⟩."],"asset":{"type":"fbar","bars":[{"den":6,"num":2},{"den":6,"num":3}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L03_challenge#9','math',4,2,'u1','L03','tb_g4_2_math_u1_L03_challenge','lesson_challenge','M4-2-u1-C3',4,'essay','teacher','「익힘」 ⟨8/9⟩ + ⟨6/9⟩ > ⟨1 □/9⟩일 때, □ 안에 들어갈 수 있는 수를 모두 구하고 어떻게 구했는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u1-C3","difficulty":4,"kind":"essay","stem":"「익힘」 ⟨8/9⟩ + ⟨6/9⟩ > ⟨1 □/9⟩일 때, □ 안에 들어갈 수 있는 수를 모두 구하고 어떻게 구했는지 설명해 보세요.","answer_guide":{"answer":"예: ⟨8/9⟩ + ⟨6/9⟩ = ⟨14/9⟩ = ⟨1 5/9⟩이다. ⟨1 5/9⟩ > ⟨1 □/9⟩이 되려면 자연수가 같으므로 □는 5보다 작아야 한다. 그래서 □ 안에 들어갈 수 있는 수는 1, 2, 3, 4이다.","scoring_points":["⟨8/9⟩ + ⟨6/9⟩ = ⟨1 5/9⟩를 구했는가","자연수가 같아 분자를 견준다고 설명했는가","1, 2, 3, 4를 모두 찾았는가"]},"explanation":["⟨8/9⟩ + ⟨6/9⟩ = ⟨1 5/9⟩예요.","□ < 5여야 해요.","1, 2, 3, 4."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L03_challenge#10','math',4,2,'u1','L03','tb_g4_2_math_u1_L03_challenge','lesson_challenge','M4-2-u1-C3',4,'essay','teacher','「익힘 퐁당」 채원이는 「⟨5/8⟩ + ⟨6/8⟩은 분모끼리, 분자끼리 각각 더해서 ⟨11/16⟩입니다.」라고 했어요. 잘못된 부분을 찾아 설명하고, 바르게 계산해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u1-C3","difficulty":4,"kind":"essay","stem":"「익힘 퐁당」 채원이는 「⟨5/8⟩ + ⟨6/8⟩은 분모끼리, 분자끼리 각각 더해서 ⟨11/16⟩입니다.」라고 했어요. 잘못된 부분을 찾아 설명하고, 바르게 계산해 보세요.","answer_guide":{"answer":"예: 분모가 같은 분수의 덧셈은 분모는 그대로 두고 분자끼리 더해야 하는데 채원이는 분모끼리도 더했다. ⟨5/8⟩ + ⟨6/8⟩은 ⟨1/8⟩이 11개이므로 ⟨11/8⟩ = ⟨1 3/8⟩이다.","scoring_points":["분모끼리 더한 것이 잘못이라고 썼는가","⟨1/8⟩의 개수로 설명했는가","⟨11/8⟩ 또는 ⟨1 3/8⟩이라고 답했는가"]},"explanation":["분모는 그대로예요.","⟨1/8⟩이 5 + 6 = 11개예요.","⟨5/8⟩ + ⟨6/8⟩ = ⟨1 3/8⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L04_basic#1','math',4,2,'u1','L04','tb_g4_2_math_u1_L04_basic','lesson_basic','M4-2-u1-C4',1,'sa','auto','⟨5/6⟩ − ⟨3/6⟩ = ⟨□/6⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u1-C4","difficulty":1,"kind":"sa","stem":"⟨5/6⟩ − ⟨3/6⟩ = ⟨□/6⟩ — □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["⟨5/6⟩는 ⟨1/6⟩이 5개, ⟨3/6⟩은 ⟨1/6⟩이 3개예요.","⟨5/6⟩ − ⟨3/6⟩ = ⟨2/6⟩ — 분모는 그대로 두고 분자끼리 빼요.","⟨1/6⟩이 5 − 3 = 2개 남아요 — 분모끼리 빼지 않아요."],"asset":{"type":"fbar","bars":[{"den":6,"num":5,"label":"⟨5/6⟩에서 ⟨3/6⟩만큼 덜어 내기"}]},"variant_rule":{"alt":[{"stem":"「익힘」 ⟨4/5⟩ − ⟨2/5⟩ = ⟨□/5⟩ — □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["⟨4/5⟩는 ⟨1/5⟩이 4개, ⟨2/5⟩는 ⟨1/5⟩이 2개예요.","⟨4/5⟩ − ⟨2/5⟩ = ⟨2/5⟩ — 분모는 그대로 두고 분자끼리 빼요.","⟨1/5⟩이 4 − 2 = 2개 남아요 — 분모끼리 빼지 않아요."],"asset":{"type":"fbar","bars":[{"den":5,"num":4,"label":"⟨4/5⟩에서 ⟨2/5⟩만큼 덜어 내기"}]}},{"stem":"⟨6/7⟩ − ⟨3/7⟩ = ⟨□/7⟩ — □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["⟨6/7⟩은 ⟨1/7⟩이 6개, ⟨3/7⟩은 ⟨1/7⟩이 3개예요.","⟨6/7⟩ − ⟨3/7⟩ = ⟨3/7⟩ — 분모는 그대로 두고 분자끼리 빼요.","⟨1/7⟩이 6 − 3 = 3개 남아요 — 분모끼리 빼지 않아요."],"asset":{"type":"fbar","bars":[{"den":7,"num":6,"label":"⟨6/7⟩에서 ⟨3/7⟩만큼 덜어 내기"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L04_basic#2','math',4,2,'u1','L04','tb_g4_2_math_u1_L04_basic','lesson_basic','M4-2-u1-C4',1,'mc','auto','⟨3/4⟩ − ⟨1/4⟩을 계산해 보세요.',ARRAY['M4-2-u1-X01','M4-2-u1-X16']::text[],true,'{"seq":2,"concept":"M4-2-u1-C4","difficulty":1,"kind":"mc","stem":"⟨3/4⟩ − ⟨1/4⟩을 계산해 보세요.","options":[{"t":"⟨2/4⟩","correct":true},{"t":"⟨2/3⟩","mis":"M4-2-u1-X01"},{"t":"⟨3/4⟩","mis":"M4-2-u1-X16"},{"t":"⟨1/4⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨3/4⟩은 ⟨1/4⟩이 3개, ⟨1/4⟩은 ⟨1/4⟩이 1개예요.","⟨3/4⟩ − ⟨1/4⟩ = ⟨2/4⟩ — 분모는 그대로 두고 분자끼리 빼요.","⟨1/4⟩이 3 − 1 = 2개 남아요 — 분모끼리 빼지 않아요."],"variant_rule":{"alt":[{"stem":"「익힘」 ⟨6/8⟩ − ⟨3/8⟩을 계산해 보세요.","options":[{"t":"⟨3/8⟩","correct":true},{"t":"⟨3/5⟩","mis":"M4-2-u1-X01"},{"t":"⟨4/8⟩","mis":"M4-2-u1-X16"},{"t":"⟨2/8⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨6/8⟩은 ⟨1/8⟩이 6개, ⟨3/8⟩은 ⟨1/8⟩이 3개예요.","⟨6/8⟩ − ⟨3/8⟩ = ⟨3/8⟩ — 분모는 그대로 두고 분자끼리 빼요.","⟨1/8⟩이 6 − 3 = 3개 남아요 — 분모끼리 빼지 않아요."]},{"stem":"「익힘」 ⟨7/11⟩ − ⟨2/11⟩를 계산해 보세요.","options":[{"t":"⟨5/11⟩","correct":true},{"t":"⟨5/9⟩","mis":"M4-2-u1-X01"},{"t":"⟨6/11⟩","mis":"M4-2-u1-X16"},{"t":"⟨4/11⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨7/11⟩은 ⟨1/11⟩이 7개, ⟨2/11⟩는 ⟨1/11⟩이 2개예요.","⟨7/11⟩ − ⟨2/11⟩ = ⟨5/11⟩ — 분모는 그대로 두고 분자끼리 빼요.","⟨1/11⟩이 7 − 2 = 5개 남아요 — 분모끼리 빼지 않아요."]},{"stem":"「확인 문제」 ⟨7/8⟩ − ⟨3/8⟩을 계산해 보세요.","options":[{"t":"⟨4/8⟩","correct":true},{"t":"⟨4/5⟩","mis":"M4-2-u1-X01"},{"t":"⟨5/8⟩","mis":"M4-2-u1-X16"},{"t":"⟨3/8⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨7/8⟩은 ⟨1/8⟩이 7개, ⟨3/8⟩은 ⟨1/8⟩이 3개예요.","⟨7/8⟩ − ⟨3/8⟩ = ⟨4/8⟩ — 분모는 그대로 두고 분자끼리 빼요.","⟨1/8⟩이 7 − 3 = 4개 남아요 — 분모끼리 빼지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L04_basic#3','math',4,2,'u1','L04','tb_g4_2_math_u1_L04_basic','lesson_basic','M4-2-u1-C4',1,'mc','auto','1 − ⟨3/5⟩을 계산해 보세요.',ARRAY['M4-2-u1-X15','M4-2-u1-X16','M4-2-u1-X14']::text[],true,'{"seq":3,"concept":"M4-2-u1-C4","difficulty":1,"kind":"mc","stem":"1 − ⟨3/5⟩을 계산해 보세요.","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨3/5⟩","mis":"M4-2-u1-X15"},{"t":"⟨1/5⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 3/5⟩","mis":"M4-2-u1-X14"}],"explanation":["1은 ⟨1/5⟩이 5개 — 1 = ⟨5/5⟩예요.","1 − ⟨3/5⟩ = ⟨5/5⟩ − ⟨3/5⟩ = ⟨2/5⟩.","1을 가분수로 바꾼 뒤 분자끼리 빼요 — 5 − 3 = 2."],"asset":{"type":"fbar","bars":[{"den":5,"num":5,"label":"1 = ⟨5/5⟩"}]},"variant_rule":{"alt":[{"stem":"1 − ⟨5/8⟩를 계산해 보세요.","options":[{"t":"⟨3/8⟩","correct":true},{"t":"⟨4/8⟩","mis":"M4-2-u1-X08"},{"t":"⟨5/8⟩","mis":"M4-2-u1-X15"},{"t":"⟨2/8⟩","mis":"M4-2-u1-X16"}],"explanation":["1은 ⟨1/8⟩이 8개 — 1 = ⟨8/8⟩이에요.","1 − ⟨5/8⟩ = ⟨8/8⟩ − ⟨5/8⟩ = ⟨3/8⟩.","1을 가분수로 바꾼 뒤 분자끼리 빼요 — 8 − 5 = 3."],"asset":{"type":"fbar","bars":[{"den":8,"num":8,"label":"1 = ⟨8/8⟩"}]}},{"stem":"「익힘」 1 − ⟨3/4⟩을 계산해 보세요.","options":[{"t":"⟨1/4⟩","correct":true},{"t":"⟨2/4⟩","mis":"M4-2-u1-X08"},{"t":"⟨3/4⟩","mis":"M4-2-u1-X15"},{"t":"⟨1 3/4⟩","mis":"M4-2-u1-X14"}],"explanation":["1은 ⟨1/4⟩이 4개 — 1 = ⟨4/4⟩예요.","1 − ⟨3/4⟩ = ⟨4/4⟩ − ⟨3/4⟩ = ⟨1/4⟩.","1을 가분수로 바꾼 뒤 분자끼리 빼요 — 4 − 3 = 1."],"asset":{"type":"fbar","bars":[{"den":4,"num":4,"label":"1 = ⟨4/4⟩"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L04_basic#4','math',4,2,'u1','L04','tb_g4_2_math_u1_L04_basic','lesson_basic','M4-2-u1-C4',1,'sa','auto','1 − ⟨3/5⟩을 계산하려면 먼저 1을 ⟨□/5⟩로 바꾸어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u1-C4","difficulty":1,"kind":"sa","stem":"1 − ⟨3/5⟩을 계산하려면 먼저 1을 ⟨□/5⟩로 바꾸어요. □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["1은 ⟨1/5⟩이 5개예요.","1 = ⟨5/5⟩로 바꾸면 ⟨5/5⟩ − ⟨3/5⟩ = ⟨2/5⟩예요.","1을 가분수로 바꾸어야 분자끼리 뺄 수 있어요 — □ = 5."],"variant_rule":{"alt":[{"stem":"1 − ⟨5/8⟩를 계산하려면 먼저 1을 ⟨□/8⟩로 바꾸어요. □에 알맞은 수를 쓰세요.","answer":["8"],"explanation":["1은 ⟨1/8⟩이 8개예요.","1 = ⟨8/8⟩로 바꾸면 ⟨8/8⟩ − ⟨5/8⟩ = ⟨3/8⟩이에요.","1을 가분수로 바꾸어야 분자끼리 뺄 수 있어요 — □ = 8."]},{"stem":"「확인 문제」 1 − ⟨9/12⟩를 계산하려면 먼저 1을 ⟨□/12⟩로 바꾸어요. □에 알맞은 수를 쓰세요.","answer":["12"],"explanation":["1은 ⟨1/12⟩이 12개예요.","1 = ⟨12/12⟩로 바꾸면 ⟨12/12⟩ − ⟨9/12⟩ = ⟨3/12⟩이에요.","1을 가분수로 바꾸어야 분자끼리 뺄 수 있어요 — □ = 12."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L04_basic#5','math',4,2,'u1','L04','tb_g4_2_math_u1_L04_basic','lesson_basic','M4-2-u1-C4',2,'mc','auto','천연 식물 영양제 ⟨5/6⟩ L 중에서 ⟨3/6⟩ L를 텃밭에 주었어요. 남은 천연 식물 영양제는 몇 L인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X16']::text[],true,'{"seq":5,"concept":"M4-2-u1-C4","difficulty":2,"kind":"mc","stem":"천연 식물 영양제 ⟨5/6⟩ L 중에서 ⟨3/6⟩ L를 텃밭에 주었어요. 남은 천연 식물 영양제는 몇 L인가요?","options":[{"t":"⟨2/6⟩ L","correct":true},{"t":"⟨2/3⟩ L","mis":"M4-2-u1-X01"},{"t":"⟨3/6⟩ L","mis":"M4-2-u1-X16"},{"t":"⟨1/6⟩ L","mis":"M4-2-u1-X16"}],"explanation":["⟨5/6⟩는 ⟨1/6⟩이 5개, ⟨3/6⟩은 ⟨1/6⟩이 3개예요.","⟨5/6⟩ − ⟨3/6⟩ = ⟨2/6⟩ L — 분모는 그대로 두고 분자끼리 빼요.","⟨1/6⟩이 5 − 3 = 2개 남아요 — 분모끼리 빼지 않아요."],"variant_rule":{"alt":[{"stem":"「익힘」 천연 식물 영양제 ⟨4/5⟩ L 중에서 ⟨2/5⟩ L를 텃밭에 주었어요. 남은 천연 식물 영양제는 몇 L인가요?","options":[{"t":"⟨2/5⟩ L","correct":true},{"t":"⟨2/3⟩ L","mis":"M4-2-u1-X01"},{"t":"⟨3/5⟩ L","mis":"M4-2-u1-X16"},{"t":"⟨1/5⟩ L","mis":"M4-2-u1-X16"}],"explanation":["⟨4/5⟩는 ⟨1/5⟩이 4개, ⟨2/5⟩는 ⟨1/5⟩이 2개예요.","⟨4/5⟩ − ⟨2/5⟩ = ⟨2/5⟩ L — 분모는 그대로 두고 분자끼리 빼요.","⟨1/5⟩이 4 − 2 = 2개 남아요 — 분모끼리 빼지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L04_basic#6','math',4,2,'u1','L04','tb_g4_2_math_u1_L04_basic','lesson_basic','M4-2-u1-C4',2,'mc','auto','「확인 문제」 1 − ⟨9/12⟩를 계산해 보세요.',ARRAY['M4-2-u1-X08','M4-2-u1-X15','M4-2-u1-X16']::text[],true,'{"seq":6,"concept":"M4-2-u1-C4","difficulty":2,"kind":"mc","stem":"「확인 문제」 1 − ⟨9/12⟩를 계산해 보세요.","options":[{"t":"⟨3/12⟩","correct":true},{"t":"⟨8/12⟩","mis":"M4-2-u1-X08"},{"t":"⟨9/12⟩","mis":"M4-2-u1-X15"},{"t":"⟨4/12⟩","mis":"M4-2-u1-X16"}],"explanation":["1은 ⟨1/12⟩이 12개 — 1 = ⟨12/12⟩예요.","1 − ⟨9/12⟩ = ⟨12/12⟩ − ⟨9/12⟩ = ⟨3/12⟩.","1을 가분수로 바꾼 뒤 분자끼리 빼요 — 12 − 9 = 3."],"variant_rule":{"alt":[{"stem":"「확인 문제」 1 − ⟨4/15⟩를 계산해 보세요.","options":[{"t":"⟨11/15⟩","correct":true},{"t":"⟨3/15⟩","mis":"M4-2-u1-X08"},{"t":"⟨4/15⟩","mis":"M4-2-u1-X15"},{"t":"⟨12/15⟩","mis":"M4-2-u1-X16"}],"explanation":["1은 ⟨1/15⟩이 15개 — 1 = ⟨15/15⟩예요.","1 − ⟨4/15⟩ = ⟨15/15⟩ − ⟨4/15⟩ = ⟨11/15⟩.","1을 가분수로 바꾼 뒤 분자끼리 빼요 — 15 − 4 = 11."]},{"stem":"「익힘」 1 − ⟨2/6⟩를 계산해 보세요.","options":[{"t":"⟨4/6⟩","correct":true},{"t":"⟨1/6⟩","mis":"M4-2-u1-X08"},{"t":"⟨2/6⟩","mis":"M4-2-u1-X15"},{"t":"⟨5/6⟩","mis":"M4-2-u1-X16"}],"explanation":["1은 ⟨1/6⟩이 6개 — 1 = ⟨6/6⟩이에요.","1 − ⟨2/6⟩ = ⟨6/6⟩ − ⟨2/6⟩ = ⟨4/6⟩.","1을 가분수로 바꾼 뒤 분자끼리 빼요 — 6 − 2 = 4."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L04_basic#7','math',4,2,'u1','L04','tb_g4_2_math_u1_L04_basic','lesson_basic','M4-2-u1-C4',2,'ox','auto','「익힘 퐁당」 서준이는 「1 − ⟨5/7⟩ = ⟨4/7⟩야.」라고 했어요. 서준이의 말이 옳은가요?',ARRAY['M4-2-u1-X08']::text[],false,'{"seq":7,"concept":"M4-2-u1-C4","difficulty":2,"kind":"ox","stem":"「익힘 퐁당」 서준이는 「1 − ⟨5/7⟩ = ⟨4/7⟩야.」라고 했어요. 서준이의 말이 옳은가요?","answer":"X","reason_options":[{"t":"1 = ⟨7/7⟩로 바꾸어 ⟨5/7⟩를 빼야 해서","correct":true},{"t":"1에서 빼니까 분자 5에서 1을 빼면 되어서","mis":"M4-2-u1-X08"}],"mis":"M4-2-u1-X08","explanation":["1 − ⟨5/7⟩는 1에서 ⟨5/7⟩만큼을 덜어 내는 거예요.","1 = ⟨7/7⟩ — ⟨7/7⟩ − ⟨5/7⟩ = ⟨2/7⟩예요.","서준이는 분자 5에서 1을 뺐어요 — 틀렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L04_basic#8','math',4,2,'u1','L04','tb_g4_2_math_u1_L04_basic','lesson_basic','M4-2-u1-C4',2,'mc','auto','「확인 문제」 계산 결과를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨8/9⟩ − ⟨2/9⟩ ○ ⟨7/9⟩ − ⟨2/9⟩',ARRAY['M4-2-u1-X15','M4-2-u1-X18']::text[],true,'{"seq":8,"concept":"M4-2-u1-C4","difficulty":2,"kind":"mc","stem":"「확인 문제」 계산 결과를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨8/9⟩ − ⟨2/9⟩ ○ ⟨7/9⟩ − ⟨2/9⟩","options":[{"t":">","correct":true},{"t":"<","mis":"M4-2-u1-X15"},{"t":"=","mis":"M4-2-u1-X18"},{"t":"알 수 없어요","mis":"M4-2-u1-X18"}],"explanation":["왼쪽 ⟨8/9⟩ − ⟨2/9⟩ = ⟨6/9⟩이에요.","오른쪽 ⟨7/9⟩ − ⟨2/9⟩ = ⟨5/9⟩예요.","⟨8/9⟩ − ⟨2/9⟩ > ⟨7/9⟩ − ⟨2/9⟩ — 계산해서 견주면 알 수 있어요."],"variant_rule":{"alt":[{"stem":"「확인 문제」 계산 결과를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  1 − ⟨4/7⟩ ○ 1 − ⟨6/7⟩","options":[{"t":">","correct":true},{"t":"<","mis":"M4-2-u1-X15"},{"t":"=","mis":"M4-2-u1-X18"},{"t":"알 수 없어요","mis":"M4-2-u1-X18"}],"explanation":["왼쪽 1 − ⟨4/7⟩ = ⟨3/7⟩이에요.","오른쪽 1 − ⟨6/7⟩ = ⟨1/7⟩이에요.","1 − ⟨4/7⟩ > 1 − ⟨6/7⟩ — 계산해서 견주면 알 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L04_basic#9','math',4,2,'u1','L04','tb_g4_2_math_u1_L04_basic','lesson_basic','M4-2-u1-C4',2,'mc','auto','「익힘」 1에서 ⟨3/11⟩을 빼고, 그 결과에서 다시 ⟨5/11⟩를 뺐어요. 계산 결과는 얼마인가요?',ARRAY['M4-2-u1-X15','M4-2-u1-X16']::text[],false,'{"seq":9,"concept":"M4-2-u1-C4","difficulty":2,"kind":"mc","stem":"「익힘」 1에서 ⟨3/11⟩을 빼고, 그 결과에서 다시 ⟨5/11⟩를 뺐어요. 계산 결과는 얼마인가요?","options":[{"t":"⟨3/11⟩","correct":true},{"t":"⟨8/11⟩","mis":"M4-2-u1-X15"},{"t":"⟨2/11⟩","mis":"M4-2-u1-X16"},{"t":"⟨4/11⟩","mis":"M4-2-u1-X16"}],"explanation":["1 − ⟨3/11⟩ = ⟨11/11⟩ − ⟨3/11⟩ = ⟨8/11⟩이에요.","⟨8/11⟩ − ⟨5/11⟩ = ⟨3/11⟩이에요.","두 번 빼는 것을 끝까지 해요 — 답은 ⟨3/11⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L04_basic#10','math',4,2,'u1','L04','tb_g4_2_math_u1_L04_basic','lesson_basic','M4-2-u1-C4',3,'sa','auto','1 − ⟨□/9⟩ > ⟨3/9⟩일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u1-C4","difficulty":3,"kind":"sa","stem":"1 − ⟨□/9⟩ > ⟨3/9⟩일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["1 = ⟨9/9⟩ — 1에서 ⟨1/9⟩을 □개 빼면 분자는 9 − □가 돼요.","1 − ⟨5/9⟩ = ⟨4/9⟩, 1 − ⟨6/9⟩ = ⟨3/9⟩이에요 — 9 − □가 3보다 커야 해요.","□는 1, 2, 3, 4, 5 — 모두 5개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L04_challenge#1','math',4,2,'u1','L04','tb_g4_2_math_u1_L04_challenge','lesson_challenge','M4-2-u1-C4',2,'mc','auto','「익힘」 계산 결과가 작은 것부터 차례대로 기호를 쓴 것은 무엇인가요?  ㉠ ⟨3/4⟩ − ⟨2/4⟩  ㉡ ⟨5/6⟩ − ⟨4/6⟩  ㉢ 1 − ⟨7/8⟩  ㉣ ⟨6/7⟩ − ⟨5/7⟩',ARRAY['M4-2-u1-X15','M4-2-u1-X17','M4-2-u1-X16']::text[],false,'{"seq":1,"concept":"M4-2-u1-C4","difficulty":2,"kind":"mc","stem":"「익힘」 계산 결과가 작은 것부터 차례대로 기호를 쓴 것은 무엇인가요?  ㉠ ⟨3/4⟩ − ⟨2/4⟩  ㉡ ⟨5/6⟩ − ⟨4/6⟩  ㉢ 1 − ⟨7/8⟩  ㉣ ⟨6/7⟩ − ⟨5/7⟩","options":[{"t":"㉢, ㉣, ㉡, ㉠","correct":true},{"t":"㉠, ㉡, ㉣, ㉢","mis":"M4-2-u1-X15"},{"t":"㉣, ㉢, ㉡, ㉠","mis":"M4-2-u1-X17"},{"t":"㉢, ㉣, ㉠, ㉡","mis":"M4-2-u1-X16"}],"explanation":["하나씩 계산해요 — ㉠ ⟨3/4⟩ − ⟨2/4⟩ = ⟨1/4⟩, ㉡ ⟨5/6⟩ − ⟨4/6⟩ = ⟨1/6⟩, ㉢ 1 − ⟨7/8⟩ = ⟨1/8⟩, ㉣ ⟨6/7⟩ − ⟨5/7⟩ = ⟨1/7⟩.","⟨1/8⟩ < ⟨1/7⟩ < ⟨1/6⟩ < ⟨1/4⟩이에요.","계산 결과가 작은 것부터 쓰면 ㉢, ㉣, ㉡, ㉠예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L04_challenge#2','math',4,2,'u1','L04','tb_g4_2_math_u1_L04_challenge','lesson_challenge','M4-2-u1-C4',2,'sa','auto','「익힘」 1 − ⟨2/6⟩ = ⟨□/6⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u1-C4","difficulty":2,"kind":"sa","stem":"「익힘」 1 − ⟨2/6⟩ = ⟨□/6⟩ — □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["1은 ⟨1/6⟩이 6개 — 1 = ⟨6/6⟩이에요.","1 − ⟨2/6⟩ = ⟨6/6⟩ − ⟨2/6⟩ = ⟨4/6⟩.","1을 가분수로 바꾼 뒤 분자끼리 빼요 — 6 − 2 = 4."],"variant_rule":{"alt":[{"stem":"「익힘」 1 − ⟨3/4⟩ = ⟨□/4⟩ — □에 알맞은 수를 쓰세요.","answer":["1"],"explanation":["1은 ⟨1/4⟩이 4개 — 1 = ⟨4/4⟩예요.","1 − ⟨3/4⟩ = ⟨4/4⟩ − ⟨3/4⟩ = ⟨1/4⟩.","1을 가분수로 바꾼 뒤 분자끼리 빼요 — 4 − 3 = 1."]},{"stem":"「확인 문제」 1 − ⟨9/12⟩ = ⟨□/12⟩ — □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["1은 ⟨1/12⟩이 12개 — 1 = ⟨12/12⟩예요.","1 − ⟨9/12⟩ = ⟨12/12⟩ − ⟨9/12⟩ = ⟨3/12⟩.","1을 가분수로 바꾼 뒤 분자끼리 빼요 — 12 − 9 = 3."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L04_challenge#3','math',4,2,'u1','L04','tb_g4_2_math_u1_L04_challenge','lesson_challenge','M4-2-u1-C4',3,'mc','auto','「익힘」 밀가루 ⟨11/13⟩ kg 중에서 쿠키를 만드는 데 ⟨5/13⟩ kg을 사용하고, 남은 밀가루는 모두 빵을 만드는 데 사용했어요. 쿠키와 빵 중에서 어느 것을 만드는 데 밀가루를 몇 kg 더 많이 사용했나요?',ARRAY['M4-2-u1-X15','M4-2-u1-X14']::text[],false,'{"seq":3,"concept":"M4-2-u1-C4","difficulty":3,"kind":"mc","stem":"「익힘」 밀가루 ⟨11/13⟩ kg 중에서 쿠키를 만드는 데 ⟨5/13⟩ kg을 사용하고, 남은 밀가루는 모두 빵을 만드는 데 사용했어요. 쿠키와 빵 중에서 어느 것을 만드는 데 밀가루를 몇 kg 더 많이 사용했나요?","options":[{"t":"빵, ⟨1/13⟩ kg","correct":true},{"t":"쿠키, ⟨1/13⟩ kg","mis":"M4-2-u1-X15"},{"t":"빵, ⟨6/13⟩ kg","mis":"M4-2-u1-X15"},{"t":"쿠키, ⟨6/13⟩ kg","mis":"M4-2-u1-X14"}],"explanation":["빵을 만드는 데 사용한 밀가루는 ⟨11/13⟩ − ⟨5/13⟩ = ⟨6/13⟩ kg이에요.","⟨5/13⟩ < ⟨6/13⟩ — 빵을 만드는 데 더 많이 사용했어요.","⟨6/13⟩ − ⟨5/13⟩ = ⟨1/13⟩ — 빵에 ⟨1/13⟩ kg 더 사용했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L04_challenge#4','math',4,2,'u1','L04','tb_g4_2_math_u1_L04_challenge','lesson_challenge','M4-2-u1-C4',3,'error','auto','친구들이 분수의 뺄셈을 했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M4-2-u1-X08','M4-2-u1-X15']::text[],false,'{"seq":4,"concept":"M4-2-u1-C4","difficulty":3,"kind":"error","stem":"친구들이 분수의 뺄셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"서준 — 「1 − ⟨5/7⟩ = ⟨4/7⟩」","correct":true,"mis_target":"M4-2-u1-X08"},{"t":"지유 — 「⟨6/7⟩ − ⟨3/7⟩ = ⟨3/7⟩」","mis":"M4-2-u1-X15"},{"t":"도윤 — 「1 − ⟨5/8⟩ = ⟨3/8⟩」","mis":"M4-2-u1-X15"},{"t":"건우 — 「⟨5/6⟩ − ⟨3/6⟩ = ⟨2/6⟩」","mis":"M4-2-u1-X15"}],"explanation":["1에서 진분수를 뺄 때는 1을 분모가 같은 가분수로 바꾸어요.","1 − ⟨5/7⟩ = ⟨7/7⟩ − ⟨5/7⟩ = ⟨2/7⟩예요.","서준이는 1을 바꾸지 않고 분자 5에서 1을 뺐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L04_challenge#5','math',4,2,'u1','L04','tb_g4_2_math_u1_L04_challenge','lesson_challenge','M4-2-u1-C4',3,'mc','auto','「익힘」 1 − □ = ⟨8/11⟩일 때, □에 알맞은 분수는 무엇인가요?',ARRAY['M4-2-u1-X15','M4-2-u1-X16','M4-2-u1-X14']::text[],false,'{"seq":5,"concept":"M4-2-u1-C4","difficulty":3,"kind":"mc","stem":"「익힘」 1 − □ = ⟨8/11⟩일 때, □에 알맞은 분수는 무엇인가요?","options":[{"t":"⟨3/11⟩","correct":true},{"t":"⟨8/11⟩","mis":"M4-2-u1-X15"},{"t":"⟨4/11⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 8/11⟩","mis":"M4-2-u1-X14"}],"explanation":["1 = ⟨11/11⟩이에요.","⟨11/11⟩에서 ⟨1/11⟩을 몇 개 빼야 ⟨8/11⟩이 남는지 생각해요 — 11 − 8 = 3.","□ = ⟨3/11⟩ — 1 − ⟨3/11⟩ = ⟨8/11⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L04_challenge#6','math',4,2,'u1','L04','tb_g4_2_math_u1_L04_challenge','lesson_challenge','M4-2-u1-C4',3,'ox','auto','지유는 「⟨5/6⟩ − ⟨3/6⟩은 분모는 그대로 두고 분자끼리 빼서 ⟨2/6⟩야.」라고 했어요. 지유의 말이 옳은가요?',ARRAY['M4-2-u1-X01']::text[],false,'{"seq":6,"concept":"M4-2-u1-C4","difficulty":3,"kind":"ox","stem":"지유는 「⟨5/6⟩ − ⟨3/6⟩은 분모는 그대로 두고 분자끼리 빼서 ⟨2/6⟩야.」라고 했어요. 지유의 말이 옳은가요?","answer":"O","reason_options":[{"t":"⟨1/6⟩이 5 − 3 = 2개 남아서","correct":true},{"t":"분모끼리도 빼야 해서","mis":"M4-2-u1-X01"}],"mis":"M4-2-u1-X01","explanation":["⟨5/6⟩는 ⟨1/6⟩이 5개, ⟨3/6⟩은 ⟨1/6⟩이 3개예요.","⟨5/6⟩ − ⟨3/6⟩ = ⟨2/6⟩ — 분모는 그대로 두고 분자끼리 빼요.","⟨1/6⟩이 5 − 3 = 2개 남아요 — 분모끼리 빼지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L04_challenge#7','math',4,2,'u1','L04','tb_g4_2_math_u1_L04_challenge','lesson_challenge','M4-2-u1-C4',3,'sa','auto','「확인 문제」 ⟨8/9⟩ − ⟨2/9⟩와 ⟨7/9⟩ − ⟨2/9⟩의 계산 결과의 차는 ⟨□/9⟩예요. □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M4-2-u1-C4","difficulty":3,"kind":"sa","stem":"「확인 문제」 ⟨8/9⟩ − ⟨2/9⟩와 ⟨7/9⟩ − ⟨2/9⟩의 계산 결과의 차는 ⟨□/9⟩예요. □에 알맞은 수를 쓰세요.","answer":["1"],"explanation":["⟨8/9⟩ − ⟨2/9⟩ = ⟨6/9⟩, ⟨7/9⟩ − ⟨2/9⟩ = ⟨5/9⟩예요.","⟨6/9⟩ − ⟨5/9⟩ = ⟨1/9⟩이에요.","빼는 수가 같으면 빼어지는 수의 차만큼 차이가 나요 — □ = 1."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L04_challenge#8','math',4,2,'u1','L04','tb_g4_2_math_u1_L04_challenge','lesson_challenge','M4-2-u1-C4',4,'essay','teacher','1 − ⟨3/5⟩을 분수 띠를 떠올려 계산하고, 1에서 진분수를 빼는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u1-C4","difficulty":4,"kind":"essay","stem":"1 − ⟨3/5⟩을 분수 띠를 떠올려 계산하고, 1에서 진분수를 빼는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 1은 ⟨1/5⟩이 5개이므로 1 = ⟨5/5⟩로 바꾼다. ⟨5/5⟩에서 ⟨3/5⟩을 빼면 ⟨1/5⟩이 2개 남으므로 1 − ⟨3/5⟩ = ⟨2/5⟩이다. 1에서 진분수를 뺄 때는 1을 분모가 같은 가분수로 바꾸어 분자끼리 뺀다.","scoring_points":["1 = ⟨5/5⟩로 바꾸었는가","⟨2/5⟩라고 답했는가","1을 가분수로 바꾸어 분자끼리 뺀다고 설명했는가"]},"explanation":["1 = ⟨5/5⟩예요.","⟨5/5⟩ − ⟨3/5⟩ = ⟨2/5⟩예요.","1을 가분수로 바꾸어 빼요."],"asset":{"type":"fbar","bars":[{"den":5,"num":5,"label":"1 = ⟨5/5⟩"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L04_challenge#9','math',4,2,'u1','L04','tb_g4_2_math_u1_L04_challenge','lesson_challenge','M4-2-u1-C4',4,'essay','teacher','「익힘」 밀가루 ⟨11/13⟩ kg 중에서 쿠키를 만드는 데 ⟨5/13⟩ kg을 사용하고, 남은 밀가루는 모두 빵을 만드는 데 사용했어요. 쿠키와 빵 중에서 어느 것을 만드는 데 밀가루를 몇 kg 더 많이 사용했는지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u1-C4","difficulty":4,"kind":"essay","stem":"「익힘」 밀가루 ⟨11/13⟩ kg 중에서 쿠키를 만드는 데 ⟨5/13⟩ kg을 사용하고, 남은 밀가루는 모두 빵을 만드는 데 사용했어요. 쿠키와 빵 중에서 어느 것을 만드는 데 밀가루를 몇 kg 더 많이 사용했는지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 빵을 만드는 데 사용한 밀가루는 ⟨11/13⟩ − ⟨5/13⟩ = ⟨6/13⟩ (kg)이다. ⟨5/13⟩ < ⟨6/13⟩이므로 빵을 만드는 데 더 많이 사용했다. ⟨6/13⟩ − ⟨5/13⟩ = ⟨1/13⟩ (kg)이므로 빵을 만드는 데 ⟨1/13⟩ kg 더 많이 사용했다.","scoring_points":["빵에 쓴 밀가루 ⟨6/13⟩ kg을 구했는가","쿠키와 빵의 양을 견주었는가","빵, ⟨1/13⟩ kg이라고 답했는가"]},"explanation":["⟨11/13⟩ − ⟨5/13⟩ = ⟨6/13⟩이에요.","⟨6/13⟩ > ⟨5/13⟩예요.","⟨6/13⟩ − ⟨5/13⟩ = ⟨1/13⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L04_challenge#10','math',4,2,'u1','L04','tb_g4_2_math_u1_L04_challenge','lesson_challenge','M4-2-u1-C4',4,'mc','auto','1 − ⟨□/9⟩ > ⟨3/9⟩에서 □ 안에 들어갈 수 있는 가장 큰 자연수는 무엇인가요?',ARRAY['M4-2-u1-X16','M4-2-u1-X15']::text[],false,'{"seq":10,"concept":"M4-2-u1-C4","difficulty":4,"kind":"mc","stem":"1 − ⟨□/9⟩ > ⟨3/9⟩에서 □ 안에 들어갈 수 있는 가장 큰 자연수는 무엇인가요?","options":[{"t":"5","correct":true},{"t":"6","mis":"M4-2-u1-X16"},{"t":"4","mis":"M4-2-u1-X16"},{"t":"3","mis":"M4-2-u1-X15"}],"explanation":["1 = ⟨9/9⟩ — 1에서 ⟨1/9⟩을 □개 빼면 ⟨1/9⟩이 9 − □개 남아요.","1 − ⟨5/9⟩ = ⟨4/9⟩이고 1 − ⟨6/9⟩ = ⟨3/9⟩이에요.","⟨3/9⟩보다 커야 하므로 가장 큰 □는 5예요 — 6이면 같아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L05_basic#1','math',4,2,'u1','L05','tb_g4_2_math_u1_L05_basic','lesson_basic','M4-2-u1-C5',1,'sa','auto','⟨1 1/5⟩ + ⟨1 2/5⟩ = ⟨2 □/5⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u1-C5","difficulty":1,"kind":"sa","stem":"⟨1 1/5⟩ + ⟨1 2/5⟩ = ⟨2 □/5⟩ — □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["방법 1 — 자연수끼리 1 + 1 = 2, 분수끼리 ⟨1/5⟩ + ⟨2/5⟩ = ⟨3/5⟩이에요.","2 + ⟨3/5⟩ = ⟨2 3/5⟩.","방법 2 — 가분수로 바꾸면 ⟨6/5⟩ + ⟨7/5⟩ = ⟨13/5⟩ = ⟨2 3/5⟩."],"variant_rule":{"alt":[{"stem":"「익힘」 ⟨1 2/6⟩ + ⟨1 3/6⟩ = ⟨2 □/6⟩ — □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["방법 1 — 자연수끼리 1 + 1 = 2, 분수끼리 ⟨2/6⟩ + ⟨3/6⟩ = ⟨5/6⟩예요.","2 + ⟨5/6⟩ = ⟨2 5/6⟩.","방법 2 — 가분수로 바꾸면 ⟨8/6⟩ + ⟨9/6⟩ = ⟨17/6⟩ = ⟨2 5/6⟩."]},{"stem":"⟨1 2/8⟩ + ⟨3 1/8⟩ = ⟨4 □/8⟩ — □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["방법 1 — 자연수끼리 1 + 3 = 4, 분수끼리 ⟨2/8⟩ + ⟨1/8⟩ = ⟨3/8⟩이에요.","4 + ⟨3/8⟩ = ⟨4 3/8⟩.","방법 2 — 가분수로 바꾸면 ⟨10/8⟩ + ⟨25/8⟩ = ⟨35/8⟩ = ⟨4 3/8⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L05_basic#2','math',4,2,'u1','L05','tb_g4_2_math_u1_L05_basic','lesson_basic','M4-2-u1-C5',1,'mc','auto','⟨2 3/4⟩ + ⟨1 2/4⟩를 계산해 보세요.',ARRAY['M4-2-u1-X01','M4-2-u1-X07','M4-2-u1-X04']::text[],true,'{"seq":2,"concept":"M4-2-u1-C5","difficulty":1,"kind":"mc","stem":"⟨2 3/4⟩ + ⟨1 2/4⟩를 계산해 보세요.","options":[{"t":"⟨4 1/4⟩","correct":true},{"t":"⟨3 5/8⟩","mis":"M4-2-u1-X01"},{"t":"⟨3 1/4⟩","mis":"M4-2-u1-X07"},{"t":"⟨5 1/4⟩","mis":"M4-2-u1-X04"}],"explanation":["방법 1 — 자연수끼리 2 + 1 = 3, 분수끼리 ⟨3/4⟩ + ⟨2/4⟩ = ⟨5/4⟩예요.","⟨5/4⟩ = ⟨1 1/4⟩ — 넘친 1을 자연수에 더해 3 + ⟨1 1/4⟩ = ⟨4 1/4⟩.","방법 2 — 가분수로 바꾸면 ⟨11/4⟩ + ⟨6/4⟩ = ⟨17/4⟩ = ⟨4 1/4⟩."],"variant_rule":{"alt":[{"stem":"⟨1 6/7⟩ + ⟨1 3/7⟩을 계산해 보세요.","options":[{"t":"⟨3 2/7⟩","correct":true},{"t":"⟨2 9/14⟩","mis":"M4-2-u1-X01"},{"t":"⟨2 2/7⟩","mis":"M4-2-u1-X07"},{"t":"⟨4 2/7⟩","mis":"M4-2-u1-X04"}],"explanation":["방법 1 — 자연수끼리 1 + 1 = 2, 분수끼리 ⟨6/7⟩ + ⟨3/7⟩ = ⟨9/7⟩예요.","⟨9/7⟩ = ⟨1 2/7⟩ — 넘친 1을 자연수에 더해 2 + ⟨1 2/7⟩ = ⟨3 2/7⟩.","방법 2 — 가분수로 바꾸면 ⟨13/7⟩ + ⟨10/7⟩ = ⟨23/7⟩ = ⟨3 2/7⟩."]},{"stem":"⟨2 4/6⟩ + ⟨2 3/6⟩을 계산해 보세요.","options":[{"t":"⟨5 1/6⟩","correct":true},{"t":"⟨4 7/12⟩","mis":"M4-2-u1-X01"},{"t":"⟨4 1/6⟩","mis":"M4-2-u1-X07"},{"t":"⟨6 1/6⟩","mis":"M4-2-u1-X04"}],"explanation":["방법 1 — 자연수끼리 2 + 2 = 4, 분수끼리 ⟨4/6⟩ + ⟨3/6⟩ = ⟨7/6⟩이에요.","⟨7/6⟩ = ⟨1 1/6⟩ — 넘친 1을 자연수에 더해 4 + ⟨1 1/6⟩ = ⟨5 1/6⟩.","방법 2 — 가분수로 바꾸면 ⟨16/6⟩ + ⟨15/6⟩ = ⟨31/6⟩ = ⟨5 1/6⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L05_basic#3','math',4,2,'u1','L05','tb_g4_2_math_u1_L05_basic','lesson_basic','M4-2-u1-C5',1,'mc','auto','「확인 문제」 ⟨2 5/9⟩ + ⟨3 2/9⟩를 계산해 보세요.',ARRAY['M4-2-u1-X01','M4-2-u1-X13','M4-2-u1-X16']::text[],true,'{"seq":3,"concept":"M4-2-u1-C5","difficulty":1,"kind":"mc","stem":"「확인 문제」 ⟨2 5/9⟩ + ⟨3 2/9⟩를 계산해 보세요.","options":[{"t":"⟨5 7/9⟩","correct":true},{"t":"⟨5 7/18⟩","mis":"M4-2-u1-X01"},{"t":"⟨7/9⟩","mis":"M4-2-u1-X13"},{"t":"⟨5 8/9⟩","mis":"M4-2-u1-X16"}],"explanation":["방법 1 — 자연수끼리 2 + 3 = 5, 분수끼리 ⟨5/9⟩ + ⟨2/9⟩ = ⟨7/9⟩이에요.","5 + ⟨7/9⟩ = ⟨5 7/9⟩.","방법 2 — 가분수로 바꾸면 ⟨23/9⟩ + ⟨29/9⟩ = ⟨52/9⟩ = ⟨5 7/9⟩."],"variant_rule":{"alt":[{"stem":"「익힘」 ⟨1 1/4⟩ + ⟨2 2/4⟩를 계산해 보세요.","options":[{"t":"⟨3 3/4⟩","correct":true},{"t":"⟨3 3/8⟩","mis":"M4-2-u1-X01"},{"t":"⟨3/4⟩","mis":"M4-2-u1-X13"},{"t":"4","mis":"M4-2-u1-X16"}],"explanation":["방법 1 — 자연수끼리 1 + 2 = 3, 분수끼리 ⟨1/4⟩ + ⟨2/4⟩ = ⟨3/4⟩이에요.","3 + ⟨3/4⟩ = ⟨3 3/4⟩.","방법 2 — 가분수로 바꾸면 ⟨5/4⟩ + ⟨10/4⟩ = ⟨15/4⟩ = ⟨3 3/4⟩."]},{"stem":"「익힘」 ⟨2 4/5⟩ + ⟨3 2/5⟩를 계산해 보세요.","options":[{"t":"⟨6 1/5⟩","correct":true},{"t":"⟨5 6/10⟩","mis":"M4-2-u1-X01"},{"t":"⟨5 1/5⟩","mis":"M4-2-u1-X07"},{"t":"⟨7 1/5⟩","mis":"M4-2-u1-X04"}],"explanation":["방법 1 — 자연수끼리 2 + 3 = 5, 분수끼리 ⟨4/5⟩ + ⟨2/5⟩ = ⟨6/5⟩이에요.","⟨6/5⟩ = ⟨1 1/5⟩ — 넘친 1을 자연수에 더해 5 + ⟨1 1/5⟩ = ⟨6 1/5⟩.","방법 2 — 가분수로 바꾸면 ⟨14/5⟩ + ⟨17/5⟩ = ⟨31/5⟩ = ⟨6 1/5⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L05_basic#4','math',4,2,'u1','L05','tb_g4_2_math_u1_L05_basic','lesson_basic','M4-2-u1-C5',1,'sa','auto','⟨2 3/4⟩ + ⟨1 2/4⟩를 가분수로 바꾸어 계산하려고 해요. ⟨2 3/4⟩ + ⟨1 2/4⟩ = ⟨11/4⟩ + ⟨□/4⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u1-C5","difficulty":1,"kind":"sa","stem":"⟨2 3/4⟩ + ⟨1 2/4⟩를 가분수로 바꾸어 계산하려고 해요. ⟨2 3/4⟩ + ⟨1 2/4⟩ = ⟨11/4⟩ + ⟨□/4⟩ — □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["⟨1 2/4⟩에서 자연수 1은 ⟨1/4⟩이 4개, ⟨2/4⟩는 ⟨1/4⟩이 2개 — ⟨1 2/4⟩ = ⟨6/4⟩이에요.","그래서 □ = 6이에요.","⟨11/4⟩ + ⟨6/4⟩ = ⟨17/4⟩ = ⟨4 1/4⟩이에요."],"variant_rule":{"alt":[{"stem":"「익힘」 ⟨1 2/6⟩ + ⟨1 3/6⟩을 가분수로 바꾸어 계산하려고 해요. ⟨1 2/6⟩ + ⟨1 3/6⟩ = ⟨8/6⟩ + ⟨□/6⟩ — □에 알맞은 수를 쓰세요.","answer":["9"],"explanation":["⟨1 3/6⟩에서 자연수 1은 ⟨1/6⟩이 6개, ⟨3/6⟩은 ⟨1/6⟩이 3개 — ⟨1 3/6⟩ = ⟨9/6⟩예요.","그래서 □ = 9예요.","⟨8/6⟩ + ⟨9/6⟩ = ⟨17/6⟩ = ⟨2 5/6⟩예요."]},{"stem":"「익힘」 ⟨1 4/5⟩ + ⟨1 3/5⟩을 가분수로 바꾸어 계산하려고 해요. ⟨1 4/5⟩ + ⟨1 3/5⟩ = ⟨9/5⟩ + ⟨□/5⟩ — □에 알맞은 수를 쓰세요.","answer":["8"],"explanation":["⟨1 3/5⟩에서 자연수 1은 ⟨1/5⟩이 5개, ⟨3/5⟩은 ⟨1/5⟩이 3개 — ⟨1 3/5⟩ = ⟨8/5⟩이에요.","그래서 □ = 8이에요.","⟨9/5⟩ + ⟨8/5⟩ = ⟨17/5⟩ = ⟨3 2/5⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L05_basic#5','math',4,2,'u1','L05','tb_g4_2_math_u1_L05_basic','lesson_basic','M4-2-u1-C5',2,'mc','auto','「확인 문제」 찬혁이는 물을 아침에 ⟨1 2/10⟩ L, 점심에 ⟨1 4/10⟩ L 마셨어요. 찬혁이가 아침과 점심에 마신 물은 모두 몇 L인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X13','M4-2-u1-X16']::text[],true,'{"seq":5,"concept":"M4-2-u1-C5","difficulty":2,"kind":"mc","stem":"「확인 문제」 찬혁이는 물을 아침에 ⟨1 2/10⟩ L, 점심에 ⟨1 4/10⟩ L 마셨어요. 찬혁이가 아침과 점심에 마신 물은 모두 몇 L인가요?","options":[{"t":"⟨2 6/10⟩ L","correct":true},{"t":"⟨2 6/20⟩ L","mis":"M4-2-u1-X01"},{"t":"⟨6/10⟩ L","mis":"M4-2-u1-X13"},{"t":"⟨2 7/10⟩ L","mis":"M4-2-u1-X16"}],"explanation":["방법 1 — 자연수끼리 1 + 1 = 2, 분수끼리 ⟨2/10⟩ + ⟨4/10⟩ = ⟨6/10⟩이에요.","2 + ⟨6/10⟩ = ⟨2 6/10⟩ L.","방법 2 — 가분수로 바꾸면 ⟨12/10⟩ + ⟨14/10⟩ = ⟨26/10⟩ = ⟨2 6/10⟩ L."],"variant_rule":{"alt":[{"stem":"「익힘」 미술 작품을 만드는 데 철사를 지유는 ⟨2 4/10⟩ m, 건우는 ⟨1 7/10⟩ m 사용했어요. 지유와 건우가 사용한 철사는 모두 몇 m인가요?","options":[{"t":"⟨4 1/10⟩ m","correct":true},{"t":"⟨3 11/20⟩ m","mis":"M4-2-u1-X01"},{"t":"⟨3 1/10⟩ m","mis":"M4-2-u1-X07"},{"t":"⟨5 1/10⟩ m","mis":"M4-2-u1-X04"}],"explanation":["방법 1 — 자연수끼리 2 + 1 = 3, 분수끼리 ⟨4/10⟩ + ⟨7/10⟩ = ⟨11/10⟩이에요.","⟨11/10⟩ = ⟨1 1/10⟩ — 넘친 1을 자연수에 더해 3 + ⟨1 1/10⟩ = ⟨4 1/10⟩ m.","방법 2 — 가분수로 바꾸면 ⟨24/10⟩ + ⟨17/10⟩ = ⟨41/10⟩ = ⟨4 1/10⟩ m."]},{"stem":"「단원 도입」 사과를 한 상자에는 ⟨1 3/4⟩ kg, 다른 상자에는 ⟨2 2/4⟩ kg 땄어요. 딴 사과는 모두 몇 kg인가요?","options":[{"t":"⟨4 1/4⟩ kg","correct":true},{"t":"⟨3 5/8⟩ kg","mis":"M4-2-u1-X01"},{"t":"⟨3 1/4⟩ kg","mis":"M4-2-u1-X07"},{"t":"⟨5 1/4⟩ kg","mis":"M4-2-u1-X04"}],"explanation":["방법 1 — 자연수끼리 1 + 2 = 3, 분수끼리 ⟨3/4⟩ + ⟨2/4⟩ = ⟨5/4⟩예요.","⟨5/4⟩ = ⟨1 1/4⟩ — 넘친 1을 자연수에 더해 3 + ⟨1 1/4⟩ = ⟨4 1/4⟩ kg.","방법 2 — 가분수로 바꾸면 ⟨7/4⟩ + ⟨10/4⟩ = ⟨17/4⟩ = ⟨4 1/4⟩ kg."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L05_basic#6','math',4,2,'u1','L05','tb_g4_2_math_u1_L05_basic','lesson_basic','M4-2-u1-C5',2,'ox','auto','도윤이는 「⟨1 6/7⟩ + ⟨1 3/7⟩ = ⟨2 2/7⟩야.」라고 했어요. 도윤이의 말이 옳은가요?',ARRAY['M4-2-u1-X07']::text[],false,'{"seq":6,"concept":"M4-2-u1-C5","difficulty":2,"kind":"ox","stem":"도윤이는 「⟨1 6/7⟩ + ⟨1 3/7⟩ = ⟨2 2/7⟩야.」라고 했어요. 도윤이의 말이 옳은가요?","answer":"X","reason_options":[{"t":"분수끼리 더한 ⟨9/7⟩ = ⟨1 2/7⟩의 1을 자연수에 더해야 해서","correct":true},{"t":"자연수끼리만 더하고 넘친 분수는 그대로 두면 되어서","mis":"M4-2-u1-X07"}],"mis":"M4-2-u1-X07","explanation":["방법 1 — 자연수끼리 1 + 1 = 2, 분수끼리 ⟨6/7⟩ + ⟨3/7⟩ = ⟨9/7⟩예요.","⟨9/7⟩ = ⟨1 2/7⟩ — 넘친 1을 자연수에 더해 2 + ⟨1 2/7⟩ = ⟨3 2/7⟩.","방법 2 — 가분수로 바꾸면 ⟨13/7⟩ + ⟨10/7⟩ = ⟨23/7⟩ = ⟨3 2/7⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L05_basic#7','math',4,2,'u1','L05','tb_g4_2_math_u1_L05_basic','lesson_basic','M4-2-u1-C5',2,'mc','auto','⟨2 3/4⟩ + ⟨1 2/4⟩를 자연수끼리, 분수끼리 더했더니 자연수는 3, 분수는 ⟨5/4⟩가 되었어요. 계산 결과를 대분수로 바르게 나타낸 것은 무엇인가요?',ARRAY['M4-2-u1-X07','M4-2-u1-X04']::text[],false,'{"seq":7,"concept":"M4-2-u1-C5","difficulty":2,"kind":"mc","stem":"⟨2 3/4⟩ + ⟨1 2/4⟩를 자연수끼리, 분수끼리 더했더니 자연수는 3, 분수는 ⟨5/4⟩가 되었어요. 계산 결과를 대분수로 바르게 나타낸 것은 무엇인가요?","options":[{"t":"⟨4 1/4⟩","correct":true},{"t":"⟨3 5/4⟩","mis":"M4-2-u1-X07"},{"t":"⟨3 1/4⟩","mis":"M4-2-u1-X07"},{"t":"⟨5 1/4⟩","mis":"M4-2-u1-X04"}],"explanation":["⟨5/4⟩ = ⟨1 1/4⟩ — 1보다 큰 가분수예요.","3 + ⟨1 1/4⟩ = ⟨4 1/4⟩ — 넘친 1을 자연수에 더해요.","⟨3 5/4⟩는 분수 부분이 가분수라 바르게 나타낸 대분수가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L05_basic#8','math',4,2,'u1','L05','tb_g4_2_math_u1_L05_basic','lesson_basic','M4-2-u1-C5',2,'mc','auto','「익힘」 계산 결과가 가장 큰 것은 무엇인가요?',ARRAY['M4-2-u1-X15','M4-2-u1-X07']::text[],false,'{"seq":8,"concept":"M4-2-u1-C5","difficulty":2,"kind":"mc","stem":"「익힘」 계산 결과가 가장 큰 것은 무엇인가요?","options":[{"t":"⟨2 4/7⟩ + ⟨4 2/7⟩","correct":true},{"t":"⟨3 1/7⟩ + ⟨1 4/7⟩","mis":"M4-2-u1-X15"},{"t":"⟨4 2/7⟩ + ⟨1 6/7⟩","mis":"M4-2-u1-X07"},{"t":"⟨2 4/7⟩ + ⟨3 5/7⟩","mis":"M4-2-u1-X07"}],"explanation":["⟨3 1/7⟩ + ⟨1 4/7⟩ = ⟨4 5/7⟩, ⟨2 4/7⟩ + ⟨4 2/7⟩ = ⟨6 6/7⟩이에요.","⟨4 2/7⟩ + ⟨1 6/7⟩ = ⟨6 1/7⟩, ⟨2 4/7⟩ + ⟨3 5/7⟩ = ⟨6 2/7⟩예요 — 분수끼리의 합이 1보다 커서 자연수가 1 커졌어요.","가장 큰 것은 ⟨6 6/7⟩인 ⟨2 4/7⟩ + ⟨4 2/7⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L05_basic#9','math',4,2,'u1','L05','tb_g4_2_math_u1_L05_basic','lesson_basic','M4-2-u1-C5',2,'sa','auto','「확인 문제」 ⟨6 1/4⟩ + ⟨4 3/4⟩ = □ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u1-C5","difficulty":2,"kind":"sa","stem":"「확인 문제」 ⟨6 1/4⟩ + ⟨4 3/4⟩ = □ — □에 알맞은 수를 쓰세요.","answer":["11"],"explanation":["방법 1 — 자연수끼리 6 + 4 = 10, 분수끼리 ⟨1/4⟩ + ⟨3/4⟩ = ⟨4/4⟩예요.","⟨4/4⟩ = 1 — 자연수에 1을 더해 10 + 1 = 11.","방법 2 — 가분수로 바꾸면 ⟨25/4⟩ + ⟨19/4⟩ = ⟨44/4⟩ = 11."],"variant_rule":{"alt":[{"stem":"「익힘」 ⟨1 3/6⟩ + ⟨2 3/6⟩ = □ — □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["방법 1 — 자연수끼리 1 + 2 = 3, 분수끼리 ⟨3/6⟩ + ⟨3/6⟩ = ⟨6/6⟩이에요.","⟨6/6⟩ = 1 — 자연수에 1을 더해 3 + 1 = 4.","방법 2 — 가분수로 바꾸면 ⟨9/6⟩ + ⟨15/6⟩ = ⟨24/6⟩ = 4."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L05_basic#10','math',4,2,'u1','L05','tb_g4_2_math_u1_L05_basic','lesson_basic','M4-2-u1-C5',3,'mc','auto','「지도서 평가」 ⟨1 5/7⟩ + ⟨1 3/7⟩을 대분수를 가분수로 바꾸어 바르게 계산한 것은 무엇인가요?',ARRAY['M4-2-u1-X03','M4-2-u1-X01','M4-2-u1-X04']::text[],false,'{"seq":10,"concept":"M4-2-u1-C5","difficulty":3,"kind":"mc","stem":"「지도서 평가」 ⟨1 5/7⟩ + ⟨1 3/7⟩을 대분수를 가분수로 바꾸어 바르게 계산한 것은 무엇인가요?","options":[{"t":"⟨12/7⟩ + ⟨10/7⟩ = ⟨22/7⟩ = ⟨3 1/7⟩","correct":true},{"t":"⟨6/7⟩ + ⟨4/7⟩ = ⟨10/7⟩ = ⟨1 3/7⟩","mis":"M4-2-u1-X03"},{"t":"⟨12/7⟩ + ⟨10/7⟩ = ⟨22/14⟩","mis":"M4-2-u1-X01"},{"t":"⟨12/7⟩ + ⟨10/7⟩ = ⟨22/7⟩ = ⟨2 1/7⟩","mis":"M4-2-u1-X04"}],"explanation":["1 = ⟨7/7⟩이라 ⟨1 5/7⟩ = ⟨12/7⟩, ⟨1 3/7⟩ = ⟨10/7⟩이에요.","⟨12/7⟩ + ⟨10/7⟩ = ⟨22/7⟩ — 분모는 그대로예요.","⟨22/7⟩는 ⟨7/7⟩이 3번, ⟨1/7⟩이 1개 — ⟨3 1/7⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L05_challenge#1','math',4,2,'u1','L05','tb_g4_2_math_u1_L05_challenge','lesson_challenge','M4-2-u1-C5',2,'mc','auto','「확인 문제」 ⟨1 9/12⟩ + ⟨3 6/12⟩을 계산해 보세요.',ARRAY['M4-2-u1-X01','M4-2-u1-X07','M4-2-u1-X04']::text[],true,'{"seq":1,"concept":"M4-2-u1-C5","difficulty":2,"kind":"mc","stem":"「확인 문제」 ⟨1 9/12⟩ + ⟨3 6/12⟩을 계산해 보세요.","options":[{"t":"⟨5 3/12⟩","correct":true},{"t":"⟨4 15/24⟩","mis":"M4-2-u1-X01"},{"t":"⟨4 3/12⟩","mis":"M4-2-u1-X07"},{"t":"⟨6 3/12⟩","mis":"M4-2-u1-X04"}],"explanation":["방법 1 — 자연수끼리 1 + 3 = 4, 분수끼리 ⟨9/12⟩ + ⟨6/12⟩ = ⟨15/12⟩예요.","⟨15/12⟩ = ⟨1 3/12⟩ — 넘친 1을 자연수에 더해 4 + ⟨1 3/12⟩ = ⟨5 3/12⟩.","방법 2 — 가분수로 바꾸면 ⟨21/12⟩ + ⟨42/12⟩ = ⟨63/12⟩ = ⟨5 3/12⟩."],"variant_rule":{"alt":[{"stem":"「익힘」 ⟨1 4/5⟩ + ⟨1 3/5⟩을 계산해 보세요.","options":[{"t":"⟨3 2/5⟩","correct":true},{"t":"⟨2 7/10⟩","mis":"M4-2-u1-X01"},{"t":"⟨2 2/5⟩","mis":"M4-2-u1-X07"},{"t":"⟨4 2/5⟩","mis":"M4-2-u1-X04"}],"explanation":["방법 1 — 자연수끼리 1 + 1 = 2, 분수끼리 ⟨4/5⟩ + ⟨3/5⟩ = ⟨7/5⟩이에요.","⟨7/5⟩ = ⟨1 2/5⟩ — 넘친 1을 자연수에 더해 2 + ⟨1 2/5⟩ = ⟨3 2/5⟩.","방법 2 — 가분수로 바꾸면 ⟨9/5⟩ + ⟨8/5⟩ = ⟨17/5⟩ = ⟨3 2/5⟩."]},{"stem":"「익힘 퐁당」 ⟨1 3/8⟩ + ⟨2 4/8⟩를 계산해 보세요.","options":[{"t":"⟨3 7/8⟩","correct":true},{"t":"⟨3 7/16⟩","mis":"M4-2-u1-X01"},{"t":"⟨7/8⟩","mis":"M4-2-u1-X13"},{"t":"4","mis":"M4-2-u1-X16"}],"explanation":["방법 1 — 자연수끼리 1 + 2 = 3, 분수끼리 ⟨3/8⟩ + ⟨4/8⟩ = ⟨7/8⟩이에요.","3 + ⟨7/8⟩ = ⟨3 7/8⟩.","방법 2 — 가분수로 바꾸면 ⟨11/8⟩ + ⟨20/8⟩ = ⟨31/8⟩ = ⟨3 7/8⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L05_challenge#2','math',4,2,'u1','L05','tb_g4_2_math_u1_L05_challenge','lesson_challenge','M4-2-u1-C5',2,'mc','auto','「지도서」 ⟨1 1/5⟩ + ⟨1 2/5⟩는 ⟨1/5⟩ + ⟨2/5⟩보다 얼마 더 큰가요?',ARRAY['M4-2-u1-X13','M4-2-u1-X16','M4-2-u1-X15']::text[],false,'{"seq":2,"concept":"M4-2-u1-C5","difficulty":2,"kind":"mc","stem":"「지도서」 ⟨1 1/5⟩ + ⟨1 2/5⟩는 ⟨1/5⟩ + ⟨2/5⟩보다 얼마 더 큰가요?","options":[{"t":"2","correct":true},{"t":"1","mis":"M4-2-u1-X13"},{"t":"3","mis":"M4-2-u1-X16"},{"t":"⟨2 3/5⟩","mis":"M4-2-u1-X15"}],"explanation":["⟨1/5⟩ + ⟨2/5⟩ = ⟨3/5⟩이에요.","⟨1 1/5⟩ + ⟨1 2/5⟩ = ⟨2 3/5⟩ — 자연수끼리 1 + 1 = 2가 더 있어요.","⟨2 3/5⟩ − ⟨3/5⟩ = 2 — 2만큼 더 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L05_challenge#3','math',4,2,'u1','L05','tb_g4_2_math_u1_L05_challenge','lesson_challenge','M4-2-u1-C5',3,'mc','auto','「익힘」 ⟨3 1/9⟩, ⟨25/9⟩, ⟨2 4/9⟩ 중에서 분수를 2개 골라 계산 결과가 가장 큰 덧셈식을 만들었어요. 계산 결과는 얼마인가요?',ARRAY['M4-2-u1-X17','M4-2-u1-X15','M4-2-u1-X01']::text[],false,'{"seq":3,"concept":"M4-2-u1-C5","difficulty":3,"kind":"mc","stem":"「익힘」 ⟨3 1/9⟩, ⟨25/9⟩, ⟨2 4/9⟩ 중에서 분수를 2개 골라 계산 결과가 가장 큰 덧셈식을 만들었어요. 계산 결과는 얼마인가요?","options":[{"t":"⟨5 8/9⟩","correct":true},{"t":"⟨5 5/9⟩","mis":"M4-2-u1-X17"},{"t":"⟨5 2/9⟩","mis":"M4-2-u1-X15"},{"t":"⟨5 8/18⟩","mis":"M4-2-u1-X01"}],"explanation":["⟨25/9⟩ = ⟨2 7/9⟩ — 세 수의 크기는 ⟨3 1/9⟩ > ⟨25/9⟩ > ⟨2 4/9⟩예요.","가장 큰 수와 둘째로 큰 수를 골라 더해요.","⟨3 1/9⟩ + ⟨25/9⟩ = ⟨3 1/9⟩ + ⟨2 7/9⟩ = ⟨5 8/9⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L05_challenge#4','math',4,2,'u1','L05','tb_g4_2_math_u1_L05_challenge','lesson_challenge','M4-2-u1-C5',3,'error','auto','「익힘 퐁당」 ⟨1 3/8⟩ + ⟨2 4/8⟩를 2가지 방법으로 계산하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u1-X03','M4-2-u1-X15']::text[],false,'{"seq":4,"concept":"M4-2-u1-C5","difficulty":3,"kind":"error","stem":"「익힘 퐁당」 ⟨1 3/8⟩ + ⟨2 4/8⟩를 2가지 방법으로 계산하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은비 — 「⟨1 3/8⟩을 가분수로 바꾸면 ⟨4/8⟩야.」","correct":true,"mis_target":"M4-2-u1-X03"},{"t":"도윤 — 「자연수끼리 1 + 2 = 3이야.」","mis":"M4-2-u1-X15"},{"t":"지유 — 「분수끼리 ⟨3/8⟩ + ⟨4/8⟩ = ⟨7/8⟩이야.」","mis":"M4-2-u1-X15"},{"t":"건우 — 「가분수로 바꾸면 ⟨11/8⟩ + ⟨20/8⟩ = ⟨31/8⟩이야.」","mis":"M4-2-u1-X15"}],"explanation":["1 = ⟨8/8⟩이라 ⟨1 3/8⟩ = ⟨11/8⟩이에요.","방법 1은 3 + ⟨7/8⟩ = ⟨3 7/8⟩, 방법 2는 ⟨31/8⟩ = ⟨3 7/8⟩이에요.","은비는 자연수 1을 ⟨1/8⟩ 1개로 셌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L05_challenge#5','math',4,2,'u1','L05','tb_g4_2_math_u1_L05_challenge','lesson_challenge','M4-2-u1-C5',3,'sa','auto','「익힘」 미술 작품을 만드는 데 철사를 지유는 ⟨2 4/10⟩ m, 건우는 ⟨1 7/10⟩ m 사용했어요. 두 사람이 사용한 철사의 길이의 합을 가분수로 나타내면 ⟨□/10⟩ m예요. □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M4-2-u1-C5","difficulty":3,"kind":"sa","stem":"「익힘」 미술 작품을 만드는 데 철사를 지유는 ⟨2 4/10⟩ m, 건우는 ⟨1 7/10⟩ m 사용했어요. 두 사람이 사용한 철사의 길이의 합을 가분수로 나타내면 ⟨□/10⟩ m예요. □에 알맞은 수를 쓰세요.","answer":["41"],"explanation":["⟨2 4/10⟩ = ⟨24/10⟩, ⟨1 7/10⟩ = ⟨17/10⟩이에요.","⟨24/10⟩ + ⟨17/10⟩ = ⟨41/10⟩이에요.","⟨41/10⟩ = ⟨4 1/10⟩ — □ = 41."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L05_challenge#6','math',4,2,'u1','L05','tb_g4_2_math_u1_L05_challenge','lesson_challenge','M4-2-u1-C5',3,'ox','auto','채원이는 「⟨1 4/5⟩ + ⟨1 3/5⟩을 가분수로 바꾸면 ⟨9/5⟩ + ⟨8/5⟩이야.」라고 했어요. 채원이의 말이 옳은가요?',ARRAY['M4-2-u1-X03']::text[],false,'{"seq":6,"concept":"M4-2-u1-C5","difficulty":3,"kind":"ox","stem":"채원이는 「⟨1 4/5⟩ + ⟨1 3/5⟩을 가분수로 바꾸면 ⟨9/5⟩ + ⟨8/5⟩이야.」라고 했어요. 채원이의 말이 옳은가요?","answer":"O","reason_options":[{"t":"1은 ⟨5/5⟩라 ⟨1 4/5⟩는 ⟨1/5⟩이 9개라서","correct":true},{"t":"자연수 1과 분자 4를 더하면 되어서","mis":"M4-2-u1-X03"}],"mis":"M4-2-u1-X03","explanation":["1 = ⟨5/5⟩ — ⟨1 4/5⟩는 ⟨1/5⟩이 5 + 4 = 9개예요.","⟨1 3/5⟩은 ⟨1/5⟩이 5 + 3 = 8개 — ⟨8/5⟩이에요.","⟨9/5⟩ + ⟨8/5⟩ = ⟨17/5⟩ = ⟨3 2/5⟩ — 채원이의 말이 옳아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L05_challenge#7','math',4,2,'u1','L05','tb_g4_2_math_u1_L05_challenge','lesson_challenge','M4-2-u1-C5',3,'mc','auto','진분수끼리의 합이 1보다 커서 1을 자연수로 넘겨야 하는 덧셈은 무엇인가요?',ARRAY['M4-2-u1-X17']::text[],false,'{"seq":7,"concept":"M4-2-u1-C5","difficulty":3,"kind":"mc","stem":"진분수끼리의 합이 1보다 커서 1을 자연수로 넘겨야 하는 덧셈은 무엇인가요?","options":[{"t":"⟨4 2/7⟩ + ⟨1 6/7⟩","correct":true},{"t":"⟨3 1/7⟩ + ⟨1 4/7⟩","mis":"M4-2-u1-X17"},{"t":"⟨2 4/7⟩ + ⟨4 2/7⟩","mis":"M4-2-u1-X17"},{"t":"⟨1 2/8⟩ + ⟨3 1/8⟩","mis":"M4-2-u1-X17"}],"explanation":["분수 부분끼리 더해 분모보다 커지면 1을 자연수로 넘겨요.","⟨2/7⟩ + ⟨6/7⟩ = ⟨8/7⟩ = ⟨1 1/7⟩이에요.","⟨1/7⟩ + ⟨4/7⟩ = ⟨5/7⟩, ⟨4/7⟩ + ⟨2/7⟩ = ⟨6/7⟩, ⟨2/8⟩ + ⟨1/8⟩ = ⟨3/8⟩은 1보다 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L05_challenge#8','math',4,2,'u1','L05','tb_g4_2_math_u1_L05_challenge','lesson_challenge','M4-2-u1-C5',4,'essay','teacher','⟨2 3/4⟩ + ⟨1 2/4⟩를 2가지 방법으로 계산하고, 두 방법을 비교해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u1-C5","difficulty":4,"kind":"essay","stem":"⟨2 3/4⟩ + ⟨1 2/4⟩를 2가지 방법으로 계산하고, 두 방법을 비교해 보세요.","answer_guide":{"answer":"예: 방법 1 — 자연수끼리 2 + 1 = 3, 분수끼리 ⟨3/4⟩ + ⟨2/4⟩ = ⟨5/4⟩ = ⟨1 1/4⟩이므로 3 + ⟨1 1/4⟩ = ⟨4 1/4⟩이다. 방법 2 — 가분수로 바꾸면 ⟨11/4⟩ + ⟨6/4⟩ = ⟨17/4⟩ = ⟨4 1/4⟩이다. 방법 1은 자연수 부분끼리 진분수 부분끼리 더하고, 방법 2는 대분수를 가분수로 바꾸어 더한다.","scoring_points":["자연수끼리·분수끼리 더해 ⟨4 1/4⟩을 구했는가","가분수로 바꾸어 ⟨17/4⟩ = ⟨4 1/4⟩을 구했는가","두 방법의 차이를 썼는가"]},"explanation":["3 + ⟨5/4⟩ = ⟨4 1/4⟩이에요.","⟨11/4⟩ + ⟨6/4⟩ = ⟨17/4⟩이에요.","두 방법의 답은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L05_challenge#9','math',4,2,'u1','L05','tb_g4_2_math_u1_L05_challenge','lesson_challenge','M4-2-u1-C5',4,'essay','teacher','「익힘」 ⟨3 1/9⟩, ⟨25/9⟩, ⟨2 4/9⟩ 중에서 분수를 2개 골라 계산 결과가 가장 큰 덧셈식을 만들고, 그렇게 고른 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u1-C5","difficulty":4,"kind":"essay","stem":"「익힘」 ⟨3 1/9⟩, ⟨25/9⟩, ⟨2 4/9⟩ 중에서 분수를 2개 골라 계산 결과가 가장 큰 덧셈식을 만들고, 그렇게 고른 까닭을 설명해 보세요.","answer_guide":{"answer":"예: ⟨25/9⟩ = ⟨2 7/9⟩이므로 세 수의 크기는 ⟨3 1/9⟩ > ⟨25/9⟩ > ⟨2 4/9⟩이다. 합이 가장 크려면 가장 큰 수와 둘째로 큰 수를 더해야 하므로 ⟨3 1/9⟩ + ⟨25/9⟩ = ⟨5 8/9⟩이다.","scoring_points":["⟨25/9⟩를 대분수로(또는 모두 가분수로) 바꾸어 크기를 견주었는가","가장 큰 수와 둘째로 큰 수를 골랐는가","⟨5 8/9⟩을 구했는가"]},"explanation":["⟨25/9⟩ = ⟨2 7/9⟩이에요.","큰 두 수를 골라요.","⟨3 1/9⟩ + ⟨25/9⟩ = ⟨5 8/9⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L05_challenge#10','math',4,2,'u1','L05','tb_g4_2_math_u1_L05_challenge','lesson_challenge','M4-2-u1-C5',4,'essay','teacher','「확인 문제」 찬혁이는 물을 아침에 ⟨1 2/10⟩ L, 점심에 ⟨1 4/10⟩ L 마셨어요. 찬혁이가 아침과 점심에 마신 물은 모두 몇 L인지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u1-C5","difficulty":4,"kind":"essay","stem":"「확인 문제」 찬혁이는 물을 아침에 ⟨1 2/10⟩ L, 점심에 ⟨1 4/10⟩ L 마셨어요. 찬혁이가 아침과 점심에 마신 물은 모두 몇 L인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 모두 몇 L인지 구하려면 두 양을 더한다. ⟨1 2/10⟩ + ⟨1 4/10⟩ = (1 + 1) + (⟨2/10⟩ + ⟨4/10⟩) = 2 + ⟨6/10⟩ = ⟨2 6/10⟩이다. 찬혁이가 마신 물은 모두 ⟨2 6/10⟩ L이다.","scoring_points":["덧셈식을 세웠는가","자연수끼리·분수끼리(또는 가분수로) 계산했는가","⟨2 6/10⟩ L라고 답했는가"]},"explanation":["모두 = 덧셈이에요.","⟨1 2/10⟩ + ⟨1 4/10⟩ = ⟨2 6/10⟩이에요.","⟨2 6/10⟩ L예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L06_basic#1','math',4,2,'u1','L06','tb_g4_2_math_u1_L06_basic','lesson_basic','M4-2-u1-C6',1,'sa','auto','⟨2 3/4⟩ − ⟨1 1/4⟩ = ⟨1 □/4⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u1-C6","difficulty":1,"kind":"sa","stem":"⟨2 3/4⟩ − ⟨1 1/4⟩ = ⟨1 □/4⟩ — □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["방법 1 — 자연수끼리 2 − 1 = 1, 분수끼리 ⟨3/4⟩ − ⟨1/4⟩ = ⟨2/4⟩예요.","1 + ⟨2/4⟩ = ⟨1 2/4⟩.","방법 2 — 가분수로 바꾸면 ⟨11/4⟩ − ⟨5/4⟩ = ⟨6/4⟩ = ⟨1 2/4⟩."],"asset":{"type":"fbar","bars":[{"den":4,"num":4},{"den":4,"num":4},{"den":4,"num":3,"label":"⟨2 3/4⟩"}]},"variant_rule":{"alt":[{"stem":"「익힘」 ⟨2 4/5⟩ − ⟨1 1/5⟩ = ⟨1 □/5⟩ — □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["방법 1 — 자연수끼리 2 − 1 = 1, 분수끼리 ⟨4/5⟩ − ⟨1/5⟩ = ⟨3/5⟩이에요.","1 + ⟨3/5⟩ = ⟨1 3/5⟩.","방법 2 — 가분수로 바꾸면 ⟨14/5⟩ − ⟨6/5⟩ = ⟨8/5⟩ = ⟨1 3/5⟩."],"asset":{"type":"fbar","bars":[{"den":5,"num":5},{"den":5,"num":5},{"den":5,"num":4,"label":"⟨2 4/5⟩"}]}},{"stem":"⟨3 3/5⟩ − ⟨1 2/5⟩ = ⟨2 □/5⟩ — □에 알맞은 수를 쓰세요.","answer":["1"],"explanation":["방법 1 — 자연수끼리 3 − 1 = 2, 분수끼리 ⟨3/5⟩ − ⟨2/5⟩ = ⟨1/5⟩이에요.","2 + ⟨1/5⟩ = ⟨2 1/5⟩.","방법 2 — 가분수로 바꾸면 ⟨18/5⟩ − ⟨7/5⟩ = ⟨11/5⟩ = ⟨2 1/5⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L06_basic#2','math',4,2,'u1','L06','tb_g4_2_math_u1_L06_basic','lesson_basic','M4-2-u1-C6',1,'mc','auto','⟨3 2/3⟩ − ⟨2 1/3⟩을 계산해 보세요.',ARRAY['M4-2-u1-X13','M4-2-u1-X16']::text[],true,'{"seq":2,"concept":"M4-2-u1-C6","difficulty":1,"kind":"mc","stem":"⟨3 2/3⟩ − ⟨2 1/3⟩을 계산해 보세요.","options":[{"t":"⟨1 1/3⟩","correct":true},{"t":"⟨1/3⟩","mis":"M4-2-u1-X13"},{"t":"⟨1 2/3⟩","mis":"M4-2-u1-X16"},{"t":"1","mis":"M4-2-u1-X16"}],"explanation":["방법 1 — 자연수끼리 3 − 2 = 1, 분수끼리 ⟨2/3⟩ − ⟨1/3⟩ = ⟨1/3⟩이에요.","1 + ⟨1/3⟩ = ⟨1 1/3⟩.","방법 2 — 가분수로 바꾸면 ⟨11/3⟩ − ⟨7/3⟩ = ⟨4/3⟩ = ⟨1 1/3⟩."],"variant_rule":{"alt":[{"stem":"⟨5 6/10⟩ − ⟨2 4/10⟩를 계산해 보세요.","options":[{"t":"⟨3 2/10⟩","correct":true},{"t":"⟨2/10⟩","mis":"M4-2-u1-X13"},{"t":"⟨3 3/10⟩","mis":"M4-2-u1-X16"},{"t":"⟨3 1/10⟩","mis":"M4-2-u1-X16"}],"explanation":["방법 1 — 자연수끼리 5 − 2 = 3, 분수끼리 ⟨6/10⟩ − ⟨4/10⟩ = ⟨2/10⟩예요.","3 + ⟨2/10⟩ = ⟨3 2/10⟩.","방법 2 — 가분수로 바꾸면 ⟨56/10⟩ − ⟨24/10⟩ = ⟨32/10⟩ = ⟨3 2/10⟩."]},{"stem":"「익힘」 ⟨3 3/4⟩ − ⟨1 2/4⟩를 계산해 보세요.","options":[{"t":"⟨2 1/4⟩","correct":true},{"t":"⟨1/4⟩","mis":"M4-2-u1-X13"},{"t":"⟨2 2/4⟩","mis":"M4-2-u1-X16"},{"t":"2","mis":"M4-2-u1-X16"}],"explanation":["방법 1 — 자연수끼리 3 − 1 = 2, 분수끼리 ⟨3/4⟩ − ⟨2/4⟩ = ⟨1/4⟩이에요.","2 + ⟨1/4⟩ = ⟨2 1/4⟩.","방법 2 — 가분수로 바꾸면 ⟨15/4⟩ − ⟨6/4⟩ = ⟨9/4⟩ = ⟨2 1/4⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L06_basic#3','math',4,2,'u1','L06','tb_g4_2_math_u1_L06_basic','lesson_basic','M4-2-u1-C6',1,'mc','auto','⟨3 4/7⟩ − ⟨3 1/7⟩을 계산해 보세요.',ARRAY['M4-2-u1-X16','M4-2-u1-X14']::text[],true,'{"seq":3,"concept":"M4-2-u1-C6","difficulty":1,"kind":"mc","stem":"⟨3 4/7⟩ − ⟨3 1/7⟩을 계산해 보세요.","options":[{"t":"⟨3/7⟩","correct":true},{"t":"⟨4/7⟩","mis":"M4-2-u1-X16"},{"t":"⟨2/7⟩","mis":"M4-2-u1-X16"},{"t":"⟨6 5/7⟩","mis":"M4-2-u1-X14"}],"explanation":["방법 1 — 자연수끼리 3 − 3 = 0, 분수끼리 ⟨4/7⟩ − ⟨1/7⟩ = ⟨3/7⟩이에요.","자연수끼리 빼면 0이라 분수 부분만 남아요 — 답은 ⟨3/7⟩.","방법 2 — 가분수로 바꾸면 ⟨25/7⟩ − ⟨22/7⟩ = ⟨3/7⟩ = ⟨3/7⟩."],"variant_rule":{"alt":[{"stem":"「익힘」 ⟨5 5/12⟩ − ⟨5 2/12⟩를 계산해 보세요.","options":[{"t":"⟨3/12⟩","correct":true},{"t":"⟨4/12⟩","mis":"M4-2-u1-X16"},{"t":"⟨2/12⟩","mis":"M4-2-u1-X16"},{"t":"⟨10 7/12⟩","mis":"M4-2-u1-X14"}],"explanation":["방법 1 — 자연수끼리 5 − 5 = 0, 분수끼리 ⟨5/12⟩ − ⟨2/12⟩ = ⟨3/12⟩이에요.","자연수끼리 빼면 0이라 분수 부분만 남아요 — 답은 ⟨3/12⟩.","방법 2 — 가분수로 바꾸면 ⟨65/12⟩ − ⟨62/12⟩ = ⟨3/12⟩ = ⟨3/12⟩."]},{"stem":"「확인 문제」 ⟨4 7/11⟩ − ⟨4 5/11⟩를 계산해 보세요.","options":[{"t":"⟨2/11⟩","correct":true},{"t":"⟨3/11⟩","mis":"M4-2-u1-X16"},{"t":"⟨1/11⟩","mis":"M4-2-u1-X16"},{"t":"⟨9 1/11⟩","mis":"M4-2-u1-X14"}],"explanation":["방법 1 — 자연수끼리 4 − 4 = 0, 분수끼리 ⟨7/11⟩ − ⟨5/11⟩ = ⟨2/11⟩예요.","자연수끼리 빼면 0이라 분수 부분만 남아요 — 답은 ⟨2/11⟩.","방법 2 — 가분수로 바꾸면 ⟨51/11⟩ − ⟨49/11⟩ = ⟨2/11⟩ = ⟨2/11⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L06_basic#4','math',4,2,'u1','L06','tb_g4_2_math_u1_L06_basic','lesson_basic','M4-2-u1-C6',1,'sa','auto','⟨3 2/3⟩ − ⟨2 1/3⟩을 가분수로 바꾸어 계산하려고 해요. ⟨3 2/3⟩ − ⟨2 1/3⟩ = ⟨11/3⟩ − ⟨□/3⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u1-C6","difficulty":1,"kind":"sa","stem":"⟨3 2/3⟩ − ⟨2 1/3⟩을 가분수로 바꾸어 계산하려고 해요. ⟨3 2/3⟩ − ⟨2 1/3⟩ = ⟨11/3⟩ − ⟨□/3⟩ — □에 알맞은 수를 쓰세요.","answer":["7"],"explanation":["⟨2 1/3⟩에서 자연수 2는 ⟨1/3⟩이 6개, ⟨1/3⟩은 ⟨1/3⟩이 1개 — ⟨2 1/3⟩ = ⟨7/3⟩이에요.","그래서 □ = 7이에요.","⟨11/3⟩ − ⟨7/3⟩ = ⟨4/3⟩ = ⟨1 1/3⟩이에요."],"variant_rule":{"alt":[{"stem":"「익힘」 ⟨2 4/5⟩ − ⟨1 1/5⟩을 가분수로 바꾸어 계산하려고 해요. ⟨2 4/5⟩ − ⟨1 1/5⟩ = ⟨14/5⟩ − ⟨□/5⟩ — □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["⟨1 1/5⟩에서 자연수 1은 ⟨1/5⟩이 5개, ⟨1/5⟩은 ⟨1/5⟩이 1개 — ⟨1 1/5⟩ = ⟨6/5⟩이에요.","그래서 □ = 6이에요.","⟨14/5⟩ − ⟨6/5⟩ = ⟨8/5⟩ = ⟨1 3/5⟩이에요."]},{"stem":"「익힘」 ⟨3 5/6⟩ − ⟨2 4/6⟩를 가분수로 바꾸어 계산하려고 해요. ⟨3 5/6⟩ − ⟨2 4/6⟩ = ⟨23/6⟩ − ⟨□/6⟩ — □에 알맞은 수를 쓰세요.","answer":["16"],"explanation":["⟨2 4/6⟩에서 자연수 2는 ⟨1/6⟩이 12개, ⟨4/6⟩는 ⟨1/6⟩이 4개 — ⟨2 4/6⟩ = ⟨16/6⟩이에요.","그래서 □ = 16이에요.","⟨23/6⟩ − ⟨16/6⟩ = ⟨7/6⟩ = ⟨1 1/6⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L06_basic#5','math',4,2,'u1','L06','tb_g4_2_math_u1_L06_basic','lesson_basic','M4-2-u1-C6',2,'mc','auto','「확인 문제」 연호가 만든 종이비행기는 ⟨3 2/10⟩ m를 날아갔고, 시우가 만든 종이비행기는 ⟨4 6/10⟩ m를 날아갔어요. 시우의 종이비행기는 연호의 종이비행기보다 몇 m 더 날아갔나요?',ARRAY['M4-2-u1-X13','M4-2-u1-X16']::text[],true,'{"seq":5,"concept":"M4-2-u1-C6","difficulty":2,"kind":"mc","stem":"「확인 문제」 연호가 만든 종이비행기는 ⟨3 2/10⟩ m를 날아갔고, 시우가 만든 종이비행기는 ⟨4 6/10⟩ m를 날아갔어요. 시우의 종이비행기는 연호의 종이비행기보다 몇 m 더 날아갔나요?","options":[{"t":"⟨1 4/10⟩ m","correct":true},{"t":"⟨4/10⟩ m","mis":"M4-2-u1-X13"},{"t":"⟨1 5/10⟩ m","mis":"M4-2-u1-X16"},{"t":"⟨1 3/10⟩ m","mis":"M4-2-u1-X16"}],"explanation":["방법 1 — 자연수끼리 4 − 3 = 1, 분수끼리 ⟨6/10⟩ − ⟨2/10⟩ = ⟨4/10⟩예요.","1 + ⟨4/10⟩ = ⟨1 4/10⟩ m.","방법 2 — 가분수로 바꾸면 ⟨46/10⟩ − ⟨32/10⟩ = ⟨14/10⟩ = ⟨1 4/10⟩ m."],"variant_rule":{"alt":[{"stem":"「익힘」 농장에서 사과를 도윤이는 ⟨2 5/9⟩ kg, 은비는 ⟨1 2/9⟩ kg 땄어요. 도윤이는 은비보다 사과를 몇 kg 더 많이 땄나요?","options":[{"t":"⟨1 3/9⟩ kg","correct":true},{"t":"⟨3/9⟩ kg","mis":"M4-2-u1-X13"},{"t":"⟨1 4/9⟩ kg","mis":"M4-2-u1-X16"},{"t":"⟨1 2/9⟩ kg","mis":"M4-2-u1-X16"}],"explanation":["방법 1 — 자연수끼리 2 − 1 = 1, 분수끼리 ⟨5/9⟩ − ⟨2/9⟩ = ⟨3/9⟩이에요.","1 + ⟨3/9⟩ = ⟨1 3/9⟩ kg.","방법 2 — 가분수로 바꾸면 ⟨23/9⟩ − ⟨11/9⟩ = ⟨12/9⟩ = ⟨1 3/9⟩ kg."]},{"stem":"드론을 사용하여 친환경 약품 ⟨2 3/4⟩ L 중에서 ⟨1 1/4⟩ L를 밭에 뿌렸어요. 남은 친환경 약품은 몇 L인가요?","options":[{"t":"⟨1 2/4⟩ L","correct":true},{"t":"⟨2/4⟩ L","mis":"M4-2-u1-X13"},{"t":"⟨1 3/4⟩ L","mis":"M4-2-u1-X16"},{"t":"⟨1 1/4⟩ L","mis":"M4-2-u1-X16"}],"explanation":["방법 1 — 자연수끼리 2 − 1 = 1, 분수끼리 ⟨3/4⟩ − ⟨1/4⟩ = ⟨2/4⟩예요.","1 + ⟨2/4⟩ = ⟨1 2/4⟩ L.","방법 2 — 가분수로 바꾸면 ⟨11/4⟩ − ⟨5/4⟩ = ⟨6/4⟩ = ⟨1 2/4⟩ L."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L06_basic#6','math',4,2,'u1','L06','tb_g4_2_math_u1_L06_basic','lesson_basic','M4-2-u1-C6',2,'mc','auto','「확인 문제」 ⟨6 2/4⟩ − ⟨2 2/4⟩를 계산해 보세요.',ARRAY['M4-2-u1-X16','M4-2-u1-X14']::text[],false,'{"seq":6,"concept":"M4-2-u1-C6","difficulty":2,"kind":"mc","stem":"「확인 문제」 ⟨6 2/4⟩ − ⟨2 2/4⟩를 계산해 보세요.","options":[{"t":"4","correct":true},{"t":"⟨4 1/4⟩","mis":"M4-2-u1-X16"},{"t":"⟨3 3/4⟩","mis":"M4-2-u1-X16"},{"t":"9","mis":"M4-2-u1-X14"}],"explanation":["방법 1 — 자연수끼리 6 − 2 = 4, 분수끼리 ⟨2/4⟩ − ⟨2/4⟩ = 0이에요.","분수 부분이 0이라 답은 자연수 4.","방법 2 — 가분수로 바꾸면 ⟨26/4⟩ − ⟨10/4⟩ = ⟨16/4⟩ = 4."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L06_basic#7','math',4,2,'u1','L06','tb_g4_2_math_u1_L06_basic','lesson_basic','M4-2-u1-C6',2,'error','auto','친구들이 대분수의 뺄셈을 했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M4-2-u1-X13','M4-2-u1-X15']::text[],false,'{"seq":7,"concept":"M4-2-u1-C6","difficulty":2,"kind":"error","stem":"친구들이 대분수의 뺄셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"은비 — 「⟨4 7/8⟩ − ⟨3 2/8⟩ = ⟨5/8⟩」","correct":true,"mis_target":"M4-2-u1-X13"},{"t":"연호 — 「⟨3 3/5⟩ − ⟨1 2/5⟩ = ⟨2 1/5⟩」","mis":"M4-2-u1-X15"},{"t":"시우 — 「⟨5 6/10⟩ − ⟨2 4/10⟩ = ⟨3 2/10⟩」","mis":"M4-2-u1-X15"},{"t":"찬혁 — 「⟨3 4/7⟩ − ⟨3 1/7⟩ = ⟨3/7⟩」","mis":"M4-2-u1-X15"}],"explanation":["대분수의 뺄셈은 자연수끼리, 분수끼리 빼요.","⟨4 7/8⟩ − ⟨3 2/8⟩ = (4 − 3) + (⟨7/8⟩ − ⟨2/8⟩) = ⟨1 5/8⟩예요.","은비는 자연수끼리 빼는 것을 빠뜨렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L06_basic#8','math',4,2,'u1','L06','tb_g4_2_math_u1_L06_basic','lesson_basic','M4-2-u1-C6',2,'mc','auto','「익힘」 두 분수 ⟨5 8/9⟩과 ⟨2 1/9⟩의 차는 얼마인가요?',ARRAY['M4-2-u1-X13','M4-2-u1-X16']::text[],true,'{"seq":8,"concept":"M4-2-u1-C6","difficulty":2,"kind":"mc","stem":"「익힘」 두 분수 ⟨5 8/9⟩과 ⟨2 1/9⟩의 차는 얼마인가요?","options":[{"t":"⟨3 7/9⟩","correct":true},{"t":"⟨7/9⟩","mis":"M4-2-u1-X13"},{"t":"⟨3 8/9⟩","mis":"M4-2-u1-X16"},{"t":"⟨3 6/9⟩","mis":"M4-2-u1-X16"}],"explanation":["방법 1 — 자연수끼리 5 − 2 = 3, 분수끼리 ⟨8/9⟩ − ⟨1/9⟩ = ⟨7/9⟩이에요.","3 + ⟨7/9⟩ = ⟨3 7/9⟩.","방법 2 — 가분수로 바꾸면 ⟨53/9⟩ − ⟨19/9⟩ = ⟨34/9⟩ = ⟨3 7/9⟩."],"variant_rule":{"alt":[{"stem":"「익힘」 두 분수 ⟨4 7/11⟩과 ⟨1 5/11⟩의 차는 얼마인가요?","options":[{"t":"⟨3 2/11⟩","correct":true},{"t":"⟨2/11⟩","mis":"M4-2-u1-X13"},{"t":"⟨3 3/11⟩","mis":"M4-2-u1-X16"},{"t":"⟨3 1/11⟩","mis":"M4-2-u1-X16"}],"explanation":["방법 1 — 자연수끼리 4 − 1 = 3, 분수끼리 ⟨7/11⟩ − ⟨5/11⟩ = ⟨2/11⟩예요.","3 + ⟨2/11⟩ = ⟨3 2/11⟩.","방법 2 — 가분수로 바꾸면 ⟨51/11⟩ − ⟨16/11⟩ = ⟨35/11⟩ = ⟨3 2/11⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L06_basic#9','math',4,2,'u1','L06','tb_g4_2_math_u1_L06_basic','lesson_basic','M4-2-u1-C6',2,'mc','auto','「익힘 퐁당」 체육 시간에 제자리멀리뛰기를 했어요. 기록이 채원 ⟨1 1/10⟩ m, 지유 ⟨1 7/10⟩ m, 서준 ⟨12/10⟩ m예요. 가장 멀리 뛴 학생은 누구인가요?',ARRAY['M4-2-u1-X02','M4-2-u1-X15','M4-2-u1-X18']::text[],false,'{"seq":9,"concept":"M4-2-u1-C6","difficulty":2,"kind":"mc","stem":"「익힘 퐁당」 체육 시간에 제자리멀리뛰기를 했어요. 기록이 채원 ⟨1 1/10⟩ m, 지유 ⟨1 7/10⟩ m, 서준 ⟨12/10⟩ m예요. 가장 멀리 뛴 학생은 누구인가요?","options":[{"t":"지유","correct":true},{"t":"서준","mis":"M4-2-u1-X02"},{"t":"채원","mis":"M4-2-u1-X15"},{"t":"세 사람이 같아요","mis":"M4-2-u1-X18"}],"explanation":["⟨12/10⟩ = ⟨1 2/10⟩예요.","⟨1 7/10⟩ > ⟨1 2/10⟩ > ⟨1 1/10⟩이에요.","가장 멀리 뛴 학생은 지유, 가장 가깝게 뛴 학생은 채원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L06_basic#10','math',4,2,'u1','L06','tb_g4_2_math_u1_L06_basic','lesson_basic','M4-2-u1-C6',3,'sa','auto','「익힘」 ⟨7 6/7⟩ − ⟨4 5/7⟩ < ⟨7 6/7⟩ − ⟨4 □/7⟩일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u1-C6","difficulty":3,"kind":"sa","stem":"「익힘」 ⟨7 6/7⟩ − ⟨4 5/7⟩ < ⟨7 6/7⟩ − ⟨4 □/7⟩일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["두 식 모두 ⟨7 6/7⟩에서 빼고 있어요.","오른쪽 계산 결과가 더 크려면 ⟨4 5/7⟩보다 작은 수를 빼야 해요.","□는 1, 2, 3, 4 — 모두 4개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L06_challenge#1','math',4,2,'u1','L06','tb_g4_2_math_u1_L06_challenge','lesson_challenge','M4-2-u1-C6',2,'mc','auto','「익힘 퐁당」 제자리멀리뛰기 기록이 채원 ⟨1 1/10⟩ m, 지유 ⟨1 7/10⟩ m, 서준 ⟨12/10⟩ m예요. 가장 멀리 뛴 학생과 가장 가깝게 뛴 학생의 기록의 차는 몇 m인가요?',ARRAY['M4-2-u1-X02','M4-2-u1-X14','M4-2-u1-X15']::text[],false,'{"seq":1,"concept":"M4-2-u1-C6","difficulty":2,"kind":"mc","stem":"「익힘 퐁당」 제자리멀리뛰기 기록이 채원 ⟨1 1/10⟩ m, 지유 ⟨1 7/10⟩ m, 서준 ⟨12/10⟩ m예요. 가장 멀리 뛴 학생과 가장 가깝게 뛴 학생의 기록의 차는 몇 m인가요?","options":[{"t":"⟨6/10⟩ m","correct":true},{"t":"⟨5/10⟩ m","mis":"M4-2-u1-X02"},{"t":"⟨2 8/10⟩ m","mis":"M4-2-u1-X14"},{"t":"⟨1/10⟩ m","mis":"M4-2-u1-X15"}],"explanation":["⟨12/10⟩ = ⟨1 2/10⟩ — 가장 멀리 뛴 학생은 지유, 가장 가깝게 뛴 학생은 채원이에요.","⟨1 7/10⟩ − ⟨1 1/10⟩ = (1 − 1) + (⟨7/10⟩ − ⟨1/10⟩) = ⟨6/10⟩이에요.","두 학생의 기록의 차는 ⟨6/10⟩ m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L06_challenge#2','math',4,2,'u1','L06','tb_g4_2_math_u1_L06_challenge','lesson_challenge','M4-2-u1-C6',2,'sa','auto','「확인 문제」 ⟨4 5/7⟩ − ⟨1 3/7⟩ = ⟨3 □/7⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u1-C6","difficulty":2,"kind":"sa","stem":"「확인 문제」 ⟨4 5/7⟩ − ⟨1 3/7⟩ = ⟨3 □/7⟩ — □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["방법 1 — 자연수끼리 4 − 1 = 3, 분수끼리 ⟨5/7⟩ − ⟨3/7⟩ = ⟨2/7⟩예요.","3 + ⟨2/7⟩ = ⟨3 2/7⟩.","방법 2 — 가분수로 바꾸면 ⟨33/7⟩ − ⟨10/7⟩ = ⟨23/7⟩ = ⟨3 2/7⟩."],"variant_rule":{"alt":[{"stem":"「익힘」 ⟨4 7/8⟩ − ⟨3 2/8⟩ = ⟨1 □/8⟩ — □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["방법 1 — 자연수끼리 4 − 3 = 1, 분수끼리 ⟨7/8⟩ − ⟨2/8⟩ = ⟨5/8⟩예요.","1 + ⟨5/8⟩ = ⟨1 5/8⟩.","방법 2 — 가분수로 바꾸면 ⟨39/8⟩ − ⟨26/8⟩ = ⟨13/8⟩ = ⟨1 5/8⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L06_challenge#3','math',4,2,'u1','L06','tb_g4_2_math_u1_L06_challenge','lesson_challenge','M4-2-u1-C6',3,'mc','auto','「익힘」 ⟨3 5/6⟩ − ⟨2 4/6⟩를 수직선으로 계산하려고 해요. ⟨23/6⟩에서 ⟨1/6⟩ 칸을 몇 칸 왼쪽으로 돌아오면 되나요?',ARRAY['M4-2-u1-X15','M4-2-u1-X13','M4-2-u1-X03']::text[],false,'{"seq":3,"concept":"M4-2-u1-C6","difficulty":3,"kind":"mc","stem":"「익힘」 ⟨3 5/6⟩ − ⟨2 4/6⟩를 수직선으로 계산하려고 해요. ⟨23/6⟩에서 ⟨1/6⟩ 칸을 몇 칸 왼쪽으로 돌아오면 되나요?","options":[{"t":"16칸","correct":true},{"t":"7칸","mis":"M4-2-u1-X15"},{"t":"4칸","mis":"M4-2-u1-X13"},{"t":"6칸","mis":"M4-2-u1-X03"}],"explanation":["⟨3 5/6⟩ = ⟨23/6⟩, ⟨2 4/6⟩ = ⟨16/6⟩이에요.","⟨23/6⟩에서 ⟨1/6⟩ 칸을 16칸 왼쪽으로 돌아오면 ⟨7/6⟩에 닿아요.","⟨23/6⟩ − ⟨16/6⟩ = ⟨7/6⟩ = ⟨1 1/6⟩이에요."],"asset":{"type":"number_line","cells":["0","1","2","3","4"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L06_challenge#4','math',4,2,'u1','L06','tb_g4_2_math_u1_L06_challenge','lesson_challenge','M4-2-u1-C6',3,'ox','auto','찬혁이는 「⟨3 4/7⟩ − ⟨3 1/7⟩의 답은 자연수 부분 0을 붙여 써야 해.」라고 했어요. 찬혁이의 말이 옳은가요?',ARRAY['M4-2-u1-X02']::text[],false,'{"seq":4,"concept":"M4-2-u1-C6","difficulty":3,"kind":"ox","stem":"찬혁이는 「⟨3 4/7⟩ − ⟨3 1/7⟩의 답은 자연수 부분 0을 붙여 써야 해.」라고 했어요. 찬혁이의 말이 옳은가요?","answer":"X","reason_options":[{"t":"자연수 부분이 0이면 진분수 ⟨3/7⟩만 써서","correct":true},{"t":"대분수끼리 뺀 답은 꼭 대분수로 써야 해서","mis":"M4-2-u1-X02"}],"mis":"M4-2-u1-X02","explanation":["자연수끼리 3 − 3 = 0, 분수끼리 ⟨4/7⟩ − ⟨1/7⟩ = ⟨3/7⟩이에요.","자연수 부분이 0이면 쓰지 않아요.","⟨3 4/7⟩ − ⟨3 1/7⟩ = ⟨3/7⟩ — 찬혁이의 말은 틀렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L06_challenge#5','math',4,2,'u1','L06','tb_g4_2_math_u1_L06_challenge','lesson_challenge','M4-2-u1-C6',3,'mc','auto','「익힘」 농장에서 사과를 도윤이는 ⟨2 5/9⟩ kg, 은비는 ⟨1 2/9⟩ kg 땄어요. 도윤이가 은비보다 사과를 몇 kg 더 많이 땄는지 구하는 식과 답으로 알맞은 것은 무엇인가요?',ARRAY['M4-2-u1-X14','M4-2-u1-X13']::text[],false,'{"seq":5,"concept":"M4-2-u1-C6","difficulty":3,"kind":"mc","stem":"「익힘」 농장에서 사과를 도윤이는 ⟨2 5/9⟩ kg, 은비는 ⟨1 2/9⟩ kg 땄어요. 도윤이가 은비보다 사과를 몇 kg 더 많이 땄는지 구하는 식과 답으로 알맞은 것은 무엇인가요?","options":[{"t":"⟨2 5/9⟩ − ⟨1 2/9⟩ = ⟨1 3/9⟩","correct":true},{"t":"⟨2 5/9⟩ + ⟨1 2/9⟩ = ⟨3 7/9⟩","mis":"M4-2-u1-X14"},{"t":"⟨2 5/9⟩ − ⟨1 2/9⟩ = ⟨3/9⟩","mis":"M4-2-u1-X13"},{"t":"⟨2 5/9⟩ − ⟨1 2/9⟩ = ⟨1 7/9⟩","mis":"M4-2-u1-X14"}],"explanation":["「몇 kg 더 많이」는 큰 수에서 작은 수를 빼요.","⟨2 5/9⟩ − ⟨1 2/9⟩ = (2 − 1) + (⟨5/9⟩ − ⟨2/9⟩) = ⟨1 3/9⟩이에요.","도윤이가 ⟨1 3/9⟩ kg 더 많이 땄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L06_challenge#6','math',4,2,'u1','L06','tb_g4_2_math_u1_L06_challenge','lesson_challenge','M4-2-u1-C6',3,'sa','auto','⟨5 6/10⟩ − ⟨2 4/10⟩ = ⟨56/10⟩ − ⟨24/10⟩ = ⟨□/10⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M4-2-u1-C6","difficulty":3,"kind":"sa","stem":"⟨5 6/10⟩ − ⟨2 4/10⟩ = ⟨56/10⟩ − ⟨24/10⟩ = ⟨□/10⟩ — □에 알맞은 수를 쓰세요.","answer":["32"],"explanation":["⟨5 6/10⟩ = ⟨56/10⟩, ⟨2 4/10⟩ = ⟨24/10⟩예요.","⟨56/10⟩ − ⟨24/10⟩ = ⟨32/10⟩ — 분모는 그대로예요.","⟨32/10⟩ = ⟨3 2/10⟩ — □ = 32."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L06_challenge#7','math',4,2,'u1','L06','tb_g4_2_math_u1_L06_challenge','lesson_challenge','M4-2-u1-C6',3,'mc','auto','「확인 문제」 □ − ⟨1 3/7⟩ = ⟨3 2/7⟩일 때, □에 알맞은 대분수는 무엇인가요?',ARRAY['M4-2-u1-X14','M4-2-u1-X16']::text[],false,'{"seq":7,"concept":"M4-2-u1-C6","difficulty":3,"kind":"mc","stem":"「확인 문제」 □ − ⟨1 3/7⟩ = ⟨3 2/7⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨4 5/7⟩","correct":true},{"t":"⟨1 6/7⟩","mis":"M4-2-u1-X14"},{"t":"⟨4 4/7⟩","mis":"M4-2-u1-X16"},{"t":"⟨5 5/7⟩","mis":"M4-2-u1-X16"}],"explanation":["□에서 ⟨1 3/7⟩을 빼서 ⟨3 2/7⟩가 남았어요.","덧셈으로 되돌려요 — □는 ⟨3 2/7⟩와 ⟨1 3/7⟩의 합이에요.","⟨3 2/7⟩ + ⟨1 3/7⟩ = ⟨4 5/7⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L06_challenge#8','math',4,2,'u1','L06','tb_g4_2_math_u1_L06_challenge','lesson_challenge','M4-2-u1-C6',4,'essay','teacher','⟨3 2/3⟩ − ⟨2 1/3⟩을 2가지 방법으로 계산하고, 두 방법을 비교해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u1-C6","difficulty":4,"kind":"essay","stem":"⟨3 2/3⟩ − ⟨2 1/3⟩을 2가지 방법으로 계산하고, 두 방법을 비교해 보세요.","answer_guide":{"answer":"예: 방법 1 — 자연수끼리 3 − 2 = 1, 분수끼리 ⟨2/3⟩ − ⟨1/3⟩ = ⟨1/3⟩이므로 ⟨1 1/3⟩이다. 방법 2 — 가분수로 바꾸면 ⟨11/3⟩ − ⟨7/3⟩ = ⟨4/3⟩ = ⟨1 1/3⟩이다. 방법 1은 자연수 부분끼리 진분수 부분끼리 빼고, 방법 2는 대분수를 가분수로 바꾸어 뺀다.","scoring_points":["자연수끼리·분수끼리 빼서 ⟨1 1/3⟩을 구했는가","가분수로 바꾸어 ⟨4/3⟩ = ⟨1 1/3⟩을 구했는가","두 방법의 차이를 썼는가"]},"explanation":["1 + ⟨1/3⟩ = ⟨1 1/3⟩이에요.","⟨11/3⟩ − ⟨7/3⟩ = ⟨4/3⟩예요.","두 방법의 답은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L06_challenge#9','math',4,2,'u1','L06','tb_g4_2_math_u1_L06_challenge','lesson_challenge','M4-2-u1-C6',4,'essay','teacher','「익힘」 ⟨7 6/7⟩ − ⟨4 5/7⟩ < ⟨7 6/7⟩ − ⟨4 □/7⟩일 때, □ 안에 들어갈 수 있는 수를 모두 구하고 그 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u1-C6","difficulty":4,"kind":"essay","stem":"「익힘」 ⟨7 6/7⟩ − ⟨4 5/7⟩ < ⟨7 6/7⟩ − ⟨4 □/7⟩일 때, □ 안에 들어갈 수 있는 수를 모두 구하고 그 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 두 식 모두 ⟨7 6/7⟩에서 빼고 있으므로 계산 결과가 더 크려면 ⟨4 5/7⟩보다 더 작은 수를 빼야 한다. ⟨4 □/7⟩ < ⟨4 5/7⟩이어야 하므로 □ 안에 들어갈 수 있는 수는 1, 2, 3, 4이다.","scoring_points":["빼어지는 수가 같다는 것을 썼는가","더 작은 수를 빼야 결과가 커진다고 설명했는가","1, 2, 3, 4를 모두 찾았는가"]},"explanation":["빼어지는 수가 같아요.","작은 수를 뺄수록 결과가 커요.","1, 2, 3, 4."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L06_challenge#10','math',4,2,'u1','L06','tb_g4_2_math_u1_L06_challenge','lesson_challenge','M4-2-u1-C6',4,'essay','teacher','「이런 활동」 그림 퀴즈 놀이를 해요. 짝이 대분수 ⟨2 3/4⟩을 막대 그림으로 그려 주었고, 나는 그중 ⟨1 1/4⟩만큼 ×표 했어요. 뺄셈식을 완성하고, 계산 결과와 그림이 어떻게 맞는지 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u1-C6","difficulty":4,"kind":"essay","stem":"「이런 활동」 그림 퀴즈 놀이를 해요. 짝이 대분수 ⟨2 3/4⟩을 막대 그림으로 그려 주었고, 나는 그중 ⟨1 1/4⟩만큼 ×표 했어요. 뺄셈식을 완성하고, 계산 결과와 그림이 어떻게 맞는지 설명해 보세요.","answer_guide":{"answer":"예: ⟨2 3/4⟩ − ⟨1 1/4⟩ = ⟨1 2/4⟩이다. 그림에서 1만큼인 막대 한 개와 ⟨1/4⟩ 한 칸에 ×표 하면 ×표 하지 않은 부분은 막대 한 개와 ⟨1/4⟩ 두 칸이 남아 ⟨1 2/4⟩가 된다. 그림과 계산 결과가 같다.","scoring_points":["뺄셈식 ⟨2 3/4⟩ − ⟨1 1/4⟩을 썼는가","⟨1 2/4⟩를 구했는가","×표 하지 않고 남은 부분이 ⟨1 2/4⟩임을 그림으로 설명했는가"]},"explanation":["자연수끼리 2 − 1 = 1이에요.","분수끼리 ⟨3/4⟩ − ⟨1/4⟩ = ⟨2/4⟩예요.","⟨2 3/4⟩ − ⟨1 1/4⟩ = ⟨1 2/4⟩."],"asset":{"type":"fbar","bars":[{"den":4,"num":4},{"den":4,"num":4},{"den":4,"num":3,"label":"⟨2 3/4⟩"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L07_basic#1','math',4,2,'u1','L07','tb_g4_2_math_u1_L07_basic','lesson_basic','M4-2-u1-C7',1,'sa','auto','2 − ⟨2/3⟩를 계산하려고 2에서 1만큼을 분수로 바꾸었어요. 2 = ⟨1 □/3⟩일 때 □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u1-C7","difficulty":1,"kind":"sa","stem":"2 − ⟨2/3⟩를 계산하려고 2에서 1만큼을 분수로 바꾸었어요. 2 = ⟨1 □/3⟩일 때 □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["1은 ⟨1/3⟩이 3개 — 1 = ⟨3/3⟩이에요.","2 = 1 + 1 = ⟨1 3/3⟩이에요.","⟨1 3/3⟩ − ⟨2/3⟩ = ⟨1 1/3⟩ — □ = 3."],"variant_rule":{"alt":[{"stem":"「익힘」 2 − ⟨3/4⟩을 계산하려고 2에서 1만큼을 분수로 바꾸었어요. 2 = ⟨1 □/4⟩일 때 □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["1은 ⟨1/4⟩이 4개 — 1 = ⟨4/4⟩예요.","2 = 1 + 1 = ⟨1 4/4⟩예요.","⟨1 4/4⟩ − ⟨3/4⟩ = ⟨1 1/4⟩ — □ = 4."]},{"stem":"3 − ⟨1/7⟩을 계산하려고 3에서 1만큼을 분수로 바꾸었어요. 3 = ⟨2 □/7⟩일 때 □에 알맞은 수를 쓰세요.","answer":["7"],"explanation":["1은 ⟨1/7⟩이 7개 — 1 = ⟨7/7⟩이에요.","3 = 2 + 1 = ⟨2 7/7⟩이에요.","⟨2 7/7⟩ − ⟨1/7⟩ = ⟨2 6/7⟩ — □ = 7."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L07_basic#2','math',4,2,'u1','L07','tb_g4_2_math_u1_L07_basic','lesson_basic','M4-2-u1-C7',1,'mc','auto','두부를 만들기 위해 친환경 콩 2 kg 중에서 ⟨2/3⟩ kg을 사용했어요. 남은 친환경 콩은 몇 kg인가요?',ARRAY['M4-2-u1-X10','M4-2-u1-X09','M4-2-u1-X16']::text[],true,'{"seq":2,"concept":"M4-2-u1-C7","difficulty":1,"kind":"mc","stem":"두부를 만들기 위해 친환경 콩 2 kg 중에서 ⟨2/3⟩ kg을 사용했어요. 남은 친환경 콩은 몇 kg인가요?","options":[{"t":"⟨1 1/3⟩ kg","correct":true},{"t":"⟨1 2/3⟩ kg","mis":"M4-2-u1-X10"},{"t":"⟨2 1/3⟩ kg","mis":"M4-2-u1-X09"},{"t":"1 kg","mis":"M4-2-u1-X16"}],"explanation":["2에서 1만큼을 ⟨3/3⟩으로 바꾸면 2 = ⟨1 3/3⟩이에요.","⟨1 3/3⟩ − ⟨2/3⟩ = ⟨1 1/3⟩ kg — 자연수 부분은 1 줄어요.","가분수로 바꾸면 ⟨6/3⟩ − ⟨2/3⟩ = ⟨4/3⟩ = ⟨1 1/3⟩ kg."],"asset":{"type":"fbar","bars":[{"den":3,"num":3},{"den":3,"num":3,"label":"2 kg"}]},"variant_rule":{"alt":[{"stem":"「익힘」 두부를 만들기 위해 친환경 콩 2 kg 중에서 ⟨3/4⟩ kg을 사용했어요. 남은 친환경 콩은 몇 kg인가요?","options":[{"t":"⟨1 1/4⟩ kg","correct":true},{"t":"⟨1 3/4⟩ kg","mis":"M4-2-u1-X10"},{"t":"⟨2 1/4⟩ kg","mis":"M4-2-u1-X09"},{"t":"⟨1 2/4⟩ kg","mis":"M4-2-u1-X16"}],"explanation":["2에서 1만큼을 ⟨4/4⟩로 바꾸면 2 = ⟨1 4/4⟩예요.","⟨1 4/4⟩ − ⟨3/4⟩ = ⟨1 1/4⟩ kg — 자연수 부분은 1 줄어요.","가분수로 바꾸면 ⟨8/4⟩ − ⟨3/4⟩ = ⟨5/4⟩ = ⟨1 1/4⟩ kg."],"asset":{"type":"fbar","bars":[{"den":4,"num":4},{"den":4,"num":4,"label":"2 kg"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L07_basic#3','math',4,2,'u1','L07','tb_g4_2_math_u1_L07_basic','lesson_basic','M4-2-u1-C7',1,'mc','auto','3 − ⟨1/7⟩을 계산해 보세요.',ARRAY['M4-2-u1-X10','M4-2-u1-X09','M4-2-u1-X19']::text[],true,'{"seq":3,"concept":"M4-2-u1-C7","difficulty":1,"kind":"mc","stem":"3 − ⟨1/7⟩을 계산해 보세요.","options":[{"t":"⟨2 6/7⟩","correct":true},{"t":"⟨2 1/7⟩","mis":"M4-2-u1-X10"},{"t":"⟨3 6/7⟩","mis":"M4-2-u1-X09"},{"t":"⟨2/7⟩","mis":"M4-2-u1-X19"}],"explanation":["3에서 1만큼을 ⟨7/7⟩로 바꾸면 3 = ⟨2 7/7⟩이에요.","⟨2 7/7⟩ − ⟨1/7⟩ = ⟨2 6/7⟩ — 자연수 부분은 1 줄어요.","가분수로 바꾸면 ⟨21/7⟩ − ⟨1/7⟩ = ⟨20/7⟩ = ⟨2 6/7⟩."],"variant_rule":{"alt":[{"stem":"「익힘」 3 − ⟨4/5⟩를 계산해 보세요.","options":[{"t":"⟨2 1/5⟩","correct":true},{"t":"⟨2 4/5⟩","mis":"M4-2-u1-X10"},{"t":"⟨3 1/5⟩","mis":"M4-2-u1-X09"},{"t":"⟨2 2/5⟩","mis":"M4-2-u1-X16"}],"explanation":["3에서 1만큼을 ⟨5/5⟩로 바꾸면 3 = ⟨2 5/5⟩예요.","⟨2 5/5⟩ − ⟨4/5⟩ = ⟨2 1/5⟩ — 자연수 부분은 1 줄어요.","가분수로 바꾸면 ⟨15/5⟩ − ⟨4/5⟩ = ⟨11/5⟩ = ⟨2 1/5⟩."]},{"stem":"「확인 문제」 5 − ⟨6/8⟩을 계산해 보세요.","options":[{"t":"⟨4 2/8⟩","correct":true},{"t":"⟨4 6/8⟩","mis":"M4-2-u1-X10"},{"t":"⟨5 2/8⟩","mis":"M4-2-u1-X09"},{"t":"⟨4 3/8⟩","mis":"M4-2-u1-X16"}],"explanation":["5에서 1만큼을 ⟨8/8⟩로 바꾸면 5 = ⟨4 8/8⟩이에요.","⟨4 8/8⟩ − ⟨6/8⟩ = ⟨4 2/8⟩ — 자연수 부분은 1 줄어요.","가분수로 바꾸면 ⟨40/8⟩ − ⟨6/8⟩ = ⟨34/8⟩ = ⟨4 2/8⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L07_basic#4','math',4,2,'u1','L07','tb_g4_2_math_u1_L07_basic','lesson_basic','M4-2-u1-C8',1,'mc','auto','⟨2 1/4⟩ − ⟨3/4⟩을 계산해 보세요.',ARRAY['M4-2-u1-X11','M4-2-u1-X16']::text[],true,'{"seq":4,"concept":"M4-2-u1-C8","difficulty":1,"kind":"mc","stem":"⟨2 1/4⟩ − ⟨3/4⟩을 계산해 보세요.","options":[{"t":"⟨1 2/4⟩","correct":true},{"t":"⟨2 2/4⟩","mis":"M4-2-u1-X11"},{"t":"⟨1 3/4⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 1/4⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨1/4⟩에서 ⟨3/4⟩을 뺄 수 없어 1만큼을 ⟨4/4⟩로 바꿔요 — ⟨2 1/4⟩ = ⟨1 5/4⟩.","⟨1 5/4⟩ − ⟨3/4⟩ = ⟨1 2/4⟩ — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨9/4⟩ − ⟨3/4⟩ = ⟨6/4⟩ = ⟨1 2/4⟩."],"asset":{"type":"fbar","bars":[{"den":4,"num":4},{"den":4,"num":4},{"den":4,"num":1,"label":"⟨2 1/4⟩"}]},"variant_rule":{"alt":[{"stem":"⟨5 3/8⟩ − ⟨4/8⟩를 계산해 보세요.","options":[{"t":"⟨4 7/8⟩","correct":true},{"t":"⟨5 1/8⟩","mis":"M4-2-u1-X11"},{"t":"⟨5 7/8⟩","mis":"M4-2-u1-X09"},{"t":"⟨4/8⟩","mis":"M4-2-u1-X03"}],"explanation":["⟨3/8⟩에서 ⟨4/8⟩를 뺄 수 없어 1만큼을 ⟨8/8⟩로 바꿔요 — ⟨5 3/8⟩ = ⟨4 11/8⟩.","⟨4 11/8⟩ − ⟨4/8⟩ = ⟨4 7/8⟩ — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨43/8⟩ − ⟨4/8⟩ = ⟨39/8⟩ = ⟨4 7/8⟩."],"asset":null},{"stem":"「익힘」 ⟨4 2/6⟩ − ⟨5/6⟩를 계산해 보세요.","options":[{"t":"⟨3 3/6⟩","correct":true},{"t":"⟨4 3/6⟩","mis":"M4-2-u1-X11"},{"t":"⟨1/6⟩","mis":"M4-2-u1-X03"},{"t":"⟨3 4/6⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨2/6⟩에서 ⟨5/6⟩를 뺄 수 없어 1만큼을 ⟨6/6⟩으로 바꿔요 — ⟨4 2/6⟩ = ⟨3 8/6⟩.","⟨3 8/6⟩ − ⟨5/6⟩ = ⟨3 3/6⟩ — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨26/6⟩ − ⟨5/6⟩ = ⟨21/6⟩ = ⟨3 3/6⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L07_basic#5','math',4,2,'u1','L07','tb_g4_2_math_u1_L07_basic','lesson_basic','M4-2-u1-C8',2,'sa','auto','⟨2 1/4⟩ − ⟨3/4⟩을 계산하려고 ⟨2 1/4⟩의 자연수에서 1만큼을 분수로 바꾸었어요. ⟨2 1/4⟩ = ⟨1 □/4⟩일 때 □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u1-C8","difficulty":2,"kind":"sa","stem":"⟨2 1/4⟩ − ⟨3/4⟩을 계산하려고 ⟨2 1/4⟩의 자연수에서 1만큼을 분수로 바꾸었어요. ⟨2 1/4⟩ = ⟨1 □/4⟩일 때 □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["1 = ⟨4/4⟩예요.","⟨2 1/4⟩ = 1 + ⟨4/4⟩ + ⟨1/4⟩ = ⟨1 5/4⟩예요.","□ = 4 + 1 = 5 — 10을 더하지 않아요."],"variant_rule":{"alt":[{"stem":"⟨5 3/8⟩ − ⟨4/8⟩를 계산하려고 ⟨5 3/8⟩의 자연수에서 1만큼을 분수로 바꾸었어요. ⟨5 3/8⟩ = ⟨4 □/8⟩일 때 □에 알맞은 수를 쓰세요.","answer":["11"],"explanation":["1 = ⟨8/8⟩이에요.","⟨5 3/8⟩ = 4 + ⟨8/8⟩ + ⟨3/8⟩ = ⟨4 11/8⟩이에요.","□ = 8 + 3 = 11 — 10을 더하지 않아요."]},{"stem":"「확인 문제」 ⟨3 2/13⟩ − ⟨6/13⟩을 계산하려고 ⟨3 2/13⟩의 자연수에서 1만큼을 분수로 바꾸었어요. ⟨3 2/13⟩ = ⟨2 □/13⟩일 때 □에 알맞은 수를 쓰세요.","answer":["15"],"explanation":["1 = ⟨13/13⟩이에요.","⟨3 2/13⟩ = 2 + ⟨13/13⟩ + ⟨2/13⟩ = ⟨2 15/13⟩예요.","□ = 13 + 2 = 15 — 10을 더하지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L07_basic#6','math',4,2,'u1','L07','tb_g4_2_math_u1_L07_basic','lesson_basic','M4-2-u1-C7',2,'ox','auto','지유는 「2 − ⟨2/3⟩는 2를 ⟨1 3/3⟩으로 바꾸어 계산하면 ⟨1 1/3⟩이야.」라고 했어요. 지유의 말이 옳은가요?',ARRAY['M4-2-u1-X19']::text[],false,'{"seq":6,"concept":"M4-2-u1-C7","difficulty":2,"kind":"ox","stem":"지유는 「2 − ⟨2/3⟩는 2를 ⟨1 3/3⟩으로 바꾸어 계산하면 ⟨1 1/3⟩이야.」라고 했어요. 지유의 말이 옳은가요?","answer":"O","reason_options":[{"t":"2에서 1만큼을 ⟨3/3⟩으로 바꾸어야 ⟨2/3⟩를 뺄 수 있어서","correct":true},{"t":"자연수 2를 분자로 보고 2 − 2를 하면 되어서","mis":"M4-2-u1-X19"}],"mis":"M4-2-u1-X19","explanation":["2에서 1만큼을 ⟨3/3⟩으로 바꾸면 2 = ⟨1 3/3⟩이에요.","⟨1 3/3⟩ − ⟨2/3⟩ = ⟨1 1/3⟩ — 자연수 부분은 1 줄어요.","가분수로 바꾸면 ⟨6/3⟩ − ⟨2/3⟩ = ⟨4/3⟩ = ⟨1 1/3⟩."],"asset":{"type":"fbar","bars":[{"den":3,"num":3},{"den":3,"num":3,"label":"2"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L07_basic#7','math',4,2,'u1','L07','tb_g4_2_math_u1_L07_basic','lesson_basic','M4-2-u1-C7',2,'error','auto','자연수에서 분수를 빼는 계산을 했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M4-2-u1-X10','M4-2-u1-X15']::text[],false,'{"seq":7,"concept":"M4-2-u1-C7","difficulty":2,"kind":"error","stem":"자연수에서 분수를 빼는 계산을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"도윤 — 「3 − ⟨1 2/4⟩ = ⟨2 2/4⟩」","correct":true,"mis_target":"M4-2-u1-X10"},{"t":"지유 — 「3 − ⟨1/7⟩ = ⟨2 6/7⟩」","mis":"M4-2-u1-X15"},{"t":"서준 — 「⟨5 3/8⟩ − ⟨4/8⟩ = ⟨4 7/8⟩」","mis":"M4-2-u1-X15"},{"t":"채원 — 「2 − ⟨2/3⟩ = ⟨1 1/3⟩」","mis":"M4-2-u1-X15"}],"explanation":["3 − ⟨1 2/4⟩는 3에서 ⟨1 2/4⟩이라는 하나의 양을 빼는 거예요.","3 = ⟨2 4/4⟩ — ⟨2 4/4⟩ − ⟨1 2/4⟩ = ⟨1 2/4⟩예요.","도윤이는 자연수끼리만 빼고 ⟨2/4⟩를 그대로 붙였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L07_basic#8','math',4,2,'u1','L07','tb_g4_2_math_u1_L07_basic','lesson_basic','M4-2-u1-C7',2,'mc','auto','「확인 문제」 5 − ⟨3/5⟩을 계산해 보세요.',ARRAY['M4-2-u1-X10','M4-2-u1-X09','M4-2-u1-X19']::text[],true,'{"seq":8,"concept":"M4-2-u1-C7","difficulty":2,"kind":"mc","stem":"「확인 문제」 5 − ⟨3/5⟩을 계산해 보세요.","options":[{"t":"⟨4 2/5⟩","correct":true},{"t":"⟨4 3/5⟩","mis":"M4-2-u1-X10"},{"t":"⟨5 2/5⟩","mis":"M4-2-u1-X09"},{"t":"⟨2/5⟩","mis":"M4-2-u1-X19"}],"explanation":["5에서 1만큼을 ⟨5/5⟩로 바꾸면 5 = ⟨4 5/5⟩예요.","⟨4 5/5⟩ − ⟨3/5⟩ = ⟨4 2/5⟩ — 자연수 부분은 1 줄어요.","가분수로 바꾸면 ⟨25/5⟩ − ⟨3/5⟩ = ⟨22/5⟩ = ⟨4 2/5⟩."],"variant_rule":{"alt":[{"stem":"「익힘」 3 − ⟨3/7⟩을 계산해 보세요.","options":[{"t":"⟨2 4/7⟩","correct":true},{"t":"⟨2 3/7⟩","mis":"M4-2-u1-X10"},{"t":"⟨3 4/7⟩","mis":"M4-2-u1-X09"},{"t":"⟨2 5/7⟩","mis":"M4-2-u1-X16"}],"explanation":["3에서 1만큼을 ⟨7/7⟩로 바꾸면 3 = ⟨2 7/7⟩이에요.","⟨2 7/7⟩ − ⟨3/7⟩ = ⟨2 4/7⟩ — 자연수 부분은 1 줄어요.","가분수로 바꾸면 ⟨21/7⟩ − ⟨3/7⟩ = ⟨18/7⟩ = ⟨2 4/7⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L07_basic#9','math',4,2,'u1','L07','tb_g4_2_math_u1_L07_basic','lesson_basic','M4-2-u1-C8',2,'mc','auto','「익힘」 ⟨2 2/5⟩ − ⟨4/5⟩를 대분수를 가분수로 바꾸어 바르게 계산한 것은 무엇인가요?',ARRAY['M4-2-u1-X03','M4-2-u1-X14','M4-2-u1-X13']::text[],false,'{"seq":9,"concept":"M4-2-u1-C8","difficulty":2,"kind":"mc","stem":"「익힘」 ⟨2 2/5⟩ − ⟨4/5⟩를 대분수를 가분수로 바꾸어 바르게 계산한 것은 무엇인가요?","options":[{"t":"⟨12/5⟩ − ⟨4/5⟩ = ⟨8/5⟩","correct":true},{"t":"⟨4/5⟩ − ⟨4/5⟩ = 0","mis":"M4-2-u1-X03"},{"t":"⟨12/5⟩ − ⟨4/5⟩ = ⟨16/5⟩","mis":"M4-2-u1-X14"},{"t":"⟨10/5⟩ − ⟨4/5⟩ = ⟨6/5⟩","mis":"M4-2-u1-X13"}],"explanation":["1 = ⟨5/5⟩이라 ⟨2 2/5⟩ = ⟨12/5⟩예요.","⟨12/5⟩ − ⟨4/5⟩ = ⟨8/5⟩ — 수직선에서 ⟨1/5⟩ 칸 4칸을 왼쪽으로 돌아와요.","⟨8/5⟩ = ⟨1 3/5⟩이에요."],"asset":{"type":"number_line","cells":["0","1","2","3"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L07_basic#10','math',4,2,'u1','L07','tb_g4_2_math_u1_L07_basic','lesson_basic','M4-2-u1-C7',3,'sa','auto','「확인 문제」 5에서 ⟨3/5⟩을 빼고, 그 결과에서 다시 ⟨2 3/5⟩을 뺐어요. 5 − ⟨3/5⟩ − ⟨2 3/5⟩ = ⟨1 □/5⟩일 때 □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u1-C7","difficulty":3,"kind":"sa","stem":"「확인 문제」 5에서 ⟨3/5⟩을 빼고, 그 결과에서 다시 ⟨2 3/5⟩을 뺐어요. 5 − ⟨3/5⟩ − ⟨2 3/5⟩ = ⟨1 □/5⟩일 때 □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["5 − ⟨3/5⟩ = ⟨4 5/5⟩ − ⟨3/5⟩ = ⟨4 2/5⟩예요.","⟨4 2/5⟩ − ⟨2 3/5⟩ = ⟨3 7/5⟩ − ⟨2 3/5⟩ = ⟨1 4/5⟩예요.","두 번 모두 1만큼을 분수로 바꾸었어요 — □ = 4."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L07_challenge#1','math',4,2,'u1','L07','tb_g4_2_math_u1_L07_challenge','lesson_challenge','M4-2-u1-C8',2,'mc','auto','「교과서」 ⟨4 2/6⟩ − ⟨7/6⟩을 계산해 보세요.',ARRAY['M4-2-u1-X11','M4-2-u1-X09','M4-2-u1-X12']::text[],false,'{"seq":1,"concept":"M4-2-u1-C8","difficulty":2,"kind":"mc","stem":"「교과서」 ⟨4 2/6⟩ − ⟨7/6⟩을 계산해 보세요.","options":[{"t":"⟨3 1/6⟩","correct":true},{"t":"⟨4 5/6⟩","mis":"M4-2-u1-X11"},{"t":"⟨4 1/6⟩","mis":"M4-2-u1-X09"},{"t":"⟨3 5/6⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨2/6⟩에서 ⟨7/6⟩을 뺄 수 없어 1만큼을 ⟨6/6⟩으로 바꿔요 — ⟨4 2/6⟩ = ⟨3 8/6⟩.","⟨3 8/6⟩ − ⟨7/6⟩ = ⟨3 1/6⟩ — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨26/6⟩ − ⟨7/6⟩ = ⟨19/6⟩ = ⟨3 1/6⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
