INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L07_challenge#4','math',4,2,'u1','L07','tb_g4_2_math_u1_L07_challenge','lesson_challenge','M4-2-u1-C7',3,'error','auto','3 − ⟨1/7⟩을 계산하는 과정을 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u1-X09','M4-2-u1-X15']::text[],true,'{"seq":4,"concept":"M4-2-u1-C7","difficulty":3,"kind":"error","stem":"3 − ⟨1/7⟩을 계산하는 과정을 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"건우 — 「3을 ⟨3 7/7⟩로 바꿨어.」","correct":true,"mis_target":"M4-2-u1-X09"},{"t":"서준 — 「3에서 1만큼을 ⟨7/7⟩로 바꾸면 ⟨2 7/7⟩이야.」","mis":"M4-2-u1-X15"},{"t":"채원 — 「⟨7/7⟩ − ⟨1/7⟩ = ⟨6/7⟩이야.」","mis":"M4-2-u1-X15"},{"t":"지유 — 「3 − ⟨1/7⟩ = ⟨2 6/7⟩이야.」","mis":"M4-2-u1-X15"}],"explanation":["3에서 1만큼을 ⟨7/7⟩로 바꾸면 자연수 부분은 1 줄어요.","3 = ⟨2 7/7⟩ — ⟨2 7/7⟩ − ⟨1/7⟩ = ⟨2 6/7⟩이에요.","⟨3 7/7⟩은 4와 같아서 3이 아니에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 3 − ⟨1/7⟩을 계산하는 과정을 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"건우 — 「3 − ⟨1/7⟩ = ⟨2 1/7⟩이야.」","correct":true,"mis_target":"M4-2-u1-X10"},{"t":"서준 — 「3에서 1만큼을 ⟨7/7⟩로 바꾸면 ⟨2 7/7⟩이야.」","mis":"M4-2-u1-X15"},{"t":"채원 — 「⟨7/7⟩ − ⟨1/7⟩ = ⟨6/7⟩이야.」","mis":"M4-2-u1-X15"},{"t":"지유 — 「가분수로 바꾸면 ⟨21/7⟩ − ⟨1/7⟩ = ⟨20/7⟩이야.」","mis":"M4-2-u1-X15"}],"explanation":["3 = ⟨2 7/7⟩로 바꾸어 빼요.","⟨2 7/7⟩ − ⟨1/7⟩ = ⟨2 6/7⟩이에요.","건우는 빼는 분수 ⟨1/7⟩을 그대로 썼어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L07_challenge#5','math',4,2,'u1','L07','tb_g4_2_math_u1_L07_challenge','lesson_challenge','M4-2-u1-C7',3,'ox','auto','「스스로 마무리하기」 은비는 「4 − ⟨3/9⟩ = ⟨1/9⟩이야.」라고 했어요. 은비의 말이 옳은가요?',ARRAY['M4-2-u1-X19']::text[],false,'{"seq":5,"concept":"M4-2-u1-C7","difficulty":3,"kind":"ox","stem":"「스스로 마무리하기」 은비는 「4 − ⟨3/9⟩ = ⟨1/9⟩이야.」라고 했어요. 은비의 말이 옳은가요?","answer":"X","reason_options":[{"t":"4 = ⟨3 9/9⟩로 바꾸어 ⟨9/9⟩에서 ⟨3/9⟩을 빼야 해서","correct":true},{"t":"자연수 4에서 분자 3을 빼면 되어서","mis":"M4-2-u1-X19"}],"mis":"M4-2-u1-X19","explanation":["4에서 1만큼을 ⟨9/9⟩로 바꾸면 4 = ⟨3 9/9⟩예요.","⟨3 9/9⟩ − ⟨3/9⟩ = ⟨3 6/9⟩ — 자연수 부분은 1 줄어요.","가분수로 바꾸면 ⟨36/9⟩ − ⟨3/9⟩ = ⟨33/9⟩ = ⟨3 6/9⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L07_challenge#6','math',4,2,'u1','L07','tb_g4_2_math_u1_L07_challenge','lesson_challenge','M4-2-u1-C7',3,'mc','auto','「지도서」 3 − ⟨1 2/4⟩를 계산해 보세요.',ARRAY['M4-2-u1-X10','M4-2-u1-X16']::text[],true,'{"seq":6,"concept":"M4-2-u1-C7","difficulty":3,"kind":"mc","stem":"「지도서」 3 − ⟨1 2/4⟩를 계산해 보세요.","options":[{"t":"⟨1 2/4⟩","correct":true},{"t":"⟨2 2/4⟩","mis":"M4-2-u1-X10"},{"t":"⟨1 3/4⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 1/4⟩","mis":"M4-2-u1-X16"}],"explanation":["3에서 1만큼을 ⟨4/4⟩로 바꾸면 3 = ⟨2 4/4⟩예요.","자연수끼리 2 − 1 = 1, 분수끼리 ⟨4/4⟩ − ⟨2/4⟩ = ⟨2/4⟩ — ⟨2 4/4⟩ − ⟨1 2/4⟩ = ⟨1 2/4⟩.","가분수로 바꾸면 ⟨12/4⟩ − ⟨6/4⟩ = ⟨6/4⟩ = ⟨1 2/4⟩."],"variant_rule":{"alt":[{"stem":"「익힘」 7 − ⟨3 3/5⟩을 계산해 보세요.","options":[{"t":"⟨3 2/5⟩","correct":true},{"t":"⟨4 3/5⟩","mis":"M4-2-u1-X10"},{"t":"⟨4 2/5⟩","mis":"M4-2-u1-X09"},{"t":"⟨3 3/5⟩","mis":"M4-2-u1-X16"}],"explanation":["7에서 1만큼을 ⟨5/5⟩로 바꾸면 7 = ⟨6 5/5⟩예요.","자연수끼리 6 − 3 = 3, 분수끼리 ⟨5/5⟩ − ⟨3/5⟩ = ⟨2/5⟩ — ⟨6 5/5⟩ − ⟨3 3/5⟩ = ⟨3 2/5⟩.","가분수로 바꾸면 ⟨35/5⟩ − ⟨18/5⟩ = ⟨17/5⟩ = ⟨3 2/5⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L07_challenge#7','math',4,2,'u1','L07','tb_g4_2_math_u1_L07_challenge','lesson_challenge','M4-2-u1-C7',3,'sa','auto','2 − ⟨2/3⟩ = ⟨6/3⟩ − ⟨2/3⟩ = ⟨□/3⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u1-C7","difficulty":3,"kind":"sa","stem":"2 − ⟨2/3⟩ = ⟨6/3⟩ − ⟨2/3⟩ = ⟨□/3⟩ — □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["1 = ⟨3/3⟩이라 2 = ⟨6/3⟩이에요.","⟨6/3⟩ − ⟨2/3⟩ = ⟨4/3⟩예요.","⟨4/3⟩ = ⟨1 1/3⟩ — □ = 4."],"variant_rule":{"alt":[{"stem":"「익힘」 2 − ⟨3/4⟩ = ⟨8/4⟩ − ⟨3/4⟩ = ⟨□/4⟩ — □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["1 = ⟨4/4⟩이라 2 = ⟨8/4⟩이에요.","⟨8/4⟩ − ⟨3/4⟩ = ⟨5/4⟩예요.","⟨5/4⟩ = ⟨1 1/4⟩ — □ = 5."]},{"stem":"「확인 문제」 5 − ⟨6/8⟩ = ⟨40/8⟩ − ⟨6/8⟩ = ⟨□/8⟩ — □에 알맞은 수를 쓰세요.","answer":["34"],"explanation":["1 = ⟨8/8⟩이라 5 = ⟨40/8⟩이에요.","⟨40/8⟩ − ⟨6/8⟩ = ⟨34/8⟩예요.","⟨34/8⟩ = ⟨4 2/8⟩ — □ = 34."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L07_challenge#8','math',4,2,'u1','L07','tb_g4_2_math_u1_L07_challenge','lesson_challenge','M4-2-u1-C7',4,'essay','teacher','두부를 만들기 위해 친환경 콩 2 kg 중에서 ⟨2/3⟩ kg을 사용했어요. 남은 친환경 콩은 몇 kg인지 그림을 떠올려 구하고, 자연수에서 진분수를 빼는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u1-C7","difficulty":4,"kind":"essay","stem":"두부를 만들기 위해 친환경 콩 2 kg 중에서 ⟨2/3⟩ kg을 사용했어요. 남은 친환경 콩은 몇 kg인지 그림을 떠올려 구하고, 자연수에서 진분수를 빼는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 2에서 1만큼을 ⟨3/3⟩으로 바꾸면 2 = ⟨1 3/3⟩이다. ⟨3/3⟩에서 ⟨2/3⟩를 빼면 ⟨1/3⟩이 남고, 남은 1과 더하면 ⟨1 1/3⟩이므로 남은 콩은 ⟨1 1/3⟩ kg이다. 자연수에서 진분수를 뺄 때는 자연수에서 1만큼을 가분수로 바꾸어 뺀다.","scoring_points":["2 = ⟨1 3/3⟩(또는 ⟨6/3⟩)으로 바꾸었는가","⟨1 1/3⟩ kg이라고 답했는가","자연수에서 1만큼을 가분수로 바꾸어 뺀다고 설명했는가"]},"explanation":["2 = ⟨1 3/3⟩이에요.","⟨1 3/3⟩ − ⟨2/3⟩ = ⟨1 1/3⟩이에요.","1만큼을 가분수로 바꾸어 빼요."],"asset":{"type":"fbar","bars":[{"den":3,"num":3},{"den":3,"num":3,"label":"2 kg"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L07_challenge#9','math',4,2,'u1','L07','tb_g4_2_math_u1_L07_challenge','lesson_challenge','M4-2-u1-C8',4,'essay','teacher','⟨2 1/4⟩ − ⟨3/4⟩을 2가지 방법으로 계산하고, 어떤 방법이 더 편리하다고 생각하는지 까닭과 함께 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u1-C8","difficulty":4,"kind":"essay","stem":"⟨2 1/4⟩ − ⟨3/4⟩을 2가지 방법으로 계산하고, 어떤 방법이 더 편리하다고 생각하는지 까닭과 함께 써 보세요.","answer_guide":{"answer":"예: 방법 1 — ⟨1/4⟩에서 ⟨3/4⟩을 뺄 수 없으므로 ⟨2 1/4⟩을 ⟨1 5/4⟩로 바꾸어 ⟨1 5/4⟩ − ⟨3/4⟩ = ⟨1 2/4⟩이다. 방법 2 — ⟨2 1/4⟩ = ⟨9/4⟩로 바꾸어 ⟨9/4⟩ − ⟨3/4⟩ = ⟨6/4⟩ = ⟨1 2/4⟩이다. 수가 작아서 가분수로 바꾸는 방법 2가 더 편리하다(어느 방법이든 까닭이 알맞으면 맞음).","scoring_points":["1만큼 바꾸어 ⟨1 2/4⟩를 구했는가","가분수로 바꾸어 ⟨6/4⟩ = ⟨1 2/4⟩를 구했는가","편리한 방법과 까닭을 썼는가"]},"explanation":["⟨1 5/4⟩ − ⟨3/4⟩ = ⟨1 2/4⟩예요.","⟨9/4⟩ − ⟨3/4⟩ = ⟨6/4⟩이에요.","두 방법의 답은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L07_challenge#10','math',4,2,'u1','L07','tb_g4_2_math_u1_L07_challenge','lesson_challenge','M4-2-u1-C7',4,'essay','teacher','「지도서 오류」 한 친구가 「3 − ⟨1 2/4⟩ = ⟨2 2/4⟩」라고 계산했어요. 잘못 계산한 까닭을 쓰고, 바르게 계산해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u1-C7","difficulty":4,"kind":"essay","stem":"「지도서 오류」 한 친구가 「3 − ⟨1 2/4⟩ = ⟨2 2/4⟩」라고 계산했어요. 잘못 계산한 까닭을 쓰고, 바르게 계산해 보세요.","answer_guide":{"answer":"예: 3에서 1만 빼고 ⟨2/4⟩는 그대로 붙였다. ⟨1 2/4⟩는 1과 ⟨2/4⟩가 합해진 하나의 양이므로 모두 빼야 한다. 3 = ⟨2 4/4⟩로 바꾸면 ⟨2 4/4⟩ − ⟨1 2/4⟩ = ⟨1 2/4⟩이다.","scoring_points":["자연수끼리만 뺀 것이 잘못이라고 썼는가","3 = ⟨2 4/4⟩로 바꾸었는가","⟨1 2/4⟩이라고 답했는가"]},"explanation":["3 = ⟨2 4/4⟩예요.","⟨2 4/4⟩ − ⟨1 2/4⟩ = ⟨1 2/4⟩예요.","⟨2/4⟩도 빼야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L08_basic#1','math',4,2,'u1','L08','tb_g4_2_math_u1_L08_basic','lesson_basic','M4-2-u1-C9',1,'sa','auto','⟨3 1/3⟩ − ⟨1 2/3⟩를 계산하려고 ⟨3 1/3⟩의 자연수에서 1만큼을 분수로 바꾸었어요. ⟨3 1/3⟩ = ⟨2 □/3⟩일 때 □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u1-C9","difficulty":1,"kind":"sa","stem":"⟨3 1/3⟩ − ⟨1 2/3⟩를 계산하려고 ⟨3 1/3⟩의 자연수에서 1만큼을 분수로 바꾸었어요. ⟨3 1/3⟩ = ⟨2 □/3⟩일 때 □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["1 = ⟨3/3⟩이에요.","⟨3 1/3⟩ = 2 + ⟨3/3⟩ + ⟨1/3⟩ = ⟨2 4/3⟩예요.","□ = 3 + 1 = 4 — 10을 더하지 않아요."],"variant_rule":{"alt":[{"stem":"⟨4 2/5⟩ − ⟨2 3/5⟩을 계산하려고 ⟨4 2/5⟩의 자연수에서 1만큼을 분수로 바꾸었어요. ⟨4 2/5⟩ = ⟨3 □/5⟩일 때 □에 알맞은 수를 쓰세요.","answer":["7"],"explanation":["1 = ⟨5/5⟩예요.","⟨4 2/5⟩ = 3 + ⟨5/5⟩ + ⟨2/5⟩ = ⟨3 7/5⟩이에요.","□ = 5 + 2 = 7 — 10을 더하지 않아요."]},{"stem":"⟨6 3/8⟩ − ⟨2 4/8⟩를 계산하려고 ⟨6 3/8⟩의 자연수에서 1만큼을 분수로 바꾸었어요. ⟨6 3/8⟩ = ⟨5 □/8⟩일 때 □에 알맞은 수를 쓰세요.","answer":["11"],"explanation":["1 = ⟨8/8⟩이에요.","⟨6 3/8⟩ = 5 + ⟨8/8⟩ + ⟨3/8⟩ = ⟨5 11/8⟩이에요.","□ = 8 + 3 = 11 — 10을 더하지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L08_basic#2','math',4,2,'u1','L08','tb_g4_2_math_u1_L08_basic','lesson_basic','M4-2-u1-C9',1,'mc','auto','⟨3 1/3⟩ − ⟨1 2/3⟩를 계산해 보세요.',ARRAY['M4-2-u1-X11','M4-2-u1-X09','M4-2-u1-X03']::text[],true,'{"seq":2,"concept":"M4-2-u1-C9","difficulty":1,"kind":"mc","stem":"⟨3 1/3⟩ − ⟨1 2/3⟩를 계산해 보세요.","options":[{"t":"⟨1 2/3⟩","correct":true},{"t":"⟨2 1/3⟩","mis":"M4-2-u1-X11"},{"t":"⟨2 2/3⟩","mis":"M4-2-u1-X09"},{"t":"⟨1/3⟩","mis":"M4-2-u1-X03"}],"explanation":["⟨1/3⟩에서 ⟨2/3⟩를 뺄 수 없어 1만큼을 ⟨3/3⟩으로 바꿔요 — ⟨3 1/3⟩ = ⟨2 4/3⟩.","⟨2 4/3⟩ − ⟨1 2/3⟩ = ⟨1 2/3⟩ — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨10/3⟩ − ⟨5/3⟩ = ⟨5/3⟩ = ⟨1 2/3⟩."],"variant_rule":{"alt":[{"stem":"⟨4 4/7⟩ − ⟨2 6/7⟩을 계산해 보세요.","options":[{"t":"⟨1 5/7⟩","correct":true},{"t":"⟨2 2/7⟩","mis":"M4-2-u1-X11"},{"t":"⟨2 5/7⟩","mis":"M4-2-u1-X09"},{"t":"⟨1 6/7⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨4/7⟩에서 ⟨6/7⟩을 뺄 수 없어 1만큼을 ⟨7/7⟩로 바꿔요 — ⟨4 4/7⟩ = ⟨3 11/7⟩.","⟨3 11/7⟩ − ⟨2 6/7⟩ = ⟨1 5/7⟩ — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨32/7⟩ − ⟨20/7⟩ = ⟨12/7⟩ = ⟨1 5/7⟩."]},{"stem":"⟨6 3/8⟩ − ⟨2 4/8⟩를 계산해 보세요.","options":[{"t":"⟨3 7/8⟩","correct":true},{"t":"⟨4 1/8⟩","mis":"M4-2-u1-X11"},{"t":"⟨4 7/8⟩","mis":"M4-2-u1-X09"},{"t":"⟨3/8⟩","mis":"M4-2-u1-X03"}],"explanation":["⟨3/8⟩에서 ⟨4/8⟩를 뺄 수 없어 1만큼을 ⟨8/8⟩로 바꿔요 — ⟨6 3/8⟩ = ⟨5 11/8⟩.","⟨5 11/8⟩ − ⟨2 4/8⟩ = ⟨3 7/8⟩ — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨51/8⟩ − ⟨20/8⟩ = ⟨31/8⟩ = ⟨3 7/8⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L08_basic#3','math',4,2,'u1','L08','tb_g4_2_math_u1_L08_basic','lesson_basic','M4-2-u1-C9',1,'mc','auto','⟨4 2/5⟩ − ⟨2 3/5⟩을 계산해 보세요.',ARRAY['M4-2-u1-X11','M4-2-u1-X09','M4-2-u1-X03']::text[],true,'{"seq":3,"concept":"M4-2-u1-C9","difficulty":1,"kind":"mc","stem":"⟨4 2/5⟩ − ⟨2 3/5⟩을 계산해 보세요.","options":[{"t":"⟨1 4/5⟩","correct":true},{"t":"⟨2 1/5⟩","mis":"M4-2-u1-X11"},{"t":"⟨2 4/5⟩","mis":"M4-2-u1-X09"},{"t":"⟨1/5⟩","mis":"M4-2-u1-X03"}],"explanation":["⟨2/5⟩에서 ⟨3/5⟩을 뺄 수 없어 1만큼을 ⟨5/5⟩로 바꿔요 — ⟨4 2/5⟩ = ⟨3 7/5⟩.","⟨3 7/5⟩ − ⟨2 3/5⟩ = ⟨1 4/5⟩ — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨22/5⟩ − ⟨13/5⟩ = ⟨9/5⟩ = ⟨1 4/5⟩."],"variant_rule":{"alt":[{"stem":"「익힘」 ⟨5 1/7⟩ − ⟨2 4/7⟩를 계산해 보세요.","options":[{"t":"⟨2 4/7⟩","correct":true},{"t":"⟨3 3/7⟩","mis":"M4-2-u1-X11"},{"t":"⟨3 4/7⟩","mis":"M4-2-u1-X09"},{"t":"⟨2 5/7⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨1/7⟩에서 ⟨4/7⟩를 뺄 수 없어 1만큼을 ⟨7/7⟩로 바꿔요 — ⟨5 1/7⟩ = ⟨4 8/7⟩.","⟨4 8/7⟩ − ⟨2 4/7⟩ = ⟨2 4/7⟩ — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨36/7⟩ − ⟨18/7⟩ = ⟨18/7⟩ = ⟨2 4/7⟩."]},{"stem":"「확인 문제」 ⟨11 1/4⟩ − ⟨2 3/4⟩을 계산해 보세요.","options":[{"t":"⟨8 2/4⟩","correct":true},{"t":"⟨9 2/4⟩","mis":"M4-2-u1-X11"},{"t":"⟨1 3/4⟩","mis":"M4-2-u1-X03"},{"t":"⟨8 3/4⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨1/4⟩에서 ⟨3/4⟩을 뺄 수 없어 1만큼을 ⟨4/4⟩로 바꿔요 — ⟨11 1/4⟩ = ⟨10 5/4⟩.","⟨10 5/4⟩ − ⟨2 3/4⟩ = ⟨8 2/4⟩ — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨45/4⟩ − ⟨11/4⟩ = ⟨34/4⟩ = ⟨8 2/4⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L08_basic#4','math',4,2,'u1','L08','tb_g4_2_math_u1_L08_basic','lesson_basic','M4-2-u1-C9',1,'sa','auto','⟨3 1/3⟩ − ⟨1 2/3⟩를 가분수로 바꾸어 계산하려고 해요. ⟨3 1/3⟩ − ⟨1 2/3⟩ = ⟨10/3⟩ − ⟨□/3⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u1-C9","difficulty":1,"kind":"sa","stem":"⟨3 1/3⟩ − ⟨1 2/3⟩를 가분수로 바꾸어 계산하려고 해요. ⟨3 1/3⟩ − ⟨1 2/3⟩ = ⟨10/3⟩ − ⟨□/3⟩ — □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["⟨1 2/3⟩에서 자연수 1은 ⟨1/3⟩이 3개, ⟨2/3⟩는 ⟨1/3⟩이 2개 — ⟨1 2/3⟩ = ⟨5/3⟩예요.","그래서 □ = 5예요.","⟨10/3⟩ − ⟨5/3⟩ = ⟨5/3⟩ = ⟨1 2/3⟩예요."],"variant_rule":{"alt":[{"stem":"「익힘」 ⟨3 3/8⟩ − ⟨1 7/8⟩을 가분수로 바꾸어 계산하려고 해요. ⟨3 3/8⟩ − ⟨1 7/8⟩ = ⟨27/8⟩ − ⟨□/8⟩ — □에 알맞은 수를 쓰세요.","answer":["15"],"explanation":["⟨1 7/8⟩에서 자연수 1은 ⟨1/8⟩이 8개, ⟨7/8⟩은 ⟨1/8⟩이 7개 — ⟨1 7/8⟩ = ⟨15/8⟩예요.","그래서 □ = 15예요.","⟨27/8⟩ − ⟨15/8⟩ = ⟨12/8⟩ = ⟨1 4/8⟩예요."]},{"stem":"「익힘」 ⟨5 1/7⟩ − ⟨1 3/7⟩을 가분수로 바꾸어 계산하려고 해요. ⟨5 1/7⟩ − ⟨1 3/7⟩ = ⟨36/7⟩ − ⟨□/7⟩ — □에 알맞은 수를 쓰세요.","answer":["10"],"explanation":["⟨1 3/7⟩에서 자연수 1은 ⟨1/7⟩이 7개, ⟨3/7⟩은 ⟨1/7⟩이 3개 — ⟨1 3/7⟩ = ⟨10/7⟩이에요.","그래서 □ = 10이에요.","⟨36/7⟩ − ⟨10/7⟩ = ⟨26/7⟩ = ⟨3 5/7⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L08_basic#5','math',4,2,'u1','L08','tb_g4_2_math_u1_L08_basic','lesson_basic','M4-2-u1-C9',2,'mc','auto','지유와 도윤이는 주말에 공원에서 자전거를 탔어요. 지유는 ⟨2 7/10⟩ km, 도윤이는 ⟨3 2/10⟩ km를 탔다면 누가 몇 km 더 많이 탔나요?',ARRAY['M4-2-u1-X15','M4-2-u1-X11','M4-2-u1-X14']::text[],false,'{"seq":5,"concept":"M4-2-u1-C9","difficulty":2,"kind":"mc","stem":"지유와 도윤이는 주말에 공원에서 자전거를 탔어요. 지유는 ⟨2 7/10⟩ km, 도윤이는 ⟨3 2/10⟩ km를 탔다면 누가 몇 km 더 많이 탔나요?","options":[{"t":"도윤, ⟨5/10⟩ km","correct":true},{"t":"지유, ⟨5/10⟩ km","mis":"M4-2-u1-X15"},{"t":"도윤, ⟨1 5/10⟩ km","mis":"M4-2-u1-X11"},{"t":"도윤, ⟨5 9/10⟩ km","mis":"M4-2-u1-X14"}],"explanation":["⟨2 7/10⟩ < ⟨3 2/10⟩ — 도윤이가 더 많이 탔어요.","⟨2/10⟩에서 ⟨7/10⟩을 뺄 수 없어 ⟨3 2/10⟩ = ⟨2 12/10⟩로 바꿔요.","⟨2 12/10⟩ − ⟨2 7/10⟩ = ⟨5/10⟩ — 도윤이가 ⟨5/10⟩ km 더 탔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L08_basic#6','math',4,2,'u1','L08','tb_g4_2_math_u1_L08_basic','lesson_basic','M4-2-u1-C9',2,'mc','auto','「익힘」 물 ⟨3 3/8⟩ L 중에서 ⟨1 7/8⟩ L를 마셨어요. 남은 물은 몇 L인가요?',ARRAY['M4-2-u1-X11','M4-2-u1-X12','M4-2-u1-X16']::text[],true,'{"seq":6,"concept":"M4-2-u1-C9","difficulty":2,"kind":"mc","stem":"「익힘」 물 ⟨3 3/8⟩ L 중에서 ⟨1 7/8⟩ L를 마셨어요. 남은 물은 몇 L인가요?","options":[{"t":"⟨1 4/8⟩ L","correct":true},{"t":"⟨2 4/8⟩ L","mis":"M4-2-u1-X11"},{"t":"⟨1 6/8⟩ L","mis":"M4-2-u1-X12"},{"t":"⟨1 5/8⟩ L","mis":"M4-2-u1-X16"}],"explanation":["⟨3/8⟩에서 ⟨7/8⟩을 뺄 수 없어 1만큼을 ⟨8/8⟩로 바꿔요 — ⟨3 3/8⟩ = ⟨2 11/8⟩.","⟨2 11/8⟩ − ⟨1 7/8⟩ = ⟨1 4/8⟩ L — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨27/8⟩ − ⟨15/8⟩ = ⟨12/8⟩ = ⟨1 4/8⟩ L."],"variant_rule":{"alt":[{"stem":"「익힘」 일주일 동안 모은 재활용품 중에서 종이는 ⟨4 2/10⟩ kg, 플라스틱은 ⟨3 6/10⟩ kg이에요. 종이를 플라스틱보다 몇 kg 더 많이 모았나요?","options":[{"t":"⟨6/10⟩ kg","correct":true},{"t":"⟨1 4/10⟩ kg","mis":"M4-2-u1-X11"},{"t":"⟨1 6/10⟩ kg","mis":"M4-2-u1-X09"},{"t":"⟨7/10⟩ kg","mis":"M4-2-u1-X16"}],"explanation":["⟨2/10⟩에서 ⟨6/10⟩을 뺄 수 없어 1만큼을 ⟨10/10⟩으로 바꿔요 — ⟨4 2/10⟩ = ⟨3 12/10⟩.","⟨3 12/10⟩ − ⟨3 6/10⟩ = ⟨6/10⟩ kg — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨42/10⟩ − ⟨36/10⟩ = ⟨6/10⟩ = ⟨6/10⟩ kg."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L08_basic#7','math',4,2,'u1','L08','tb_g4_2_math_u1_L08_basic','lesson_basic','M4-2-u1-C9',2,'ox','auto','「교과서」 은비는 「⟨5 1/6⟩ − ⟨3 5/6⟩ = (5 − 3) + (⟨5/6⟩ − ⟨1/6⟩) = ⟨2 4/6⟩야.」라고 했어요. 은비의 계산이 옳은가요?',ARRAY['M4-2-u1-X11']::text[],false,'{"seq":7,"concept":"M4-2-u1-C9","difficulty":2,"kind":"ox","stem":"「교과서」 은비는 「⟨5 1/6⟩ − ⟨3 5/6⟩ = (5 − 3) + (⟨5/6⟩ − ⟨1/6⟩) = ⟨2 4/6⟩야.」라고 했어요. 은비의 계산이 옳은가요?","answer":"X","reason_options":[{"t":"⟨1/6⟩에서 ⟨5/6⟩를 뺄 수 없으면 1만큼을 ⟨6/6⟩으로 바꾸어 빼야 해서","correct":true},{"t":"큰 분자에서 작은 분자를 빼면 되어서","mis":"M4-2-u1-X11"}],"mis":"M4-2-u1-X11","explanation":["⟨1/6⟩에서 ⟨5/6⟩를 뺄 수 없어 1만큼을 ⟨6/6⟩으로 바꿔요 — ⟨5 1/6⟩ = ⟨4 7/6⟩.","⟨4 7/6⟩ − ⟨3 5/6⟩ = ⟨1 2/6⟩ — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨31/6⟩ − ⟨23/6⟩ = ⟨8/6⟩ = ⟨1 2/6⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L08_basic#8','math',4,2,'u1','L08','tb_g4_2_math_u1_L08_basic','lesson_basic','M4-2-u1-C9',2,'mc','auto','「익힘」 계산 결과가 3보다 큰 것은 무엇인가요?',ARRAY['M4-2-u1-X17','M4-2-u1-X11']::text[],false,'{"seq":8,"concept":"M4-2-u1-C9","difficulty":2,"kind":"mc","stem":"「익힘」 계산 결과가 3보다 큰 것은 무엇인가요?","options":[{"t":"7 − ⟨3 3/5⟩","correct":true},{"t":"3 − ⟨3/7⟩","mis":"M4-2-u1-X17"},{"t":"⟨6 5/8⟩ − ⟨3 6/8⟩","mis":"M4-2-u1-X11"},{"t":"⟨5 3/9⟩ − ⟨22/9⟩","mis":"M4-2-u1-X17"}],"explanation":["7 − ⟨3 3/5⟩ = ⟨6 5/5⟩ − ⟨3 3/5⟩ = ⟨3 2/5⟩ — 3보다 커요.","3 − ⟨3/7⟩ = ⟨2 4/7⟩, ⟨6 5/8⟩ − ⟨3 6/8⟩ = ⟨2 7/8⟩이에요.","⟨5 3/9⟩ − ⟨22/9⟩ = ⟨48/9⟩ − ⟨22/9⟩ = ⟨26/9⟩ = ⟨2 8/9⟩ — 3보다 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L08_basic#9','math',4,2,'u1','L08','tb_g4_2_math_u1_L08_basic','lesson_basic','M4-2-u1-C9',2,'error','auto','대분수의 뺄셈을 했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M4-2-u1-X03','M4-2-u1-X15']::text[],false,'{"seq":9,"concept":"M4-2-u1-C9","difficulty":2,"kind":"error","stem":"대분수의 뺄셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"건우 — 「⟨5 1/7⟩ − ⟨1 3/7⟩ = ⟨6/7⟩ − ⟨4/7⟩ = ⟨2/7⟩」","correct":true,"mis_target":"M4-2-u1-X03"},{"t":"서준 — 「⟨4 2/5⟩ − ⟨2 3/5⟩ = ⟨1 4/5⟩」","mis":"M4-2-u1-X15"},{"t":"채원 — 「⟨3 1/3⟩ − ⟨1 2/3⟩ = ⟨1 2/3⟩」","mis":"M4-2-u1-X15"},{"t":"도윤 — 「⟨6 3/8⟩ − ⟨2 4/8⟩ = ⟨3 7/8⟩」","mis":"M4-2-u1-X15"}],"explanation":["대분수를 가분수로 바꿀 때 자연수는 분모만큼의 단위분수로 바꿔요 — ⟨5 1/7⟩ = ⟨36/7⟩.","⟨36/7⟩ − ⟨10/7⟩ = ⟨26/7⟩ = ⟨3 5/7⟩예요.","건우는 자연수를 분자에 더해서 ⟨6/7⟩으로 바꾸었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L08_basic#10','math',4,2,'u1','L08','tb_g4_2_math_u1_L08_basic','lesson_basic','M4-2-u1-C9',3,'mc','auto','「재미있는 수학」 수 카드 1, 5, 7, 8을 한 번씩만 사용하여 뺄셈식 ⟨8 5/9⟩ − ⟨1 7/9⟩을 완성했어요. 계산 결과는 얼마인가요?',ARRAY['M4-2-u1-X11','M4-2-u1-X09','M4-2-u1-X12']::text[],false,'{"seq":10,"concept":"M4-2-u1-C9","difficulty":3,"kind":"mc","stem":"「재미있는 수학」 수 카드 1, 5, 7, 8을 한 번씩만 사용하여 뺄셈식 ⟨8 5/9⟩ − ⟨1 7/9⟩을 완성했어요. 계산 결과는 얼마인가요?","options":[{"t":"⟨6 7/9⟩","correct":true},{"t":"⟨7 2/9⟩","mis":"M4-2-u1-X11"},{"t":"⟨7 7/9⟩","mis":"M4-2-u1-X09"},{"t":"⟨6 8/9⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨5/9⟩에서 ⟨7/9⟩을 뺄 수 없어 1만큼을 ⟨9/9⟩로 바꿔요 — ⟨8 5/9⟩ = ⟨7 14/9⟩.","⟨7 14/9⟩ − ⟨1 7/9⟩ = ⟨6 7/9⟩ — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨77/9⟩ − ⟨16/9⟩ = ⟨61/9⟩ = ⟨6 7/9⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L08_challenge#1','math',4,2,'u1','L08','tb_g4_2_math_u1_L08_challenge','lesson_challenge','M4-2-u1-C9',2,'mc','auto','「교과서」 친구가 「⟨5 2/9⟩ − ⟨1 4/9⟩ = ⟨7/9⟩ − ⟨5/9⟩ = ⟨2/9⟩」라고 계산했어요. 바르게 계산한 값은 얼마인가요?',ARRAY['M4-2-u1-X03','M4-2-u1-X11','M4-2-u1-X09']::text[],false,'{"seq":1,"concept":"M4-2-u1-C9","difficulty":2,"kind":"mc","stem":"「교과서」 친구가 「⟨5 2/9⟩ − ⟨1 4/9⟩ = ⟨7/9⟩ − ⟨5/9⟩ = ⟨2/9⟩」라고 계산했어요. 바르게 계산한 값은 얼마인가요?","options":[{"t":"⟨3 7/9⟩","correct":true},{"t":"⟨2/9⟩","mis":"M4-2-u1-X03"},{"t":"⟨4 2/9⟩","mis":"M4-2-u1-X11"},{"t":"⟨4 7/9⟩","mis":"M4-2-u1-X09"}],"explanation":["⟨2/9⟩에서 ⟨4/9⟩를 뺄 수 없어 1만큼을 ⟨9/9⟩로 바꿔요 — ⟨5 2/9⟩ = ⟨4 11/9⟩.","⟨4 11/9⟩ − ⟨1 4/9⟩ = ⟨3 7/9⟩ — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨47/9⟩ − ⟨13/9⟩ = ⟨34/9⟩ = ⟨3 7/9⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L08_challenge#2','math',4,2,'u1','L08','tb_g4_2_math_u1_L08_challenge','lesson_challenge','M4-2-u1-C9',2,'sa','auto','「확인 문제」 ⟨11 1/4⟩ − ⟨2 3/4⟩ = ⟨8 □/4⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u1-C9","difficulty":2,"kind":"sa","stem":"「확인 문제」 ⟨11 1/4⟩ − ⟨2 3/4⟩ = ⟨8 □/4⟩ — □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["⟨1/4⟩에서 ⟨3/4⟩을 뺄 수 없어 1만큼을 ⟨4/4⟩로 바꿔요 — ⟨11 1/4⟩ = ⟨10 5/4⟩.","⟨10 5/4⟩ − ⟨2 3/4⟩ = ⟨8 2/4⟩ — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨45/4⟩ − ⟨11/4⟩ = ⟨34/4⟩ = ⟨8 2/4⟩."],"variant_rule":{"alt":[{"stem":"「확인 문제」 ⟨4 2/5⟩ − ⟨2 3/5⟩ = ⟨1 □/5⟩ — □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["⟨2/5⟩에서 ⟨3/5⟩을 뺄 수 없어 1만큼을 ⟨5/5⟩로 바꿔요 — ⟨4 2/5⟩ = ⟨3 7/5⟩.","⟨3 7/5⟩ − ⟨2 3/5⟩ = ⟨1 4/5⟩ — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨22/5⟩ − ⟨13/5⟩ = ⟨9/5⟩ = ⟨1 4/5⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L08_challenge#3','math',4,2,'u1','L08','tb_g4_2_math_u1_L08_challenge','lesson_challenge','M4-2-u1-C9',3,'mc','auto','「교과서」 친구가 「⟨3 1/7⟩ − ⟨1 6/7⟩ = ⟨2 11/7⟩ − ⟨1 6/7⟩ = ⟨1 5/7⟩」라고 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 무엇인가요?',ARRAY['M4-2-u1-X11','M4-2-u1-X03','M4-2-u1-X09']::text[],false,'{"seq":3,"concept":"M4-2-u1-C9","difficulty":3,"kind":"mc","stem":"「교과서」 친구가 「⟨3 1/7⟩ − ⟨1 6/7⟩ = ⟨2 11/7⟩ − ⟨1 6/7⟩ = ⟨1 5/7⟩」라고 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"1만큼을 ⟨7/7⟩이 아니라 ⟨10/7⟩으로 바꾸었다","correct":true},{"t":"분수 부분끼리 거꾸로 뺐다","mis":"M4-2-u1-X11"},{"t":"대분수를 가분수로 바꿀 때 자연수를 분자에 더했다","mis":"M4-2-u1-X03"},{"t":"1만큼을 바꾸고도 자연수 부분에서 1을 빼지 않았다","mis":"M4-2-u1-X09"}],"explanation":["⟨3 1/7⟩에서 1만큼을 분수로 바꾸면 ⟨7/7⟩ — ⟨3 1/7⟩ = ⟨2 8/7⟩이에요.","⟨2 8/7⟩ − ⟨1 6/7⟩ = ⟨1 2/7⟩예요.","친구는 1을 ⟨10/7⟩으로 바꾸어 ⟨2 11/7⟩이라고 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L08_challenge#4','math',4,2,'u1','L08','tb_g4_2_math_u1_L08_challenge','lesson_challenge','M4-2-u1-C9',3,'mc','auto','「재미있는 수학」 수 카드 2, 3, 4, 6을 한 번씩만 사용하여 뺄셈식 ⟨6 3/9⟩ − ⟨2 4/9⟩를 완성했어요. 계산 결과는 얼마인가요?',ARRAY['M4-2-u1-X11','M4-2-u1-X09','M4-2-u1-X03']::text[],false,'{"seq":4,"concept":"M4-2-u1-C9","difficulty":3,"kind":"mc","stem":"「재미있는 수학」 수 카드 2, 3, 4, 6을 한 번씩만 사용하여 뺄셈식 ⟨6 3/9⟩ − ⟨2 4/9⟩를 완성했어요. 계산 결과는 얼마인가요?","options":[{"t":"⟨3 8/9⟩","correct":true},{"t":"⟨4 1/9⟩","mis":"M4-2-u1-X11"},{"t":"⟨4 8/9⟩","mis":"M4-2-u1-X09"},{"t":"⟨3/9⟩","mis":"M4-2-u1-X03"}],"explanation":["⟨3/9⟩에서 ⟨4/9⟩를 뺄 수 없어 1만큼을 ⟨9/9⟩로 바꿔요 — ⟨6 3/9⟩ = ⟨5 12/9⟩.","⟨5 12/9⟩ − ⟨2 4/9⟩ = ⟨3 8/9⟩ — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨57/9⟩ − ⟨22/9⟩ = ⟨35/9⟩ = ⟨3 8/9⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L08_challenge#5','math',4,2,'u1','L08','tb_g4_2_math_u1_L08_challenge','lesson_challenge','M4-2-u1-C9',3,'sa','auto','「익힘」 일주일 동안 모은 재활용품 중에서 종이는 ⟨4 2/10⟩ kg, 플라스틱은 ⟨3 6/10⟩ kg이에요. 종이를 플라스틱보다 ⟨□/10⟩ kg 더 많이 모았어요. □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M4-2-u1-C9","difficulty":3,"kind":"sa","stem":"「익힘」 일주일 동안 모은 재활용품 중에서 종이는 ⟨4 2/10⟩ kg, 플라스틱은 ⟨3 6/10⟩ kg이에요. 종이를 플라스틱보다 ⟨□/10⟩ kg 더 많이 모았어요. □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["⟨2/10⟩에서 ⟨6/10⟩을 뺄 수 없어 1만큼을 ⟨10/10⟩으로 바꿔요 — ⟨4 2/10⟩ = ⟨3 12/10⟩.","⟨3 12/10⟩ − ⟨3 6/10⟩ = ⟨6/10⟩ — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨42/10⟩ − ⟨36/10⟩ = ⟨6/10⟩ = ⟨6/10⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L08_challenge#6','math',4,2,'u1','L08','tb_g4_2_math_u1_L08_challenge','lesson_challenge','M4-2-u1-C9',3,'ox','auto','「이런 활동」 건우는 「수 카드로 대분수의 뺄셈식을 만들 때 빼어지는 수는 작게, 빼는 수는 크게 만들수록 계산 결과가 작아져.」라고 했어요. 건우의 말이 옳은가요?',ARRAY['M4-2-u1-X17']::text[],false,'{"seq":6,"concept":"M4-2-u1-C9","difficulty":3,"kind":"ox","stem":"「이런 활동」 건우는 「수 카드로 대분수의 뺄셈식을 만들 때 빼어지는 수는 작게, 빼는 수는 크게 만들수록 계산 결과가 작아져.」라고 했어요. 건우의 말이 옳은가요?","answer":"O","reason_options":[{"t":"빼어지는 수가 작고 빼는 수가 클수록 차가 작아서","correct":true},{"t":"자연수 부분만 크게 만들면 되어서","mis":"M4-2-u1-X17"}],"mis":"M4-2-u1-X17","explanation":["계산 결과가 가장 작은 식을 만들 때 생각할 점이에요.","빼어지는 수가 작을수록, 빼는 수가 클수록 차가 작아요.","예: 수 카드 1, 5, 7, 8로 ⟨8 1/9⟩ − ⟨7 5/9⟩ = ⟨5/9⟩처럼 만들 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L08_challenge#7','math',4,2,'u1','L08','tb_g4_2_math_u1_L08_challenge','lesson_challenge','M4-2-u1-C9',3,'mc','auto','「확인 문제」 □ − ⟨2 3/5⟩ = ⟨1 4/5⟩일 때, □에 알맞은 대분수는 무엇인가요?',ARRAY['M4-2-u1-X09','M4-2-u1-X14','M4-2-u1-X16']::text[],false,'{"seq":7,"concept":"M4-2-u1-C9","difficulty":3,"kind":"mc","stem":"「확인 문제」 □ − ⟨2 3/5⟩ = ⟨1 4/5⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨4 2/5⟩","correct":true},{"t":"⟨3 2/5⟩","mis":"M4-2-u1-X09"},{"t":"⟨4/5⟩","mis":"M4-2-u1-X14"},{"t":"⟨5 2/5⟩","mis":"M4-2-u1-X16"}],"explanation":["□에서 ⟨2 3/5⟩을 빼서 ⟨1 4/5⟩가 남았어요.","덧셈으로 되돌려요 — □는 ⟨1 4/5⟩와 ⟨2 3/5⟩의 합이에요.","⟨1 4/5⟩ + ⟨2 3/5⟩ = ⟨4 2/5⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L08_challenge#8','math',4,2,'u1','L08','tb_g4_2_math_u1_L08_challenge','lesson_challenge','M4-2-u1-C9',4,'essay','teacher','「교과서」 친구가 「⟨5 1/6⟩ − ⟨3 5/6⟩ = (5 − 3) + (⟨5/6⟩ − ⟨1/6⟩) = ⟨2 4/6⟩」라고 계산했어요. 잘못 계산한 곳을 찾아 이유를 설명하고, 바르게 계산해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u1-C9","difficulty":4,"kind":"essay","stem":"「교과서」 친구가 「⟨5 1/6⟩ − ⟨3 5/6⟩ = (5 − 3) + (⟨5/6⟩ − ⟨1/6⟩) = ⟨2 4/6⟩」라고 계산했어요. 잘못 계산한 곳을 찾아 이유를 설명하고, 바르게 계산해 보세요.","answer_guide":{"answer":"예: ⟨1/6⟩에서 ⟨5/6⟩를 뺄 수 없는데 분수 부분끼리 거꾸로 ⟨5/6⟩에서 ⟨1/6⟩을 뺐다. ⟨5 1/6⟩에서 1만큼을 가분수로 바꾸면 ⟨4 7/6⟩이므로 ⟨4 7/6⟩ − ⟨3 5/6⟩ = ⟨1 2/6⟩이다.","scoring_points":["분수 부분끼리 거꾸로 뺀 것이 잘못이라고 썼는가","⟨5 1/6⟩ = ⟨4 7/6⟩로 바꾸었는가","⟨1 2/6⟩이라고 답했는가"]},"explanation":["⟨5 1/6⟩ = ⟨4 7/6⟩이에요.","⟨4 7/6⟩ − ⟨3 5/6⟩ = ⟨1 2/6⟩예요.","거꾸로 빼지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L08_challenge#9','math',4,2,'u1','L08','tb_g4_2_math_u1_L08_challenge','lesson_challenge','M4-2-u1-C9',4,'essay','teacher','「익힘」 「서술형」 일주일 동안 모은 재활용품 중에서 종이는 ⟨4 2/10⟩ kg, 플라스틱은 ⟨3 6/10⟩ kg이에요. 종이를 플라스틱보다 몇 kg 더 많이 모았는지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u1-C9","difficulty":4,"kind":"essay","stem":"「익힘」 「서술형」 일주일 동안 모은 재활용품 중에서 종이는 ⟨4 2/10⟩ kg, 플라스틱은 ⟨3 6/10⟩ kg이에요. 종이를 플라스틱보다 몇 kg 더 많이 모았는지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 종이를 플라스틱보다 더 많이 모은 양은 ⟨4 2/10⟩ − ⟨3 6/10⟩으로 구한다. ⟨2/10⟩에서 ⟨6/10⟩을 뺄 수 없으므로 ⟨4 2/10⟩ = ⟨3 12/10⟩로 바꾸면 ⟨3 12/10⟩ − ⟨3 6/10⟩ = ⟨6/10⟩ (kg)이다. 종이를 ⟨6/10⟩ kg 더 많이 모았다.","scoring_points":["뺄셈식을 세웠는가","1만큼 바꾸어(또는 가분수로) 계산했는가","⟨6/10⟩ kg이라고 답했는가"]},"explanation":["⟨4 2/10⟩ = ⟨3 12/10⟩예요.","⟨3 12/10⟩ − ⟨3 6/10⟩ = ⟨6/10⟩이에요.","⟨6/10⟩ kg 더 모았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L08_challenge#10','math',4,2,'u1','L08','tb_g4_2_math_u1_L08_challenge','lesson_challenge','M4-2-u1-C9',4,'essay','teacher','「익힘」 물 ⟨3 3/8⟩ L 중에서 ⟨1 7/8⟩ L를 마셨어요. 남은 물은 몇 L인지 2가지 방법으로 구해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u1-C9","difficulty":4,"kind":"essay","stem":"「익힘」 물 ⟨3 3/8⟩ L 중에서 ⟨1 7/8⟩ L를 마셨어요. 남은 물은 몇 L인지 2가지 방법으로 구해 보세요.","answer_guide":{"answer":"예: 방법 1 — ⟨3 3/8⟩에서 1만큼을 가분수로 바꾸어 ⟨2 11/8⟩ − ⟨1 7/8⟩ = ⟨1 4/8⟩ (L)이다. 방법 2 — 대분수를 가분수로 바꾸어 ⟨27/8⟩ − ⟨15/8⟩ = ⟨12/8⟩ = ⟨1 4/8⟩ (L)이다.","scoring_points":["1만큼 바꾸어 계산했는가","가분수로 바꾸어 계산했는가","⟨1 4/8⟩ L(또는 ⟨12/8⟩ L)라고 답했는가"]},"explanation":["⟨2 11/8⟩ − ⟨1 7/8⟩ = ⟨1 4/8⟩예요.","⟨27/8⟩ − ⟨15/8⟩ = ⟨12/8⟩예요.","남은 물은 ⟨1 4/8⟩ L예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L09_basic#1','math',4,2,'u1','L09','tb_g4_2_math_u1_L09_basic','lesson_basic','M4-2-u1-C10',1,'sa','auto','「나는야 분수왕」 ⟨2 3/5⟩ + ⟨7/5⟩ = □ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u1-C10","difficulty":1,"kind":"sa","stem":"「나는야 분수왕」 ⟨2 3/5⟩ + ⟨7/5⟩ = □ — □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["⟨7/5⟩ = ⟨1 2/5⟩예요.","⟨2 3/5⟩ + ⟨1 2/5⟩ = 3 + ⟨5/5⟩ = 4예요.","가분수로 바꾸면 ⟨13/5⟩ + ⟨7/5⟩ = ⟨20/5⟩ = 4 — □ = 4."],"variant_rule":{"alt":[{"stem":"「나는야 분수왕」 ⟨2 2/5⟩ + ⟨1 3/5⟩ = □ — □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["방법 1 — 자연수끼리 2 + 1 = 3, 분수끼리 ⟨2/5⟩ + ⟨3/5⟩ = ⟨5/5⟩예요.","⟨5/5⟩ = 1 — 자연수에 1을 더해 3 + 1 = 4.","방법 2 — 가분수로 바꾸면 ⟨12/5⟩ + ⟨8/5⟩ = ⟨20/5⟩ = 4."]},{"stem":"「나는야 분수왕」 ⟨3 3/5⟩ + ⟨2/5⟩ = □ — □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["방법 1 — 자연수 3은 그대로, 분수끼리 ⟨3/5⟩ + ⟨2/5⟩ = ⟨5/5⟩예요.","⟨5/5⟩ = 1 — 자연수에 1을 더해 3 + 1 = 4.","방법 2 — 가분수로 바꾸면 ⟨18/5⟩ + ⟨2/5⟩ = ⟨20/5⟩ = 4."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L09_basic#2','math',4,2,'u1','L09','tb_g4_2_math_u1_L09_basic','lesson_basic','M4-2-u1-C10',1,'sa','auto','「나는야 분수왕」 ⟨2 3/5⟩ − ⟨3/5⟩ = □ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u1-C10","difficulty":1,"kind":"sa","stem":"「나는야 분수왕」 ⟨2 3/5⟩ − ⟨3/5⟩ = □ — □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["방법 1 — 자연수 2는 그대로, 분수끼리 ⟨3/5⟩ − ⟨3/5⟩ = 0이에요.","분수 부분이 0이라 답은 자연수 2.","방법 2 — 가분수로 바꾸면 ⟨13/5⟩ − ⟨3/5⟩ = ⟨10/5⟩ = 2."],"variant_rule":{"alt":[{"stem":"「나는야 분수왕」 ⟨2 2/5⟩ − ⟨2/5⟩ = □ — □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["방법 1 — 자연수 2는 그대로, 분수끼리 ⟨2/5⟩ − ⟨2/5⟩ = 0이에요.","분수 부분이 0이라 답은 자연수 2.","방법 2 — 가분수로 바꾸면 ⟨12/5⟩ − ⟨2/5⟩ = ⟨10/5⟩ = 2."]},{"stem":"「나는야 분수왕」 ⟨3 3/5⟩ − ⟨1 3/5⟩ = □ — □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["방법 1 — 자연수끼리 3 − 1 = 2, 분수끼리 ⟨3/5⟩ − ⟨3/5⟩ = 0이에요.","분수 부분이 0이라 답은 자연수 2.","방법 2 — 가분수로 바꾸면 ⟨18/5⟩ − ⟨8/5⟩ = ⟨10/5⟩ = 2."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L09_basic#3','math',4,2,'u1','L09','tb_g4_2_math_u1_L09_basic','lesson_basic','M4-2-u1-C10',1,'mc','auto','「지도서」 4를 분모가 5인 가분수로 나타내면 무엇인가요?',ARRAY['M4-2-u1-X05','M4-2-u1-X03','M4-2-u1-X16']::text[],true,'{"seq":3,"concept":"M4-2-u1-C10","difficulty":1,"kind":"mc","stem":"「지도서」 4를 분모가 5인 가분수로 나타내면 무엇인가요?","options":[{"t":"⟨20/5⟩","correct":true},{"t":"⟨4/5⟩","mis":"M4-2-u1-X05"},{"t":"⟨9/5⟩","mis":"M4-2-u1-X03"},{"t":"⟨16/5⟩","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨5/5⟩ — 1은 ⟨1/5⟩이 5개예요.","4는 ⟨1/5⟩이 4 × 5 = 20개예요.","4 = ⟨20/5⟩ — 합이 4인 덧셈식을 찾을 때 써요."],"variant_rule":{"alt":[{"stem":"「지도서」 2를 분모가 5인 가분수로 나타내면 무엇인가요?","options":[{"t":"⟨10/5⟩","correct":true},{"t":"⟨2/5⟩","mis":"M4-2-u1-X05"},{"t":"⟨7/5⟩","mis":"M4-2-u1-X03"},{"t":"⟨12/5⟩","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨5/5⟩ — 1은 ⟨1/5⟩이 5개예요.","2는 ⟨1/5⟩이 2 × 5 = 10개예요.","2 = ⟨10/5⟩ — 차가 2인 뺄셈식을 찾을 때 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L09_basic#4','math',4,2,'u1','L09','tb_g4_2_math_u1_L09_basic','lesson_basic','M4-2-u1-C10',1,'mc','auto','「지도서」 ⟨3 3/5⟩을 가분수로 나타내면 무엇인가요?',ARRAY['M4-2-u1-X03','M4-2-u1-X16']::text[],true,'{"seq":4,"concept":"M4-2-u1-C10","difficulty":1,"kind":"mc","stem":"「지도서」 ⟨3 3/5⟩을 가분수로 나타내면 무엇인가요?","options":[{"t":"⟨18/5⟩","correct":true},{"t":"⟨6/5⟩","mis":"M4-2-u1-X03"},{"t":"⟨19/5⟩","mis":"M4-2-u1-X16"},{"t":"⟨17/5⟩","mis":"M4-2-u1-X16"}],"explanation":["자연수 3은 ⟨1/5⟩이 3 × 5 = 15개예요.","분수 부분 ⟨3/5⟩은 ⟨1/5⟩이 3개예요.","15 + 3 = 18 — ⟨3 3/5⟩ = ⟨18/5⟩."],"variant_rule":{"alt":[{"stem":"「지도서」 ⟨2 3/5⟩을 가분수로 나타내면 무엇인가요?","options":[{"t":"⟨13/5⟩","correct":true},{"t":"⟨5/5⟩","mis":"M4-2-u1-X03"},{"t":"⟨14/5⟩","mis":"M4-2-u1-X16"},{"t":"⟨12/5⟩","mis":"M4-2-u1-X16"}],"explanation":["자연수 2는 ⟨1/5⟩이 2 × 5 = 10개예요.","분수 부분 ⟨3/5⟩은 ⟨1/5⟩이 3개예요.","10 + 3 = 13 — ⟨2 3/5⟩ = ⟨13/5⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L09_basic#5','math',4,2,'u1','L09','tb_g4_2_math_u1_L09_basic','lesson_basic','M4-2-u1-C10',2,'mc','auto','「나는야 분수왕」 분수 카드 ⟨1 4/5⟩, ⟨1/5⟩, ⟨16/5⟩, ⟨3/5⟩, ⟨2 3/5⟩, ⟨2 2/5⟩, ⟨3 3/5⟩, ⟨2/5⟩, ⟨7/5⟩, ⟨1 3/5⟩이 있어요. ⟨2 3/5⟩과 더해서 4가 되는 카드는 무엇인가요?',ARRAY['M4-2-u1-X16','M4-2-u1-X17']::text[],false,'{"seq":5,"concept":"M4-2-u1-C10","difficulty":2,"kind":"mc","stem":"「나는야 분수왕」 분수 카드 ⟨1 4/5⟩, ⟨1/5⟩, ⟨16/5⟩, ⟨3/5⟩, ⟨2 3/5⟩, ⟨2 2/5⟩, ⟨3 3/5⟩, ⟨2/5⟩, ⟨7/5⟩, ⟨1 3/5⟩이 있어요. ⟨2 3/5⟩과 더해서 4가 되는 카드는 무엇인가요?","options":[{"t":"⟨7/5⟩","correct":true},{"t":"⟨1 3/5⟩","mis":"M4-2-u1-X16"},{"t":"⟨2/5⟩","mis":"M4-2-u1-X17"},{"t":"⟨1 4/5⟩","mis":"M4-2-u1-X16"}],"explanation":["4 − ⟨2 3/5⟩ = ⟨3 5/5⟩ − ⟨2 3/5⟩ = ⟨1 2/5⟩예요.","⟨1 2/5⟩ = ⟨7/5⟩ — 가분수 카드 ⟨7/5⟩을 골라요.","⟨2 3/5⟩ + ⟨7/5⟩ = ⟨13/5⟩ + ⟨7/5⟩ = ⟨20/5⟩ = 4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L09_basic#6','math',4,2,'u1','L09','tb_g4_2_math_u1_L09_basic','lesson_basic','M4-2-u1-C10',2,'mc','auto','「나는야 분수왕」 분수 카드 ⟨1 4/5⟩, ⟨1/5⟩, ⟨16/5⟩, ⟨3/5⟩, ⟨2 3/5⟩, ⟨2 2/5⟩, ⟨3 3/5⟩, ⟨2/5⟩, ⟨7/5⟩, ⟨1 3/5⟩이 있어요. ⟨3 3/5⟩에서 빼서 2가 되는 카드는 무엇인가요?',ARRAY['M4-2-u1-X13','M4-2-u1-X16']::text[],false,'{"seq":6,"concept":"M4-2-u1-C10","difficulty":2,"kind":"mc","stem":"「나는야 분수왕」 분수 카드 ⟨1 4/5⟩, ⟨1/5⟩, ⟨16/5⟩, ⟨3/5⟩, ⟨2 3/5⟩, ⟨2 2/5⟩, ⟨3 3/5⟩, ⟨2/5⟩, ⟨7/5⟩, ⟨1 3/5⟩이 있어요. ⟨3 3/5⟩에서 빼서 2가 되는 카드는 무엇인가요?","options":[{"t":"⟨1 3/5⟩","correct":true},{"t":"⟨3/5⟩","mis":"M4-2-u1-X13"},{"t":"⟨1 4/5⟩","mis":"M4-2-u1-X16"},{"t":"⟨7/5⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨3 3/5⟩ − 2 = ⟨1 3/5⟩이에요.","⟨3 3/5⟩ − ⟨1 3/5⟩ = (3 − 1) + (⟨3/5⟩ − ⟨3/5⟩) = 2예요.","⟨3/5⟩을 빼면 ⟨3 3/5⟩ − ⟨3/5⟩ = 3이 되어 2가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L09_basic#7','math',4,2,'u1','L09','tb_g4_2_math_u1_L09_basic','lesson_basic','M4-2-u1-C10',2,'ox','auto','「나는야 분수왕」 서준이는 「뺄셈식 □ − □ = 2에서 빼지는 수에는 2보다 작은 분수 카드를 쓸 수 없어.」라고 했어요. 서준이의 말이 옳은가요?',ARRAY['M4-2-u1-X17']::text[],false,'{"seq":7,"concept":"M4-2-u1-C10","difficulty":2,"kind":"ox","stem":"「나는야 분수왕」 서준이는 「뺄셈식 □ − □ = 2에서 빼지는 수에는 2보다 작은 분수 카드를 쓸 수 없어.」라고 했어요. 서준이의 말이 옳은가요?","answer":"O","reason_options":[{"t":"빼는 수가 있으면 차는 빼지는 수보다 작아져서","correct":true},{"t":"빼지는 수에는 어떤 카드를 써도 되어서","mis":"M4-2-u1-X17"}],"mis":"M4-2-u1-X17","explanation":["차가 2가 되려면 빼지는 수가 2보다 커야 해요.","⟨1 4/5⟩처럼 2보다 작은 수에서는 무엇을 빼도 2가 될 수 없어요.","그래서 ⟨2 3/5⟩, ⟨2 2/5⟩, ⟨3 3/5⟩, ⟨16/5⟩처럼 2보다 큰 카드만 살펴보면 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L09_basic#8','math',4,2,'u1','L09','tb_g4_2_math_u1_L09_basic','lesson_basic','M4-2-u1-C10',2,'mc','auto','「나는야 분수왕」 분수 카드 ⟨1 2/3⟩, ⟨1/3⟩, ⟨13/3⟩, ⟨3 1/3⟩, ⟨2 1/3⟩ 중에서 3장을 골라 계산 결과가 6이 되는 덧셈식을 완성하려고 해요. 골라야 하는 카드 3장은 무엇인가요?',ARRAY['M4-2-u1-X17','M4-2-u1-X16']::text[],false,'{"seq":8,"concept":"M4-2-u1-C10","difficulty":2,"kind":"mc","stem":"「나는야 분수왕」 분수 카드 ⟨1 2/3⟩, ⟨1/3⟩, ⟨13/3⟩, ⟨3 1/3⟩, ⟨2 1/3⟩ 중에서 3장을 골라 계산 결과가 6이 되는 덧셈식을 완성하려고 해요. 골라야 하는 카드 3장은 무엇인가요?","options":[{"t":"⟨1/3⟩, ⟨3 1/3⟩, ⟨2 1/3⟩","correct":true},{"t":"⟨1 2/3⟩, ⟨1/3⟩, ⟨13/3⟩","mis":"M4-2-u1-X17"},{"t":"⟨1 2/3⟩, ⟨3 1/3⟩, ⟨2 1/3⟩","mis":"M4-2-u1-X17"},{"t":"⟨1/3⟩, ⟨13/3⟩, ⟨2 1/3⟩","mis":"M4-2-u1-X16"}],"explanation":["6 = ⟨18/3⟩ — 세 카드의 ⟨1/3⟩ 개수의 합이 18이 되게 골라요.","⟨1/3⟩ + ⟨3 1/3⟩ + ⟨2 1/3⟩ = ⟨1/3⟩ + ⟨10/3⟩ + ⟨7/3⟩ = ⟨18/3⟩이에요.","⟨18/3⟩ = 6 — 다른 3장은 6이 되지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L09_basic#9','math',4,2,'u1','L09','tb_g4_2_math_u1_L09_basic','lesson_basic','M4-2-u1-C10',2,'mc','auto','「익힘」 가 과일 바구니에는 파인애플과 배가 한 개씩 들어 있고, 바구니까지 모두 ⟨2 3/10⟩ kg이에요. 배 한 개는 ⟨6/10⟩ kg, 바구니 한 개는 ⟨4/10⟩ kg일 때 파인애플의 무게는 몇 kg인가요?',ARRAY['M4-2-u1-X15','M4-2-u1-X14']::text[],false,'{"seq":9,"concept":"M4-2-u1-C10","difficulty":2,"kind":"mc","stem":"「익힘」 가 과일 바구니에는 파인애플과 배가 한 개씩 들어 있고, 바구니까지 모두 ⟨2 3/10⟩ kg이에요. 배 한 개는 ⟨6/10⟩ kg, 바구니 한 개는 ⟨4/10⟩ kg일 때 파인애플의 무게는 몇 kg인가요?","options":[{"t":"⟨1 3/10⟩ kg","correct":true},{"t":"⟨1 7/10⟩ kg","mis":"M4-2-u1-X15"},{"t":"⟨1 9/10⟩ kg","mis":"M4-2-u1-X15"},{"t":"⟨3 3/10⟩ kg","mis":"M4-2-u1-X14"}],"explanation":["파인애플의 무게는 가 바구니의 무게에서 배와 바구니의 무게를 빼서 구해요.","⟨2 3/10⟩ − ⟨6/10⟩ − ⟨4/10⟩ = ⟨1 7/10⟩ − ⟨4/10⟩ = ⟨1 3/10⟩이에요.","배와 바구니를 먼저 더해 ⟨6/10⟩ + ⟨4/10⟩ = 1을 빼도 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L09_basic#10','math',4,2,'u1','L09','tb_g4_2_math_u1_L09_basic','lesson_basic','M4-2-u1-C10',3,'sa','auto','「익힘」 가 바구니(파인애플·배·바구니)는 ⟨2 3/10⟩ kg, 나 바구니(멜론·배·바구니)는 ⟨2 7/10⟩ kg이에요. 배 한 개는 ⟨6/10⟩ kg, 바구니 한 개는 ⟨4/10⟩ kg이에요. 파인애플, 멜론, 배가 한 개씩 들어 있는 다 바구니의 무게는 몇 kg인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u1-C10","difficulty":3,"kind":"sa","stem":"「익힘」 가 바구니(파인애플·배·바구니)는 ⟨2 3/10⟩ kg, 나 바구니(멜론·배·바구니)는 ⟨2 7/10⟩ kg이에요. 배 한 개는 ⟨6/10⟩ kg, 바구니 한 개는 ⟨4/10⟩ kg이에요. 파인애플, 멜론, 배가 한 개씩 들어 있는 다 바구니의 무게는 몇 kg인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["배와 바구니는 ⟨6/10⟩ + ⟨4/10⟩ = 1 kg — 파인애플은 ⟨2 3/10⟩ − 1 = ⟨1 3/10⟩ kg, 멜론은 ⟨2 7/10⟩ − 1 = ⟨1 7/10⟩ kg이에요.","⟨1 3/10⟩ + ⟨1 7/10⟩ + 1 = 4예요.","다 바구니의 무게는 4 kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L09_challenge#1','math',4,2,'u1','L09','tb_g4_2_math_u1_L09_challenge','lesson_challenge','M4-2-u1-C10',2,'mc','auto','「나는야 분수왕」 분수 카드 ⟨1 4/5⟩, ⟨1/5⟩, ⟨16/5⟩, ⟨3/5⟩, ⟨2 3/5⟩, ⟨2 2/5⟩, ⟨3 3/5⟩, ⟨2/5⟩, ⟨7/5⟩, ⟨1 3/5⟩이 있어요. 두 장을 골라 □ + □ = 4를 만들 수 없는 것은 무엇인가요?',ARRAY['M4-2-u1-X17']::text[],false,'{"seq":1,"concept":"M4-2-u1-C10","difficulty":2,"kind":"mc","stem":"「나는야 분수왕」 분수 카드 ⟨1 4/5⟩, ⟨1/5⟩, ⟨16/5⟩, ⟨3/5⟩, ⟨2 3/5⟩, ⟨2 2/5⟩, ⟨3 3/5⟩, ⟨2/5⟩, ⟨7/5⟩, ⟨1 3/5⟩이 있어요. 두 장을 골라 □ + □ = 4를 만들 수 없는 것은 무엇인가요?","options":[{"t":"⟨16/5⟩, ⟨3/5⟩","correct":true},{"t":"⟨2 3/5⟩, ⟨7/5⟩","mis":"M4-2-u1-X17"},{"t":"⟨2 2/5⟩, ⟨1 3/5⟩","mis":"M4-2-u1-X17"},{"t":"⟨3 3/5⟩, ⟨2/5⟩","mis":"M4-2-u1-X17"}],"explanation":["4 = ⟨20/5⟩ — 두 카드의 ⟨1/5⟩ 개수의 합이 20이어야 해요.","⟨16/5⟩ + ⟨3/5⟩ = ⟨19/5⟩ = ⟨3 4/5⟩ — 4가 아니에요.","⟨2 3/5⟩ + ⟨7/5⟩ = 4, ⟨2 2/5⟩ + ⟨1 3/5⟩ = 4, ⟨3 3/5⟩ + ⟨2/5⟩ = 4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L09_challenge#2','math',4,2,'u1','L09','tb_g4_2_math_u1_L09_challenge','lesson_challenge','M4-2-u1-C10',2,'sa','auto','「지도서」 4는 ⟨1/5⟩이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u1-C10","difficulty":2,"kind":"sa","stem":"「지도서」 4는 ⟨1/5⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["1은 ⟨1/5⟩이 5개예요.","4는 1이 4개 — ⟨1/5⟩이 4 × 5 = 20개예요.","4 = ⟨20/5⟩."],"variant_rule":{"alt":[{"stem":"「지도서」 2는 ⟨1/5⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["1은 ⟨1/5⟩이 5개예요.","2는 1이 2개 — ⟨1/5⟩이 2 × 5 = 10개예요.","2 = ⟨10/5⟩."]},{"stem":"「지도서」 6은 ⟨1/3⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["1은 ⟨1/3⟩이 3개예요.","6은 1이 6개 — ⟨1/3⟩이 6 × 3 = 18개예요.","6 = ⟨18/3⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L09_challenge#3','math',4,2,'u1','L09','tb_g4_2_math_u1_L09_challenge','lesson_challenge','M4-2-u1-C10',3,'mc','auto','「나는야 분수왕」 분수 카드 10장(⟨1 4/5⟩, ⟨1/5⟩, ⟨16/5⟩, ⟨3/5⟩, ⟨2 3/5⟩, ⟨2 2/5⟩, ⟨3 3/5⟩, ⟨2/5⟩, ⟨7/5⟩, ⟨1 3/5⟩)을 한 번씩만 사용해요. 덧셈식 ⟨2 3/5⟩ + ⟨7/5⟩ = 4를 먼저 만들었다면, 뺄셈식 □ − □ = 2에 쓸 수 있는 두 카드는 무엇인가요?',ARRAY['M4-2-u1-X15','M4-2-u1-X17','M4-2-u1-X16']::text[],false,'{"seq":3,"concept":"M4-2-u1-C10","difficulty":3,"kind":"mc","stem":"「나는야 분수왕」 분수 카드 10장(⟨1 4/5⟩, ⟨1/5⟩, ⟨16/5⟩, ⟨3/5⟩, ⟨2 3/5⟩, ⟨2 2/5⟩, ⟨3 3/5⟩, ⟨2/5⟩, ⟨7/5⟩, ⟨1 3/5⟩)을 한 번씩만 사용해요. 덧셈식 ⟨2 3/5⟩ + ⟨7/5⟩ = 4를 먼저 만들었다면, 뺄셈식 □ − □ = 2에 쓸 수 있는 두 카드는 무엇인가요?","options":[{"t":"⟨2 2/5⟩, ⟨2/5⟩","correct":true},{"t":"⟨2 3/5⟩, ⟨3/5⟩","mis":"M4-2-u1-X15"},{"t":"⟨3 3/5⟩, ⟨2/5⟩","mis":"M4-2-u1-X17"},{"t":"⟨16/5⟩, ⟨1 4/5⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨2 3/5⟩과 ⟨7/5⟩은 이미 썼으니 다시 쓸 수 없어요.","⟨2 2/5⟩ − ⟨2/5⟩ = 2예요.","⟨3 3/5⟩ − ⟨2/5⟩ = ⟨3 1/5⟩, ⟨16/5⟩ − ⟨1 4/5⟩ = ⟨7/5⟩ — 2가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L09_challenge#4','math',4,2,'u1','L09','tb_g4_2_math_u1_L09_challenge','lesson_challenge','M4-2-u1-C10',3,'error','auto','「나는야 분수왕」 합이 4가 되는 두 카드를 찾는 방법을 친구들이 말했어요. 알맞지 않은 방법을 말한 친구는 누구인가요?',ARRAY['M4-2-u1-X17','M4-2-u1-X15']::text[],false,'{"seq":4,"concept":"M4-2-u1-C10","difficulty":3,"kind":"error","stem":"「나는야 분수왕」 합이 4가 되는 두 카드를 찾는 방법을 친구들이 말했어요. 알맞지 않은 방법을 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「분자가 가장 큰 ⟨16/5⟩ 카드는 꼭 써야 해.」","correct":true,"mis_target":"M4-2-u1-X17"},{"t":"서준 — 「모두 가분수로 바꾸어 합이 ⟨20/5⟩이 되는 두 카드를 찾아.」","mis":"M4-2-u1-X15"},{"t":"채원 — 「어림해서 2와 3 사이의 수와 1과 2 사이의 수를 고르고 계산으로 확인해.」","mis":"M4-2-u1-X15"},{"t":"지유 — 「대분수로 바꾸어 분수 부분의 합이 1이 되는지 살펴봐.」","mis":"M4-2-u1-X15"}],"explanation":["⟨16/5⟩ = ⟨3 1/5⟩ — 더해서 4가 되려면 ⟨4/5⟩가 있어야 하는데 그런 카드가 없어요.","어림하기, 가분수로 바꾸기, 분수 부분 살펴보기는 모두 좋은 방법이에요.","분자가 큰 카드 하나만 보고 정하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L09_challenge#5','math',4,2,'u1','L09','tb_g4_2_math_u1_L09_challenge','lesson_challenge','M4-2-u1-C10',3,'sa','auto','「익힘」 나 과일 바구니에는 멜론과 배가 한 개씩 들어 있고, 바구니까지 모두 ⟨2 7/10⟩ kg이에요. 배 한 개는 ⟨6/10⟩ kg, 바구니 한 개는 ⟨4/10⟩ kg일 때 멜론의 무게는 ⟨1 □/10⟩ kg이에요. □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M4-2-u1-C10","difficulty":3,"kind":"sa","stem":"「익힘」 나 과일 바구니에는 멜론과 배가 한 개씩 들어 있고, 바구니까지 모두 ⟨2 7/10⟩ kg이에요. 배 한 개는 ⟨6/10⟩ kg, 바구니 한 개는 ⟨4/10⟩ kg일 때 멜론의 무게는 ⟨1 □/10⟩ kg이에요. □에 알맞은 수를 쓰세요.","answer":["7"],"explanation":["멜론의 무게는 나 바구니의 무게에서 배와 바구니의 무게를 빼서 구해요.","⟨2 7/10⟩ − ⟨6/10⟩ − ⟨4/10⟩ = ⟨2 1/10⟩ − ⟨4/10⟩ = ⟨1 7/10⟩이에요.","배와 바구니를 합한 1을 빼도 ⟨2 7/10⟩ − 1 = ⟨1 7/10⟩ — □ = 7."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L09_challenge#6','math',4,2,'u1','L09','tb_g4_2_math_u1_L09_challenge','lesson_challenge','M4-2-u1-C10',3,'ox','auto','「나는야 분수왕」 채원이는 「⟨1/3⟩ + ⟨3 1/3⟩ + ⟨2 1/3⟩ = 6이야.」라고 했어요. 채원이의 말이 옳은가요?',ARRAY['M4-2-u1-X01']::text[],false,'{"seq":6,"concept":"M4-2-u1-C10","difficulty":3,"kind":"ox","stem":"「나는야 분수왕」 채원이는 「⟨1/3⟩ + ⟨3 1/3⟩ + ⟨2 1/3⟩ = 6이야.」라고 했어요. 채원이의 말이 옳은가요?","answer":"O","reason_options":[{"t":"자연수끼리 3 + 2 = 5, 분수끼리 ⟨3/3⟩ = 1이라 모두 6이라서","correct":true},{"t":"분모끼리도 더해야 해서","mis":"M4-2-u1-X01"}],"mis":"M4-2-u1-X01","explanation":["자연수끼리 3 + 2 = 5예요.","분수끼리 ⟨1/3⟩ + ⟨1/3⟩ + ⟨1/3⟩ = ⟨3/3⟩ = 1이에요.","5 + 1 = 6 — 채원이의 말이 옳아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L09_challenge#7','math',4,2,'u1','L09','tb_g4_2_math_u1_L09_challenge','lesson_challenge','M4-2-u1-C10',3,'mc','auto','「익힘」 가 바구니(파인애플·배·바구니)는 ⟨2 3/10⟩ kg, 나 바구니(멜론·배·바구니)는 ⟨2 7/10⟩ kg, 배는 ⟨6/10⟩ kg, 바구니는 ⟨4/10⟩ kg이에요. 가와 나의 무게를 더한 뒤 필요 없는 것을 빼서 다 바구니(파인애플·멜론·배·바구니)의 무게를 구하는 식으로 알맞은 것은 무엇인가요?',ARRAY['M4-2-u1-X15','M4-2-u1-X14']::text[],false,'{"seq":7,"concept":"M4-2-u1-C10","difficulty":3,"kind":"mc","stem":"「익힘」 가 바구니(파인애플·배·바구니)는 ⟨2 3/10⟩ kg, 나 바구니(멜론·배·바구니)는 ⟨2 7/10⟩ kg, 배는 ⟨6/10⟩ kg, 바구니는 ⟨4/10⟩ kg이에요. 가와 나의 무게를 더한 뒤 필요 없는 것을 빼서 다 바구니(파인애플·멜론·배·바구니)의 무게를 구하는 식으로 알맞은 것은 무엇인가요?","options":[{"t":"⟨2 3/10⟩ + ⟨2 7/10⟩ − ⟨6/10⟩ − ⟨4/10⟩","correct":true},{"t":"⟨2 3/10⟩ + ⟨2 7/10⟩ − ⟨6/10⟩","mis":"M4-2-u1-X15"},{"t":"⟨2 3/10⟩ + ⟨2 7/10⟩","mis":"M4-2-u1-X15"},{"t":"⟨2 3/10⟩ + ⟨2 7/10⟩ + ⟨6/10⟩ + ⟨4/10⟩","mis":"M4-2-u1-X14"}],"explanation":["가와 나를 더하면 배 2개, 바구니 2개가 들어 있어요.","다 바구니에는 배와 바구니가 한 개씩이라 배 한 개와 바구니 한 개를 빼요.","⟨2 3/10⟩ + ⟨2 7/10⟩ − ⟨6/10⟩ − ⟨4/10⟩ = 5 − 1 = 4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L09_challenge#8','math',4,2,'u1','L09','tb_g4_2_math_u1_L09_challenge','lesson_challenge','M4-2-u1-C10',4,'essay','teacher','「나는야 분수왕」 분수 카드 10장(⟨1 4/5⟩, ⟨1/5⟩, ⟨16/5⟩, ⟨3/5⟩, ⟨2 3/5⟩, ⟨2 2/5⟩, ⟨3 3/5⟩, ⟨2/5⟩, ⟨7/5⟩, ⟨1 3/5⟩)을 한 번씩만 사용하여 □ + □ = 4인 덧셈식과 □ − □ = 2인 뺄셈식을 완성하고, 어떻게 찾았는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u1-C10","difficulty":4,"kind":"essay","stem":"「나는야 분수왕」 분수 카드 10장(⟨1 4/5⟩, ⟨1/5⟩, ⟨16/5⟩, ⟨3/5⟩, ⟨2 3/5⟩, ⟨2 2/5⟩, ⟨3 3/5⟩, ⟨2/5⟩, ⟨7/5⟩, ⟨1 3/5⟩)을 한 번씩만 사용하여 □ + □ = 4인 덧셈식과 □ − □ = 2인 뺄셈식을 완성하고, 어떻게 찾았는지 설명해 보세요.","answer_guide":{"answer":"예: ⟨2 3/5⟩ + ⟨7/5⟩ = 4, ⟨2 2/5⟩ − ⟨2/5⟩ = 2(또는 ⟨2 2/5⟩ + ⟨1 3/5⟩ = 4, ⟨2 3/5⟩ − ⟨3/5⟩ = 2). 4 = ⟨20/5⟩, 2 = ⟨10/5⟩이므로 모두 가분수로 바꾸어 ⟨1/5⟩ 개수의 합이 20, 차가 10인 두 카드를 찾았다. 덧셈식에 쓴 카드는 뺄셈식에 다시 쓰지 않았다.","scoring_points":["합이 4인 덧셈식을 바르게 썼는가","차가 2인 뺄셈식을 카드를 겹치지 않게 썼는가","어림이나 가분수로 바꾸기 등 찾은 방법을 설명했는가"]},"explanation":["4 = ⟨20/5⟩, 2 = ⟨10/5⟩이에요.","⟨2 3/5⟩ + ⟨7/5⟩ = 4, ⟨2 2/5⟩ − ⟨2/5⟩ = 2예요.","카드를 겹치지 않게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L09_challenge#9','math',4,2,'u1','L09','tb_g4_2_math_u1_L09_challenge','lesson_challenge','M4-2-u1-C10',4,'essay','teacher','「나는야 분수왕」 분수 카드 ⟨1 2/3⟩, ⟨1/3⟩, ⟨13/3⟩, ⟨3 1/3⟩, ⟨2 1/3⟩ 중에서 3장을 골라 계산 결과가 6이 되는 덧셈식을 완성하고, 어떤 전략으로 찾았는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u1-C10","difficulty":4,"kind":"essay","stem":"「나는야 분수왕」 분수 카드 ⟨1 2/3⟩, ⟨1/3⟩, ⟨13/3⟩, ⟨3 1/3⟩, ⟨2 1/3⟩ 중에서 3장을 골라 계산 결과가 6이 되는 덧셈식을 완성하고, 어떤 전략으로 찾았는지 설명해 보세요.","answer_guide":{"answer":"예: ⟨1/3⟩ + ⟨3 1/3⟩ + ⟨2 1/3⟩ = 6이다. 6 = ⟨18/3⟩이므로 모두 가분수로 바꾸어 ⟨1/3⟩ 개수의 합이 18인 세 카드를 찾았다(또는 카드 2장을 먼저 더하고 6이 되려면 얼마가 더 필요한지 어림했다).","scoring_points":["⟨1/3⟩ + ⟨3 1/3⟩ + ⟨2 1/3⟩ = 6을 찾았는가","6 = ⟨18/3⟩처럼 가분수로 바꾸거나 어림했는가","찾은 전략을 설명했는가"]},"explanation":["6 = ⟨18/3⟩이에요.","⟨1/3⟩ + ⟨10/3⟩ + ⟨7/3⟩ = ⟨18/3⟩이에요.","⟨1/3⟩ + ⟨3 1/3⟩ + ⟨2 1/3⟩ = 6."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_L09_challenge#10','math',4,2,'u1','L09','tb_g4_2_math_u1_L09_challenge','lesson_challenge','M4-2-u1-C10',4,'essay','teacher','「익힘」 가 바구니(파인애플·배·바구니)는 ⟨2 3/10⟩ kg, 나 바구니(멜론·배·바구니)는 ⟨2 7/10⟩ kg, 배 한 개는 ⟨6/10⟩ kg, 바구니 한 개는 ⟨4/10⟩ kg이에요. 다 바구니(파인애플·멜론·배·바구니)의 무게를 구하는 방법을 2가지 이상 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u1-C10","difficulty":4,"kind":"essay","stem":"「익힘」 가 바구니(파인애플·배·바구니)는 ⟨2 3/10⟩ kg, 나 바구니(멜론·배·바구니)는 ⟨2 7/10⟩ kg, 배 한 개는 ⟨6/10⟩ kg, 바구니 한 개는 ⟨4/10⟩ kg이에요. 다 바구니(파인애플·멜론·배·바구니)의 무게를 구하는 방법을 2가지 이상 설명해 보세요.","answer_guide":{"answer":"예: 방법 1 — 파인애플 ⟨2 3/10⟩ − ⟨6/10⟩ − ⟨4/10⟩ = ⟨1 3/10⟩ (kg), 멜론 ⟨2 7/10⟩ − ⟨6/10⟩ − ⟨4/10⟩ = ⟨1 7/10⟩ (kg)을 구해 ⟨1 3/10⟩ + ⟨1 7/10⟩ + ⟨6/10⟩ + ⟨4/10⟩ = 4 (kg)이다. 방법 2 — 가와 나를 더한 ⟨2 3/10⟩ + ⟨2 7/10⟩ = 5 (kg)에서 배 한 개와 바구니 한 개를 빼면 5 − ⟨6/10⟩ − ⟨4/10⟩ = 4 (kg)이다.","scoring_points":["파인애플·멜론의 무게를 구해 더하는 방법을 썼는가","가와 나를 더한 뒤 빼는 방법을 썼는가","4 kg이라고 답했는가"]},"explanation":["파인애플 ⟨1 3/10⟩ kg, 멜론 ⟨1 7/10⟩ kg이에요.","⟨2 3/10⟩ + ⟨2 7/10⟩ = 5예요.","다 바구니는 4 kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_a#1','math',4,2,'u1','','tb_g4_2_math_u1_review_a','unit_review','M4-2-u1-C2',1,'mc','auto','「스스로 마무리하기」 빈칸을 채워요. 분수 띠로 1을 ⟨1/3⟩과 □로 갈랐어요. □에 알맞은 분수는 무엇인가요?',ARRAY['M4-2-u1-X06','M4-2-u1-X05']::text[],false,'{"seq":1,"concept":"M4-2-u1-C2","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 빈칸을 채워요. 분수 띠로 1을 ⟨1/3⟩과 □로 갈랐어요. □에 알맞은 분수는 무엇인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨1/3⟩","mis":"M4-2-u1-X06"},{"t":"⟨4/3⟩","mis":"M4-2-u1-X06"},{"t":"⟨3/3⟩","mis":"M4-2-u1-X05"}],"explanation":["1 = ⟨3/3⟩ — ⟨1/3⟩이 3개예요.","⟨1/3⟩은 ⟨1/3⟩이 1개라 3 − 1 = 2개가 모자라요.","⟨1/3⟩ + ⟨2/3⟩ = ⟨3/3⟩ = 1이에요."],"asset":{"type":"fbar","bars":[{"den":3,"num":1,"label":"1을 가르기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_a#2','math',4,2,'u1','','tb_g4_2_math_u1_review_a','unit_review','M4-2-u1-C3',1,'sa','auto','「스스로 마무리하기」 빈칸을 채워요. ⟨1/5⟩ + ⟨3/5⟩ = ⟨□/5⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M4-2-u1-C3","difficulty":1,"kind":"sa","stem":"「스스로 마무리하기」 빈칸을 채워요. ⟨1/5⟩ + ⟨3/5⟩ = ⟨□/5⟩ — □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["⟨1/5⟩은 ⟨1/5⟩이 1개, ⟨3/5⟩은 ⟨1/5⟩이 3개예요.","⟨1/5⟩ + ⟨3/5⟩ = ⟨4/5⟩ — 분모는 그대로 두고 분자끼리 더해요.","분모끼리 더한 ⟨4/10⟩는 답이 아니에요 — 답은 ⟨4/5⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_a#3','math',4,2,'u1','','tb_g4_2_math_u1_review_a','unit_review','M4-2-u1-C4',1,'sa','auto','「스스로 마무리하기」 빈칸을 채워요. ⟨6/9⟩ − ⟨2/9⟩ = ⟨□/9⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M4-2-u1-C4","difficulty":1,"kind":"sa","stem":"「스스로 마무리하기」 빈칸을 채워요. ⟨6/9⟩ − ⟨2/9⟩ = ⟨□/9⟩ — □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["⟨6/9⟩은 ⟨1/9⟩이 6개, ⟨2/9⟩는 ⟨1/9⟩이 2개예요.","⟨6/9⟩ − ⟨2/9⟩ = ⟨4/9⟩ — 분모는 그대로 두고 분자끼리 빼요.","⟨1/9⟩이 6 − 2 = 4개 남아요 — 분모끼리 빼지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_a#4','math',4,2,'u1','','tb_g4_2_math_u1_review_a','unit_review','M4-2-u1-C5',1,'mc','auto','「스스로 마무리하기」 빈칸을 채워요. ⟨1 1/4⟩ + ⟨2 2/4⟩를 계산해 보세요.',ARRAY['M4-2-u1-X01','M4-2-u1-X13','M4-2-u1-X16']::text[],false,'{"seq":4,"concept":"M4-2-u1-C5","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 빈칸을 채워요. ⟨1 1/4⟩ + ⟨2 2/4⟩를 계산해 보세요.","options":[{"t":"⟨3 3/4⟩","correct":true},{"t":"⟨3 3/8⟩","mis":"M4-2-u1-X01"},{"t":"⟨3/4⟩","mis":"M4-2-u1-X13"},{"t":"4","mis":"M4-2-u1-X16"}],"explanation":["방법 1 — 자연수끼리 1 + 2 = 3, 분수끼리 ⟨1/4⟩ + ⟨2/4⟩ = ⟨3/4⟩이에요.","3 + ⟨3/4⟩ = ⟨3 3/4⟩.","방법 2 — 가분수로 바꾸면 ⟨5/4⟩ + ⟨10/4⟩ = ⟨15/4⟩ = ⟨3 3/4⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_a#5','math',4,2,'u1','','tb_g4_2_math_u1_review_a','unit_review','M4-2-u1-C6',1,'sa','auto','「스스로 마무리하기」 빈칸을 채워요. ⟨3 3/4⟩ − ⟨1 1/4⟩ = ⟨15/4⟩ − ⟨5/4⟩ = ⟨□/4⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M4-2-u1-C6","difficulty":1,"kind":"sa","stem":"「스스로 마무리하기」 빈칸을 채워요. ⟨3 3/4⟩ − ⟨1 1/4⟩ = ⟨15/4⟩ − ⟨5/4⟩ = ⟨□/4⟩ — □에 알맞은 수를 쓰세요.","answer":["10"],"explanation":["⟨3 3/4⟩ = ⟨15/4⟩, ⟨1 1/4⟩ = ⟨5/4⟩예요.","⟨15/4⟩ − ⟨5/4⟩ = ⟨10/4⟩ — 분모는 그대로예요.","⟨10/4⟩ = ⟨2 2/4⟩ — □ = 10."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_a#6','math',4,2,'u1','','tb_g4_2_math_u1_review_a','unit_review','M4-2-u1-C8',1,'mc','auto','「스스로 마무리하기」 빈칸을 채워요. ⟨2 1/6⟩ − ⟨5/6⟩를 계산해 보세요.',ARRAY['M4-2-u1-X11','M4-2-u1-X09','M4-2-u1-X16']::text[],false,'{"seq":6,"concept":"M4-2-u1-C8","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 빈칸을 채워요. ⟨2 1/6⟩ − ⟨5/6⟩를 계산해 보세요.","options":[{"t":"⟨1 2/6⟩","correct":true},{"t":"⟨2 4/6⟩","mis":"M4-2-u1-X11"},{"t":"⟨2 2/6⟩","mis":"M4-2-u1-X09"},{"t":"⟨1 3/6⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨1/6⟩에서 ⟨5/6⟩를 뺄 수 없어 1만큼을 ⟨6/6⟩으로 바꿔요 — ⟨2 1/6⟩ = ⟨1 7/6⟩.","⟨1 7/6⟩ − ⟨5/6⟩ = ⟨1 2/6⟩ — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨13/6⟩ − ⟨5/6⟩ = ⟨8/6⟩ = ⟨1 2/6⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_a#7','math',4,2,'u1','','tb_g4_2_math_u1_review_a','unit_review','M4-2-u1-C3',1,'mc','auto','「스스로 마무리하기」 1번 그림을 보고 ⟨3/5⟩ + ⟨4/5⟩를 계산하여 대분수로 나타내면 얼마인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X04']::text[],false,'{"seq":7,"concept":"M4-2-u1-C3","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 1번 그림을 보고 ⟨3/5⟩ + ⟨4/5⟩를 계산하여 대분수로 나타내면 얼마인가요?","options":[{"t":"⟨1 2/5⟩","correct":true},{"t":"⟨7/10⟩","mis":"M4-2-u1-X01"},{"t":"⟨2/5⟩","mis":"M4-2-u1-X04"},{"t":"⟨2 2/5⟩","mis":"M4-2-u1-X04"}],"explanation":["⟨3/5⟩은 ⟨1/5⟩이 3개, ⟨4/5⟩는 ⟨1/5⟩이 4개예요.","⟨3/5⟩ + ⟨4/5⟩ = ⟨7/5⟩ — 분모는 그대로 두고 분자끼리 더해요.","⟨7/5⟩ = ⟨1 2/5⟩ — 분모끼리 더하지 않아요."],"asset":{"type":"fbar","bars":[{"den":5,"num":3},{"den":5,"num":4}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_a#8','math',4,2,'u1','','tb_g4_2_math_u1_review_a','unit_review','M4-2-u1-C7',1,'match','auto','「스스로 마무리하기」 2번 계산 결과끼리 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u1-C7","difficulty":1,"kind":"match","stem":"「스스로 마무리하기」 2번 계산 결과끼리 알맞게 이으세요.","pairs":[{"l":"⟨2/7⟩ + ⟨3/7⟩","r":"⟨5/7⟩"},{"l":"⟨1 4/12⟩ + ⟨3 7/12⟩","r":"⟨4 11/12⟩"},{"l":"⟨8/10⟩ − ⟨2/10⟩","r":"⟨6/10⟩"},{"l":"3 − ⟨1 3/4⟩","r":"⟨1 1/4⟩"}],"mis":"M4-2-u1-X09","explanation":["⟨2/7⟩ + ⟨3/7⟩ = ⟨5/7⟩, ⟨8/10⟩ − ⟨2/10⟩ = ⟨6/10⟩이에요.","⟨1 4/12⟩ + ⟨3 7/12⟩ = ⟨4 11/12⟩이에요.","3 − ⟨1 3/4⟩ = ⟨2 4/4⟩ − ⟨1 3/4⟩ = ⟨1 1/4⟩ — 1만큼을 ⟨4/4⟩로 바꾸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_a#9','math',4,2,'u1','','tb_g4_2_math_u1_review_a','unit_review','M4-2-u1-C5',2,'mc','auto','「스스로 마무리하기」 3번 두 분수 ⟨4 3/6⟩과 ⟨22/6⟩의 합은 얼마인가요?',ARRAY['M4-2-u1-X07','M4-2-u1-X16','M4-2-u1-X14']::text[],false,'{"seq":9,"concept":"M4-2-u1-C5","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 3번 두 분수 ⟨4 3/6⟩과 ⟨22/6⟩의 합은 얼마인가요?","options":[{"t":"⟨8 1/6⟩","correct":true},{"t":"⟨7 1/6⟩","mis":"M4-2-u1-X07"},{"t":"⟨8 2/6⟩","mis":"M4-2-u1-X16"},{"t":"⟨5/6⟩","mis":"M4-2-u1-X14"}],"explanation":["⟨22/6⟩ = ⟨3 4/6⟩예요.","⟨4 3/6⟩ + ⟨3 4/6⟩ = 7 + ⟨7/6⟩ = 7 + ⟨1 1/6⟩ = ⟨8 1/6⟩이에요.","가분수로 바꾸면 ⟨27/6⟩ + ⟨22/6⟩ = ⟨49/6⟩ = ⟨8 1/6⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_a#10','math',4,2,'u1','','tb_g4_2_math_u1_review_a','unit_review','M4-2-u1-C5',2,'mc','auto','「스스로 마무리하기」 4번 계산 결과가 큰 것부터 차례대로 기호를 쓴 것은 무엇인가요?  ㉠ ⟨1 3/8⟩ + ⟨2 4/8⟩  ㉡ ⟨4 5/8⟩ − ⟨1 3/8⟩  ㉢ ⟨3 3/8⟩ + ⟨5/8⟩',ARRAY['M4-2-u1-X15','M4-2-u1-X17','M4-2-u1-X16']::text[],false,'{"seq":10,"concept":"M4-2-u1-C5","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 4번 계산 결과가 큰 것부터 차례대로 기호를 쓴 것은 무엇인가요?  ㉠ ⟨1 3/8⟩ + ⟨2 4/8⟩  ㉡ ⟨4 5/8⟩ − ⟨1 3/8⟩  ㉢ ⟨3 3/8⟩ + ⟨5/8⟩","options":[{"t":"㉢, ㉠, ㉡","correct":true},{"t":"㉡, ㉠, ㉢","mis":"M4-2-u1-X15"},{"t":"㉠, ㉢, ㉡","mis":"M4-2-u1-X17"},{"t":"㉢, ㉡, ㉠","mis":"M4-2-u1-X16"}],"explanation":["하나씩 계산해요 — ㉠ ⟨1 3/8⟩ + ⟨2 4/8⟩ = ⟨3 7/8⟩, ㉡ ⟨4 5/8⟩ − ⟨1 3/8⟩ = ⟨3 2/8⟩, ㉢ ⟨3 3/8⟩ + ⟨5/8⟩ = 4.","4 > ⟨3 7/8⟩ > ⟨3 2/8⟩예요.","계산 결과가 큰 것부터 쓰면 ㉢, ㉠, ㉡예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_a#11','math',4,2,'u1','','tb_g4_2_math_u1_review_a','unit_review','M4-2-u1-C4',2,'mc','auto','「스스로 마무리하기」 5번 미술 시간에 지점토로 동물 모형 만들기를 하고 있어요. 지점토 1 kg 중에서 거북 모형을 만드는 데 ⟨4/6⟩ kg을 사용했어요. 남은 지점토는 몇 kg인가요?',ARRAY['M4-2-u1-X08','M4-2-u1-X15','M4-2-u1-X16']::text[],false,'{"seq":11,"concept":"M4-2-u1-C4","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 5번 미술 시간에 지점토로 동물 모형 만들기를 하고 있어요. 지점토 1 kg 중에서 거북 모형을 만드는 데 ⟨4/6⟩ kg을 사용했어요. 남은 지점토는 몇 kg인가요?","options":[{"t":"⟨2/6⟩ kg","correct":true},{"t":"⟨3/6⟩ kg","mis":"M4-2-u1-X08"},{"t":"⟨4/6⟩ kg","mis":"M4-2-u1-X15"},{"t":"⟨1/6⟩ kg","mis":"M4-2-u1-X16"}],"explanation":["1은 ⟨1/6⟩이 6개 — 1 = ⟨6/6⟩이에요.","1 − ⟨4/6⟩ = ⟨6/6⟩ − ⟨4/6⟩ = ⟨2/6⟩ kg.","1을 가분수로 바꾼 뒤 분자끼리 빼요 — 6 − 4 = 2."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_a#12','math',4,2,'u1','','tb_g4_2_math_u1_review_a','unit_review','M4-2-u1-C7',2,'mc','auto','「스스로 마무리하기」 6번 친구가 「4 − ⟨3/9⟩ = ⟨1/9⟩」이라고 계산했어요. 바르게 계산한 값은 얼마인가요?',ARRAY['M4-2-u1-X19','M4-2-u1-X10','M4-2-u1-X09']::text[],false,'{"seq":12,"concept":"M4-2-u1-C7","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 6번 친구가 「4 − ⟨3/9⟩ = ⟨1/9⟩」이라고 계산했어요. 바르게 계산한 값은 얼마인가요?","options":[{"t":"⟨3 6/9⟩","correct":true},{"t":"⟨1/9⟩","mis":"M4-2-u1-X19"},{"t":"⟨3 3/9⟩","mis":"M4-2-u1-X10"},{"t":"⟨4 6/9⟩","mis":"M4-2-u1-X09"}],"explanation":["4에서 1만큼을 ⟨9/9⟩로 바꾸면 4 = ⟨3 9/9⟩예요.","⟨3 9/9⟩ − ⟨3/9⟩ = ⟨3 6/9⟩ — 자연수 부분은 1 줄어요.","가분수로 바꾸면 ⟨36/9⟩ − ⟨3/9⟩ = ⟨33/9⟩ = ⟨3 6/9⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_a#13','math',4,2,'u1','','tb_g4_2_math_u1_review_a','unit_review','M4-2-u1-C5',2,'mc','auto','「스스로 마무리하기」 7번 ⟨3 2/5⟩ + □ > 5에서 □ 안에 들어갈 수 있는 수를 보기에서 모두 찾은 것은 무엇인가요?  보기 ㉠ ⟨1 2/5⟩  ㉡ ⟨8/5⟩  ㉢ 2  ㉣ ⟨2 3/5⟩',ARRAY['M4-2-u1-X16','M4-2-u1-X15']::text[],false,'{"seq":13,"concept":"M4-2-u1-C5","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 7번 ⟨3 2/5⟩ + □ > 5에서 □ 안에 들어갈 수 있는 수를 보기에서 모두 찾은 것은 무엇인가요?  보기 ㉠ ⟨1 2/5⟩  ㉡ ⟨8/5⟩  ㉢ 2  ㉣ ⟨2 3/5⟩","options":[{"t":"㉢, ㉣","correct":true},{"t":"㉡, ㉢, ㉣","mis":"M4-2-u1-X16"},{"t":"㉠, ㉡","mis":"M4-2-u1-X15"},{"t":"㉣","mis":"M4-2-u1-X16"}],"explanation":["⟨3 2/5⟩ + ⟨1 2/5⟩ = ⟨4 4/5⟩, ⟨3 2/5⟩ + ⟨8/5⟩ = 5예요.","⟨3 2/5⟩ + 2 = ⟨5 2/5⟩, ⟨3 2/5⟩ + ⟨2 3/5⟩ = 6이에요.","5보다 큰 것은 ㉢, ㉣ — ㉡은 5와 같아서 들어갈 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_a#14','math',4,2,'u1','','tb_g4_2_math_u1_review_a','unit_review','M4-2-u1-C9',2,'mc','auto','「스스로 마무리하기」 8번 채원이는 학교에서 집에 가는 길에 도서관에 들러 책을 빌리려고 해요. 학교에서 도서관까지 ⟨1 2/7⟩ km, 도서관에서 집까지 ⟨6/7⟩ km, 학교에서 집으로 곧장 가는 길은 ⟨1 5/7⟩ km예요. 학교에서 도서관을 지나 집에 가는 길은 곧장 가는 길보다 몇 km 더 먼가요?',ARRAY['M4-2-u1-X15','M4-2-u1-X11','M4-2-u1-X14']::text[],false,'{"seq":14,"concept":"M4-2-u1-C9","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 8번 채원이는 학교에서 집에 가는 길에 도서관에 들러 책을 빌리려고 해요. 학교에서 도서관까지 ⟨1 2/7⟩ km, 도서관에서 집까지 ⟨6/7⟩ km, 학교에서 집으로 곧장 가는 길은 ⟨1 5/7⟩ km예요. 학교에서 도서관을 지나 집에 가는 길은 곧장 가는 길보다 몇 km 더 먼가요?","options":[{"t":"⟨3/7⟩ km","correct":true},{"t":"⟨2 1/7⟩ km","mis":"M4-2-u1-X15"},{"t":"⟨1 4/7⟩ km","mis":"M4-2-u1-X11"},{"t":"⟨3 6/7⟩ km","mis":"M4-2-u1-X14"}],"explanation":["학교에서 도서관을 지나 집까지: ⟨1 2/7⟩ + ⟨6/7⟩ = ⟨1 8/7⟩ = ⟨2 1/7⟩ km예요.","⟨2 1/7⟩ − ⟨1 5/7⟩ = ⟨1 8/7⟩ − ⟨1 5/7⟩ = ⟨3/7⟩이에요.","도서관을 지나 가는 길이 ⟨3/7⟩ km 더 멀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_a#15','math',4,2,'u1','','tb_g4_2_math_u1_review_a','unit_review','M4-2-u1-C5',2,'mc','auto','「만화」 두 농부가 사과를 ⟨2 2/4⟩ kg과 ⟨1 3/4⟩ kg 땄어요. 두 사람이 딴 사과는 모두 몇 kg인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X07','M4-2-u1-X04']::text[],false,'{"seq":15,"concept":"M4-2-u1-C5","difficulty":2,"kind":"mc","stem":"「만화」 두 농부가 사과를 ⟨2 2/4⟩ kg과 ⟨1 3/4⟩ kg 땄어요. 두 사람이 딴 사과는 모두 몇 kg인가요?","options":[{"t":"⟨4 1/4⟩ kg","correct":true},{"t":"⟨3 5/8⟩ kg","mis":"M4-2-u1-X01"},{"t":"⟨3 1/4⟩ kg","mis":"M4-2-u1-X07"},{"t":"⟨5 1/4⟩ kg","mis":"M4-2-u1-X04"}],"explanation":["방법 1 — 자연수끼리 2 + 1 = 3, 분수끼리 ⟨2/4⟩ + ⟨3/4⟩ = ⟨5/4⟩예요.","⟨5/4⟩ = ⟨1 1/4⟩ — 넘친 1을 자연수에 더해 3 + ⟨1 1/4⟩ = ⟨4 1/4⟩ kg.","방법 2 — 가분수로 바꾸면 ⟨10/4⟩ + ⟨7/4⟩ = ⟨17/4⟩ = ⟨4 1/4⟩ kg."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_a#16','math',4,2,'u1','','tb_g4_2_math_u1_review_a','unit_review','M4-2-u1-C9',2,'mc','auto','「만화」 한 농부는 사과를 ⟨2 2/4⟩ kg, 다른 농부는 ⟨1 3/4⟩ kg 땄어요. ⟨2 2/4⟩ kg을 딴 농부는 몇 kg 더 많이 땄나요?',ARRAY['M4-2-u1-X11','M4-2-u1-X09','M4-2-u1-X16']::text[],false,'{"seq":16,"concept":"M4-2-u1-C9","difficulty":2,"kind":"mc","stem":"「만화」 한 농부는 사과를 ⟨2 2/4⟩ kg, 다른 농부는 ⟨1 3/4⟩ kg 땄어요. ⟨2 2/4⟩ kg을 딴 농부는 몇 kg 더 많이 땄나요?","options":[{"t":"⟨3/4⟩ kg","correct":true},{"t":"⟨1 1/4⟩ kg","mis":"M4-2-u1-X11"},{"t":"⟨1 3/4⟩ kg","mis":"M4-2-u1-X09"},{"t":"1 kg","mis":"M4-2-u1-X16"}],"explanation":["⟨2/4⟩에서 ⟨3/4⟩을 뺄 수 없어 1만큼을 ⟨4/4⟩로 바꿔요 — ⟨2 2/4⟩ = ⟨1 6/4⟩.","⟨1 6/4⟩ − ⟨1 3/4⟩ = ⟨3/4⟩ kg — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨10/4⟩ − ⟨7/4⟩ = ⟨3/4⟩ = ⟨3/4⟩ kg."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_a#17','math',4,2,'u1','','tb_g4_2_math_u1_review_a','unit_review','M4-2-u1-C2',3,'sa','auto','분수 띠로 1을 분모가 6인 진분수 두 개로 가르려고 해요. 순서만 바꾼 것은 한 가지로 셀 때, 가르는 방법은 모두 몇 가지인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"M4-2-u1-C2","difficulty":3,"kind":"sa","stem":"분수 띠로 1을 분모가 6인 진분수 두 개로 가르려고 해요. 순서만 바꾼 것은 한 가지로 셀 때, 가르는 방법은 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["1 = ⟨6/6⟩ — 두 분수의 분자의 합이 6이 되게 갈라요.","⟨1/6⟩과 ⟨5/6⟩, ⟨2/6⟩와 ⟨4/6⟩, ⟨3/6⟩과 ⟨3/6⟩이에요.","순서만 바꾼 것은 한 가지로 세면 모두 3가지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_a#18','math',4,2,'u1','','tb_g4_2_math_u1_review_a','unit_review','M4-2-u1-C3',3,'sa','auto','「익힘 퐁당」 ⟨5/8⟩ + ⟨□/8⟩ = ⟨1 3/8⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"M4-2-u1-C3","difficulty":3,"kind":"sa","stem":"「익힘 퐁당」 ⟨5/8⟩ + ⟨□/8⟩ = ⟨1 3/8⟩ — □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["⟨1 3/8⟩ = ⟨11/8⟩ — ⟨1/8⟩이 11개예요.","⟨5/8⟩는 ⟨1/8⟩이 5개라 11 − 5 = 6개를 더 모아야 해요.","⟨5/8⟩ + ⟨6/8⟩ = ⟨1 3/8⟩ — □ = 6."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_a#19','math',4,2,'u1','','tb_g4_2_math_u1_review_a','unit_review','M4-2-u1-C5',3,'sa','auto','⟨2 3/4⟩ + ⟨1 2/4⟩ = ⟨11/4⟩ + ⟨6/4⟩ = ⟨□/4⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M4-2-u1-C5","difficulty":3,"kind":"sa","stem":"⟨2 3/4⟩ + ⟨1 2/4⟩ = ⟨11/4⟩ + ⟨6/4⟩ = ⟨□/4⟩ — □에 알맞은 수를 쓰세요.","answer":["17"],"explanation":["⟨2 3/4⟩ = ⟨11/4⟩, ⟨1 2/4⟩ = ⟨6/4⟩이에요.","⟨11/4⟩ + ⟨6/4⟩ = ⟨17/4⟩ — 분모는 그대로예요.","⟨17/4⟩ = ⟨4 1/4⟩ — □ = 17."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_a#20','math',4,2,'u1','','tb_g4_2_math_u1_review_a','unit_review','M4-2-u1-C8',3,'error','auto','⟨2 1/4⟩ − ⟨3/4⟩을 계산하는 과정을 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u1-X12','M4-2-u1-X15']::text[],false,'{"seq":20,"concept":"M4-2-u1-C8","difficulty":3,"kind":"error","stem":"⟨2 1/4⟩ − ⟨3/4⟩을 계산하는 과정을 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「⟨2 1/4⟩을 ⟨1 11/4⟩로 바꿨어.」","correct":true,"mis_target":"M4-2-u1-X12"},{"t":"서준 — 「⟨1/4⟩에서 ⟨3/4⟩을 뺄 수 없어서 1만큼을 ⟨4/4⟩로 바꿔.」","mis":"M4-2-u1-X15"},{"t":"채원 — 「⟨2 1/4⟩ = ⟨1 5/4⟩야.」","mis":"M4-2-u1-X15"},{"t":"지유 — 「⟨1 5/4⟩ − ⟨3/4⟩ = ⟨1 2/4⟩야.」","mis":"M4-2-u1-X15"}],"explanation":["1 = ⟨4/4⟩ — 1만큼을 바꾸면 분자에 4를 더해요.","⟨2 1/4⟩ = ⟨1 5/4⟩ — ⟨1 5/4⟩ − ⟨3/4⟩ = ⟨1 2/4⟩예요.","도윤이는 분자에 4가 아니라 10을 더했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_a#21','math',4,2,'u1','','tb_g4_2_math_u1_review_a','unit_review','M4-2-u1-C9',3,'mc','auto','「교과서」 친구가 「⟨5 1/6⟩ − ⟨3 5/6⟩ = (5 − 3) + (⟨5/6⟩ − ⟨1/6⟩) = ⟨2 4/6⟩」라고 계산했어요. 바르게 계산한 값은 얼마인가요?',ARRAY['M4-2-u1-X11','M4-2-u1-X09','M4-2-u1-X16']::text[],false,'{"seq":21,"concept":"M4-2-u1-C9","difficulty":3,"kind":"mc","stem":"「교과서」 친구가 「⟨5 1/6⟩ − ⟨3 5/6⟩ = (5 − 3) + (⟨5/6⟩ − ⟨1/6⟩) = ⟨2 4/6⟩」라고 계산했어요. 바르게 계산한 값은 얼마인가요?","options":[{"t":"⟨1 2/6⟩","correct":true},{"t":"⟨2 4/6⟩","mis":"M4-2-u1-X11"},{"t":"⟨2 2/6⟩","mis":"M4-2-u1-X09"},{"t":"⟨1 3/6⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨1/6⟩에서 ⟨5/6⟩를 뺄 수 없어 1만큼을 ⟨6/6⟩으로 바꿔요 — ⟨5 1/6⟩ = ⟨4 7/6⟩.","⟨4 7/6⟩ − ⟨3 5/6⟩ = ⟨1 2/6⟩ — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨31/6⟩ − ⟨23/6⟩ = ⟨8/6⟩ = ⟨1 2/6⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_a#22','math',4,2,'u1','','tb_g4_2_math_u1_review_a','unit_review','M4-2-u1-C10',3,'mc','auto','「나는야 분수왕」 분수 카드 ⟨1 4/5⟩, ⟨1/5⟩, ⟨16/5⟩, ⟨3/5⟩, ⟨2 3/5⟩, ⟨2 2/5⟩, ⟨3 3/5⟩, ⟨2/5⟩, ⟨7/5⟩, ⟨1 3/5⟩이 있어요. ⟨2 2/5⟩와 더해서 4가 되는 카드는 무엇인가요?',ARRAY['M4-2-u1-X16','M4-2-u1-X17']::text[],false,'{"seq":22,"concept":"M4-2-u1-C10","difficulty":3,"kind":"mc","stem":"「나는야 분수왕」 분수 카드 ⟨1 4/5⟩, ⟨1/5⟩, ⟨16/5⟩, ⟨3/5⟩, ⟨2 3/5⟩, ⟨2 2/5⟩, ⟨3 3/5⟩, ⟨2/5⟩, ⟨7/5⟩, ⟨1 3/5⟩이 있어요. ⟨2 2/5⟩와 더해서 4가 되는 카드는 무엇인가요?","options":[{"t":"⟨1 3/5⟩","correct":true},{"t":"⟨1 4/5⟩","mis":"M4-2-u1-X16"},{"t":"⟨3/5⟩","mis":"M4-2-u1-X17"},{"t":"⟨2 3/5⟩","mis":"M4-2-u1-X16"}],"explanation":["4 − ⟨2 2/5⟩ = ⟨3 5/5⟩ − ⟨2 2/5⟩ = ⟨1 3/5⟩이에요.","⟨2 2/5⟩ + ⟨1 3/5⟩ = 3 + ⟨5/5⟩ = 4예요.","⟨3/5⟩을 더하면 ⟨2 2/5⟩ + ⟨3/5⟩ = 3이 되어 4가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_a#23','math',4,2,'u1','','tb_g4_2_math_u1_review_a','unit_review','M4-2-u1-C9',4,'mc','auto','「재미있는 수학·이런 활동」 수 카드 1, 5, 7, 8을 한 번씩만 사용하여 분모가 9인 대분수 두 개를 만들고(자연수 부분과 분자에 한 장씩), 큰 대분수에서 작은 대분수를 빼려고 해요. 계산 결과가 가장 작은 뺄셈식의 계산 결과는 얼마인가요?',ARRAY['M4-2-u1-X16','M4-2-u1-X17']::text[],false,'{"seq":23,"concept":"M4-2-u1-C9","difficulty":4,"kind":"mc","stem":"「재미있는 수학·이런 활동」 수 카드 1, 5, 7, 8을 한 번씩만 사용하여 분모가 9인 대분수 두 개를 만들고(자연수 부분과 분자에 한 장씩), 큰 대분수에서 작은 대분수를 빼려고 해요. 계산 결과가 가장 작은 뺄셈식의 계산 결과는 얼마인가요?","options":[{"t":"⟨5/9⟩","correct":true},{"t":"⟨1 2/9⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 4/9⟩","mis":"M4-2-u1-X16"},{"t":"⟨6 7/9⟩","mis":"M4-2-u1-X17"}],"explanation":["차가 작으려면 두 대분수의 크기가 가까워야 해요 — 자연수 부분이 가장 가까운 두 카드를 골라요.","⟨8 1/9⟩ − ⟨7 5/9⟩ = ⟨5/9⟩예요.","교과서의 ⟨8 5/9⟩ − ⟨1 7/9⟩ = ⟨6 7/9⟩과 견주어 보세요 — 카드를 어디에 놓느냐에 따라 결과가 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_a#24','math',4,2,'u1','','tb_g4_2_math_u1_review_a','unit_review','M4-2-u1-C10',4,'mc','auto','「나는야 분수왕」 분수 카드 10장(⟨1 4/5⟩, ⟨1/5⟩, ⟨16/5⟩, ⟨3/5⟩, ⟨2 3/5⟩, ⟨2 2/5⟩, ⟨3 3/5⟩, ⟨2/5⟩, ⟨7/5⟩, ⟨1 3/5⟩)을 한 번씩만 사용해요. 덧셈식 ⟨2 2/5⟩ + ⟨1 3/5⟩ = 4를 먼저 만들었다면, 뺄셈식 □ − □ = 2에 쓸 수 있는 두 카드는 무엇인가요?',ARRAY['M4-2-u1-X15','M4-2-u1-X16']::text[],false,'{"seq":24,"concept":"M4-2-u1-C10","difficulty":4,"kind":"mc","stem":"「나는야 분수왕」 분수 카드 10장(⟨1 4/5⟩, ⟨1/5⟩, ⟨16/5⟩, ⟨3/5⟩, ⟨2 3/5⟩, ⟨2 2/5⟩, ⟨3 3/5⟩, ⟨2/5⟩, ⟨7/5⟩, ⟨1 3/5⟩)을 한 번씩만 사용해요. 덧셈식 ⟨2 2/5⟩ + ⟨1 3/5⟩ = 4를 먼저 만들었다면, 뺄셈식 □ − □ = 2에 쓸 수 있는 두 카드는 무엇인가요?","options":[{"t":"⟨2 3/5⟩, ⟨3/5⟩","correct":true},{"t":"⟨2 2/5⟩, ⟨2/5⟩","mis":"M4-2-u1-X15"},{"t":"⟨3 3/5⟩, ⟨1 3/5⟩","mis":"M4-2-u1-X15"},{"t":"⟨16/5⟩, ⟨1/5⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨2 2/5⟩와 ⟨1 3/5⟩은 이미 썼으니 다시 쓸 수 없어요.","⟨2 3/5⟩ − ⟨3/5⟩ = 2예요.","⟨16/5⟩ − ⟨1/5⟩ = ⟨15/5⟩ = 3 — 2가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_a#25','math',4,2,'u1','','tb_g4_2_math_u1_review_a','unit_review','M4-2-u1-C7',4,'essay','teacher','「스스로 마무리하기」 6번 「서술형」 친구가 「4 − ⟨3/9⟩ = ⟨1/9⟩」이라고 계산했어요. 잘못 계산한 곳을 찾아 이유를 쓰고, 바르게 계산해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u1-C7","difficulty":4,"kind":"essay","stem":"「스스로 마무리하기」 6번 「서술형」 친구가 「4 − ⟨3/9⟩ = ⟨1/9⟩」이라고 계산했어요. 잘못 계산한 곳을 찾아 이유를 쓰고, 바르게 계산해 보세요.","answer_guide":{"answer":"예: 자연수 4에서 분자 3을 빼서 계산했다. 자연수에서 분수를 뺄 때는 자연수에서 1만큼을 분모가 같은 가분수로 바꾸어야 한다. 4 = ⟨3 9/9⟩이므로 4 − ⟨3/9⟩ = ⟨3 9/9⟩ − ⟨3/9⟩ = ⟨3 6/9⟩이다.","scoring_points":["자연수에서 분자를 뺀 것이 잘못이라고 썼는가","4 = ⟨3 9/9⟩(또는 ⟨36/9⟩)로 바꾸었는가","⟨3 6/9⟩이라고 답했는가"]},"explanation":["4 = ⟨3 9/9⟩예요.","⟨3 9/9⟩ − ⟨3/9⟩ = ⟨3 6/9⟩이에요.","자연수를 분자처럼 빼지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_b#1','math',4,2,'u1','','tb_g4_2_math_u1_review_b','unit_review','M4-2-u1-C2',1,'mc','auto','「확인 문제」 분수 띠로 1을 ⟨3/5⟩과 □로 갈랐어요. □에 알맞은 분수는 무엇인가요?',ARRAY['M4-2-u1-X06','M4-2-u1-X16']::text[],false,'{"seq":1,"concept":"M4-2-u1-C2","difficulty":1,"kind":"mc","stem":"「확인 문제」 분수 띠로 1을 ⟨3/5⟩과 □로 갈랐어요. □에 알맞은 분수는 무엇인가요?","options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨3/5⟩","mis":"M4-2-u1-X06"},{"t":"⟨5/3⟩","mis":"M4-2-u1-X06"},{"t":"⟨1/5⟩","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨5/5⟩ — ⟨1/5⟩이 5개예요.","⟨3/5⟩은 ⟨1/5⟩이 3개라 5 − 3 = 2개가 모자라요.","⟨3/5⟩ + ⟨2/5⟩ = ⟨5/5⟩ = 1이에요."],"asset":{"type":"fbar","bars":[{"den":5,"num":3,"label":"1을 가르기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_b#2','math',4,2,'u1','','tb_g4_2_math_u1_review_b','unit_review','M4-2-u1-C3',1,'sa','auto','⟨4/7⟩ + ⟨2/7⟩ = ⟨□/7⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M4-2-u1-C3","difficulty":1,"kind":"sa","stem":"⟨4/7⟩ + ⟨2/7⟩ = ⟨□/7⟩ — □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["⟨4/7⟩는 ⟨1/7⟩이 4개, ⟨2/7⟩는 ⟨1/7⟩이 2개예요.","⟨4/7⟩ + ⟨2/7⟩ = ⟨6/7⟩ — 분모는 그대로 두고 분자끼리 더해요.","분모끼리 더한 ⟨6/14⟩은 답이 아니에요 — 답은 ⟨6/7⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_b#3','math',4,2,'u1','','tb_g4_2_math_u1_review_b','unit_review','M4-2-u1-C4',1,'sa','auto','⟨6/7⟩ − ⟨3/7⟩ = ⟨□/7⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M4-2-u1-C4","difficulty":1,"kind":"sa","stem":"⟨6/7⟩ − ⟨3/7⟩ = ⟨□/7⟩ — □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["⟨6/7⟩은 ⟨1/7⟩이 6개, ⟨3/7⟩은 ⟨1/7⟩이 3개예요.","⟨6/7⟩ − ⟨3/7⟩ = ⟨3/7⟩ — 분모는 그대로 두고 분자끼리 빼요.","⟨1/7⟩이 6 − 3 = 3개 남아요 — 분모끼리 빼지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_b#4','math',4,2,'u1','','tb_g4_2_math_u1_review_b','unit_review','M4-2-u1-C5',1,'mc','auto','⟨1 2/8⟩ + ⟨3 1/8⟩을 계산해 보세요.',ARRAY['M4-2-u1-X01','M4-2-u1-X13','M4-2-u1-X16']::text[],false,'{"seq":4,"concept":"M4-2-u1-C5","difficulty":1,"kind":"mc","stem":"⟨1 2/8⟩ + ⟨3 1/8⟩을 계산해 보세요.","options":[{"t":"⟨4 3/8⟩","correct":true},{"t":"⟨4 3/16⟩","mis":"M4-2-u1-X01"},{"t":"⟨3/8⟩","mis":"M4-2-u1-X13"},{"t":"⟨4 4/8⟩","mis":"M4-2-u1-X16"}],"explanation":["방법 1 — 자연수끼리 1 + 3 = 4, 분수끼리 ⟨2/8⟩ + ⟨1/8⟩ = ⟨3/8⟩이에요.","4 + ⟨3/8⟩ = ⟨4 3/8⟩.","방법 2 — 가분수로 바꾸면 ⟨10/8⟩ + ⟨25/8⟩ = ⟨35/8⟩ = ⟨4 3/8⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_b#5','math',4,2,'u1','','tb_g4_2_math_u1_review_b','unit_review','M4-2-u1-C6',1,'sa','auto','⟨3 2/3⟩ − ⟨2 1/3⟩ = ⟨11/3⟩ − ⟨7/3⟩ = ⟨□/3⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M4-2-u1-C6","difficulty":1,"kind":"sa","stem":"⟨3 2/3⟩ − ⟨2 1/3⟩ = ⟨11/3⟩ − ⟨7/3⟩ = ⟨□/3⟩ — □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["⟨3 2/3⟩ = ⟨11/3⟩, ⟨2 1/3⟩ = ⟨7/3⟩이에요.","⟨11/3⟩ − ⟨7/3⟩ = ⟨4/3⟩ — 분모는 그대로예요.","⟨4/3⟩ = ⟨1 1/3⟩ — □ = 4."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_b#6','math',4,2,'u1','','tb_g4_2_math_u1_review_b','unit_review','M4-2-u1-C8',1,'mc','auto','⟨2 1/4⟩ − ⟨3/4⟩을 계산해 보세요.',ARRAY['M4-2-u1-X11','M4-2-u1-X16']::text[],false,'{"seq":6,"concept":"M4-2-u1-C8","difficulty":1,"kind":"mc","stem":"⟨2 1/4⟩ − ⟨3/4⟩을 계산해 보세요.","options":[{"t":"⟨1 2/4⟩","correct":true},{"t":"⟨2 2/4⟩","mis":"M4-2-u1-X11"},{"t":"⟨1 3/4⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 1/4⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨1/4⟩에서 ⟨3/4⟩을 뺄 수 없어 1만큼을 ⟨4/4⟩로 바꿔요 — ⟨2 1/4⟩ = ⟨1 5/4⟩.","⟨1 5/4⟩ − ⟨3/4⟩ = ⟨1 2/4⟩ — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨9/4⟩ − ⟨3/4⟩ = ⟨6/4⟩ = ⟨1 2/4⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_b#7','math',4,2,'u1','','tb_g4_2_math_u1_review_b','unit_review','M4-2-u1-C3',1,'mc','auto','그림을 보고 ⟨3/4⟩ + ⟨2/4⟩를 계산하여 대분수로 나타내면 얼마인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X04']::text[],false,'{"seq":7,"concept":"M4-2-u1-C3","difficulty":1,"kind":"mc","stem":"그림을 보고 ⟨3/4⟩ + ⟨2/4⟩를 계산하여 대분수로 나타내면 얼마인가요?","options":[{"t":"⟨1 1/4⟩","correct":true},{"t":"⟨5/8⟩","mis":"M4-2-u1-X01"},{"t":"⟨1/4⟩","mis":"M4-2-u1-X04"},{"t":"⟨2 1/4⟩","mis":"M4-2-u1-X04"}],"explanation":["⟨3/4⟩은 ⟨1/4⟩이 3개, ⟨2/4⟩는 ⟨1/4⟩이 2개예요.","⟨3/4⟩ + ⟨2/4⟩ = ⟨5/4⟩ — 분모는 그대로 두고 분자끼리 더해요.","⟨5/4⟩ = ⟨1 1/4⟩ — 분모끼리 더하지 않아요."],"asset":{"type":"fbar","bars":[{"den":4,"num":3},{"den":4,"num":2}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_b#8','math',4,2,'u1','','tb_g4_2_math_u1_review_b','unit_review','M4-2-u1-C7',1,'match','auto','「확인 문제」 계산 결과끼리 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u1-C7","difficulty":1,"kind":"match","stem":"「확인 문제」 계산 결과끼리 알맞게 이으세요.","pairs":[{"l":"⟨4/8⟩ + ⟨3/8⟩","r":"⟨7/8⟩"},{"l":"1 − ⟨9/12⟩","r":"⟨3/12⟩"},{"l":"⟨6 1/4⟩ + ⟨4 3/4⟩","r":"11"},{"l":"5 − ⟨6/8⟩","r":"⟨4 2/8⟩"}],"mis":"M4-2-u1-X09","explanation":["⟨4/8⟩ + ⟨3/8⟩ = ⟨7/8⟩, 1 − ⟨9/12⟩ = ⟨3/12⟩이에요.","⟨6 1/4⟩ + ⟨4 3/4⟩ = 10 + ⟨4/4⟩ = 11이에요.","5 − ⟨6/8⟩ = ⟨4 8/8⟩ − ⟨6/8⟩ = ⟨4 2/8⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_b#9','math',4,2,'u1','','tb_g4_2_math_u1_review_b','unit_review','M4-2-u1-C6',2,'mc','auto','「스스로 마무리하기」 3번 두 분수 ⟨4 3/6⟩과 ⟨22/6⟩의 차는 얼마인가요?',ARRAY['M4-2-u1-X11','M4-2-u1-X09','M4-2-u1-X14']::text[],false,'{"seq":9,"concept":"M4-2-u1-C6","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 3번 두 분수 ⟨4 3/6⟩과 ⟨22/6⟩의 차는 얼마인가요?","options":[{"t":"⟨5/6⟩","correct":true},{"t":"⟨1 1/6⟩","mis":"M4-2-u1-X11"},{"t":"⟨1 5/6⟩","mis":"M4-2-u1-X09"},{"t":"⟨8 1/6⟩","mis":"M4-2-u1-X14"}],"explanation":["⟨22/6⟩ = ⟨3 4/6⟩예요.","⟨4 3/6⟩ − ⟨3 4/6⟩ = ⟨3 9/6⟩ − ⟨3 4/6⟩ = ⟨5/6⟩ — ⟨3/6⟩에서 ⟨4/6⟩를 뺄 수 없어 1만큼 바꿨어요.","가분수로 바꾸면 ⟨27/6⟩ − ⟨22/6⟩ = ⟨5/6⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_b#10','math',4,2,'u1','','tb_g4_2_math_u1_review_b','unit_review','M4-2-u1-C3',2,'mc','auto','「확인 문제」 계산 결과가 큰 것부터 차례대로 기호를 쓴 것은 무엇인가요?  ㉠ ⟨4/9⟩ + ⟨8/9⟩  ㉡ ⟨4/9⟩ + ⟨6/9⟩  ㉢ ⟨8/9⟩ + ⟨7/9⟩',ARRAY['M4-2-u1-X15','M4-2-u1-X17','M4-2-u1-X16']::text[],false,'{"seq":10,"concept":"M4-2-u1-C3","difficulty":2,"kind":"mc","stem":"「확인 문제」 계산 결과가 큰 것부터 차례대로 기호를 쓴 것은 무엇인가요?  ㉠ ⟨4/9⟩ + ⟨8/9⟩  ㉡ ⟨4/9⟩ + ⟨6/9⟩  ㉢ ⟨8/9⟩ + ⟨7/9⟩","options":[{"t":"㉢, ㉠, ㉡","correct":true},{"t":"㉡, ㉠, ㉢","mis":"M4-2-u1-X15"},{"t":"㉠, ㉢, ㉡","mis":"M4-2-u1-X17"},{"t":"㉢, ㉡, ㉠","mis":"M4-2-u1-X16"}],"explanation":["하나씩 계산해요 — ㉠ ⟨4/9⟩ + ⟨8/9⟩ = ⟨1 3/9⟩, ㉡ ⟨4/9⟩ + ⟨6/9⟩ = ⟨1 1/9⟩, ㉢ ⟨8/9⟩ + ⟨7/9⟩ = ⟨1 6/9⟩.","⟨1 6/9⟩ > ⟨1 3/9⟩ > ⟨1 1/9⟩이에요.","계산 결과가 큰 것부터 쓰면 ㉢, ㉠, ㉡예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_b#11','math',4,2,'u1','','tb_g4_2_math_u1_review_b','unit_review','M4-2-u1-C4',2,'mc','auto','천연 식물 영양제 ⟨5/6⟩ L 중에서 ⟨3/6⟩ L를 텃밭에 주었어요. 남은 천연 식물 영양제는 몇 L인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X16']::text[],false,'{"seq":11,"concept":"M4-2-u1-C4","difficulty":2,"kind":"mc","stem":"천연 식물 영양제 ⟨5/6⟩ L 중에서 ⟨3/6⟩ L를 텃밭에 주었어요. 남은 천연 식물 영양제는 몇 L인가요?","options":[{"t":"⟨2/6⟩ L","correct":true},{"t":"⟨2/3⟩ L","mis":"M4-2-u1-X01"},{"t":"⟨3/6⟩ L","mis":"M4-2-u1-X16"},{"t":"⟨1/6⟩ L","mis":"M4-2-u1-X16"}],"explanation":["⟨5/6⟩는 ⟨1/6⟩이 5개, ⟨3/6⟩은 ⟨1/6⟩이 3개예요.","⟨5/6⟩ − ⟨3/6⟩ = ⟨2/6⟩ L — 분모는 그대로 두고 분자끼리 빼요.","⟨1/6⟩이 5 − 3 = 2개 남아요 — 분모끼리 빼지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_b#12','math',4,2,'u1','','tb_g4_2_math_u1_review_b','unit_review','M4-2-u1-C7',2,'mc','auto','「지도서」 친구가 「3 − ⟨1 2/4⟩ = ⟨2 2/4⟩」라고 계산했어요. 바르게 계산한 값은 얼마인가요?',ARRAY['M4-2-u1-X10','M4-2-u1-X16']::text[],false,'{"seq":12,"concept":"M4-2-u1-C7","difficulty":2,"kind":"mc","stem":"「지도서」 친구가 「3 − ⟨1 2/4⟩ = ⟨2 2/4⟩」라고 계산했어요. 바르게 계산한 값은 얼마인가요?","options":[{"t":"⟨1 2/4⟩","correct":true},{"t":"⟨2 2/4⟩","mis":"M4-2-u1-X10"},{"t":"⟨1 3/4⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 1/4⟩","mis":"M4-2-u1-X16"}],"explanation":["3에서 1만큼을 ⟨4/4⟩로 바꾸면 3 = ⟨2 4/4⟩예요.","자연수끼리 2 − 1 = 1, 분수끼리 ⟨4/4⟩ − ⟨2/4⟩ = ⟨2/4⟩ — ⟨2 4/4⟩ − ⟨1 2/4⟩ = ⟨1 2/4⟩.","가분수로 바꾸면 ⟨12/4⟩ − ⟨6/4⟩ = ⟨6/4⟩ = ⟨1 2/4⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_b#13','math',4,2,'u1','','tb_g4_2_math_u1_review_b','unit_review','M4-2-u1-C3',2,'mc','auto','「익힘」 ⟨8/9⟩ + ⟨6/9⟩ > ⟨1 □/9⟩에서 □ 안에 들어갈 수 있는 자연수를 모두 찾은 것은 무엇인가요?',ARRAY['M4-2-u1-X16','M4-2-u1-X15']::text[],false,'{"seq":13,"concept":"M4-2-u1-C3","difficulty":2,"kind":"mc","stem":"「익힘」 ⟨8/9⟩ + ⟨6/9⟩ > ⟨1 □/9⟩에서 □ 안에 들어갈 수 있는 자연수를 모두 찾은 것은 무엇인가요?","options":[{"t":"1, 2, 3, 4","correct":true},{"t":"1, 2, 3, 4, 5","mis":"M4-2-u1-X16"},{"t":"5, 6, 7, 8","mis":"M4-2-u1-X15"},{"t":"1, 2, 3","mis":"M4-2-u1-X16"}],"explanation":["⟨8/9⟩ + ⟨6/9⟩ = ⟨14/9⟩ = ⟨1 5/9⟩예요.","⟨1 5/9⟩가 더 크려면 □는 5보다 작아야 해요.","1, 2, 3, 4 — 5를 넣으면 크기가 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_b#14','math',4,2,'u1','','tb_g4_2_math_u1_review_b','unit_review','M4-2-u1-C4',2,'mc','auto','「익힘」 밀가루 ⟨11/13⟩ kg 중에서 쿠키를 만드는 데 ⟨5/13⟩ kg을 사용하고, 남은 밀가루는 모두 빵을 만드는 데 사용했어요. 쿠키와 빵 중에서 어느 것을 만드는 데 밀가루를 몇 kg 더 많이 사용했나요?',ARRAY['M4-2-u1-X15','M4-2-u1-X14']::text[],false,'{"seq":14,"concept":"M4-2-u1-C4","difficulty":2,"kind":"mc","stem":"「익힘」 밀가루 ⟨11/13⟩ kg 중에서 쿠키를 만드는 데 ⟨5/13⟩ kg을 사용하고, 남은 밀가루는 모두 빵을 만드는 데 사용했어요. 쿠키와 빵 중에서 어느 것을 만드는 데 밀가루를 몇 kg 더 많이 사용했나요?","options":[{"t":"빵, ⟨1/13⟩ kg","correct":true},{"t":"쿠키, ⟨1/13⟩ kg","mis":"M4-2-u1-X15"},{"t":"빵, ⟨6/13⟩ kg","mis":"M4-2-u1-X15"},{"t":"쿠키, ⟨6/13⟩ kg","mis":"M4-2-u1-X14"}],"explanation":["빵을 만드는 데 사용한 밀가루는 ⟨11/13⟩ − ⟨5/13⟩ = ⟨6/13⟩ kg이에요.","⟨5/13⟩ < ⟨6/13⟩ — 빵을 만드는 데 더 많이 사용했어요.","⟨6/13⟩ − ⟨5/13⟩ = ⟨1/13⟩ — 빵에 ⟨1/13⟩ kg 더 사용했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_b#15','math',4,2,'u1','','tb_g4_2_math_u1_review_b','unit_review','M4-2-u1-C5',2,'mc','auto','「익힘」 미술 작품을 만드는 데 철사를 지유는 ⟨2 4/10⟩ m, 건우는 ⟨1 7/10⟩ m 사용했어요. 지유와 건우가 사용한 철사는 모두 몇 m인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X07','M4-2-u1-X04']::text[],false,'{"seq":15,"concept":"M4-2-u1-C5","difficulty":2,"kind":"mc","stem":"「익힘」 미술 작품을 만드는 데 철사를 지유는 ⟨2 4/10⟩ m, 건우는 ⟨1 7/10⟩ m 사용했어요. 지유와 건우가 사용한 철사는 모두 몇 m인가요?","options":[{"t":"⟨4 1/10⟩ m","correct":true},{"t":"⟨3 11/20⟩ m","mis":"M4-2-u1-X01"},{"t":"⟨3 1/10⟩ m","mis":"M4-2-u1-X07"},{"t":"⟨5 1/10⟩ m","mis":"M4-2-u1-X04"}],"explanation":["방법 1 — 자연수끼리 2 + 1 = 3, 분수끼리 ⟨4/10⟩ + ⟨7/10⟩ = ⟨11/10⟩이에요.","⟨11/10⟩ = ⟨1 1/10⟩ — 넘친 1을 자연수에 더해 3 + ⟨1 1/10⟩ = ⟨4 1/10⟩ m.","방법 2 — 가분수로 바꾸면 ⟨24/10⟩ + ⟨17/10⟩ = ⟨41/10⟩ = ⟨4 1/10⟩ m."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_b#16','math',4,2,'u1','','tb_g4_2_math_u1_review_b','unit_review','M4-2-u1-C9',2,'mc','auto','지유는 자전거를 ⟨2 7/10⟩ km, 도윤이는 ⟨3 2/10⟩ km 탔어요. 도윤이는 지유보다 몇 km 더 많이 탔나요?',ARRAY['M4-2-u1-X11','M4-2-u1-X16']::text[],false,'{"seq":16,"concept":"M4-2-u1-C9","difficulty":2,"kind":"mc","stem":"지유는 자전거를 ⟨2 7/10⟩ km, 도윤이는 ⟨3 2/10⟩ km 탔어요. 도윤이는 지유보다 몇 km 더 많이 탔나요?","options":[{"t":"⟨5/10⟩ km","correct":true},{"t":"⟨1 5/10⟩ km","mis":"M4-2-u1-X11"},{"t":"⟨6/10⟩ km","mis":"M4-2-u1-X16"},{"t":"⟨4/10⟩ km","mis":"M4-2-u1-X16"}],"explanation":["⟨2/10⟩에서 ⟨7/10⟩을 뺄 수 없어 1만큼을 ⟨10/10⟩으로 바꿔요 — ⟨3 2/10⟩ = ⟨2 12/10⟩.","⟨2 12/10⟩ − ⟨2 7/10⟩ = ⟨5/10⟩ km — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨32/10⟩ − ⟨27/10⟩ = ⟨5/10⟩ = ⟨5/10⟩ km."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_b#17','math',4,2,'u1','','tb_g4_2_math_u1_review_b','unit_review','M4-2-u1-C2',3,'sa','auto','분수 띠로 1을 분모가 5인 진분수 두 개로 가르려고 해요. 순서만 바꾼 것은 한 가지로 셀 때, 가르는 방법은 모두 몇 가지인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"M4-2-u1-C2","difficulty":3,"kind":"sa","stem":"분수 띠로 1을 분모가 5인 진분수 두 개로 가르려고 해요. 순서만 바꾼 것은 한 가지로 셀 때, 가르는 방법은 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["1 = ⟨5/5⟩ — 두 분수의 분자의 합이 5가 되게 갈라요.","⟨1/5⟩과 ⟨4/5⟩, ⟨2/5⟩와 ⟨3/5⟩이에요.","순서만 바꾼 것은 한 가지로 세면 모두 2가지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_b#18','math',4,2,'u1','','tb_g4_2_math_u1_review_b','unit_review','M4-2-u1-C3',3,'sa','auto','⟨3/4⟩ + ⟨□/4⟩ = ⟨1 1/4⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"M4-2-u1-C3","difficulty":3,"kind":"sa","stem":"⟨3/4⟩ + ⟨□/4⟩ = ⟨1 1/4⟩ — □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["⟨1 1/4⟩ = ⟨5/4⟩ — ⟨1/4⟩이 5개예요.","⟨3/4⟩은 ⟨1/4⟩이 3개라 5 − 3 = 2개를 더 모아야 해요.","⟨3/4⟩ + ⟨2/4⟩ = ⟨1 1/4⟩ — □ = 2."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_b#19','math',4,2,'u1','','tb_g4_2_math_u1_review_b','unit_review','M4-2-u1-C5',3,'sa','auto','「익힘」 ⟨1 4/5⟩ + ⟨1 3/5⟩ = ⟨9/5⟩ + ⟨8/5⟩ = ⟨□/5⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M4-2-u1-C5","difficulty":3,"kind":"sa","stem":"「익힘」 ⟨1 4/5⟩ + ⟨1 3/5⟩ = ⟨9/5⟩ + ⟨8/5⟩ = ⟨□/5⟩ — □에 알맞은 수를 쓰세요.","answer":["17"],"explanation":["⟨1 4/5⟩ = ⟨9/5⟩, ⟨1 3/5⟩ = ⟨8/5⟩이에요.","⟨9/5⟩ + ⟨8/5⟩ = ⟨17/5⟩ — 분모는 그대로예요.","⟨17/5⟩ = ⟨3 2/5⟩ — □ = 17."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_b#20','math',4,2,'u1','','tb_g4_2_math_u1_review_b','unit_review','M4-2-u1-C8',3,'error','auto','⟨5 3/8⟩ − ⟨4/8⟩를 계산하는 과정을 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u1-X11','M4-2-u1-X15']::text[],false,'{"seq":20,"concept":"M4-2-u1-C8","difficulty":3,"kind":"error","stem":"⟨5 3/8⟩ − ⟨4/8⟩를 계산하는 과정을 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「⟨5 3/8⟩ − ⟨4/8⟩ = ⟨5 1/8⟩이야.」","correct":true,"mis_target":"M4-2-u1-X11"},{"t":"서준 — 「⟨3/8⟩에서 ⟨4/8⟩를 뺄 수 없어.」","mis":"M4-2-u1-X15"},{"t":"채원 — 「⟨5 3/8⟩ = ⟨4 11/8⟩이야.」","mis":"M4-2-u1-X15"},{"t":"지유 — 「⟨4 11/8⟩ − ⟨4/8⟩ = ⟨4 7/8⟩이야.」","mis":"M4-2-u1-X15"}],"explanation":["⟨3/8⟩에서 ⟨4/8⟩를 뺄 수 없어요.","⟨5 3/8⟩ = ⟨4 11/8⟩ — ⟨4 11/8⟩ − ⟨4/8⟩ = ⟨4 7/8⟩이에요.","도윤이는 분자를 거꾸로 4 − 3으로 뺐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_b#21','math',4,2,'u1','','tb_g4_2_math_u1_review_b','unit_review','M4-2-u1-C9',3,'mc','auto','「교과서」 친구가 「⟨5 2/9⟩ − ⟨1 4/9⟩ = ⟨7/9⟩ − ⟨5/9⟩ = ⟨2/9⟩」라고 계산했어요. 바르게 계산한 값은 얼마인가요?',ARRAY['M4-2-u1-X03','M4-2-u1-X11','M4-2-u1-X09']::text[],false,'{"seq":21,"concept":"M4-2-u1-C9","difficulty":3,"kind":"mc","stem":"「교과서」 친구가 「⟨5 2/9⟩ − ⟨1 4/9⟩ = ⟨7/9⟩ − ⟨5/9⟩ = ⟨2/9⟩」라고 계산했어요. 바르게 계산한 값은 얼마인가요?","options":[{"t":"⟨3 7/9⟩","correct":true},{"t":"⟨2/9⟩","mis":"M4-2-u1-X03"},{"t":"⟨4 2/9⟩","mis":"M4-2-u1-X11"},{"t":"⟨4 7/9⟩","mis":"M4-2-u1-X09"}],"explanation":["⟨2/9⟩에서 ⟨4/9⟩를 뺄 수 없어 1만큼을 ⟨9/9⟩로 바꿔요 — ⟨5 2/9⟩ = ⟨4 11/9⟩.","⟨4 11/9⟩ − ⟨1 4/9⟩ = ⟨3 7/9⟩ — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨47/9⟩ − ⟨13/9⟩ = ⟨34/9⟩ = ⟨3 7/9⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_b#22','math',4,2,'u1','','tb_g4_2_math_u1_review_b','unit_review','M4-2-u1-C10',3,'mc','auto','「나는야 분수왕」 분수 카드 ⟨1 4/5⟩, ⟨1/5⟩, ⟨16/5⟩, ⟨3/5⟩, ⟨2 3/5⟩, ⟨2 2/5⟩, ⟨3 3/5⟩, ⟨2/5⟩, ⟨7/5⟩, ⟨1 3/5⟩이 있어요. ⟨2 3/5⟩에서 빼서 2가 되는 카드는 무엇인가요?',ARRAY['M4-2-u1-X13','M4-2-u1-X16']::text[],false,'{"seq":22,"concept":"M4-2-u1-C10","difficulty":3,"kind":"mc","stem":"「나는야 분수왕」 분수 카드 ⟨1 4/5⟩, ⟨1/5⟩, ⟨16/5⟩, ⟨3/5⟩, ⟨2 3/5⟩, ⟨2 2/5⟩, ⟨3 3/5⟩, ⟨2/5⟩, ⟨7/5⟩, ⟨1 3/5⟩이 있어요. ⟨2 3/5⟩에서 빼서 2가 되는 카드는 무엇인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"⟨1 3/5⟩","mis":"M4-2-u1-X13"},{"t":"⟨2/5⟩","mis":"M4-2-u1-X16"},{"t":"⟨1/5⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨2 3/5⟩ − 2 = ⟨3/5⟩이에요.","⟨2 3/5⟩ − ⟨3/5⟩ = 2예요.","⟨1 3/5⟩을 빼면 ⟨2 3/5⟩ − ⟨1 3/5⟩ = 1이 되어 2가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_b#23','math',4,2,'u1','','tb_g4_2_math_u1_review_b','unit_review','M4-2-u1-C9',4,'mc','auto','「재미있는 수학·이런 활동」 수 카드 2, 3, 4, 6을 한 번씩만 사용하여 분모가 9인 대분수 두 개를 만들고(자연수 부분과 분자에 한 장씩), 큰 대분수에서 작은 대분수를 빼려고 해요. 계산 결과가 가장 큰 뺄셈식의 계산 결과는 얼마인가요?',ARRAY['M4-2-u1-X16','M4-2-u1-X17']::text[],false,'{"seq":23,"concept":"M4-2-u1-C9","difficulty":4,"kind":"mc","stem":"「재미있는 수학·이런 활동」 수 카드 2, 3, 4, 6을 한 번씩만 사용하여 분모가 9인 대분수 두 개를 만들고(자연수 부분과 분자에 한 장씩), 큰 대분수에서 작은 대분수를 빼려고 해요. 계산 결과가 가장 큰 뺄셈식의 계산 결과는 얼마인가요?","options":[{"t":"⟨4 1/9⟩","correct":true},{"t":"⟨3 2/9⟩","mis":"M4-2-u1-X16"},{"t":"⟨2 7/9⟩","mis":"M4-2-u1-X16"},{"t":"⟨3 8/9⟩","mis":"M4-2-u1-X17"}],"explanation":["차가 크려면 가장 큰 대분수에서 가장 작은 대분수를 빼요 — 자연수 부분에 가장 큰 수와 가장 작은 수를 놓아요.","⟨6 4/9⟩ − ⟨2 3/9⟩ = ⟨4 1/9⟩이에요.","교과서의 ⟨6 3/9⟩ − ⟨2 4/9⟩ = ⟨3 8/9⟩과 견주어 보세요 — 카드를 어디에 놓느냐에 따라 결과가 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_b#24','math',4,2,'u1','','tb_g4_2_math_u1_review_b','unit_review','M4-2-u1-C10',4,'mc','auto','「나는야 분수왕」 분수 카드 10장(⟨1 4/5⟩, ⟨1/5⟩, ⟨16/5⟩, ⟨3/5⟩, ⟨2 3/5⟩, ⟨2 2/5⟩, ⟨3 3/5⟩, ⟨2/5⟩, ⟨7/5⟩, ⟨1 3/5⟩)을 한 번씩만 사용해요. 덧셈식 ⟨2 3/5⟩ + ⟨7/5⟩ = 4를 먼저 만들었다면, 뺄셈식 □ − □ = 2에 쓸 수 있는 두 카드는 무엇인가요?',ARRAY['M4-2-u1-X15','M4-2-u1-X17','M4-2-u1-X16']::text[],false,'{"seq":24,"concept":"M4-2-u1-C10","difficulty":4,"kind":"mc","stem":"「나는야 분수왕」 분수 카드 10장(⟨1 4/5⟩, ⟨1/5⟩, ⟨16/5⟩, ⟨3/5⟩, ⟨2 3/5⟩, ⟨2 2/5⟩, ⟨3 3/5⟩, ⟨2/5⟩, ⟨7/5⟩, ⟨1 3/5⟩)을 한 번씩만 사용해요. 덧셈식 ⟨2 3/5⟩ + ⟨7/5⟩ = 4를 먼저 만들었다면, 뺄셈식 □ − □ = 2에 쓸 수 있는 두 카드는 무엇인가요?","options":[{"t":"⟨2 2/5⟩, ⟨2/5⟩","correct":true},{"t":"⟨2 3/5⟩, ⟨3/5⟩","mis":"M4-2-u1-X15"},{"t":"⟨3 3/5⟩, ⟨2/5⟩","mis":"M4-2-u1-X17"},{"t":"⟨16/5⟩, ⟨1 4/5⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨2 3/5⟩과 ⟨7/5⟩은 이미 썼으니 다시 쓸 수 없어요.","⟨2 2/5⟩ − ⟨2/5⟩ = 2예요.","⟨3 3/5⟩ − ⟨2/5⟩ = ⟨3 1/5⟩, ⟨16/5⟩ − ⟨1 4/5⟩ = ⟨7/5⟩ — 2가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_b#25','math',4,2,'u1','','tb_g4_2_math_u1_review_b','unit_review','M4-2-u1-C9',4,'essay','teacher','「스스로 마무리하기」 8번 채원이는 학교에서 도서관(⟨1 2/7⟩ km)을 지나 집(도서관에서 ⟨6/7⟩ km)에 가려고 해요. 학교에서 집으로 곧장 가는 길은 ⟨1 5/7⟩ km예요. 도서관을 지나 가는 길이 곧장 가는 길보다 몇 km 더 먼지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u1-C9","difficulty":4,"kind":"essay","stem":"「스스로 마무리하기」 8번 채원이는 학교에서 도서관(⟨1 2/7⟩ km)을 지나 집(도서관에서 ⟨6/7⟩ km)에 가려고 해요. 학교에서 집으로 곧장 가는 길은 ⟨1 5/7⟩ km예요. 도서관을 지나 가는 길이 곧장 가는 길보다 몇 km 더 먼지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 학교에서 도서관을 지나 집에 가는 길은 ⟨1 2/7⟩ + ⟨6/7⟩ = ⟨2 1/7⟩ (km)이다. 곧장 가는 길은 ⟨1 5/7⟩ km이므로 ⟨2 1/7⟩ − ⟨1 5/7⟩ = ⟨1 8/7⟩ − ⟨1 5/7⟩ = ⟨3/7⟩ (km) 더 멀다.","scoring_points":["도서관을 지나 가는 길 ⟨2 1/7⟩ km를 구했는가","뺄셈식을 세워 1만큼 바꾸어 계산했는가","⟨3/7⟩ km라고 답했는가"]},"explanation":["⟨1 2/7⟩ + ⟨6/7⟩ = ⟨2 1/7⟩이에요.","⟨2 1/7⟩ − ⟨1 5/7⟩ = ⟨3/7⟩이에요.","⟨3/7⟩ km 더 멀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_c#1','math',4,2,'u1','','tb_g4_2_math_u1_review_c','unit_review','M4-2-u1-C2',1,'mc','auto','분수 띠로 1을 ⟨2/6⟩와 □로 갈랐어요. □에 알맞은 분수는 무엇인가요?',ARRAY['M4-2-u1-X06','M4-2-u1-X16']::text[],false,'{"seq":1,"concept":"M4-2-u1-C2","difficulty":1,"kind":"mc","stem":"분수 띠로 1을 ⟨2/6⟩와 □로 갈랐어요. □에 알맞은 분수는 무엇인가요?","options":[{"t":"⟨4/6⟩","correct":true},{"t":"⟨2/6⟩","mis":"M4-2-u1-X06"},{"t":"⟨6/2⟩","mis":"M4-2-u1-X06"},{"t":"⟨5/6⟩","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨6/6⟩ — ⟨1/6⟩이 6개예요.","⟨2/6⟩는 ⟨1/6⟩이 2개라 6 − 2 = 4개가 모자라요.","⟨2/6⟩ + ⟨4/6⟩ = ⟨6/6⟩ = 1이에요."],"asset":{"type":"fbar","bars":[{"den":6,"num":2,"label":"1을 가르기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_c#2','math',4,2,'u1','','tb_g4_2_math_u1_review_c','unit_review','M4-2-u1-C3',1,'sa','auto','「익힘」 ⟨2/9⟩ + ⟨5/9⟩ = ⟨□/9⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M4-2-u1-C3","difficulty":1,"kind":"sa","stem":"「익힘」 ⟨2/9⟩ + ⟨5/9⟩ = ⟨□/9⟩ — □에 알맞은 수를 쓰세요.","answer":["7"],"explanation":["⟨2/9⟩는 ⟨1/9⟩이 2개, ⟨5/9⟩는 ⟨1/9⟩이 5개예요.","⟨2/9⟩ + ⟨5/9⟩ = ⟨7/9⟩ — 분모는 그대로 두고 분자끼리 더해요.","분모끼리 더한 ⟨7/18⟩은 답이 아니에요 — 답은 ⟨7/9⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_c#3','math',4,2,'u1','','tb_g4_2_math_u1_review_c','unit_review','M4-2-u1-C4',1,'sa','auto','「익힘」 ⟨7/11⟩ − ⟨2/11⟩ = ⟨□/11⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M4-2-u1-C4","difficulty":1,"kind":"sa","stem":"「익힘」 ⟨7/11⟩ − ⟨2/11⟩ = ⟨□/11⟩ — □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["⟨7/11⟩은 ⟨1/11⟩이 7개, ⟨2/11⟩는 ⟨1/11⟩이 2개예요.","⟨7/11⟩ − ⟨2/11⟩ = ⟨5/11⟩ — 분모는 그대로 두고 분자끼리 빼요.","⟨1/11⟩이 7 − 2 = 5개 남아요 — 분모끼리 빼지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_c#4','math',4,2,'u1','','tb_g4_2_math_u1_review_c','unit_review','M4-2-u1-C5',1,'mc','auto','「확인 문제」 ⟨2 5/9⟩ + ⟨3 2/9⟩를 계산해 보세요.',ARRAY['M4-2-u1-X01','M4-2-u1-X13','M4-2-u1-X16']::text[],false,'{"seq":4,"concept":"M4-2-u1-C5","difficulty":1,"kind":"mc","stem":"「확인 문제」 ⟨2 5/9⟩ + ⟨3 2/9⟩를 계산해 보세요.","options":[{"t":"⟨5 7/9⟩","correct":true},{"t":"⟨5 7/18⟩","mis":"M4-2-u1-X01"},{"t":"⟨7/9⟩","mis":"M4-2-u1-X13"},{"t":"⟨5 8/9⟩","mis":"M4-2-u1-X16"}],"explanation":["방법 1 — 자연수끼리 2 + 3 = 5, 분수끼리 ⟨5/9⟩ + ⟨2/9⟩ = ⟨7/9⟩이에요.","5 + ⟨7/9⟩ = ⟨5 7/9⟩.","방법 2 — 가분수로 바꾸면 ⟨23/9⟩ + ⟨29/9⟩ = ⟨52/9⟩ = ⟨5 7/9⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_c#5','math',4,2,'u1','','tb_g4_2_math_u1_review_c','unit_review','M4-2-u1-C6',1,'sa','auto','「익힘」 ⟨2 4/5⟩ − ⟨1 1/5⟩ = ⟨14/5⟩ − ⟨6/5⟩ = ⟨□/5⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M4-2-u1-C6","difficulty":1,"kind":"sa","stem":"「익힘」 ⟨2 4/5⟩ − ⟨1 1/5⟩ = ⟨14/5⟩ − ⟨6/5⟩ = ⟨□/5⟩ — □에 알맞은 수를 쓰세요.","answer":["8"],"explanation":["⟨2 4/5⟩ = ⟨14/5⟩, ⟨1 1/5⟩ = ⟨6/5⟩이에요.","⟨14/5⟩ − ⟨6/5⟩ = ⟨8/5⟩ — 분모는 그대로예요.","⟨8/5⟩ = ⟨1 3/5⟩ — □ = 8."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_c#6','math',4,2,'u1','','tb_g4_2_math_u1_review_c','unit_review','M4-2-u1-C8',1,'mc','auto','⟨5 3/8⟩ − ⟨4/8⟩를 계산해 보세요.',ARRAY['M4-2-u1-X11','M4-2-u1-X09','M4-2-u1-X03']::text[],false,'{"seq":6,"concept":"M4-2-u1-C8","difficulty":1,"kind":"mc","stem":"⟨5 3/8⟩ − ⟨4/8⟩를 계산해 보세요.","options":[{"t":"⟨4 7/8⟩","correct":true},{"t":"⟨5 1/8⟩","mis":"M4-2-u1-X11"},{"t":"⟨5 7/8⟩","mis":"M4-2-u1-X09"},{"t":"⟨4/8⟩","mis":"M4-2-u1-X03"}],"explanation":["⟨3/8⟩에서 ⟨4/8⟩를 뺄 수 없어 1만큼을 ⟨8/8⟩로 바꿔요 — ⟨5 3/8⟩ = ⟨4 11/8⟩.","⟨4 11/8⟩ − ⟨4/8⟩ = ⟨4 7/8⟩ — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨43/8⟩ − ⟨4/8⟩ = ⟨39/8⟩ = ⟨4 7/8⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_c#7','math',4,2,'u1','','tb_g4_2_math_u1_review_c','unit_review','M4-2-u1-C3',1,'mc','auto','「익힘」 그림을 보고 ⟨5/7⟩ + ⟨4/7⟩를 계산하여 대분수로 나타내면 얼마인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X04']::text[],false,'{"seq":7,"concept":"M4-2-u1-C3","difficulty":1,"kind":"mc","stem":"「익힘」 그림을 보고 ⟨5/7⟩ + ⟨4/7⟩를 계산하여 대분수로 나타내면 얼마인가요?","options":[{"t":"⟨1 2/7⟩","correct":true},{"t":"⟨9/14⟩","mis":"M4-2-u1-X01"},{"t":"⟨2/7⟩","mis":"M4-2-u1-X04"},{"t":"⟨2 2/7⟩","mis":"M4-2-u1-X04"}],"explanation":["⟨5/7⟩는 ⟨1/7⟩이 5개, ⟨4/7⟩는 ⟨1/7⟩이 4개예요.","⟨5/7⟩ + ⟨4/7⟩ = ⟨9/7⟩ — 분모는 그대로 두고 분자끼리 더해요.","⟨9/7⟩ = ⟨1 2/7⟩ — 분모끼리 더하지 않아요."],"asset":{"type":"fbar","bars":[{"den":7,"num":5},{"den":7,"num":4}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_c#8','math',4,2,'u1','','tb_g4_2_math_u1_review_c','unit_review','M4-2-u1-C7',1,'match','auto','계산 결과끼리 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u1-C7","difficulty":1,"kind":"match","stem":"계산 결과끼리 알맞게 이으세요.","pairs":[{"l":"⟨4/7⟩ + ⟨2/7⟩","r":"⟨6/7⟩"},{"l":"1 − ⟨5/8⟩","r":"⟨3/8⟩"},{"l":"⟨1 2/8⟩ + ⟨3 1/8⟩","r":"⟨4 3/8⟩"},{"l":"3 − ⟨1/7⟩","r":"⟨2 6/7⟩"}],"mis":"M4-2-u1-X09","explanation":["⟨4/7⟩ + ⟨2/7⟩ = ⟨6/7⟩, 1 − ⟨5/8⟩ = ⟨3/8⟩이에요.","⟨1 2/8⟩ + ⟨3 1/8⟩ = ⟨4 3/8⟩이에요.","3 − ⟨1/7⟩ = ⟨2 7/7⟩ − ⟨1/7⟩ = ⟨2 6/7⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_c#9','math',4,2,'u1','','tb_g4_2_math_u1_review_c','unit_review','M4-2-u1-C5',2,'mc','auto','「익힘」 두 분수 ⟨3 1/9⟩과 ⟨25/9⟩의 합은 얼마인가요?',ARRAY['M4-2-u1-X07','M4-2-u1-X16','M4-2-u1-X14']::text[],false,'{"seq":9,"concept":"M4-2-u1-C5","difficulty":2,"kind":"mc","stem":"「익힘」 두 분수 ⟨3 1/9⟩과 ⟨25/9⟩의 합은 얼마인가요?","options":[{"t":"⟨5 8/9⟩","correct":true},{"t":"⟨4 8/9⟩","mis":"M4-2-u1-X07"},{"t":"⟨5 7/9⟩","mis":"M4-2-u1-X16"},{"t":"⟨3/9⟩","mis":"M4-2-u1-X14"}],"explanation":["⟨25/9⟩ = ⟨2 7/9⟩이에요.","⟨3 1/9⟩ + ⟨2 7/9⟩ = 5 + ⟨8/9⟩ = ⟨5 8/9⟩이에요.","가분수로 바꾸면 ⟨28/9⟩ + ⟨25/9⟩ = ⟨53/9⟩ = ⟨5 8/9⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_c#10','math',4,2,'u1','','tb_g4_2_math_u1_review_c','unit_review','M4-2-u1-C4',2,'mc','auto','「익힘」 계산 결과가 작은 것부터 차례대로 기호를 쓴 것은 무엇인가요?  ㉠ ⟨3/4⟩ − ⟨2/4⟩  ㉡ ⟨5/6⟩ − ⟨4/6⟩  ㉢ 1 − ⟨7/8⟩  ㉣ ⟨6/7⟩ − ⟨5/7⟩',ARRAY['M4-2-u1-X15','M4-2-u1-X17','M4-2-u1-X16']::text[],false,'{"seq":10,"concept":"M4-2-u1-C4","difficulty":2,"kind":"mc","stem":"「익힘」 계산 결과가 작은 것부터 차례대로 기호를 쓴 것은 무엇인가요?  ㉠ ⟨3/4⟩ − ⟨2/4⟩  ㉡ ⟨5/6⟩ − ⟨4/6⟩  ㉢ 1 − ⟨7/8⟩  ㉣ ⟨6/7⟩ − ⟨5/7⟩","options":[{"t":"㉢, ㉣, ㉡, ㉠","correct":true},{"t":"㉠, ㉡, ㉣, ㉢","mis":"M4-2-u1-X15"},{"t":"㉣, ㉢, ㉡, ㉠","mis":"M4-2-u1-X17"},{"t":"㉢, ㉣, ㉠, ㉡","mis":"M4-2-u1-X16"}],"explanation":["하나씩 계산해요 — ㉠ ⟨3/4⟩ − ⟨2/4⟩ = ⟨1/4⟩, ㉡ ⟨5/6⟩ − ⟨4/6⟩ = ⟨1/6⟩, ㉢ 1 − ⟨7/8⟩ = ⟨1/8⟩, ㉣ ⟨6/7⟩ − ⟨5/7⟩ = ⟨1/7⟩.","⟨1/8⟩ < ⟨1/7⟩ < ⟨1/6⟩ < ⟨1/4⟩이에요.","계산 결과가 작은 것부터 쓰면 ㉢, ㉣, ㉡, ㉠예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_c#11','math',4,2,'u1','','tb_g4_2_math_u1_review_c','unit_review','M4-2-u1-C4',2,'mc','auto','「익힘」 1 − ⟨2/6⟩를 계산해 보세요.',ARRAY['M4-2-u1-X08','M4-2-u1-X15','M4-2-u1-X16']::text[],false,'{"seq":11,"concept":"M4-2-u1-C4","difficulty":2,"kind":"mc","stem":"「익힘」 1 − ⟨2/6⟩를 계산해 보세요.","options":[{"t":"⟨4/6⟩","correct":true},{"t":"⟨1/6⟩","mis":"M4-2-u1-X08"},{"t":"⟨2/6⟩","mis":"M4-2-u1-X15"},{"t":"⟨5/6⟩","mis":"M4-2-u1-X16"}],"explanation":["1은 ⟨1/6⟩이 6개 — 1 = ⟨6/6⟩이에요.","1 − ⟨2/6⟩ = ⟨6/6⟩ − ⟨2/6⟩ = ⟨4/6⟩.","1을 가분수로 바꾼 뒤 분자끼리 빼요 — 6 − 2 = 4."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_c#12','math',4,2,'u1','','tb_g4_2_math_u1_review_c','unit_review','M4-2-u1-C4',2,'mc','auto','「익힘 퐁당」 친구가 「1 − ⟨5/7⟩ = ⟨4/7⟩」라고 계산했어요. 바르게 계산한 값은 얼마인가요?',ARRAY['M4-2-u1-X08','M4-2-u1-X15','M4-2-u1-X16']::text[],false,'{"seq":12,"concept":"M4-2-u1-C4","difficulty":2,"kind":"mc","stem":"「익힘 퐁당」 친구가 「1 − ⟨5/7⟩ = ⟨4/7⟩」라고 계산했어요. 바르게 계산한 값은 얼마인가요?","options":[{"t":"⟨2/7⟩","correct":true},{"t":"⟨4/7⟩","mis":"M4-2-u1-X08"},{"t":"⟨5/7⟩","mis":"M4-2-u1-X15"},{"t":"⟨3/7⟩","mis":"M4-2-u1-X16"}],"explanation":["1은 ⟨1/7⟩이 7개 — 1 = ⟨7/7⟩이에요.","1 − ⟨5/7⟩ = ⟨7/7⟩ − ⟨5/7⟩ = ⟨2/7⟩.","1을 가분수로 바꾼 뒤 분자끼리 빼요 — 7 − 5 = 2."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_c#13','math',4,2,'u1','','tb_g4_2_math_u1_review_c','unit_review','M4-2-u1-C6',2,'mc','auto','「익힘」 ⟨7 6/7⟩ − ⟨4 5/7⟩ < ⟨7 6/7⟩ − ⟨4 □/7⟩에서 □ 안에 들어갈 수 있는 자연수를 모두 찾은 것은 무엇인가요?',ARRAY['M4-2-u1-X16','M4-2-u1-X15']::text[],false,'{"seq":13,"concept":"M4-2-u1-C6","difficulty":2,"kind":"mc","stem":"「익힘」 ⟨7 6/7⟩ − ⟨4 5/7⟩ < ⟨7 6/7⟩ − ⟨4 □/7⟩에서 □ 안에 들어갈 수 있는 자연수를 모두 찾은 것은 무엇인가요?","options":[{"t":"1, 2, 3, 4","correct":true},{"t":"1, 2, 3, 4, 5","mis":"M4-2-u1-X16"},{"t":"6","mis":"M4-2-u1-X15"},{"t":"5, 6","mis":"M4-2-u1-X15"}],"explanation":["두 식 모두 ⟨7 6/7⟩에서 빼고 있어요.","결과가 더 크려면 ⟨4 5/7⟩보다 작은 수를 빼야 해요.","1, 2, 3, 4 — 5를 넣으면 크기가 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_c#14','math',4,2,'u1','','tb_g4_2_math_u1_review_c','unit_review','M4-2-u1-C10',2,'mc','auto','「익힘」 가 과일 바구니에는 파인애플과 배가 한 개씩 들어 있고, 바구니까지 모두 ⟨2 3/10⟩ kg이에요. 배 한 개는 ⟨6/10⟩ kg, 바구니 한 개는 ⟨4/10⟩ kg일 때 파인애플의 무게는 몇 kg인가요?',ARRAY['M4-2-u1-X15','M4-2-u1-X14']::text[],false,'{"seq":14,"concept":"M4-2-u1-C10","difficulty":2,"kind":"mc","stem":"「익힘」 가 과일 바구니에는 파인애플과 배가 한 개씩 들어 있고, 바구니까지 모두 ⟨2 3/10⟩ kg이에요. 배 한 개는 ⟨6/10⟩ kg, 바구니 한 개는 ⟨4/10⟩ kg일 때 파인애플의 무게는 몇 kg인가요?","options":[{"t":"⟨1 3/10⟩ kg","correct":true},{"t":"⟨1 7/10⟩ kg","mis":"M4-2-u1-X15"},{"t":"⟨1 9/10⟩ kg","mis":"M4-2-u1-X15"},{"t":"⟨3 3/10⟩ kg","mis":"M4-2-u1-X14"}],"explanation":["파인애플의 무게는 가 바구니의 무게에서 배와 바구니의 무게를 빼서 구해요.","⟨2 3/10⟩ − ⟨6/10⟩ − ⟨4/10⟩ = ⟨1 7/10⟩ − ⟨4/10⟩ = ⟨1 3/10⟩이에요.","배와 바구니를 먼저 더해 ⟨6/10⟩ + ⟨4/10⟩ = 1을 빼도 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_c#15','math',4,2,'u1','','tb_g4_2_math_u1_review_c','unit_review','M4-2-u1-C5',2,'mc','auto','「확인 문제」 찬혁이는 물을 아침에 ⟨1 2/10⟩ L, 점심에 ⟨1 4/10⟩ L 마셨어요. 찬혁이가 아침과 점심에 마신 물은 모두 몇 L인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X13','M4-2-u1-X16']::text[],false,'{"seq":15,"concept":"M4-2-u1-C5","difficulty":2,"kind":"mc","stem":"「확인 문제」 찬혁이는 물을 아침에 ⟨1 2/10⟩ L, 점심에 ⟨1 4/10⟩ L 마셨어요. 찬혁이가 아침과 점심에 마신 물은 모두 몇 L인가요?","options":[{"t":"⟨2 6/10⟩ L","correct":true},{"t":"⟨2 6/20⟩ L","mis":"M4-2-u1-X01"},{"t":"⟨6/10⟩ L","mis":"M4-2-u1-X13"},{"t":"⟨2 7/10⟩ L","mis":"M4-2-u1-X16"}],"explanation":["방법 1 — 자연수끼리 1 + 1 = 2, 분수끼리 ⟨2/10⟩ + ⟨4/10⟩ = ⟨6/10⟩이에요.","2 + ⟨6/10⟩ = ⟨2 6/10⟩ L.","방법 2 — 가분수로 바꾸면 ⟨12/10⟩ + ⟨14/10⟩ = ⟨26/10⟩ = ⟨2 6/10⟩ L."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_c#16','math',4,2,'u1','','tb_g4_2_math_u1_review_c','unit_review','M4-2-u1-C9',2,'mc','auto','「익힘」 물 ⟨3 3/8⟩ L 중에서 ⟨1 7/8⟩ L를 마셨어요. 남은 물은 몇 L인가요?',ARRAY['M4-2-u1-X11','M4-2-u1-X12','M4-2-u1-X16']::text[],false,'{"seq":16,"concept":"M4-2-u1-C9","difficulty":2,"kind":"mc","stem":"「익힘」 물 ⟨3 3/8⟩ L 중에서 ⟨1 7/8⟩ L를 마셨어요. 남은 물은 몇 L인가요?","options":[{"t":"⟨1 4/8⟩ L","correct":true},{"t":"⟨2 4/8⟩ L","mis":"M4-2-u1-X11"},{"t":"⟨1 6/8⟩ L","mis":"M4-2-u1-X12"},{"t":"⟨1 5/8⟩ L","mis":"M4-2-u1-X16"}],"explanation":["⟨3/8⟩에서 ⟨7/8⟩을 뺄 수 없어 1만큼을 ⟨8/8⟩로 바꿔요 — ⟨3 3/8⟩ = ⟨2 11/8⟩.","⟨2 11/8⟩ − ⟨1 7/8⟩ = ⟨1 4/8⟩ L — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨27/8⟩ − ⟨15/8⟩ = ⟨12/8⟩ = ⟨1 4/8⟩ L."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_c#17','math',4,2,'u1','','tb_g4_2_math_u1_review_c','unit_review','M4-2-u1-C2',3,'sa','auto','분수 띠로 1을 분모가 4인 진분수 두 개로 가르려고 해요. 순서만 바꾼 것은 한 가지로 셀 때, 가르는 방법은 모두 몇 가지인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"M4-2-u1-C2","difficulty":3,"kind":"sa","stem":"분수 띠로 1을 분모가 4인 진분수 두 개로 가르려고 해요. 순서만 바꾼 것은 한 가지로 셀 때, 가르는 방법은 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["1 = ⟨4/4⟩ — 두 분수의 분자의 합이 4가 되게 갈라요.","⟨1/4⟩과 ⟨3/4⟩, ⟨2/4⟩와 ⟨2/4⟩예요.","순서만 바꾼 것은 한 가지로 세면 모두 2가지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_c#18','math',4,2,'u1','','tb_g4_2_math_u1_review_c','unit_review','M4-2-u1-C3',3,'sa','auto','⟨7/9⟩ + ⟨□/9⟩ = ⟨1 3/9⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"M4-2-u1-C3","difficulty":3,"kind":"sa","stem":"⟨7/9⟩ + ⟨□/9⟩ = ⟨1 3/9⟩ — □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["⟨1 3/9⟩ = ⟨12/9⟩ — ⟨1/9⟩이 12개예요.","⟨7/9⟩은 ⟨1/9⟩이 7개라 12 − 7 = 5개를 더 모아야 해요.","⟨7/9⟩ + ⟨5/9⟩ = ⟨1 3/9⟩ — □ = 5."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_c#19','math',4,2,'u1','','tb_g4_2_math_u1_review_c','unit_review','M4-2-u1-C5',3,'sa','auto','「익힘 퐁당」 ⟨1 3/8⟩ + ⟨2 4/8⟩ = ⟨11/8⟩ + ⟨20/8⟩ = ⟨□/8⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M4-2-u1-C5","difficulty":3,"kind":"sa","stem":"「익힘 퐁당」 ⟨1 3/8⟩ + ⟨2 4/8⟩ = ⟨11/8⟩ + ⟨20/8⟩ = ⟨□/8⟩ — □에 알맞은 수를 쓰세요.","answer":["31"],"explanation":["⟨1 3/8⟩ = ⟨11/8⟩, ⟨2 4/8⟩ = ⟨20/8⟩이에요.","⟨11/8⟩ + ⟨20/8⟩ = ⟨31/8⟩ — 분모는 그대로예요.","⟨31/8⟩ = ⟨3 7/8⟩ — □ = 31."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_c#20','math',4,2,'u1','','tb_g4_2_math_u1_review_c','unit_review','M4-2-u1-C7',3,'error','auto','3 − ⟨1/7⟩을 계산하는 과정을 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u1-X09','M4-2-u1-X15']::text[],false,'{"seq":20,"concept":"M4-2-u1-C7","difficulty":3,"kind":"error","stem":"3 − ⟨1/7⟩을 계산하는 과정을 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"건우 — 「3을 ⟨3 7/7⟩로 바꿨어.」","correct":true,"mis_target":"M4-2-u1-X09"},{"t":"서준 — 「3에서 1만큼을 ⟨7/7⟩로 바꾸면 ⟨2 7/7⟩이야.」","mis":"M4-2-u1-X15"},{"t":"채원 — 「⟨7/7⟩ − ⟨1/7⟩ = ⟨6/7⟩이야.」","mis":"M4-2-u1-X15"},{"t":"지유 — 「3 − ⟨1/7⟩ = ⟨2 6/7⟩이야.」","mis":"M4-2-u1-X15"}],"explanation":["3에서 1만큼을 ⟨7/7⟩로 바꾸면 자연수 부분은 1 줄어요.","3 = ⟨2 7/7⟩ — ⟨2 7/7⟩ − ⟨1/7⟩ = ⟨2 6/7⟩이에요.","⟨3 7/7⟩은 4와 같아서 3이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_c#21','math',4,2,'u1','','tb_g4_2_math_u1_review_c','unit_review','M4-2-u1-C9',3,'mc','auto','「교과서」 친구가 「⟨3 1/7⟩ − ⟨1 6/7⟩ = ⟨2 11/7⟩ − ⟨1 6/7⟩ = ⟨1 5/7⟩」라고 계산했어요. 바르게 계산한 값은 얼마인가요?',ARRAY['M4-2-u1-X12','M4-2-u1-X11','M4-2-u1-X09']::text[],false,'{"seq":21,"concept":"M4-2-u1-C9","difficulty":3,"kind":"mc","stem":"「교과서」 친구가 「⟨3 1/7⟩ − ⟨1 6/7⟩ = ⟨2 11/7⟩ − ⟨1 6/7⟩ = ⟨1 5/7⟩」라고 계산했어요. 바르게 계산한 값은 얼마인가요?","options":[{"t":"⟨1 2/7⟩","correct":true},{"t":"⟨1 5/7⟩","mis":"M4-2-u1-X12"},{"t":"⟨2 5/7⟩","mis":"M4-2-u1-X11"},{"t":"⟨2 2/7⟩","mis":"M4-2-u1-X09"}],"explanation":["⟨1/7⟩에서 ⟨6/7⟩을 뺄 수 없어 1만큼을 ⟨7/7⟩로 바꿔요 — ⟨3 1/7⟩ = ⟨2 8/7⟩.","⟨2 8/7⟩ − ⟨1 6/7⟩ = ⟨1 2/7⟩ — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨22/7⟩ − ⟨13/7⟩ = ⟨9/7⟩ = ⟨1 2/7⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_c#22','math',4,2,'u1','','tb_g4_2_math_u1_review_c','unit_review','M4-2-u1-C10',3,'mc','auto','「나는야 분수왕」 분수 카드 ⟨1 2/3⟩, ⟨1/3⟩, ⟨13/3⟩, ⟨3 1/3⟩, ⟨2 1/3⟩ 중에서 3장을 골라 계산 결과가 6이 되는 덧셈식을 완성하려고 해요. 골라야 하는 카드 3장은 무엇인가요?',ARRAY['M4-2-u1-X17','M4-2-u1-X16']::text[],false,'{"seq":22,"concept":"M4-2-u1-C10","difficulty":3,"kind":"mc","stem":"「나는야 분수왕」 분수 카드 ⟨1 2/3⟩, ⟨1/3⟩, ⟨13/3⟩, ⟨3 1/3⟩, ⟨2 1/3⟩ 중에서 3장을 골라 계산 결과가 6이 되는 덧셈식을 완성하려고 해요. 골라야 하는 카드 3장은 무엇인가요?","options":[{"t":"⟨1/3⟩, ⟨3 1/3⟩, ⟨2 1/3⟩","correct":true},{"t":"⟨1 2/3⟩, ⟨1/3⟩, ⟨13/3⟩","mis":"M4-2-u1-X17"},{"t":"⟨1 2/3⟩, ⟨3 1/3⟩, ⟨2 1/3⟩","mis":"M4-2-u1-X17"},{"t":"⟨1/3⟩, ⟨13/3⟩, ⟨2 1/3⟩","mis":"M4-2-u1-X16"}],"explanation":["6 = ⟨18/3⟩ — 세 카드의 ⟨1/3⟩ 개수의 합이 18이 되게 골라요.","⟨1/3⟩ + ⟨3 1/3⟩ + ⟨2 1/3⟩ = ⟨1/3⟩ + ⟨10/3⟩ + ⟨7/3⟩ = ⟨18/3⟩이에요.","⟨18/3⟩ = 6 — 다른 3장은 6이 되지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_c#23','math',4,2,'u1','','tb_g4_2_math_u1_review_c','unit_review','M4-2-u1-C9',4,'mc','auto','「재미있는 수학·이런 활동」 수 카드 1, 5, 7, 8을 한 번씩만 사용하여 분모가 9인 대분수 두 개를 만들고(자연수 부분과 분자에 한 장씩), 큰 대분수에서 작은 대분수를 빼려고 해요. 계산 결과가 가장 큰 뺄셈식의 계산 결과는 얼마인가요?',ARRAY['M4-2-u1-X16','M4-2-u1-X17']::text[],false,'{"seq":23,"concept":"M4-2-u1-C9","difficulty":4,"kind":"mc","stem":"「재미있는 수학·이런 활동」 수 카드 1, 5, 7, 8을 한 번씩만 사용하여 분모가 9인 대분수 두 개를 만들고(자연수 부분과 분자에 한 장씩), 큰 대분수에서 작은 대분수를 빼려고 해요. 계산 결과가 가장 큰 뺄셈식의 계산 결과는 얼마인가요?","options":[{"t":"⟨7 2/9⟩","correct":true},{"t":"⟨6 3/9⟩","mis":"M4-2-u1-X16"},{"t":"⟨5 6/9⟩","mis":"M4-2-u1-X16"},{"t":"⟨6 7/9⟩","mis":"M4-2-u1-X17"}],"explanation":["차가 크려면 가장 큰 대분수에서 가장 작은 대분수를 빼요 — 자연수 부분에 가장 큰 수와 가장 작은 수를 놓아요.","⟨8 7/9⟩ − ⟨1 5/9⟩ = ⟨7 2/9⟩예요.","교과서의 ⟨8 5/9⟩ − ⟨1 7/9⟩ = ⟨6 7/9⟩과 견주어 보세요 — 카드를 어디에 놓느냐에 따라 결과가 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_c#24','math',4,2,'u1','','tb_g4_2_math_u1_review_c','unit_review','M4-2-u1-C10',4,'mc','auto','「익힘」 가 바구니(파인애플·배·바구니)는 ⟨2 3/10⟩ kg, 나 바구니(멜론·배·바구니)는 ⟨2 7/10⟩ kg, 배 한 개는 ⟨6/10⟩ kg, 바구니 한 개는 ⟨4/10⟩ kg이에요. 파인애플·멜론·배가 한 개씩 든 다 바구니의 무게는 몇 kg인가요?',ARRAY['M4-2-u1-X15']::text[],false,'{"seq":24,"concept":"M4-2-u1-C10","difficulty":4,"kind":"mc","stem":"「익힘」 가 바구니(파인애플·배·바구니)는 ⟨2 3/10⟩ kg, 나 바구니(멜론·배·바구니)는 ⟨2 7/10⟩ kg, 배 한 개는 ⟨6/10⟩ kg, 바구니 한 개는 ⟨4/10⟩ kg이에요. 파인애플·멜론·배가 한 개씩 든 다 바구니의 무게는 몇 kg인가요?","options":[{"t":"4 kg","correct":true},{"t":"5 kg","mis":"M4-2-u1-X15"},{"t":"⟨4 4/10⟩ kg","mis":"M4-2-u1-X15"},{"t":"⟨4 6/10⟩ kg","mis":"M4-2-u1-X15"}],"explanation":["가와 나를 더하면 ⟨2 3/10⟩ + ⟨2 7/10⟩ = 5 kg — 배 2개와 바구니 2개가 들어 있어요.","다 바구니에는 배와 바구니가 한 개씩이라 하나씩 빼요.","5 − ⟨6/10⟩ − ⟨4/10⟩ = 4 — 다 바구니는 4 kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_c#25','math',4,2,'u1','','tb_g4_2_math_u1_review_c','unit_review','M4-2-u1-C5',4,'essay','teacher','「만화」 두 농부가 사과를 ⟨2 2/4⟩ kg과 ⟨1 3/4⟩ kg 땄어요. 두 사람이 딴 사과는 모두 몇 kg인지, ⟨2 2/4⟩ kg을 딴 농부가 몇 kg 더 많이 땄는지 각각 구하고, 분수의 덧셈과 뺄셈을 어떻게 하는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u1-C5","difficulty":4,"kind":"essay","stem":"「만화」 두 농부가 사과를 ⟨2 2/4⟩ kg과 ⟨1 3/4⟩ kg 땄어요. 두 사람이 딴 사과는 모두 몇 kg인지, ⟨2 2/4⟩ kg을 딴 농부가 몇 kg 더 많이 땄는지 각각 구하고, 분수의 덧셈과 뺄셈을 어떻게 하는지 설명해 보세요.","answer_guide":{"answer":"예: 모두 — ⟨2 2/4⟩ + ⟨1 3/4⟩ = (2 + 1) + (⟨2/4⟩ + ⟨3/4⟩) = 3 + ⟨5/4⟩ = ⟨4 1/4⟩ (kg). 더 많이 딴 양 — ⟨2 2/4⟩에서 1만큼을 가분수로 바꾸어 ⟨1 6/4⟩ − ⟨1 3/4⟩ = ⟨3/4⟩ (kg). 분모가 같은 분수의 덧셈과 뺄셈은 분모는 그대로 두고 자연수끼리, 분수끼리 계산하며, 분수끼리 뺄 수 없으면 1만큼을 가분수로 바꾼다.","scoring_points":["⟨4 1/4⟩ kg을 구했는가","⟨3/4⟩ kg을 구했는가","분모는 그대로 두고 계산하는 방법을 설명했는가"]},"explanation":["⟨2 2/4⟩ + ⟨1 3/4⟩ = ⟨4 1/4⟩이에요.","⟨2 2/4⟩ − ⟨1 3/4⟩ = ⟨3/4⟩이에요.","분모처럼 한결같이 — 분모는 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_d#1','math',4,2,'u1','','tb_g4_2_math_u1_review_d','unit_review','M4-2-u1-C2',1,'mc','auto','분수 띠로 1을 ⟨1/4⟩과 □로 갈랐어요. □에 알맞은 분수는 무엇인가요?',ARRAY['M4-2-u1-X06','M4-2-u1-X16']::text[],false,'{"seq":1,"concept":"M4-2-u1-C2","difficulty":1,"kind":"mc","stem":"분수 띠로 1을 ⟨1/4⟩과 □로 갈랐어요. □에 알맞은 분수는 무엇인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨1/4⟩","mis":"M4-2-u1-X06"},{"t":"⟨2/4⟩","mis":"M4-2-u1-X16"},{"t":"⟨5/4⟩","mis":"M4-2-u1-X06"}],"explanation":["1 = ⟨4/4⟩ — ⟨1/4⟩이 4개예요.","⟨1/4⟩은 ⟨1/4⟩이 1개라 4 − 1 = 3개가 모자라요.","⟨1/4⟩ + ⟨3/4⟩ = ⟨4/4⟩ = 1이에요."],"asset":{"type":"fbar","bars":[{"den":4,"num":1,"label":"1을 가르기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_d#2','math',4,2,'u1','','tb_g4_2_math_u1_review_d','unit_review','M4-2-u1-C3',1,'sa','auto','「확인 문제」 ⟨4/8⟩ + ⟨3/8⟩ = ⟨□/8⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M4-2-u1-C3","difficulty":1,"kind":"sa","stem":"「확인 문제」 ⟨4/8⟩ + ⟨3/8⟩ = ⟨□/8⟩ — □에 알맞은 수를 쓰세요.","answer":["7"],"explanation":["⟨4/8⟩는 ⟨1/8⟩이 4개, ⟨3/8⟩은 ⟨1/8⟩이 3개예요.","⟨4/8⟩ + ⟨3/8⟩ = ⟨7/8⟩ — 분모는 그대로 두고 분자끼리 더해요.","분모끼리 더한 ⟨7/16⟩은 답이 아니에요 — 답은 ⟨7/8⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_d#3','math',4,2,'u1','','tb_g4_2_math_u1_review_d','unit_review','M4-2-u1-C4',1,'sa','auto','「익힘」 ⟨6/8⟩ − ⟨3/8⟩ = ⟨□/8⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M4-2-u1-C4","difficulty":1,"kind":"sa","stem":"「익힘」 ⟨6/8⟩ − ⟨3/8⟩ = ⟨□/8⟩ — □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["⟨6/8⟩은 ⟨1/8⟩이 6개, ⟨3/8⟩은 ⟨1/8⟩이 3개예요.","⟨6/8⟩ − ⟨3/8⟩ = ⟨3/8⟩ — 분모는 그대로 두고 분자끼리 빼요.","⟨1/8⟩이 6 − 3 = 3개 남아요 — 분모끼리 빼지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_d#4','math',4,2,'u1','','tb_g4_2_math_u1_review_d','unit_review','M4-2-u1-C5',1,'mc','auto','⟨1 1/5⟩ + ⟨1 2/5⟩를 계산해 보세요.',ARRAY['M4-2-u1-X01','M4-2-u1-X13','M4-2-u1-X16']::text[],false,'{"seq":4,"concept":"M4-2-u1-C5","difficulty":1,"kind":"mc","stem":"⟨1 1/5⟩ + ⟨1 2/5⟩를 계산해 보세요.","options":[{"t":"⟨2 3/5⟩","correct":true},{"t":"⟨2 3/10⟩","mis":"M4-2-u1-X01"},{"t":"⟨3/5⟩","mis":"M4-2-u1-X13"},{"t":"⟨2 4/5⟩","mis":"M4-2-u1-X16"}],"explanation":["방법 1 — 자연수끼리 1 + 1 = 2, 분수끼리 ⟨1/5⟩ + ⟨2/5⟩ = ⟨3/5⟩이에요.","2 + ⟨3/5⟩ = ⟨2 3/5⟩.","방법 2 — 가분수로 바꾸면 ⟨6/5⟩ + ⟨7/5⟩ = ⟨13/5⟩ = ⟨2 3/5⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_d#5','math',4,2,'u1','','tb_g4_2_math_u1_review_d','unit_review','M4-2-u1-C6',1,'sa','auto','「익힘」 ⟨3 5/6⟩ − ⟨2 4/6⟩ = ⟨23/6⟩ − ⟨16/6⟩ = ⟨□/6⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M4-2-u1-C6","difficulty":1,"kind":"sa","stem":"「익힘」 ⟨3 5/6⟩ − ⟨2 4/6⟩ = ⟨23/6⟩ − ⟨16/6⟩ = ⟨□/6⟩ — □에 알맞은 수를 쓰세요.","answer":["7"],"explanation":["⟨3 5/6⟩ = ⟨23/6⟩, ⟨2 4/6⟩ = ⟨16/6⟩이에요.","⟨23/6⟩ − ⟨16/6⟩ = ⟨7/6⟩ — 분모는 그대로예요.","⟨7/6⟩ = ⟨1 1/6⟩ — □ = 7."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_d#6','math',4,2,'u1','','tb_g4_2_math_u1_review_d','unit_review','M4-2-u1-C8',1,'mc','auto','「익힘」 ⟨4 2/6⟩ − ⟨5/6⟩를 계산해 보세요.',ARRAY['M4-2-u1-X11','M4-2-u1-X03','M4-2-u1-X16']::text[],false,'{"seq":6,"concept":"M4-2-u1-C8","difficulty":1,"kind":"mc","stem":"「익힘」 ⟨4 2/6⟩ − ⟨5/6⟩를 계산해 보세요.","options":[{"t":"⟨3 3/6⟩","correct":true},{"t":"⟨4 3/6⟩","mis":"M4-2-u1-X11"},{"t":"⟨1/6⟩","mis":"M4-2-u1-X03"},{"t":"⟨3 4/6⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨2/6⟩에서 ⟨5/6⟩를 뺄 수 없어 1만큼을 ⟨6/6⟩으로 바꿔요 — ⟨4 2/6⟩ = ⟨3 8/6⟩.","⟨3 8/6⟩ − ⟨5/6⟩ = ⟨3 3/6⟩ — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨26/6⟩ − ⟨5/6⟩ = ⟨21/6⟩ = ⟨3 3/6⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_d#7','math',4,2,'u1','','tb_g4_2_math_u1_review_d','unit_review','M4-2-u1-C3',1,'mc','auto','그림을 보고 ⟨7/9⟩ + ⟨5/9⟩를 계산하여 대분수로 나타내면 얼마인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X04']::text[],false,'{"seq":7,"concept":"M4-2-u1-C3","difficulty":1,"kind":"mc","stem":"그림을 보고 ⟨7/9⟩ + ⟨5/9⟩를 계산하여 대분수로 나타내면 얼마인가요?","options":[{"t":"⟨1 3/9⟩","correct":true},{"t":"⟨12/18⟩","mis":"M4-2-u1-X01"},{"t":"⟨3/9⟩","mis":"M4-2-u1-X04"},{"t":"⟨2 3/9⟩","mis":"M4-2-u1-X04"}],"explanation":["⟨7/9⟩은 ⟨1/9⟩이 7개, ⟨5/9⟩는 ⟨1/9⟩이 5개예요.","⟨7/9⟩ + ⟨5/9⟩ = ⟨12/9⟩ — 분모는 그대로 두고 분자끼리 더해요.","⟨12/9⟩ = ⟨1 3/9⟩ — 분모끼리 더하지 않아요."],"asset":{"type":"fbar","bars":[{"den":9,"num":7},{"den":9,"num":5}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_d#8','math',4,2,'u1','','tb_g4_2_math_u1_review_d','unit_review','M4-2-u1-C7',1,'match','auto','「익힘」 계산 결과끼리 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u1-C7","difficulty":1,"kind":"match","stem":"「익힘」 계산 결과끼리 알맞게 이으세요.","pairs":[{"l":"⟨2/9⟩ + ⟨5/9⟩","r":"⟨7/9⟩"},{"l":"⟨7/11⟩ − ⟨2/11⟩","r":"⟨5/11⟩"},{"l":"⟨1 1/4⟩ + ⟨2 2/4⟩","r":"⟨3 3/4⟩"},{"l":"3 − ⟨4/5⟩","r":"⟨2 1/5⟩"}],"mis":"M4-2-u1-X09","explanation":["⟨2/9⟩ + ⟨5/9⟩ = ⟨7/9⟩, ⟨7/11⟩ − ⟨2/11⟩ = ⟨5/11⟩예요.","⟨1 1/4⟩ + ⟨2 2/4⟩ = ⟨3 3/4⟩이에요.","3 − ⟨4/5⟩ = ⟨2 5/5⟩ − ⟨4/5⟩ = ⟨2 1/5⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_d#9','math',4,2,'u1','','tb_g4_2_math_u1_review_d','unit_review','M4-2-u1-C9',2,'mc','auto','「익힘」 두 분수 ⟨5 3/9⟩과 ⟨22/9⟩의 차는 얼마인가요?',ARRAY['M4-2-u1-X11','M4-2-u1-X09','M4-2-u1-X14']::text[],false,'{"seq":9,"concept":"M4-2-u1-C9","difficulty":2,"kind":"mc","stem":"「익힘」 두 분수 ⟨5 3/9⟩과 ⟨22/9⟩의 차는 얼마인가요?","options":[{"t":"⟨2 8/9⟩","correct":true},{"t":"⟨3 1/9⟩","mis":"M4-2-u1-X11"},{"t":"⟨3 8/9⟩","mis":"M4-2-u1-X09"},{"t":"⟨7 7/9⟩","mis":"M4-2-u1-X14"}],"explanation":["⟨22/9⟩ = ⟨2 4/9⟩예요.","⟨5 3/9⟩ − ⟨2 4/9⟩ = ⟨4 12/9⟩ − ⟨2 4/9⟩ = ⟨2 8/9⟩이에요.","가분수로 바꾸면 ⟨48/9⟩ − ⟨22/9⟩ = ⟨26/9⟩ = ⟨2 8/9⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_d#10','math',4,2,'u1','','tb_g4_2_math_u1_review_d','unit_review','M4-2-u1-C5',2,'mc','auto','「익힘」 계산 결과가 큰 것부터 차례대로 기호를 쓴 것은 무엇인가요?  ㉠ ⟨3 1/7⟩ + ⟨1 4/7⟩  ㉡ ⟨2 4/7⟩ + ⟨4 2/7⟩  ㉢ ⟨4 2/7⟩ + ⟨1 6/7⟩  ㉣ ⟨2 4/7⟩ + ⟨3 5/7⟩',ARRAY['M4-2-u1-X15','M4-2-u1-X17','M4-2-u1-X16']::text[],false,'{"seq":10,"concept":"M4-2-u1-C5","difficulty":2,"kind":"mc","stem":"「익힘」 계산 결과가 큰 것부터 차례대로 기호를 쓴 것은 무엇인가요?  ㉠ ⟨3 1/7⟩ + ⟨1 4/7⟩  ㉡ ⟨2 4/7⟩ + ⟨4 2/7⟩  ㉢ ⟨4 2/7⟩ + ⟨1 6/7⟩  ㉣ ⟨2 4/7⟩ + ⟨3 5/7⟩","options":[{"t":"㉡, ㉣, ㉢, ㉠","correct":true},{"t":"㉠, ㉢, ㉣, ㉡","mis":"M4-2-u1-X15"},{"t":"㉣, ㉡, ㉢, ㉠","mis":"M4-2-u1-X17"},{"t":"㉡, ㉣, ㉠, ㉢","mis":"M4-2-u1-X16"}],"explanation":["하나씩 계산해요 — ㉠ ⟨3 1/7⟩ + ⟨1 4/7⟩ = ⟨4 5/7⟩, ㉡ ⟨2 4/7⟩ + ⟨4 2/7⟩ = ⟨6 6/7⟩, ㉢ ⟨4 2/7⟩ + ⟨1 6/7⟩ = ⟨6 1/7⟩, ㉣ ⟨2 4/7⟩ + ⟨3 5/7⟩ = ⟨6 2/7⟩.","⟨6 6/7⟩ > ⟨6 2/7⟩ > ⟨6 1/7⟩ > ⟨4 5/7⟩예요.","계산 결과가 큰 것부터 쓰면 ㉡, ㉣, ㉢, ㉠예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_d#11','math',4,2,'u1','','tb_g4_2_math_u1_review_d','unit_review','M4-2-u1-C4',2,'mc','auto','「확인 문제」 1 − ⟨4/15⟩를 계산해 보세요.',ARRAY['M4-2-u1-X08','M4-2-u1-X15','M4-2-u1-X16']::text[],false,'{"seq":11,"concept":"M4-2-u1-C4","difficulty":2,"kind":"mc","stem":"「확인 문제」 1 − ⟨4/15⟩를 계산해 보세요.","options":[{"t":"⟨11/15⟩","correct":true},{"t":"⟨3/15⟩","mis":"M4-2-u1-X08"},{"t":"⟨4/15⟩","mis":"M4-2-u1-X15"},{"t":"⟨12/15⟩","mis":"M4-2-u1-X16"}],"explanation":["1은 ⟨1/15⟩이 15개 — 1 = ⟨15/15⟩예요.","1 − ⟨4/15⟩ = ⟨15/15⟩ − ⟨4/15⟩ = ⟨11/15⟩.","1을 가분수로 바꾼 뒤 분자끼리 빼요 — 15 − 4 = 11."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_d#12','math',4,2,'u1','','tb_g4_2_math_u1_review_d','unit_review','M4-2-u1-C3',2,'mc','auto','「익힘 퐁당」 친구가 「⟨5/8⟩ + ⟨6/8⟩ = ⟨11/16⟩」이라고 계산했어요. 바르게 계산한 값은 얼마인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X04']::text[],false,'{"seq":12,"concept":"M4-2-u1-C3","difficulty":2,"kind":"mc","stem":"「익힘 퐁당」 친구가 「⟨5/8⟩ + ⟨6/8⟩ = ⟨11/16⟩」이라고 계산했어요. 바르게 계산한 값은 얼마인가요?","options":[{"t":"⟨1 3/8⟩","correct":true},{"t":"⟨11/16⟩","mis":"M4-2-u1-X01"},{"t":"⟨3/8⟩","mis":"M4-2-u1-X04"},{"t":"⟨2 3/8⟩","mis":"M4-2-u1-X04"}],"explanation":["⟨5/8⟩는 ⟨1/8⟩이 5개, ⟨6/8⟩은 ⟨1/8⟩이 6개예요.","⟨5/8⟩ + ⟨6/8⟩ = ⟨11/8⟩ — 분모는 그대로 두고 분자끼리 더해요.","⟨11/8⟩ = ⟨1 3/8⟩ — 분모끼리 더하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_d#13','math',4,2,'u1','','tb_g4_2_math_u1_review_d','unit_review','M4-2-u1-C4',2,'mc','auto','1 − ⟨□/9⟩ > ⟨3/9⟩에서 □ 안에 들어갈 수 있는 자연수를 모두 찾은 것은 무엇인가요?',ARRAY['M4-2-u1-X16','M4-2-u1-X15']::text[],false,'{"seq":13,"concept":"M4-2-u1-C4","difficulty":2,"kind":"mc","stem":"1 − ⟨□/9⟩ > ⟨3/9⟩에서 □ 안에 들어갈 수 있는 자연수를 모두 찾은 것은 무엇인가요?","options":[{"t":"1, 2, 3, 4, 5","correct":true},{"t":"1, 2, 3, 4, 5, 6","mis":"M4-2-u1-X16"},{"t":"6, 7, 8","mis":"M4-2-u1-X15"},{"t":"1, 2, 3, 4","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨9/9⟩ — 1에서 ⟨1/9⟩을 □개 빼면 ⟨1/9⟩이 9 − □개 남아요.","1 − ⟨5/9⟩ = ⟨4/9⟩, 1 − ⟨6/9⟩ = ⟨3/9⟩이에요.","1, 2, 3, 4, 5 — 6을 넣으면 크기가 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_d#14','math',4,2,'u1','','tb_g4_2_math_u1_review_d','unit_review','M4-2-u1-C6',2,'mc','auto','「익힘 퐁당」 제자리멀리뛰기 기록이 채원 ⟨1 1/10⟩ m, 지유 ⟨1 7/10⟩ m, 서준 ⟨12/10⟩ m예요. 가장 멀리 뛴 학생과 가장 가깝게 뛴 학생의 기록의 차는 몇 m인가요?',ARRAY['M4-2-u1-X02','M4-2-u1-X14','M4-2-u1-X15']::text[],false,'{"seq":14,"concept":"M4-2-u1-C6","difficulty":2,"kind":"mc","stem":"「익힘 퐁당」 제자리멀리뛰기 기록이 채원 ⟨1 1/10⟩ m, 지유 ⟨1 7/10⟩ m, 서준 ⟨12/10⟩ m예요. 가장 멀리 뛴 학생과 가장 가깝게 뛴 학생의 기록의 차는 몇 m인가요?","options":[{"t":"⟨6/10⟩ m","correct":true},{"t":"⟨5/10⟩ m","mis":"M4-2-u1-X02"},{"t":"⟨2 8/10⟩ m","mis":"M4-2-u1-X14"},{"t":"⟨1/10⟩ m","mis":"M4-2-u1-X15"}],"explanation":["⟨12/10⟩ = ⟨1 2/10⟩ — 가장 멀리 뛴 학생은 지유, 가장 가깝게 뛴 학생은 채원이에요.","⟨1 7/10⟩ − ⟨1 1/10⟩ = (1 − 1) + (⟨7/10⟩ − ⟨1/10⟩) = ⟨6/10⟩이에요.","두 학생의 기록의 차는 ⟨6/10⟩ m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_d#15','math',4,2,'u1','','tb_g4_2_math_u1_review_d','unit_review','M4-2-u1-C5',2,'mc','auto','말린 바나나 껍질 ⟨1 1/5⟩ kg과 커피 가루 ⟨1 2/5⟩ kg을 섞어서 천연 비료를 만들었어요. 만든 천연 비료는 모두 몇 kg인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X13','M4-2-u1-X16']::text[],false,'{"seq":15,"concept":"M4-2-u1-C5","difficulty":2,"kind":"mc","stem":"말린 바나나 껍질 ⟨1 1/5⟩ kg과 커피 가루 ⟨1 2/5⟩ kg을 섞어서 천연 비료를 만들었어요. 만든 천연 비료는 모두 몇 kg인가요?","options":[{"t":"⟨2 3/5⟩ kg","correct":true},{"t":"⟨2 3/10⟩ kg","mis":"M4-2-u1-X01"},{"t":"⟨3/5⟩ kg","mis":"M4-2-u1-X13"},{"t":"⟨2 4/5⟩ kg","mis":"M4-2-u1-X16"}],"explanation":["방법 1 — 자연수끼리 1 + 1 = 2, 분수끼리 ⟨1/5⟩ + ⟨2/5⟩ = ⟨3/5⟩이에요.","2 + ⟨3/5⟩ = ⟨2 3/5⟩ kg.","방법 2 — 가분수로 바꾸면 ⟨6/5⟩ + ⟨7/5⟩ = ⟨13/5⟩ = ⟨2 3/5⟩ kg."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_d#16','math',4,2,'u1','','tb_g4_2_math_u1_review_d','unit_review','M4-2-u1-C9',2,'mc','auto','「익힘」 일주일 동안 모은 재활용품 중에서 종이는 ⟨4 2/10⟩ kg, 플라스틱은 ⟨3 6/10⟩ kg이에요. 종이를 플라스틱보다 몇 kg 더 많이 모았나요?',ARRAY['M4-2-u1-X11','M4-2-u1-X09','M4-2-u1-X16']::text[],false,'{"seq":16,"concept":"M4-2-u1-C9","difficulty":2,"kind":"mc","stem":"「익힘」 일주일 동안 모은 재활용품 중에서 종이는 ⟨4 2/10⟩ kg, 플라스틱은 ⟨3 6/10⟩ kg이에요. 종이를 플라스틱보다 몇 kg 더 많이 모았나요?","options":[{"t":"⟨6/10⟩ kg","correct":true},{"t":"⟨1 4/10⟩ kg","mis":"M4-2-u1-X11"},{"t":"⟨1 6/10⟩ kg","mis":"M4-2-u1-X09"},{"t":"⟨7/10⟩ kg","mis":"M4-2-u1-X16"}],"explanation":["⟨2/10⟩에서 ⟨6/10⟩을 뺄 수 없어 1만큼을 ⟨10/10⟩으로 바꿔요 — ⟨4 2/10⟩ = ⟨3 12/10⟩.","⟨3 12/10⟩ − ⟨3 6/10⟩ = ⟨6/10⟩ kg — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨42/10⟩ − ⟨36/10⟩ = ⟨6/10⟩ = ⟨6/10⟩ kg."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_d#17','math',4,2,'u1','','tb_g4_2_math_u1_review_d','unit_review','M4-2-u1-C2',3,'sa','auto','「익힘」 ⟨5/6⟩ + ⟨□/6⟩ = 1 — □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"M4-2-u1-C2","difficulty":3,"kind":"sa","stem":"「익힘」 ⟨5/6⟩ + ⟨□/6⟩ = 1 — □에 알맞은 수를 쓰세요.","answer":["1"],"explanation":["1 = ⟨6/6⟩ — ⟨1/6⟩이 6개예요.","⟨5/6⟩는 ⟨1/6⟩이 5개라 6 − 5 = 1개가 모자라요.","⟨5/6⟩ + ⟨1/6⟩ = 1 — □ = 1."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_d#18','math',4,2,'u1','','tb_g4_2_math_u1_review_d','unit_review','M4-2-u1-C3',3,'sa','auto','「익힘」 ⟨8/13⟩ + ⟨□/13⟩ = ⟨1 2/13⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"M4-2-u1-C3","difficulty":3,"kind":"sa","stem":"「익힘」 ⟨8/13⟩ + ⟨□/13⟩ = ⟨1 2/13⟩ — □에 알맞은 수를 쓰세요.","answer":["7"],"explanation":["⟨1 2/13⟩ = ⟨15/13⟩ — ⟨1/13⟩이 15개예요.","⟨8/13⟩은 ⟨1/13⟩이 8개라 15 − 8 = 7개를 더 모아야 해요.","⟨8/13⟩ + ⟨7/13⟩ = ⟨1 2/13⟩ — □ = 7."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_d#19','math',4,2,'u1','','tb_g4_2_math_u1_review_d','unit_review','M4-2-u1-C5',3,'sa','auto','「지도서 평가」 ⟨1 5/7⟩ + ⟨1 3/7⟩ = ⟨12/7⟩ + ⟨10/7⟩ = ⟨□/7⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M4-2-u1-C5","difficulty":3,"kind":"sa","stem":"「지도서 평가」 ⟨1 5/7⟩ + ⟨1 3/7⟩ = ⟨12/7⟩ + ⟨10/7⟩ = ⟨□/7⟩ — □에 알맞은 수를 쓰세요.","answer":["22"],"explanation":["⟨1 5/7⟩ = ⟨12/7⟩, ⟨1 3/7⟩ = ⟨10/7⟩이에요.","⟨12/7⟩ + ⟨10/7⟩ = ⟨22/7⟩ — 분모는 그대로예요.","⟨22/7⟩ = ⟨3 1/7⟩ — □ = 22."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_d#20','math',4,2,'u1','','tb_g4_2_math_u1_review_d','unit_review','M4-2-u1-C7',3,'error','auto','2 − ⟨2/3⟩를 계산하는 과정을 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u1-X10','M4-2-u1-X15']::text[],false,'{"seq":20,"concept":"M4-2-u1-C7","difficulty":3,"kind":"error","stem":"2 − ⟨2/3⟩를 계산하는 과정을 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은비 — 「2 − ⟨2/3⟩ = ⟨1 2/3⟩야.」","correct":true,"mis_target":"M4-2-u1-X10"},{"t":"서준 — 「2에서 1만큼을 ⟨3/3⟩으로 바꿔.」","mis":"M4-2-u1-X15"},{"t":"채원 — 「2 = ⟨1 3/3⟩이야.」","mis":"M4-2-u1-X15"},{"t":"지유 — 「⟨1 3/3⟩ − ⟨2/3⟩ = ⟨1 1/3⟩이야.」","mis":"M4-2-u1-X15"}],"explanation":["2 = ⟨1 3/3⟩이에요.","⟨1 3/3⟩ − ⟨2/3⟩ = ⟨1 1/3⟩이에요.","은비는 빼는 분수 ⟨2/3⟩를 그대로 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_d#21','math',4,2,'u1','','tb_g4_2_math_u1_review_d','unit_review','M4-2-u1-C9',3,'mc','auto','「익힘 퐁당」 친구가 「⟨5 1/7⟩ − ⟨1 3/7⟩ = ⟨6/7⟩ − ⟨4/7⟩ = ⟨2/7⟩」라고 계산했어요. 바르게 계산한 값은 얼마인가요?',ARRAY['M4-2-u1-X03','M4-2-u1-X11','M4-2-u1-X09']::text[],false,'{"seq":21,"concept":"M4-2-u1-C9","difficulty":3,"kind":"mc","stem":"「익힘 퐁당」 친구가 「⟨5 1/7⟩ − ⟨1 3/7⟩ = ⟨6/7⟩ − ⟨4/7⟩ = ⟨2/7⟩」라고 계산했어요. 바르게 계산한 값은 얼마인가요?","options":[{"t":"⟨3 5/7⟩","correct":true},{"t":"⟨2/7⟩","mis":"M4-2-u1-X03"},{"t":"⟨4 2/7⟩","mis":"M4-2-u1-X11"},{"t":"⟨4 5/7⟩","mis":"M4-2-u1-X09"}],"explanation":["⟨1/7⟩에서 ⟨3/7⟩을 뺄 수 없어 1만큼을 ⟨7/7⟩로 바꿔요 — ⟨5 1/7⟩ = ⟨4 8/7⟩.","⟨4 8/7⟩ − ⟨1 3/7⟩ = ⟨3 5/7⟩ — 자연수 부분이 1 줄었어요.","가분수로 바꾸면 ⟨36/7⟩ − ⟨10/7⟩ = ⟨26/7⟩ = ⟨3 5/7⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_d#22','math',4,2,'u1','','tb_g4_2_math_u1_review_d','unit_review','M4-2-u1-C5',3,'mc','auto','「익힘」 ⟨3 1/9⟩, ⟨25/9⟩, ⟨2 4/9⟩ 중에서 분수를 2개 골라 계산 결과가 가장 큰 덧셈식을 만들었어요. 계산 결과는 얼마인가요?',ARRAY['M4-2-u1-X17','M4-2-u1-X15','M4-2-u1-X01']::text[],false,'{"seq":22,"concept":"M4-2-u1-C5","difficulty":3,"kind":"mc","stem":"「익힘」 ⟨3 1/9⟩, ⟨25/9⟩, ⟨2 4/9⟩ 중에서 분수를 2개 골라 계산 결과가 가장 큰 덧셈식을 만들었어요. 계산 결과는 얼마인가요?","options":[{"t":"⟨5 8/9⟩","correct":true},{"t":"⟨5 5/9⟩","mis":"M4-2-u1-X17"},{"t":"⟨5 2/9⟩","mis":"M4-2-u1-X15"},{"t":"⟨5 8/18⟩","mis":"M4-2-u1-X01"}],"explanation":["⟨25/9⟩ = ⟨2 7/9⟩ — 세 수의 크기는 ⟨3 1/9⟩ > ⟨25/9⟩ > ⟨2 4/9⟩예요.","가장 큰 수와 둘째로 큰 수를 골라 더해요.","⟨3 1/9⟩ + ⟨25/9⟩ = ⟨3 1/9⟩ + ⟨2 7/9⟩ = ⟨5 8/9⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_d#23','math',4,2,'u1','','tb_g4_2_math_u1_review_d','unit_review','M4-2-u1-C9',4,'mc','auto','「재미있는 수학·이런 활동」 수 카드 2, 3, 4, 6을 한 번씩만 사용하여 분모가 9인 대분수 두 개를 만들고(자연수 부분과 분자에 한 장씩), 큰 대분수에서 작은 대분수를 빼려고 해요. 계산 결과가 가장 작은 뺄셈식의 계산 결과는 얼마인가요?',ARRAY['M4-2-u1-X16','M4-2-u1-X17']::text[],false,'{"seq":23,"concept":"M4-2-u1-C9","difficulty":4,"kind":"mc","stem":"「재미있는 수학·이런 활동」 수 카드 2, 3, 4, 6을 한 번씩만 사용하여 분모가 9인 대분수 두 개를 만들고(자연수 부분과 분자에 한 장씩), 큰 대분수에서 작은 대분수를 빼려고 해요. 계산 결과가 가장 작은 뺄셈식의 계산 결과는 얼마인가요?","options":[{"t":"⟨5/9⟩","correct":true},{"t":"⟨7/9⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 2/9⟩","mis":"M4-2-u1-X16"},{"t":"⟨3 8/9⟩","mis":"M4-2-u1-X17"}],"explanation":["차가 작으려면 두 대분수의 크기가 가까워야 해요 — 자연수 부분이 가장 가까운 두 카드를 골라요.","⟨4 2/9⟩ − ⟨3 6/9⟩ = ⟨5/9⟩예요.","교과서의 ⟨6 3/9⟩ − ⟨2 4/9⟩ = ⟨3 8/9⟩과 견주어 보세요 — 카드를 어디에 놓느냐에 따라 결과가 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_d#24','math',4,2,'u1','','tb_g4_2_math_u1_review_d','unit_review','M4-2-u1-C10',4,'mc','auto','「나는야 분수왕」 분수 카드 10장(⟨1 4/5⟩, ⟨1/5⟩, ⟨16/5⟩, ⟨3/5⟩, ⟨2 3/5⟩, ⟨2 2/5⟩, ⟨3 3/5⟩, ⟨2/5⟩, ⟨7/5⟩, ⟨1 3/5⟩)을 한 번씩만 사용해요. 덧셈식 ⟨3 3/5⟩ + ⟨2/5⟩ = 4를 먼저 만들었다면, 뺄셈식 □ − □ = 2에 쓸 수 있는 두 카드는 무엇인가요?',ARRAY['M4-2-u1-X15','M4-2-u1-X16']::text[],false,'{"seq":24,"concept":"M4-2-u1-C10","difficulty":4,"kind":"mc","stem":"「나는야 분수왕」 분수 카드 10장(⟨1 4/5⟩, ⟨1/5⟩, ⟨16/5⟩, ⟨3/5⟩, ⟨2 3/5⟩, ⟨2 2/5⟩, ⟨3 3/5⟩, ⟨2/5⟩, ⟨7/5⟩, ⟨1 3/5⟩)을 한 번씩만 사용해요. 덧셈식 ⟨3 3/5⟩ + ⟨2/5⟩ = 4를 먼저 만들었다면, 뺄셈식 □ − □ = 2에 쓸 수 있는 두 카드는 무엇인가요?","options":[{"t":"⟨2 3/5⟩, ⟨3/5⟩","correct":true},{"t":"⟨2 2/5⟩, ⟨2/5⟩","mis":"M4-2-u1-X15"},{"t":"⟨3 3/5⟩, ⟨1 3/5⟩","mis":"M4-2-u1-X15"},{"t":"⟨1 4/5⟩, ⟨1/5⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨3 3/5⟩과 ⟨2/5⟩는 이미 썼으니 다시 쓸 수 없어요.","⟨2 3/5⟩ − ⟨3/5⟩ = 2예요.","⟨1 4/5⟩ − ⟨1/5⟩ = ⟨1 3/5⟩ — 2가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u1_review_d#25','math',4,2,'u1','','tb_g4_2_math_u1_review_d','unit_review','M4-2-u1-C1',4,'essay','teacher','「지도서 오류」 한 친구가 「5 + ⟨5/9⟩ = ⟨10/9⟩」이라고 계산했어요. 이 계산이 틀린 까닭을 설명하고, 바르게 계산해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u1-C1","difficulty":4,"kind":"essay","stem":"「지도서 오류」 한 친구가 「5 + ⟨5/9⟩ = ⟨10/9⟩」이라고 계산했어요. 이 계산이 틀린 까닭을 설명하고, 바르게 계산해 보세요.","answer_guide":{"answer":"예: 5 + ⟨5/9⟩는 대분수 ⟨5 5/9⟩로 5보다 큰 수인데 ⟨10/9⟩ = ⟨1 1/9⟩은 1보다 조금 큰 수라 같을 수 없다. 자연수 5를 분자에 그대로 더했기 때문이다. 5 = ⟨45/9⟩이므로 ⟨45/9⟩ + ⟨5/9⟩ = ⟨50/9⟩ = ⟨5 5/9⟩이다.","scoring_points":["⟨10/9⟩은 1보다 조금 큰 수라 같을 수 없다고 썼는가","자연수를 분자에 더한 것이 잘못이라고 썼는가","⟨5 5/9⟩(또는 ⟨50/9⟩)이라고 답했는가"]},"explanation":["5 = ⟨45/9⟩예요.","⟨45/9⟩ + ⟨5/9⟩ = ⟨50/9⟩ = ⟨5 5/9⟩예요.","자연수를 분자처럼 더하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
